// Part-of-speech labels, keyed by the JMdict codes carried in vocab-authority.json.
const POS_LABEL = {
  n: "名詞", "n-suf": "名詞（接尾）", "n-pref": "名詞（接頭）", "n-adv": "名詞兼副詞",
  "n-t": "時間名詞", pn: "代名詞", num: "數詞", ctr: "量詞",
  adv: "副詞", "adv-to": "副詞（可加「と」）",
  "adj-i": "い形容詞", "adj-na": "な形容詞", "adj-no": "の形容詞（後接名詞加「の」）",
  "adj-f": "連體詞", "adj-t": "たる形容詞", "adj-nari": "なり形容詞",
  vs: "サ變動詞（名詞＋する）", "vs-s": "サ變動詞（〜す）", "vs-i": "サ變動詞（〜ずる）",
  vt: "他動詞", vi: "自動詞", v1: "一段動詞", vk: "カ變動詞（来る）", vz: "サ變動詞（〜ずる）",
  v5u: "五段動詞（う結尾）", v5k: "五段動詞（く結尾）", v5g: "五段動詞（ぐ結尾）",
  v5s: "五段動詞（す結尾）", v5t: "五段動詞（つ結尾）", v5n: "五段動詞（ぬ結尾）",
  v5b: "五段動詞（ぶ結尾）", v5m: "五段動詞（む結尾）", v5r: "五段動詞（る結尾）",
  v5aru: "五段動詞（特殊活用）", "v5k-s": "五段動詞（行く型）",
  "v5u-s": "五段動詞（特殊活用）", "v5r-i": "五段動詞（特殊活用）",
  exp: "慣用表現", int: "感嘆詞", conj: "接續詞", prt: "助詞", suf: "接尾語", pref: "接頭語",
  "aux-adj": "助動詞（形容詞型）", "aux-v": "助動詞", aux: "助動詞", cop: "斷定助動詞",
};

function posLabels(pos = []) {
  const seen = new Set();
  const labels = [];
  for (const code of pos) {
    const label = POS_LABEL[code];
    if (label && !seen.has(label)) {
      seen.add(label);
      labels.push(label);
    }
  }
  return labels;
}

// Advice that actually differs by word class, instead of one sentence for all 4000.
function posAdvice(pos = []) {
  const has = (code) => pos.includes(code);
  const tips = [];
  if (has("vt") && has("vi")) tips.push("他動詞與自動詞同形，靠助詞「を／が」判斷是誰做、誰變化");
  else if (has("vt")) tips.push("他動詞，受詞用「を」標示");
  else if (has("vi")) tips.push("自動詞，不以「を」標示直接受詞");
  if (has("vs") || has("vs-s") || has("vs-i")) tips.push("加「する」即可當動詞使用");
  if (has("adj-i")) tips.push("い形容詞，修飾名詞時直接接，否定為「〜くない」");
  if (has("adj-na")) tips.push("な形容詞，修飾名詞時要加「な」");
  if (has("adj-no")) tips.push("修飾名詞時要加「の」");
  if (has("adv") || has("adv-to")) tips.push("副詞，用來修飾動作或整句語氣");
  if (has("n-suf") || has("suf")) tips.push("接在其他語詞後面構成新詞");
  if (has("n-pref") || has("pref")) tips.push("接在其他語詞前面構成新詞");
  if (has("ctr")) tips.push("量詞，接在數字後面計數");
  if (has("exp")) tips.push("固定說法，整句一起記");
  if (has("int")) tips.push("感嘆詞，單獨使用表達語氣");
  if (has("prt")) tips.push("助詞，注意它標示的是主語、受詞還是範圍");
  if (!tips.length) tips.push("請連同例句中的搭配一起記憶");
  return tips;
}

function vocabUsageZh(row, meaningZh) {
  const labels = posLabels(row.pos);
  const head = labels.length ? "詞性：" + labels.join("、") + "。" : "";
  const senseCount = (row.senses || []).length;
  const teachingCount = vocabTeachingSenses[row.id]?.length ?? 0;
  const primary = meaningZh.split("；")[0];
  const multi =
    teachingCount > 0
      ? "展開「比較詞義」，查看本詞的 " + teachingCount + " 組用法，並依句中語境辨義。"
      : senseCount > 1
      ? "本詞另有 " + (senseCount - 1) + " 個義項，本卡以最常用的「" + primary + "」為主，其餘請依上下文判斷。"
      : "";
  // JMdict's s_inf notes are English and would be the only non-Chinese text on
  // the card, so they are deliberately not surfaced here.
  return (head + posAdvice(row.pos).join("；") + "。" + multi).trim();
}

// Explanation shape varies by word class so the 4000 cards do not all read alike.
const reviewedVocabExplanations = new Map([
  ["このボタンを押してください。","「ボタン」在這裡是名詞，指按鈕。「ボタンを押す」表示按下按鈕。"],
  ["部屋のライトを消してください。","「ライト」在這裡是名詞，指照明用的燈。「ライトを消す」表示關燈。"],
  ["冷蔵庫に何か入っている。","「何か」（なにか）由「何」加上「か」構成，指某個未明說的東西。例句表示冰箱裡有東西。"],
  ["今回の旅行は楽しかったです。","「今回」（こんかい）指這一次。「今回の旅行」表示這次旅行，「の」把「今回」和「旅行」連在一起。"],
  ["これから会議が始まります。","「これから」在這裡指接下來。「これから会議が始まります」表示會議即將開始。"],
  ["昼を過ぎて店が空いてきた。","「空く」（すく）在這裡指人變少、沒那麼擁擠。「店が空いてきた」表示店裡的客人漸漸少了。"],
  ["紙に丸を描く。", "「描く」有「かく」和「えがく」兩種讀法。「紙に丸を描く」是畫圓圈，這個搭配常讀「かく」。「小説で人物を描く」指在小說中刻畫人物，「将来の姿を思い描く」是想像未來的樣子，這兩個搭配讀「えがく」。"],
  ["車にオイルを補充しました。", "在汽車保養的語境中，「オイル」可指機油。搭配「オリーブ」時，「オリーブオイル」指橄欖油。按摩時使用的油可稱為「マッサージオイル」。"],
  ["駅前の洋品店で買った。", "「洋品店」（ようひんてん）指販售西式服飾及配件的店。例句表示在車站前的服飾店買了東西。"],
  ["粉を水で溶いた。", "「溶く」（とく）在「粉を水で溶く」指用水把粉調開。和雞蛋搭配時，「卵を溶く」是把蛋打散攪勻。"],
  ["肉を裏返して焼いた。", "「裏返す」（うらがえす）在這裡指把肉翻面，讓原本朝下的一面轉到上面。"],
  ["彼と同様に私もそう思う。", "「同様に」（どうように）表示以相同的方式或有相同的情況。「彼と同様に」表示和他一樣。"],
  ["彼はその団体の一員です。", "「団体」（だんたい）可指組織，也可指共同行動的一群人。「その団体の一員」是該組織的一名成員，「団体で旅行する」則是以團體方式旅行。"],
  ["定期的に運動しています。", "「定期的に」（ていきてきに）修飾動作，表示按固定週期進行。通勤時說「定期を買う」常指買定期乘車票，銀行語境中的「定期に預ける」則指存定期存款。"],
  ["和英辞典で単語を調べた。", "「和英辞典」（わえいじてん）是從日文查英文的辭典。例句表示用這種辭典查了單字。"],
  ["電子辞書はとても便利です。", "「電子」（でんし）在「電子辞書」中修飾「辞書」，表示電子式辭典。在「電子は負の電荷をもつ」中，「電子」指帶負電荷的粒子。"],
  ["蛇口を捩って水を止めた。", "「捩る」（ねじる，常寫成假名「ねじる」）在本句指轉動水龍頭。「足首をねじる」則可指扭到腳踝。"],
  ["そんなやり方は狡い。", "「狡い」（ずるい）形容人善於耍手段時可譯為「狡猾」。「そんなやり方は狡い」是在指責做法不公平，口語可譯為「那種做法太耍賴了」。"],
  ["彼はあちこち旅行した。", "「あちこち旅行する」指到各地旅行。「あちこち」也可描述東西分散在各處，例如「書類があちこちに散らばっている」。"],
  ["風船を膨らました。", "「膨らます」（ふくらます）指使東西鼓起來。「風船を膨らました」表示把氣球吹鼓。"],
  ["ご無沙汰しております。", "「無沙汰」（ぶさた）指一段時間沒有聯絡。「ご無沙汰しております」是久未聯絡時的客氣問候。"],
  ["彼は3日連続で遅刻した。", "「連続」（れんぞく）表示中間沒有間斷。「三日連続で」指接連三天。"],
  ["カメラのレンズを交換しました。", "「レンズ」的譯法隨搭配而變。「カメラのレンズ」是相機鏡頭，「眼鏡のレンズ」是眼鏡鏡片。這句表示更換了相機鏡頭。"],
  ["板が湿気で反ってしまった。", "「反る」（そる）用於木板時可指翹曲變形。「板が湿気で反った」表示木板受潮翹曲。「上体が後ろに反る」則指上半身向後彎。"],
  ["彼の言葉は皮肉に聞こえた。", "「皮肉」（ひにく）在本句指言語上的挖苦，所以「皮肉に聞こえた」是聽起來像在挖苦人。「皮肉な結果」也可指事與願違、帶有諷刺意味的結果。"],
  ["彼女とは長く付き合っている。", "「付き合う」（つきあう）在這裡表示和對方長期交往。兩人的關係要看前後文。"],
  ["いい考えが浮かんだ。", "「浮かぶ」（うかぶ）的意思取決於主語。「考えが浮かぶ」是想到點子，「木の葉が水に浮かぶ」是葉子浮在水上，「顔に笑みが浮かぶ」是臉上露出笑容。"],
  ["代金を払い戻してもらった。", "「払い戻す」（はらいもどす）指退還已付或已存入的款項，例如「切符の代金を払い戻す」是退還票款。「払い戻してもらった」從收款者的角度表示拿到了退款。"],
  ["会計は別々にしてください。", "「別々に」（べつべつに）表示各自分開處理。例句是在請店家分開結帳。"],
  ["彼に直接話してください。", "「直接」（ちょくせつ）在這裡修飾「話す」。「彼に直接話してください」表示請直接跟他談。"],
  ["この犬はすぐ人に馴れる。", "「人に馴れる」（なれる）在本句指狗逐漸習慣和人相處。表示熟悉工作或環境時，常用同音的「慣れる」，例如「仕事に慣れる」。"],
  ["京都は観光客が多い。", "「観光客」（かんこうきゃく）由「観光」和「客」組成，指到某地觀光的人。例句表示京都有很多遊客。"],
  ["このケーキはカロリーが高い。", "「カロリーが高い」在食品的語境中表示熱量高。例句形容這款蛋糕的熱量很高。"],
  ["日帰りで温泉に行った。", "「日帰りで」（ひがえりで）表示當天往返。例句表示去泡溫泉並在當天回來。"],
  ["父の兄である伯父さんが遊びに来た。", "「伯父さん」（おじさん）在這句指爸爸的哥哥，也可指父母姊姊的丈夫。父母的弟弟或妹妹的丈夫通常寫「叔父さん」。泛稱鄰居等成年男性時，常寫成假名「おじさん」。"],
  ["将来について不安を感じる。", "「不安」（ふあん）在「不安を感じる」中是名詞，指擔心或焦慮。例句表示對未來感到不安。"],
  ["税を含めて千円です。", "「税を含める」（ふくめる）指把稅金計入總額。「皮肉を含めた言い方」表示把諷刺意味放進話裡。「言い含める」指把事情交代清楚，「煮含める」則指用烹煮讓食材吸收湯汁。"],
  ["天井から照明を吊る。", "「照明を吊る」（つる）指把燈具懸掛起來。「目がつる」則形容眼角上揚，「縫い目がつる」指縫線太緊，使附近布料繃皺。"],
  ["今後ともよろしくお願いします。", "「今後とも」（こんごとも）表示往後也一樣。「今後ともよろしくお願いします」用於請對方今後也繼續關照。"],
  ["話がようやく纏まった。", "「話が纏まる」（まとまる）在協商語境中指談妥。「荷物が一つにまとまる」是行李集中成一件，「考えがまとまる」則是想法整理成形。"],
  ["食べ物を残すのはもったいないです。", "「食べ物を残すのはもったいない」是在說留下食物很浪費。「私にはもったいないお言葉です」則是受稱讚時的謙遜說法，表示對方給的評價太高，自己受之有愧。"],
  ["意見を一つに纏めた。", "「意見を一つに纏める」（まとめる）指把意見彙整成一個說法。「要点をまとめる」是整理重點，「交渉をまとめる」則指使協商達成結果。"],
  ["池に落ち葉が点々と浮かぶ。", "「点々と」（てんてんと）在本句表示落葉零星分布在水面。「赤い点々」則把「点々」當名詞用，指一個個紅點。"],
  ["道を進むと川に突き当たる。", "「突き当たる」（つきあたる）在本句指走到河邊，道路被河阻隔。移動中的人或物碰上障礙物時，如「壁に突き当たる」，可指撞上牆壁。「難題に突き当たる」則是遇到難題。"],
  ["欠席した父に代わって挨拶した。", "「父に代わって」（ちちにかわって）表示代替父親，這裡是代他致詞。「前任者に代わる」可表示接任。指人員輪替時也可寫「替わる」，指物品交換時可寫「換わる」。"],
  ["私はクラシック音楽が好きです。", "「クラシック音楽」是古典音樂，單說「クラシック」也可指這類音樂。「クラシックなデザイン」則形容設計具有古典或歷久不衰的風格。"],
  ["大して難しくない。", "「大して」（たいして）常和否定形式搭配。「大して難しくない」表示並不怎麼難。"],
  ["大凡の見当はついた。", "「大凡」（おおよそ，常寫成假名）在「大凡の見当」是名詞，指大致的情況。「おおよそ百人」中的「おおよそ」則用在數字前，表示大約一百人。"],
  ["旅行に着替えを持っていく。", "「着替え」（きがえ）可指替換用的衣服，也可指換衣服的動作。「着替えを持っていく」是帶換洗衣物，「着替えを済ませる」則是換好衣服。"],
  ["指定された場所に行ってください。", "「指定された」（していされた）是「指定する」的被動形式。「指定された場所」表示已指定的地點。"],
  ["どの方法にも長短がある。", "「長短」（ちょうたん）在這裡指優點與缺點。例句表示每種方法都有優缺點。"],
  ["通り掛かった人が助けてくれた。", "「通り掛かる」（とおりかかる）表示碰巧經過。「通り掛かった人」指恰好路過的人。"],
  ["フライパンで豆を煎った。", "「煎る」（いる）在這裡指用乾熱烘炒食材。例句表示用平底鍋乾炒豆子。"],
  ["送り仮名が間違っている。", "「送り仮名」（おくりがな）是日語詞中寫在漢字後面的假名，例如「食べる」的「べる」。例句指出這部分寫錯了。"],
  ["憎らしいほどうまい。", "「憎らしい」（にくらしい）單用可表示討厭、可惡。「憎らしいほどうまい」則是帶戲謔的讚嘆，意思是厲害得讓人羨慕甚至有點嫉妒。"],
  ["彼は大学で物理を専攻しています。", "「物理」（ぶつり）在「物理を専攻する」是「物理学」的簡稱，意思是主修物理學。「物理の法則」則指自然界的物理規律。"],
  ["車の速力を落とした。", "「速力を落とす」（そくりょくをおとす）表示減速。例句表示把車速放慢了。"],
  ["彼は難しい選択を迫られた。", "「選択を迫られる」（せんたくをせまられる）表示情勢迫使某人做選擇。例句表示他不得不做出艱難的選擇。"],
  ["駅前で待ち合わせよう。", "「待ち合わせる」（まちあわせる）指約好時間和地點碰面。例句是在提議到車站前碰面。"],
  ["船は北へ針路を取った。", "「針路」（しんろ）在這裡指船航行的方向。「北へ針路を取った」表示船選擇朝北航行。"],
  ["塵紙で手をふいた。", "「塵紙」（ちりがみ）指擦拭用的薄紙，依用途可譯為紙巾或衛生紙。本句用來擦手，譯為紙巾或面紙都合適。"],
  ["月が水平線から昇った。", "「水平線」（すいへいせん）在這裡指遠處水面與天空相接的界線。例句表示月亮從水天相接處升起。"],
  ["この店は瀬戸物を扱っている。", "「瀬戸物」（せともの）可特指日本瀨戶出產的陶瓷，也可泛指陶瓷器。本句只說這家店經營陶瓷器，是否為瀨戶產要看前後文。"],
  ["原稿を清書した。", "「清書する」（せいしょする）指把草稿工整地抄成正式版本。「原稿を清書した」表示把原稿謄寫整齊。"],
  ["会場がようやく静まった。", "「会場が静まる」（しずまる）表示會場的聲音漸漸停下來。「騒ぎが鎮まる」常用同音的「鎮まる」，表示騷動平息。"],
  ["うちわで顔を扇いだ。", "「扇ぐ」（あおぐ）在本句指用團扇朝臉搧風。表示鼓動他人採取行動時，也可見「反乱をあおる」，常寫作「煽る」。"],
  ["近所の小父さんに挨拶した。", "「小父さん」（おじさん）在本句是對鄰近成年男性的稱呼，常寫成假名「おじさん」。同音的「伯父さん」和「叔父さん」則用於親屬稱謂。"],
  ["彼は父親にそっくりだ。", "「～にそっくりだ」表示和某人或某物非常相像。「父親にそっくりだ」表示他長得跟父親很像。"],
  ["車のブレーキが効かない。", "「ブレーキ」在本句指車輛的煞車，「ブレーキが効かない」表示煞車失靈。「物価の上昇にブレーキをかける」是比喻用法，意思是抑制物價上漲。"],
  ["床の間に花を飾った。", "「床の間」（とこのま）是和室內用來陳設花卉、掛軸等物品的凹間。例句表示在這個位置擺了花。"],
  ["池の魚が殖えてきた。", "「殖える」（ふえる）在這裡指生物繁殖後數量增加。「池の魚が殖えてきた」表示池裡的魚漸漸變多了。"],
  ["財産を殖やす方法を考える。", "「殖やす」（ふやす）在這裡指讓財產增加。「財産を殖やす方法」表示增加財產的方法。"],
  ["寝間着のまま朝食を食べた。", "「寝間着のまま」（ねまきのまま）表示仍穿著睡衣。例句表示還沒換衣服就吃了早餐。"],
  ["難しい漢字に振り仮名をつけた。", "「振り仮名」（ふりがな）是標在漢字旁或上方的假名，用來提示讀音。例句表示替難讀的漢字加上假名注音。"],
  ["豆を一晩水に浸けた。", "「浸ける」（つける）在這裡指把食材放進水裡浸泡。例句表示把豆子放在水中泡了一整晚。"],
  ["遅れて申し訳ない。", "「遅れて申し訳ない」（おくれてもうしわけない）是為遲到道歉。受人幫忙時說「お手数をおかけして申し訳ありません」，則帶有因麻煩對方而過意不去、也感謝對方費心的語氣。"],
  ["音楽のリズムに合わせて踊った。", "「リズムに合わせて」（リズムにあわせて）表示配合節奏。例句描述隨著音樂的節奏跳舞。"],
  ["彼の気持ちを酌んであげて。", "「酌む」（くむ）在「気持ちを酌む」中指設身處地體諒對方的感受。例句是在請對方體諒他的心情。"],
  ["汗を手拭いでふいた。", "「手拭い」（てぬぐい）是日式布巾，可以用來擦手或擦汗。例句表示用布巾擦了汗。"],
  ["彼は毎日ジムでトレーニングをしている。", "「ジムでトレーニングをする」指在健身房鍛鍊身體。「接客のトレーニング」則是學習如何接待顧客的訓練。"],
  ["10時以降は静かにしてください。", "「以降」（いこう）表示從某個時間點起，包含該時間點。「10時以降」表示從十點起。"],
  ["先生が読む言葉の書取をした。", "「書取」（かきとり，也寫作「書き取り」）可指把聽到的內容寫下來，也可指照著文字寫下來。本句是把老師念出的詞語寫下來，所以譯為「聽寫」。"],
  ["隣に女の人が座った。", "「女の人」（おんなのひと）指女性。例句表示有一位女性在旁邊坐了下來。"],
  ["消費税が上がった。", "「消費」（しょうひ）指耗用物品等。「消費税」（しょうひぜい）指對消費課徵的稅。例句表示消費稅調高了。"],
  ["夜が更けても眠れない。", "「更ける」（ふける）指夜色漸深。「夜が更けても」表示即使夜已深，後半句說仍然睡不著。"],
  ["店の前に行列ができた。", "「行列」（ぎょうれつ）在這裡指排成一列的人。「店の前に行列ができた」表示店門口排起了隊。"],
  ["この資料は参考になります。", "「参考になる」（さんこうになる）表示有參考價值。例句表示這份資料能提供有用的參考。"],
  ["税を差し引きした額です。", "「税を差し引きした額」指扣掉稅額後所剩的金額。「差し引き」作名詞也可指加減後的餘額；談潮汐時則可指海水的漲退。"],
  ["部屋が散らかっている。", "「散らかっている」（ちらかっている）描述東西散放、尚未收拾的狀態。例句表示房間亂七八糟。"],
  ["スマートフォンの普及は急速に進んだ。", "「普及」（ふきゅう）在這裡指越來越多人使用某項產品。例句表示智慧型手機很快就普及了。"],
  ["想像力を働かせなさい。", "「想像力」（そうぞうりょく）指想像的能力。「想像力を働かせる」表示發揮想像力。"],
  ["父はアルコールを飲まない。", "「アルコールを飲む」在本句指喝含酒精的飲料。「アルコールで手を消毒する」則指用消毒酒精消毒雙手。"],
  ["彼は足が不自由だ。", "「足が不自由だ」（あしがふじゆうだ）表示腿腳活動不便。「生活に不自由する」可指生活遇到困難，「お金に不自由しない」則表示手頭寬裕。"],
  ["スカイブルーのシャツを買った。", "「スカイブルー」指像晴空一樣的淺藍色。例句表示買了一件天藍色襯衫。"],
  ["雪で交通機関が止まった。", "「交通機関」（こうつうきかん）在這裡指交通運輸服務。例句表示交通因下雪而停擺。"],
  ["次はあなたのターンです。", "「あなたのターン」在遊戲中指輪到你的回合。「スキーでターンする」則是在滑雪時轉向。"],
  ["厚かましいお願いですが。", "「厚かましいお願いですが」（あつかましいおねがいですが）是提出請求前的客套話，可譯為「冒昧請您幫個忙」。"],
  ["彼は不正行為で逮捕された。", "「不正」（ふせい）指不正當的做法，具體譯法取決於搭配。「不正行為で逮捕された」表示因不法行為被逮捕。「試験での不正」則可譯為考試舞弊。"],
  ["これから駅に向うところだ。", "「向う」（むかう）在這裡指朝目的地前進。「これから駅に向うところだ」表示正要前往車站。"],
  ["首にマフラーを巻いた。", "「首にマフラーを巻く」（まく）是把圍巾繞在脖子上。「時計のぜんまいを巻く」是給鐘上發條。「時間が押しているので巻いてください」則可在工作現場表示請加快進度。"],
  ["彼はその大会で優勝した。", "「大会」（たいかい）的意思取決於活動性質。「大会で優勝する」是在競賽中奪冠，「全国大会」也可指來自各地的人參加的大型集會。"],
  ["それは事実です。", "「事実」（じじつ）在這裡是名詞。「それは事実です」表示那是事實。"],
  ["電線がショートした。", "「電線がショートする」指電線短路。「ショートヘア」指短髮，棒球裡的「ショート」指游擊位置或游擊手。"],
  ["どんなに頑張っても、無理だった。", "「どんなに～ても」表示「無論多麼……都……」，所以例句是「無論多努力，還是辦不到」。「どんなにうれしかったことか」則用來感嘆當時有多高興。"],
  ["長らく御無沙汰しております。", "「御無沙汰しております」（ごぶさたしております）是久未聯絡時的客氣問候。「長らく」強調已經有一段時間。"],
  ["封筒に御中と書いた。", "「御中」（おんちゅう）寫在公司、機關或部門等收件單位的名稱後，用來敬稱該單位。"],
  ["彼女はロングヘアだ。", "「ロング」在「ロングヘア」中表示長，整個詞指長髮。"],
  ["母に言い付けられた仕事をした。", "「仕事を言い付ける」（いいつける）是吩咐人做事，例句說做了母親交代的工作。「先生に言いつける」在告知別人過失的語境中，則表示向老師告狀。"],
  ["お金持ちが必ずしも幸せとは限らない。", "「必ずしも」（かならずしも）常和否定表達搭配。「必ずしも幸せとは限らない」表示未必幸福。"],
  ["そのレストランは評判が良い。", "「評判」（ひょうばん）指別人對某人或某事的評價，也可指流傳的名聲。「評判が良い」是口碑好，「悪い評判が広がる」則是負面評價傳開。"],
  ["ガソリンタンクが空になった。", "「ガソリンタンク」是裝汽油的油箱，「タンクが空になった」表示油箱空了。用於軍事時，「タンク」可指坦克車。"],
  ["問題の解決策を見つけた。", "「解決策」（かいけつさく）指解決問題的方法。例句表示找到了能解決問題的辦法。"],
  ["彼はチームのヘッドとして責任を負っている。", "「ヘッド」的譯法取決於搭配。「チームのヘッド」指團隊的負責人，「クラブのヘッド」在高爾夫球語境中則指球桿的桿頭。"],
  ["昨夜は御馳走になった。", "「御馳走になる」（ごちそうになる）表示接受別人的飲食招待。例句表示昨晚有人請客。"],
  ["ガソリンスタンドで給油した。", "「ガソリンスタンド」是加油站。單說「スタンド」時，依語境也可指球場看台、桌上的檯燈或販賣物品的攤位。"],
  ["彼は試験に失敗した。", "「試験に失敗する」（しけんにしっぱいする）表示考試沒考好。這句只說考試結果不理想，是否及格要看前後文。"],
  ["もう少しお時間をいただけますか。", "「お時間をいただけますか」是謙遜地請對方撥出時間。「料理がおいしくいただける」可指能享用料理。「その態度はいただけない」則是在說那種態度不妥。"],
  ["彼とは一度きり会っただけだ。", "「一度きり」是只有一次。「彼は出かけたきり帰ってこない」把「きり」接在動詞過去形後，表示出去後就一直沒回來。"],
  ["予算をオーバーしてしまった。", "「予算をオーバーする」是超出預算。「オーバーな身振り」則形容動作誇張。單說「オーバー」在服裝語境也可指外套或大衣。"],
  ["住民は詳しい説明を求めている。", "「説明を求める」（もとめる）是向對方要求說明。「答えを求める」是尋求答案。商店用語「店頭でお求めいただけます」則表示可在店面購買。"],
  ["素晴らしいショットを撮った。", "「ショットを撮る」在攝影語境指拍下照片或鏡頭。「バスケットボールのショット」則指投籃，「ウイスキーのショット」可指用小杯盛的一份威士忌。"],
  ["十を二で割ると五になる。", "「十を二で割る」（わる）是十除以二，結果是五。「皿を割る」是打破盤子，「酒を水で割る」是加水稀釋酒。「気温が零度を割る」則指氣溫跌破零度。"],
  ["気温はマイナス5度です。", "「マイナス５度」是零下五度。「マイナスの影響」是負面影響，「電池のマイナス極」指電池負極。檢查結果若以正負號記錄，負號可表示陰性。"],
  ["そのドラマの最終エピソードを見た。", "「最終エピソード」在影集語境指最後一集。「旅のエピソードを話す」則指分享旅途中發生的一段小故事或軼事。"],
  ["この景色にも見慣れてきた。", "「見慣れる」（みなれる）指因為常看到而逐漸習慣。「見慣れてきた」表示漸漸看慣了。"],
  ["この仕事はつらい。", "「つらい」可形容身體或心裡難受。「この仕事はつらい」是說這份工作很辛苦，「別れがつらい」則是因分離而感到難過。"],
  ["地震による被害は大きかった。", "「被害」（ひがい）在這裡指災害造成的損失。「地震による被害」表示地震造成的損害。"],
  ["ホワイトボードに書きました。", "「ボード」指板子。在「ホワイトボード」中指白板，而「掲示ボード」指供張貼公告的布告板。"],
  ["彼は自分の誤りを認めた。", "「誤りを認める」（みとめる）是承認錯誤。「申請を認める」是核准申請，「研究の価値を認める」是肯定研究的價值。「変化を認める」在觀察紀錄裡則指察覺變化。"],
  ["なくした鍵が見付かった。", "「見付かる」（みつかる）表示某樣東西被找到。例句用「鍵が」指出找到的是原先弄丟的鑰匙。"],
  ["彼は非常に忙しいです。", "「非常に」（ひじょうに）在這裡是程度副詞，表示「非常」。「非常に忙しい」表示非常忙。"],
  ["彼は私にコールしました。", "「私にコールする」在本句指打電話給我。「観客から選手へのコール」則指觀眾呼喊選手的名字，「コールオプション」在金融語境中指買權。"],
  ["彼の意見は批判された。", "「批判された」（ひはんされた）是「批判する」的被動形式。例句表示他的意見受到批評。"],
  ["会議で報告書を提出しました。", "「報告書」（ほうこくしょ）指書面報告。例句表示在會議上交了一份書面報告。"],
  ["アンケートにご協力ください。", "「アンケート」指用問卷進行的調查。「アンケートにご協力ください」是在請對方配合填寫問卷。"],
  ["画面にエラーメッセージが表示された。", "「画面に表示する」（ひょうじする）指讓文字或圖像出現在螢幕上。「原材料を表示する」則指在包裝等處標示原料。"],
  ["彼は新しい世界記録を樹立した。", "「世界記録を樹立する」（せかいきろくをじゅりつする）表示創下世界紀錄。例句表示他創下了新的世界紀錄。"],
  ["彼がもうすぐやってくる。", "「やってくる」在本句表示來到說話者這裡，「もうすぐ」說明即將發生。「このやり方でずっとやってきた」則用「～てくる」表示某種做法從過去持續到現在。"],
  ["子どもが暗い部屋を怖がる。", "「～がる」表示從舉止看出別人的感受。「怖がる」（こわがる）表示顯得害怕，例句說孩子怕昏暗的房間。"],
  ["それが彼が日本語を学び始めたきっかけだった。", "「きっかけ」在這裡指促使某人開始做一件事的契機。例句表示那件事促使他開始學日語。"],
  ["彼はボディビルディングをしています。", "「ボディビルディング」指透過訓練雕塑身體的健美運動。「車のボディ」則指車身，「ボディーブロー」是拳擊中打向軀幹的一擊。"],
  ["そのホテルにはメイドサービスがあります。", "「メイド」指女僕或女性家務服務人員。「メイドサービス」在旅館語境中指客房清潔等服務。"],
  ["どうしても彼に会いたい。", "「どうしても会いたい」表示無論如何都想見面，強調願望很強。搭配否定時，「どうしても思い出せない」則表示怎麼也想不起來。"],
  ["私たちのミッションは世界平和です。", "「私たちのミッション」在本句指團隊的使命。「ミッションを遂行する」指執行任務。汽車語境中的「ミッション」則可作「トランスミッション」的簡稱，指變速器等傳動裝置。"],
  ["彼女はダイヤの指輪をしています。", "「ダイヤ」在這裡是「ダイヤモンド」的簡稱。「ダイヤの指輪」指鑽戒。"],
  ["ホテルでダブルの部屋を予約しました。", "飯店的「ダブル」在本句指配有一張雙人床的房型。「ダブルのジャケット」可指雙排扣外套，球賽的「ダブルス」則指雙打。"],
  ["彼のパフォーマンスは素晴らしかった。", "「パフォーマンス」依情境可指表演或表現。「舞台でのパフォーマンス」是舞台演出，「機器のパフォーマンス」指設備效能。「ただのパフォーマンス」有時是在批評對方只是在作秀。"],
  ["この製品のサンプルをください。", "「製品のサンプル」指供試用或檢查的產品樣品。「食品サンプル」在餐廳的展示語境中，則指仿照餐點製成的模型。"],
  ["彼はレコーディングスタジオで働いている。", "「レコーディングスタジオ」是錄音室。「スタジオ」也可指攝影棚或工作室，例如「撮影スタジオ」。"],
  ["歯に食べ物が挟まった。", "「挟まる」（はさまる）在這裡指東西卡在兩物之間。例句表示食物卡在牙縫裡。"],
  ["オールシーズン使える服です。", "「オールシーズン」指全年、四季，所以這句表示這件衣服四季都能穿。口語的「オールする」則指熬夜到天亮。"],
  ["どの程度の日本語が話せますか？", "「どの程度」（どのていど）詢問能說到什麼程度。放在數量後面時，「程度」也可表示約數，例如「三十分程度」指大約三十分鐘。"],
  ["何もしないよりましだ。", "「～よりましだ」表示兩者比較起來，前者還好一些。「何もしないよりましだ」就是說這樣至少比什麼都不做好。「二割増し」中的同音「増し」則指增加兩成。"],
  ["マスメディアの影響は大きい。", "「マスメディア」指面向大眾的大眾傳播媒體。「マスプロダクション」裡的「マス」則表示大規模，整個詞指大量生產。"],
  ["ディズニーランドは楽しい場所です。", "「ディズニーランド」裡的「ランド」是樂園名稱的一部分。外來語複合詞中的「ランド」也可表示土地、區域或設施用地。"],
  ["今日は仕事がオフです。", "「仕事がオフ」在本句表示今天不用上班。「電源をオフにする」是關閉電源，「オフシーズン」指休賽期或淡季，「二割オフ」則指打八折。"],
  ["客間にお茶を運んだ。", "「客間」（きゃくま）指家中用來接待客人的房間。例句表示把茶端到會客室。"],
  ["二本の線をクロスさせて描いた。", "「クロスさせる」在本句指讓兩條線交叉。足球中的「クロスを上げる」則指從邊路把球傳向門前。"],
  ["そもそも、なぜこんなことになったのですか？", "「そもそも」在本句把問題拉回事情的起因。「そもそもその前提は正しいのか」則是把討論拉回最基本的前提，追問這個前提是否成立。"],
  ["彼の意見ははっきりしている。", "「はっきりしている」表示內容清楚明確。例句表示他的意見很明確。"],
  ["練習はまだまだ必要です。", "「まだまだ」強調目前的進度或程度距離某個目標還有一段差距。「練習はまだまだ必要です」表示還需要很多練習。「まだまだ時間がある」則表示時間還多得很。"],
  ["ボールはラインの外でアウトになった。", "球落在界線外時的「アウト」指出界。棒球說「打者がアウトになる」是打者出局。「それはアウトだ」在口語也可表示某種做法不被接受。"],
  ["新しい惑星が発見された。", "「発見された」（はっけんされた）是「発見する」的被動形式。例句表示一顆新行星被發現了。"],
  ["コンピュータウイルスに感染した。", "「ウイルス」指病毒。「コンピュータウイルス」是電腦病毒，「インフルエンザウイルス」則指流感病毒。"],
  ["彼の仕事は高い評価を受けました。", "「評価」（ひょうか）可指依標準評估，如「資産を評価する」是評估資產價值。「高い評価を受ける」則表明評價是正面的，本句是說他的工作獲得高度肯定。"],
  ["この本は読みにくい。", "「～にくい」接在動詞的連用形後，表示某個動作不容易做到。「読みにくい」就是難以閱讀。"],
  ["メニューに追加があります。", "「追加」（ついか）表示在原有內容上再加東西。這句表示菜單有新增品項。「資料を追加する」則指加入更多資料。"],
  ["一次試験にパスした。", "「試験にパスする」指通過考試。「入場パス」是入場證，「ボールをパスする」是傳球。遊戲中單說「パス」也可表示跳過自己的回合。"],
  ["そのニュースは全国で報道されました。", "「全国で」（ぜんこくで）指出報導的範圍是全國各地。例句表示這則消息在全國各地獲得報導。"],
  ["彼はチームをリードしている。", "「チームをリードする」指帶領團隊。「三点差でリードする」則是以三分之差領先。新聞或文章中的「リード文」指開頭概述重點的導語。"],
  ["新しいゲームが来月発売されます。", "「発売されます」（はつばいされます）是「発売する」的被動形式。例句表示新遊戲將在下個月開始販售。"],
  ["彼女はパートで働いている。", "「パートで働く」指以兼職形式工作，「パートの人」則可指兼職員工。「合唱のソプラノパート」中的「パート」指合唱的女高音聲部。"],
  ["秋の気配が感じられる。", "「気配」（けはい）指能察覺的跡象。「秋の気配」是秋意，「人の気配」表示感覺附近有人。金融語境中的「相場の気配」則指市場行情的動向。"],
  ["この仕事はとてもハードです。", "「ハードな仕事」是吃力或辛苦的工作。「ハードな素材」可指質地硬的材料。在電腦語境中，「ハード」可作為「ハードウェア」（硬體）或「ハードディスク」（硬碟）的簡稱。"],
  ["間も無く電車が参ります。", "「間も無く」（まもなく，也寫作「間もなく」）用於車站廣播時表示電車即將進站。「到着して間もなく雨が降った」則表示到達後沒過多久就下雨了。"],
  ["彼はその計画の一部を担当しています。", "「計画の一部」（けいかくのいちぶ）指計畫中的一部分。「資料を一部ください」中的「一部」則用來計算份數，表示請給我一份資料。"],
  ["この入場券はただでもらえる。", "「ただで」在本句指免費。「ただの紙」是普通的紙，「ただ見ていただけ」是僅僅看著。接在一句話後的「ただ、条件があります」則表示轉折，可譯為「不過，有個條件」。"],
  ["最終電車に乗り遅れました。", "「最終電車」（さいしゅうでんしゃ）指當天最後一班電車。談車班時，單說「最終」也可指末班車。「最終結果」則指最後得出的結果。"],
  ["この状況はやばい。", "「やばい」是口語表達。本句通常表示情況不妙或有危險。若看到精彩表演而說「この演奏、やばい」，則也可能在稱讚演奏很厲害，需看語氣與情境。"],
  ["彼はラブソングを歌った。", "「ラブソング」是情歌。網球計分時的「ラブ」則表示零分，例如「フィフティーン・ラブ」是十五比零。"],
  ["この説明は分かりやすい。", "「～やすい」接在動詞的連用形後。「分かりやすい」表示容易理解，「壊れやすい」表示容易壞，說的是某種情況容易發生。單獨寫成「安い」時，則可表示價格便宜。"],
  ["この映画はアクションが見どころだ。", "「アクション」在這裡指電影裡的動作場面。「アクションが見どころだ」表示動作場面是這部電影的看點。"],
  ["彼は子供っぽいところがある。", "接尾詞「っぽい」在「子供っぽい」中表示像小孩、有孩子氣。「白っぽい」表示顏色偏白，「忘れっぽい」則形容容易忘記事情。"],
  ["彼の言葉に温かさを感ずる。", "「温かさを感ずる」指感受到話語中的溫暖。「感ずる」是較書面的說法，現代常用「感じる」；說「人の親切に感じる」也可以表達受到感動。"],
  ["漢和辞典で漢字を調べた。", "「漢和辞典」是用日文解說漢字與漢字詞的字典。「漢和」也可合稱中國與日本，或指漢語與日語之間的對照。"],
  ["新しい切手が発行された。", "「発行」（はっこう）用於郵票、鈔票或護照時，可譯為發行或核發。「雑誌を発行する」則可譯為發行或出版雜誌。"],
  ["彼女は指に美しいリングをしていた。", "「リング」在這裡指戒指。「指にリングをしていた」表示手指上戴著戒指。"],
  ["スピードを落としてください。", "「スピードを落とす」表示降低速度。例句是在請對方減速。"],
  ["予想が外れてしまった。", "「予想が外れる」（はずれる）是預測落空。「ボタンが外れる」指鈕扣脫落，「候補から外れる」是退出候選範圍，「常識から外れる」則表示偏離一般常識。"],
  ["これは私にとってプラスになった。", "「プラスになる」在本句指帶來好處。計算時「プラス」可指加號或正數，電池上可指正極。檢驗結果用「＋」標示時，可表示陽性。"],
  ["各々の意見を聞いた。", "「各々」（おのおの）指各自、每一個。「各々の意見」是每個人的意見，「各々で確認する」則是各自確認。"],
  ["この辺りにコンビニはありますか？", "「この辺り」（このあたり）在問路時指這一帶。「来週の水曜辺り」指下週三前後，「京都辺りはどうですか」也可用來提出京都這個候選地點。"],
  ["フェイスパックを使った。", "「フェイスパック」在保養語境中指敷在臉上的面膜。「牛乳を１パック買う」是買一盒牛奶，「パック旅行」則指將交通或住宿等項目組合出售的套裝旅行。"],
  ["彼はコミックを読むのが好きだ。", "「コミックを読む」指看漫畫。形容表演時，「コミック」也可表示滑稽或喜劇風格，例如「コミックオペラ」。"],
  ["三日ごとに水をやってください。", "「ごと」接在表示時間的詞後面，表示固定間隔。「三日ごとに」就是每隔三天。"],
  ["何々という店だったか忘れた。", "「何々という店」的「何々」可暫代記不清的店名。「何々？」單獨說出時，也可用來追問剛才發生了什麼。"],
  ["何かトラブルがありましたか？", "「トラブル」在本句泛指麻煩或問題。「客とのトラブル」可能指與顧客的糾紛，「機械のトラブル」則可能指機器故障。"],
  ["果たしてこの計画は成功するのだろうか。", "「果たして」（はたして）用於這類疑問句時，可譯為「究竟」。例句是在問這項計畫究竟會不會成功。"],
  ["空がにわかに暗くなった。", "「にわかに暗くなる」表示突然變暗。「にわか雨」是突如其來的陣雨。「にわかファン」則可指因一時熱潮才加入的新粉絲，視語氣可能帶有揶揄。"],
  ["風邪でダウンして、一日中寝ていた。", "「風邪でダウンする」表示因感冒病倒。「サーバーがダウンする」指伺服器停止運作，「ダウンジャケット」的「ダウン」則是羽絨。"],
  ["コンサートホールで演奏会があった。", "「コンサートホール」是音樂廳。餐廳中的「ホール」則可指客人用餐與服務生接待的區域，例如「ホールスタッフ」指外場人員。"],
  ["彼は自由な時間が多い。", "「自由な時間」（じゆうなじかん）指可以自行安排的空閒時間。例句表示他有很多空閒時間。"],
  ["彼のランクは高い。", "「ランクが高い」表示他所處的級別較高。在競賽或評比中，「ランク」也可指排名。"],
  ["これは一般的に知られています。", "「一般的に知られている」表示廣為人知。「一般の人」可指普通民眾，「一般公開」中的「一般」則指面向公眾。"],
  ["しっかり勉強してください。", "「しっかり勉強する」是認真用功。「手すりをしっかり握る」是牢牢握住扶手，「しっかりした作り」則形容結構牢固。"],
  ["この書類のコピーをください。", "「書類のコピー」是文件的影本。「コピーする」可指複印文件或複製文字。「広告のコピー」中的「コピー」則指廣告文案。"],
  ["そのままにしておいてください。", "「そのままにしておく」是放著維持原狀。「荷物を受け取って、そのまま帰った」則表示領了行李後就直接回去。"],
  ["契約書にサインしてください。", "「サインする」在這裡指簽名。「契約書にサインしてください」表示請在合約上簽名。"],
  ["そんなアホなことをするな。", "「アホ」是口語，可指笨蛋。「アホなこと」則指蠢事。「するな」是語氣直接的禁止用法。"],
  ["サイトに登録しました。", "「登録する」（とうろくする）在網站的語境中指註冊。「サイトに登録しました」表示已在網站上完成註冊。"],
  ["私からご説明いたします。", "「いたす」是「する」的謙讓說法。「ご説明いたします」用來客氣地表示自己會向對方說明。"],
  ["アニメのグッズを集めている。", "「グッズ」在這裡指和動畫作品相關的周邊商品。例句表示正在收集動畫周邊。"],
  ["このデザインは新しいパターンです。", "「パターン」在設計語境中可以指圖樣或設計樣式。例句表示這是一種新的樣式。"],
  ["彼の計画は完全です。", "「完全」（かんぜん）在這裡形容計畫完備、沒有缺漏。例句表示他的計畫很周全。"],
  ["要望に応ずるのは難しい。", "「要望に応ずる」（ようぼうにおうずる）是答應或設法滿足要求，所以本句可譯為「很難滿足這項要求」。「呼びかけに応ずる」則指響應號召。"],
  ["とりあえず、これでいいです。", "「とりあえず」在這裡表示先作暫時決定。「とりあえず、これでいいです」表示目前先這樣就可以了。"],
  ["この本はなかなか面白い。", "後面接正面評價時，「なかなか面白い」表示相當有趣。搭配否定時，「なかなか来ない」表示等了很久還沒來。"],
  ["仕事はほぼ終わりました。", "「ほぼ終わった」表示幾乎做完，只剩一些工作。「ほぼ百人」則是估算人數，指大約一百人。"],
  ["コップを引っ繰り返してしまった。", "「引っ繰り返す」（ひっくりかえす）指把東西翻過來或弄倒。「コップを引っ繰り返した」在本句表示把杯子弄翻。「判決をひっくり返す」則是推翻判決。"],
  ["強い風で看板が引っ繰り返った。", "「看板が引っ繰り返った」表示招牌被風吹翻。形容人時可指往後摔倒；談事態或結果時也可比喻局勢逆轉。"],
  ["彼はバランス感覚が良い。", "「バランス感覚」（バランスかんかく）指感知並維持平衡的能力。例句表示他的平衡感很好。"],
  ["銀行口座から現金を引き出した。", "「現金を引き出す」（ひきだす）是提領現金。「箱から道具を引き出す」是從箱裡拿出工具，「生徒の力を引き出す」則指激發學生的能力。"],
  ["彼の説明に納得がいった。", "「説明に納得がいく」（なっとくがいく）表示理解說明的理由，並覺得說得通。「条件に納得する」則表示了解條件後覺得可以接受。"],
  ["髪をカットしてもらった。", "「髪をカットする」指剪頭髮。「予算をカットする」是刪減預算；影視製作的「一カット」則可指一個鏡頭。"],
  ["そのニュースはテレビで放送されました。", "「放送されました」（ほうそうされました）是「放送する」的被動形式。例句表示這則新聞已在電視上播出。"],
  ["彼はかなり背が高い。", "「かなり」在這裡是表示程度的副詞。「かなり背が高い」表示身高相當高。"],
  ["彼女は女子学生です。", "「女子学生」（じょしがくせい）由「女子」和「学生」組成，指女學生。"],
  ["私のボスはとても厳しい。", "「ボス」在這裡指自己的上司或老闆。例句表示說話者的上司很嚴格。"],
  ["さらに詳しく説明してください。", "「さらに」修飾「詳しく」，表示要說明得更詳細。「さらに、別の理由もある」中的「さらに」則表示「此外」。"],
  ["その歌は大ヒットした。", "「歌が大ヒットする」指歌曲大受歡迎。「ヒットを打つ」在棒球中指打出安打，「検索でヒットする」則表示搜尋到相符的結果。"],
  ["彼はテレビのインタビューを受けた。", "「インタビューを受ける」表示接受採訪。例句表示他接受了電視媒體的採訪。"],
  ["映画でキスシーンがあった。", "「キス」指親吻。「キスシーン」指電影或戲劇中的吻戲。"],
  ["良いタイミングで彼に会えた。", "「タイミング」指事情發生的時機。「良いタイミングで彼に会えた」表示剛好在合適的時機遇見了他。"],
  ["もしかしたら遅れるかもしれない。", "「もしかしたら」常與「かもしれない」搭配，表示有某種可能。例句表示說話者可能會遲到。"],
  ["うわさでは、彼は医者らしい。", "「医者らしい」在本句根據傳聞作推測，可譯為「他好像是醫師」。「子どもらしい笑顔」則形容笑容具有孩童特有的樣子。"],
  ["つい言ってしまった。", "「つい言ってしまった」表示一不留神就說出口了。「ついさっき」指就在剛才，「ついそこ」則指就在那附近。"],
  ["彼女はブランド品が好きだ。", "「ブランド品」（ブランドひん）在這裡指知名品牌的商品。例句表示她喜歡買或使用名牌商品。"],
  ["本のカバーが破れている。", "「本のカバー」指包覆書本的書衣或封套。「曲をカバーする」指翻唱或重新演奏他人的作品，「不足分をカバーする」則表示把缺少的部分補上。"],
  ["新しいキャンペーンが始まった。", "「キャンペーン」可指為特定目的發起的活動。「割引キャンペーン」是折扣促銷，「交通安全キャンペーン」則是交通安全宣導活動。"],
  ["そのままでいい。", "「そのままでいい」表示保持現狀就好。「目を閉じたまま待つ」是閉著眼睛等，「言われたままに書く」則是照著對方說的內容寫。"],
  ["結び目をほどいた。", "「ほどく」在這裡指把綁住的東西解開。「結び目をほどいた」表示把打好的結解開了。"],
  ["車のエンジンがかからない。", "「エンジンがかからない」表示引擎發動不了。例句指汽車的引擎無法啟動。"],
  ["初日はまごまごしていた。", "「まごまごする」表示因為不知道該怎麼辦而手忙腳亂。「初日はまごまごしていた」描述第一天不知所措的情況。"],
  ["彼は新しいシングルをリリースした。", "「シングルをリリースする」指發行單曲。住宿時「シングル」可指單人房或單人床，球賽的「シングルス」則指單打。"],
  ["あいつは変なやつだ。", "「やつ」是口語。在本句用於人，可譯為「那傢伙真奇怪」。用於物品時，「赤いやつを取って」則是請對方拿紅色的那個。"],
  ["フルマラソンを走った。", "「フル」在「フルマラソン」中表示全程。例句表示跑了全程馬拉松。"],
  ["彼は私の良い話し相手です。", "「話し相手」（はなしあいて）指聊天的對象。「対戦相手」是比賽對手，「交渉相手」則是談判的另一方。"],
  ["ガス漏れに注意してください。", "「ガス漏れ」在家用燃料語境中指瓦斯外洩。「有毒ガス」則指有毒的氣體，「ガスコンロ」是使用瓦斯的爐具。"],
  ["彼はマラソンレースで優勝した。", "「レース」在「マラソンレース」中指競速比賽。例句表示他在馬拉松比賽中拿了冠軍。"],
  ["そのアニメのキャラクターはとても人気がある。", "「アニメのキャラクター」指動畫角色。形容真人時，「明るいキャラクター」則可表示個性開朗。"],
  ["この小説は実話をベースにしている。", "「実話をベースにする」指以真實故事為基礎。「作戦のベース」可指行動基地，棒球的「ベース」則指壘包。"],
  ["床をぴかぴかに磨いた。", "「ぴかぴかに磨く」是擦拭到亮晶晶的。「ぴかぴかの靴」則可能形容鞋子擦得很亮，或形容鞋子嶄新。"],
  ["携帯電話のケースを買った。", "「携帯電話のケース」指手機殼。「このケースに当てはまる」則表示適用於這種情況。"],
  ["テレビのプログラムを見た。", "「テレビのプログラム」指電視節目，也可依語境指節目安排。「演奏会のプログラム」可指印好的節目表，「プログラムを書く」在資訊語境中則是寫程式。"],
  ["彼はなんて親切なんだろう。", "「なんて親切なんだろう」是感嘆對方真親切。「今、なんて言った？」的「なんて」則用於追問對方剛才說了什麼。"],
  ["このウェブサイトへのアクセスは簡単です。", "「アクセス」在這裡指連線到網站並開啟頁面。「ウェブサイトへのアクセスは簡単です」表示這個網站很容易連上。"],
  ["彼女は独自のスタイルを持っている。", "「スタイル」在這裡指個人的風格。「独自のスタイルを持っている」表示有自己獨特的風格。"],
  ["このWi-Fiはフリーです。", "例句的「フリー」表示無線網路免費提供。「フリーで働く」則是以自由工作者的身分工作，「フリーサイズ」指適合多種身形的單一尺碼。"],
  ["その店は午前10時にオープンします。", "搭配店家每日的營業時間時，「オープンする」表示開門營業。若談的是新店第一次開始營業，則可譯為開幕。「オープンな議論」則表示開放的討論。"],
  ["試験の結果はどうでしたか。", "「試験の結果」指考試的結果。「調べた結果」可用來帶出調查所得的發現；植物學的「結果」也可指結實。"],
  ["父は今、家におります。", "「家におります」在本句是對外人客氣地說自己的父親在家。部分方言用「おる」表示「在」，不帶謙讓語氣。「お待ちしております」裡的「おります」則用於表示正在等待。"],
  ["彼女ははきはきと答えた。", "「はきはきと」形容說話清楚、俐落。例句表示她清楚而乾脆地回答了。"],
  ["新しいソフトをインストールしました。", "「ソフトをインストールする」中的「ソフト」是「ソフトウェア」（軟體）的簡稱。「ソフトな肌触り」形容觸感柔軟，「ソフトクリーム」則是霜淇淋。"],
  ["その場合は、私に連絡してください。", "「その場合は」（そのばあいは）指前面所說的情況，可譯成「如果是這樣」。例句請對方在那種情況下與自己聯絡。"],
  ["ゲームをプレイする。", "「ゲームをプレイする」指玩遊戲。也能說「選手のプレイ」指運動表現，或「ギターをプレイする」指彈奏吉他。"],
  ["彼の今日の出来は素晴らしかった。", "「今日の出来」（きょうのでき）指今天的表現或成果。「よい出来の作品」形容作品完成得好，「今年は米の出来がよい」則形容今年稻米的收成好。"],
  ["列車のダイヤグラムを確認した。", "「ダイヤグラム」是用圖示呈現關係的圖表。「列車のダイヤグラム」用圖線呈現列車的運行時刻。"],
  ["レースのスタート地点。", "「スタート地点」（スタートちてん）指開始的地點。在競速比賽中，就是比賽的起點。"],
  ["そんなにどなるな。", "「どなる」指生氣時大聲吼叫。「そんなにどなるな」表示別那樣大吼，句尾的「な」表示禁止。"],
  ["この本のタイトルは何ですか？", "「本のタイトル」指書名，「映画のタイトル」指片名。競賽中的「タイトルを獲得する」則是贏得冠軍頭銜。"],
  ["そのほかは順調です。", "「そのほかは順調です」的「そのほか」指其餘事項。列舉時用「そのほかに」則可接著補充其他項目。"],
  ["このセットには何が含まれていますか？", "「このセット」在本句指成套販售或提供的物品。「髪をセットする」是整理頭髮，「タイマーをセットする」是設定計時器，網球中的「一セット」則指一盤。"],
  ["写真をSNSにアップした。", "「写真をアップする」指把照片上傳。「売上がアップする」指銷售額提升，「顔のアップ」則指臉部特寫。"],
  ["彼はクラスでトップの成績だ。", "「クラスでトップ」指在班上名列第一。「組織のトップ」可指組織的最高負責人，「サイトのトップ」則可指網站首頁。"],
  ["彼は家族のために一生懸命働いた。", "「家族のために」是為了家人。「日本語を学ぶために」表示目的，「大雨のために中止した」則表示原因，意思是因為大雨而取消。"],
  ["彼の思いが伝わった。", "「思い」（おもい）在本句指對方想傳達的心情或想法。「夢への思い」可指對夢想的憧憬，「故郷への思い」則可指對故鄉的思念。"],
  ["新しいキャラクターが登場しました。", "「登場する」（とうじょうする）在本句指新角色出現。「舞台に登場する」是登上舞台，「新製品が登場する」則表示新產品問世。"],
  ["週末にライブに行きます。", "「ライブに行く」通常指去看現場演出。「ライブ中継」則是現場直播，重點在內容於事件進行的同時播出。"],
  ["彼はビジネスマンとして海外で働いている。", "「ビジネスマン」的「マン」是外來語構詞成分，指從事商業工作的人。「カメラマン」的「マン」也用於人物名稱。"],
  ["彼女はファッションモデルです。", "「ファッションモデル」指展示服裝的模特兒。「模型のモデル」可指供仿製的原型，「数理モデル」是用數學描述現象的模型，「最新モデル」則可指產品的最新型號。"],
  ["彼の日本語のレベルは高いです。", "「日本語のレベル」指日語能力的水準。「騒音レベル」用來描述噪音的程度，測量儀器中的「レベル」則可指水準儀。"],
  ["彼はプロのサッカー選手です。", "「プロのサッカー選手」是職業足球選手。在「演奏会のプロ」這類語境中，「プロ」也可能是「プログラム」的簡稱。"],
  ["雨だ。そのため中止になった。", "「そのため」承接前面的原因，表示「因此」。在「そのために準備した」這類句子中，「そのために」也可表示「為此」。"],
  ["荷物をチェックしてください。", "「荷物をチェックする」在本句指檢查行李。「チェック柄」是格紋，「チェックを入れる」則可指在欄位裡打勾。"],
  ["ごめんください、どなたかいますか。", "到人家門前說「ごめんください」是在招呼裡面的人，意思接近「請問有人在嗎？」這個短語也可用作請對方原諒的客氣說法。"],
  ["さきおとといから雨だ。", "「さきおととい」指今天往前數三天。「さきおとといから」表示從大前天開始。"],
  ["彼は典型的な日本人です。", "「典型的な」（てんけいてきな）表示具有某一類事物的代表性特徵。例句用它來描述說話者眼中的典型日本人。"],
  ["花が一日でしぼんだ。", "「花がしぼむ」是花朵枯萎或縮起來。「風船がしぼむ」表示氣球洩了氣，「期待がしぼむ」則比喻期待逐漸消退。"],
  ["物語の展開が予想外だった。", "「物語の展開」（ものがたりのてんかい）指情節如何發展。數學中「式を展開する」指展開算式，電腦操作中的「圧縮ファイルを展開する」則是解壓縮檔案。"],
  ["待たせてすまない。", "「待たせてすまない」是在為讓人久等道歉。「すまないが、手を貸してくれ」則用在請託前，表示不好意思麻煩對方。"],
  ["そういえば、彼はどうした。", "「そういえば」表示「這麼說來」，用於聽到前面的話後想起另一件相關的事。例句接著問那個人後來怎麼了。"],
  ["おまたせしました、どうぞ。", "「おまたせしました」用來向等候的人打招呼。例句先說「讓您久等了」，再用「どうぞ」請對方接過物品或先行。"],
  ["電車の運行が一時停止した。", "「一時停止」（いちじていし）在本句指電車暫停行駛。「免許停止」是暫停駕駛執照效力，「支払いを停止する」則是停止付款。"],
  ["ご飯のお代わりをください。", "「お代わり」（おかわり）是在吃完或喝完一份後再要一份。「ご飯のお代わり」是再添一碗飯，「コーヒーのお代わり」則是續杯。訓練狗時也會說「お手、お代わり」，請牠在伸出一隻前腳後換另一隻。"],
  ["このサービスは無料で提供されています。", "「提供されています」（ていきょうされています）是被動形式，表示服務目前有供應。「無料で」表示無須付費。"],
  ["かしこまりました、すぐお持ちします。", "「かしこまりました」是服務場合常用的客氣回覆，表示明白並接受對方的要求。例句接著承諾馬上送來。"],
  ["ごくろうさまでした。", "「ごくろうさま」用來慰勞他人的辛勞，常見於上對下的場合。「ごくろうさまでした」是在工作告一段落後說「辛苦了」。"],
  ["こちらこそよろしく。", "「こちらこそ」用來回應對方的客套話，表示自己才該這麼說。「こちらこそよろしく」可譯為「我才要請您多指教」。"],
  ["この規則はすべての場合に適用される。", "「適用される」（てきようされる）是「適用する」的被動形式。「すべての場合に」指出這條規則適用的範圍。"],
  ["徹底した調査が必要だ。", "「徹底した調査」（てっていしたちょうさ）是全面而仔細的調查。「安全対策を徹底する」則表示確實貫徹安全措施。"],
  ["火で餅をあぶった。", "「餅をあぶる」是把年糕靠近火烤。「手を火にあぶる」則是把手靠近火取暖。"],
  ["年末はあわただしい。", "「年末はあわただしい」指年底事情多，忙得匆促。「あわただしく出ていく」則描述匆匆離開的樣子。"],
  ["ええと、名前は何でしたか。", "「ええと」是說話時用來停頓的語氣詞。例句中的說話者一邊回想，一邊問對方的名字。"],
  ["おおざっぱに計算してみた。", "「おおざっぱに計算する」表示先做粗略估算。「おおざっぱな仕事」在批評別人時，則可形容工作做得太粗疏。"],
  ["おかげさまで元気です。", "「おかげさまで」是回應對方關心時的客氣說法，可譯為「託您的福」。例句是在告訴對方自己很好。"],
  ["おさきに失礼します。", "「お先に失礼します」是比其他人早離開時的客氣說法，可譯為「我先走了」。「どうぞお先に」則是客氣地請對方先行。"],
  ["後ろから急におどかされた。", "「おどかされた」是「おどかす」的被動形式。「後ろから急におどかされた」表示突然被人從背後嚇了一跳。"],
  ["よろしくおねがいします。", "「おねがいします」用來客氣地提出請求。「よろしくおねがいします」可依場合譯為「麻煩您了」或「請多指教」。"],
  ["結果は努力に因る。", "「努力に因る」（よる）在本句指結果取決於努力。「事故は不注意による」則標明事故的成因。這兩類用法也常直接寫成假名「よる」。"],
  ["二人は同格に扱われる。", "「同格」（どうかく）在這裡指地位或等級相同。「同格に扱われる」表示被視為地位相當的人來對待。"],
  ["坊っちゃんはお元気ですか。", "「坊っちゃん」（ぼっちゃん）在本句是稱對方的兒子。「お坊っちゃん育ち」則可形容在優渥環境長大、較少接觸社會磨練的人。"],
  ["応接室でお待ちください。", "「応接」（おうせつ）在這裡指接待訪客。「応接室」（おうせつしつ）就是接待訪客的會客室。"],
  ["スープが煮えるまで待ってください。", "「煮える」（にえる）在這裡指湯煮好。「スープが煮えるまで待ってください」表示請等到湯煮好。"],
  ["あちらこちら探し回った。", "「あちらこちら探し回った」指四處尋找。「順序があちらこちらになる」一類說法則可描述順序紊亂。"],
  ["そのニュースは多くの人々の注目を集めた。", "「注目を集める」（ちゅうもくをあつめる）表示吸引關注。例句表示那則新聞吸引了許多人的注意。"],
  ["苦心の末に完成した。", "「苦心の末に」（くしんのすえに）表示費了很多心思之後。例句表示經過一番努力才終於完成。"],
  ["知らない人に話し掛けられた。", "「人に話し掛ける」（はなしかける）指主動開口和某人說話。例句的「話し掛けられた」是被動形，表示有陌生人來搭話。"],
  ["親孝行をしたいと思う。", "「親孝行」指以行動孝順父母。「祖父母孝行」等說法也可把「孝行」用於對其他長輩的照顧和回報。"],
  ["蛇口を捻って水を出した。", "「蛇口を捻る」（ひねる）是轉動水龍頭。「足首をひねる」可指扭傷腳踝。「知恵を絞って答えをひねり出す」則指費心構思出答案。"],
  ["名簿は五十音順に並んでいる。", "「五十音順」（ごじゅうおんじゅん）指依日語假名的順序排列。例句表示名冊上的名字按讀音排列。"],
  ["プロジェクトは最終段階に入った。", "「最終段階」（さいしゅうだんかい）指專案進程的最後一個階段。「難しさを三段階に分ける」則指把難度分成三級。"],
  ["部屋の明かりが点いた。", "「点く」（つく）是自動詞。「明かりが点く」表示燈亮了，「火が点く」則表示火被點燃、開始燃燒。"],
  ["叔母さんは料理が上手だ。", "「叔母さん」（おばさん）可指父母的妹妹，也可指父母弟弟的妻子。對應父母的姊姊或父母哥哥的妻子時，寫作同音的「伯母さん」。"],
  ["あの女の子は私の妹です。", "「女の子」（おんなのこ）通常指女孩。口語也可用來稱年輕女性。這句用「私の妹」交代說話者和對方的關係。"],
  ["この水は底まで透き通っている。", "「水が透き通る」（すきとおる）指水清澈透明，可以看見底部。「透き通った声」則形容聲音清澈。"],
  ["封筒に宛名を書いた。", "「宛名」（あてな）指收件人的姓名或名稱，也可連同地址指信封上的收件資訊。「封筒に」標出書寫的位置。"],
  ["彼の演技が観客の目を奪った。", "「目を奪う」（めをうばう）表示某人或某物特別吸引目光。例句表示他的演技吸引了觀眾的注意。"],
  ["ボールを転がして遊ぶ。", "「ボールを転がす」指讓球滾動。不動產語境的「土地を転がす」則可指買進土地後轉手牟利。"],
  ["この部屋は日当たりがいい。", "「日当たりがいい」（ひあたりがいい）表示採光好。「一日当たり」（いちにちあたり）則是按天計算，可譯為「每天」或「每一天」。"],
  ["広々とした部屋に住みたい。", "「広々とした」（ひろびろとした）用來形容空間開闊。「広々とした部屋」指寬敞的房間。"],
  ["外務大臣が記者会見を開いた。", "「大臣」（だいじん）在這裡指內閣閣員。「外務大臣」（がいむだいじん）是主管外交事務的部長。"],
  ["このジャムの正味は二百グラムだ。", "「正味」（しょうみ）在本句指扣除容器後的果醬淨重。「正味二時間」則指扣除休息等時間後，實際用掉兩個小時。"],
  ["彼女はいつも若々しい。", "「若々しい」（わかわかしい）在這裡形容一個人看起來年輕有活力。例句表示她總是顯得很年輕。"],
  ["浴衣には草履がよく似合います。", "「草履」（ぞうり）指日式夾腳便鞋。例句表示這種鞋和浴衣很相配。"],
  ["命に係わる問題だ。", "「命に係わる」（いのちにかかわる）表示關乎性命。「事件に関わる」也可表示和事件有關或涉入事件。"],
  ["彼は奥の部屋に引っ込んだ。", "「奥の部屋に引っ込む」（ひっこむ）指退到裡面的房間。「道路から引っ込んだ家」是離道路往裡退一些的房子，「表舞台から引っ込む」則是退出公眾視野。"],
  ["漸く仕事が終わった。", "「漸く」（ようやく，常寫成假名）在本句表示經過一段時間或努力，工作終於做完。「ようやく間に合った」也可指好不容易趕上，時間幾乎不夠。"],
  ["彼は社長の代理として会議に出席した。", "「代理として」（だいりとして）表示以代理人的身分做某件事。例句表示他代表社長出席會議。"],
  ["彼の意見は大いに参考になった。", "「大いに」（おおいに）在這裡強調幫助的程度。「大いに参考になった」表示非常有參考價值。"],
  ["長年の努力が実った。", "「実る」（みのる）在這裡比喻努力有了成果。「長年の努力が実った」表示多年的努力終於有了成果。"],
  ["明日は祭日なので学校は休みだ。", "「祭日なので学校は休みだ」的「祭日」是口語中對節日假期的說法。日本現行制度的正式名稱為「国民の祝日」；歷史語境的「祭日」也可指舉行祭典的日子。"],
  ["彼は大きな溜息をついた。", "「溜息をつく」（ためいきをつく）是「嘆氣」的常見搭配。「大きな溜息をついた」表示重重嘆了一口氣。"],
  ["お客様の要望に対応します。", "「要望に対応する」（たいおうする）指處理或因應需求。「番号に対応する項目」指和該編號相對應的項目，「新しい機種に対応する」則表示支援新的機型。"],
  ["彼は落ち着いて振る舞った。", "「振る舞う」（ふるまう）在這裡指一個人表現出來的舉止。「落ち着いて振る舞った」表示舉止沉著。"],
  ["この布は目が粗い。", "「目が粗い」在這裡指布料的織紋較疏。「粒が粗い」則指顆粒較大，例如粗粒砂糖。"],
  ["彼との出会いは私の人生を変えた。", "「彼との出会い」（であい）指與他的相遇，也可特指兩人第一次見面。「本との出会い」則比喻第一次接觸到某本書。"],
  ["着物に足袋を合わせた。", "「足袋」（たび）是日本傳統的分趾襪，拇趾與其他腳趾分開。例句表示用足袋搭配和服。"],
  ["子どもに習字を習わせている。", "「習字」（しゅうじ）指練習把字寫得端正。「子どもに習字を習わせている」表示讓孩子學習寫字。"],
  ["大層お世話になりました。", "「大層お世話になりました」的「大層」是副詞，用來加強感謝的程度。「大層な話」也可以形容說法煞有介事或誇張。"],
  ["彼は警察に逮捕された。", "「逮捕された」（たいほされた）是「逮捕する」的被動形式。「警察に」指出執行逮捕的是警方。"],
  ["英和辞典で単語を調べた。", "「英和」（えいわ）指從英語到日語。「英和辞典」用日語解釋英語詞彙，單說「英和」有時也指這類辭典。"],
  ["急いだら却って遅くなった。", "「却って」（かえって）表示結果和原先期待的方向相反。例句表示本來想趕快完成，結果反而更慢了。"],
  ["彼の存在は大きい。", "「存在が大きい」（そんざいがおおきい）在這裡形容一個人的影響或重要性很大。例句表示他舉足輕重。"],
  ["何分初心者ですので、ご指導をお願いします。", "「何分」（なにぶん）在本句用於交代原因，意思是「因為我畢竟是初學者，還請您指導」。「何分よろしくお願いします」則是客氣地請對方多關照。"],
  ["多少の遅れは許容範囲です。", "「多少の遅れ」（たしょうのおくれ）指少許延遲。「金額の多少」則指金額的多寡，重點是數量的大小。"],
  ["そこから問題が生ずる。", "「問題が生ずる」（しょうずる）表示問題發生。「そこから」指出問題從何而來。「生ずる」也可寫作意思相近的「生じる」。"],
  ["目上の人には敬語を使う。", "「目上」（めうえ）指職位、身分或輩分比自己高。「目上の人には」指出敬語所用的對象。"],
  ["箱の容積を計算した。", "「容積」（ようせき）在這裡指箱子內部可容納東西的空間大小。「箱の容積を計算した」表示算出了箱子的容積。"],
  ["領事館で手続きをした。", "「領事館」（りょうじかん）是領事辦公、提供領事服務的機構。例句表示在領事館辦理了手續。"],
  ["試験に落第してしまった。", "「試験に落第する」（らくだいする）指考試沒通過。「衛生面では落第だ」則可用來批評衛生狀況達不到標準。"],
  ["彼はすぐ職場に溶け込んだ。", "「溶け込む」（とけこむ）在這裡比喻融入新環境。「職場に溶け込んだ」表示適應了職場環境，成為其中的一員。"],
  ["その町は造船業で栄えている。", "「造船業」（ぞうせんぎょう）指建造船舶的產業。例句表示那個城鎮靠造船業而繁榮。"],
  ["甚だしい誤解があった。", "「甚だしい」（はなはだしい）在這裡強調程度之深。「甚だしい誤解」指非常嚴重的誤解。"],
  ["二本の線が直角に交わる。", "「直角」（ちょっかく）指九十度的角。「直角に交わる」表示兩條線相交成九十度。"],
  ["初詣にお参りに行きました。", "「お参り」（おまいり）表示到神社、寺院參拜，也可用於掃墓，如「お墓参り」。「初詣」指新年第一次參拜。"],
  ["いい方法を思い付いた。", "「いい方法を思い付く」（おもいつく）指想到一個好辦法。想找例子時說「適当な例が思い付かない」，表示一時想不到合適的例子。"],
  ["ケーキを四等分した。", "「四等分する」（よんとうぶんする）指分成四個大小相同的部分。例句表示把蛋糕分成四等分。"],
  ["彼は相当な努力をした。", "「相当な努力」（そうとうなどりょく）指付出很大的努力。「１時間分に相当する」則表示相當於一小時的量，「規模に相当する設備」可指與規模相稱的設備。"],
  ["帰り道で夕立に遭った。", "「夕立」（ゆうだち）指夏季午後到傍晚突然下起的陣雨，雨勢常很強。例句是說回家路上碰到了這種陣雨。"],
  ["マッチを擦って火をつけた。", "「擦る」在「マッチを擦る」常讀作「する」，意思是擦火柴。「手で目を擦る」則常讀作「こする」，是用手揉眼睛。"],
  ["この道は凸凹している。", "「凸凹している」（でこぼこしている）形容路面高低不平。「成績に凸凹がある」則可比喻各項成績高低不一。"],
  ["彼は耳元で何かを囁いた。", "「耳元で囁く」（ささやく）指在耳邊低聲說話。「引退がささやかれている」則表示有人私下傳說某人可能引退。"],
  ["為すべきことはまだ多い。", "「為す」（なす）在這裡指做某件事。「為すべきこと」表示應該做的事。"],
  ["バスは次の停留所で止まります。", "「停留所」（ていりゅうじょ）是公車或路面電車的停靠站。「で」標出車輛停靠的地點。"],
  ["専制的なやり方に反対する。", "「専制的な」（せんせいてきな）在這裡形容一意掌控、不讓他人參與決定的做法。例句表示反對這種專制的做法。"],
  ["目下の者にも礼儀を守る。", "「目下」（めした）指地位或輩分比自己低的人。「目下の者にも」表示即使對方地位或輩分較低，也要以禮相待。"],
  ["話が本題から逸れてしまった。", "「本題から逸れる」（それる）指話題偏離重點。「進路から逸れる」則用於方向或路線，表示偏離原來的路徑。"],
  ["六月の初旬に帰ります。", "「初旬」（しょじゅん）指一個月的前十天。「六月の初旬に」表示在六月上旬。"],
  ["彼は全身で喜びを表現した。", "「全身」（ぜんしん）指整個身體。「全身で喜びを表現した」表示用整個身體表達喜悅。"],
  ["この計画は全般的に良い。", "「全般的に」（ぜんぱんてきに）表示從整體來看。例句表示整體來看，這項計畫不錯。"],
  ["電話の応対は丁寧に。", "「応対」（おうたい）在這裡指接聽電話時的應對。「電話の応対は丁寧に」是在提醒接電話時要有禮貌。"],
  ["彼の狙いは世界平和です。", "「狙い」（ねらい）在這裡指想達成的目標。例句表示他的目標是世界和平。"],
  ["明け方に雨がやんだ。", "「明け方」（あけがた）是表示時間的名詞，指天快亮的時候。「明け方に雨がやんだ」表示雨在拂曉時停了。"],
  ["放課後、教室で自習した。", "「自習」（じしゅう）指自己讀書或練習。在學校也可指老師不授課、由學生自行學習，例如「先生が来られず、この時間は自習になった」。"],
  ["彼は労働組合のメンバーです。", "「組合」（くみあい）指成員為共同目的組成的團體。「労働組合」是勞工組成的工會，「協同組合」則是合作社。"],
  ["会議が長引いてしまった。", "「長引く」（ながびく）指事情持續得比預期久。「会議が長引いてしまった」表示會議拖得比預期久。"],
  ["色の組合せがいい。", "「碁」（ご）指圍棋。「碁を打つ」是「下圍棋」的固定搭配。"],
  ["痛みは幾分やわらいだ。", "「幾分やわらいだ」的「幾分」修飾程度，表示稍微減輕。「幾分か」也可指未指明的一部分或一些數量。"],
  ["この川の水は澄んでいる。", "「水が澄む」（すむ）表示水變清澈。「澄んだ声」是清亮的聲音，「心が澄む」則指心境變得平靜澄明。"],
  ["叔父さんの家に泊まった。", "「叔父さん」（おじさん）指父母的弟弟，或父母的妹妹的丈夫。若是父母的哥哥，通常寫「伯父さん」。只寫假名「おじさん」也可用於一般年長男性的稱呼。"],
  ["人は見掛けによらない。", "「見掛けによらない」表示無法單憑外表判斷。「見掛けの重さ」一類搭配中，「見掛け」也可表示表觀上、看起來呈現的量。"],
  ["同僚の送別会に出た。", "「送別会」（そうべつかい）由「送別」和「会」組成，指為即將離開的人舉辦的歡送聚會。"],
  ["二人で交替して運転した。", "「交替する」（こうたいする）指輪流做同一件事。「二人で交替して運転した」表示兩人輪流開車。"],
  ["こちらを御覧ください。", "「御覧ください」（ごらんください）是用尊敬語請對方看。「読んでご覧」則把「ご覧」接在動詞後，表示叫對方試著讀讀看。"],
  ["暖房で部屋を暖めた。", "「部屋を暖める」（あたためる）是使房間變暖和。「スープを温める」則常用同音的「温める」，指把湯加熱。"],
  ["井戸から水を汲んだ。", "「汲む」（くむ）在本句指從井裡打水。「お茶を汲む」是斟茶，「相手の気持ちを汲む」是體察對方的心情。「伝統を汲む」則指承襲傳統。"],
  ["今年の夏は蒸し暑い日が多い。", "「蒸し暑い」（むしあつい）形容天氣又熱又潮濕。「蒸し暑い日」就是悶熱的日子。"],
  ["合鍵を作製してもらった。", "「合鍵を作製する」指製作備用鑰匙。「作製」常見於實物加工，而「作成」常見於「書類を作成する」等編製文件的搭配。"],
  ["欲張りは身を滅ぼす。", "「欲張り」（よくばり）在這裡指貪心。「欲張りは身を滅ぼす」表示貪心會害了自己。"],
  ["今日の暑さは格別だ。", "「格別だ」（かくべつだ）指程度特別突出，本句說今天特別熱。「格別においしい」則用「格別に」修飾後面的評價，表示特別好吃。"],
  ["彼はそのプロジェクトの責任者です。", "「責任者」（せきにんしゃ）是負責某項工作的主管或承辦人。「責任を負う」表示承擔責任。「賠償責任」則指依法或依約負有賠償義務。"],
  ["障子を通して光が差し込む。", "「障子」（しょうじ）是日式的透光紙拉門。例句表示光線透過紙拉門照進來。"],
  ["秋が深まってきた。", "「深まる」（ふかまる）表示程度加深。「秋が深まる」是秋意漸濃，「理解が深まる」則指理解變得更深入。"],
  ["洗ったらシャツが縮んだ。", "「縮む」（ちぢむ）在這裡指衣服縮水。「洗ったらシャツが縮んだ」表示襯衫洗過後變小了。"],
  ["前の車を追い越した。", "「車を追い越す」（おいこす）在本句指超車。比喻用法如「成績で先輩を追い越す」，表示成績超過原先領先的前輩。"],
  ["新しいビルの設計図が完成した。", "「設計図」（せっけいず）由「設計」和「図」組成，指呈現設計內容的圖。例句表示新大樓的設計圖完成了。"],
  ["二軒は塀を隔てて建っている。", "「塀を隔てて」（へいをへだてて）指中間隔著一道牆。「十年の時を隔てて」則表示相隔十年，兩個事件之間隔的是時間。"],
  ["支払いを催促された。", "「催促された」（さいそくされた）是「催促する」的被動形式。「支払いを催促された」表示被催著付款。"],
  ["この数字が現実を物語る。", "「物語る」（ものがたる）在這裡指某項證據反映事實。例句表示這個數字反映了實際情況。"],
  ["野菜を柔らかくなるまで煮る。", "「煮る」（にる）在這裡指用熱水或湯汁把食材煮熟。「柔らかくなるまで」表示一直煮到蔬菜變軟。"],
  ["会は五時に閉会した。", "「閉会する」（へいかいする）指會議或活動正式結束。例句表示會議在五點散會。"],
  ["彼は強い精神力を持っている。", "「精神力」（せいしんりょく）指心理上的力量或毅力。「助け合いの精神」指彼此互助的態度，「法律の精神」則指法律背後的基本理念。"],
  ["ラジオに雑音が入る。", "「雑音」（ざつおん）在本句指收音機受到干擾時混入的聲音。一般也可指讓人分心的噪音。把周圍的意見形容成「雑音」時，則是在比喻那些意見像噪音一樣干擾判斷。"],
  ["差し支えなければ教えてください。", "「差し支え」（さしつかえ）在這裡指不便之處。「差し支えなければ」是客氣地說「如果方便的話」。"],
  ["彼は会社に損害賠償を請求した。", "「請求する」（せいきゅうする）在這裡是要求賠償。「会社に」標出向誰要求。「代金を請求する」則指向對方請款。"],
  ["母を一晩中看病した。", "「看病する」（かんびょうする）指照顧生病的人。例句表示照顧生病的母親一整晚。"],
  ["好機を逃がしてしまった。", "「逃がす」（にがす）在這裡指錯失機會。「好機を逃がしてしまった」表示錯過了大好機會。"],
  ["市民に節電を呼び掛けた。", "「呼び掛ける」（よびかける）在這裡指公開呼籲。「市民に」指出呼籲的對象，「節電を」指出希望市民節約用電。"],
  ["寝台列車で旅をした。", "「寝台」（しんだい）在「寝台列車」中指供旅客睡覺的臥鋪。例句表示搭臥鋪列車旅行。"],
  ["四字熟語を覚えている。", "「熟語」（じゅくご）可指組合漢字形成的詞，也可指意思約定俗成的慣用語。「四字熟語」是由四個漢字構成的固定詞語。"],
  ["昼食は十二時にとる。", "「とる」和餐名搭配時可以表示用餐。「昼食は十二時にとる」表示十二點吃午餐。"],
  ["受取をもらってください。", "「受取をもらう」的「受取」指收據，也可寫作「受取書」。「荷物の受け取り」則指出面收取包裹這件事。"],
  ["子供たちが校庭で遊んでいる。", "「校庭」（こうてい）是校內的戶外場地。這句指孩子們在學校操場上玩，「で」標示活動地點。"],
  ["彼女は絵の具を使って美しい絵を描いた。", "「絵の具」（えのぐ）指繪畫用的顏料。「絵の具を使って」表示使用顏料，後半句說她畫了一幅漂亮的畫。"],
  ["その会社はすごい勢いで成長している。", "「すごい勢いで成長する」（いきおい）指成長得又快又猛。「水の勢い」指水流的力道，「その場の勢いで引き受ける」則是受當下氣氛或一時衝動影響而答應。"],
  ["所々に花が咲いている。", "「所々」（ところどころ）在這裡指分散的幾個地方。「所々に花が咲いている」表示零星幾處開著花。"],
  ["重役会議が開かれた。", "「重役会議」（じゅうやくかいぎ）指由董事等高階主管參加的會議。「重役を務める」則是擔任重要職務。"],
  ["交渉は無事に成立した。", "「交渉が成立する」（せいりつする）表示談判順利達成協議。「政府が成立する」是政府組成，「条件を満たせば等式が成立する」則是等式在該條件下成立。"],
  ["最近この辺りは物騒だ。", "「物騒」（ぶっそう）在這裡形容地方不太安全，讓人擔心可能出事。例句表示最近這一帶不太平安。"],
  ["花の香りを嗅いだ。", "「嗅ぐ」（かぐ）指用鼻子聞氣味。例句表示聞了花的香氣。"],
  ["この電車は空港に直通する。", "「直通する」（ちょくつうする）指不必換車就能到達目的地。例句表示這班電車直達機場。"],
  ["講義を筆記した。", "「講義を筆記する」（ひっきする）是把講課內容記下來。「筆記試験」則指用書面作答的考試。"],
  ["このテーブルは四角い形をしている。", "「四角い」（しかくい）在本句形容桌子的外形有四個角。「四角」也可以是長方形。要明確表示四邊等長且四角皆為直角，可用「正方形」。"],
  ["確認を怠ってはいけない。", "「確認を怠る」指疏於確認。古文裡，「怠る」也可用於病情好轉的語境，與這句現代用法不同。"],
  ["その建物の建設費用は推定10億円だ。", "「推定１０億円」（すいていじゅうおくえん）表示估計是十億日圓。「事故の原因を推定する」則是依照現有資料推測事故原因。"],
  ["ボタンを縫い付けた。", "「縫い付ける」（ぬいつける）由「縫う」和「付ける」組成，指用針線把東西固定住。例句表示把鈕扣縫上了。"],
  ["散歩が朝の日課だ。", "「日課」（にっか）在這裡指每天固定做的事。「散歩が朝の日課だ」表示每天早上都會散步。"],
  ["このナイフは鈍い。", "「鈍い」（にぶい）在本句形容刀不鋒利。「反応が鈍い」是反應不靈敏，「動きが鈍い」是動作遲緩，「鈍い音」則指沉悶的聲響。"],
  ["手頃な値段の店を探す。", "「手頃な値段」（てごろなねだん）表示價格適中、容易負擔。「手頃な大きさ」則是大小合適，便於使用或攜帶。"],
  ["花瓶に花を挿した。", "「花瓶に花を挿す」（さす）是把花插進花瓶。「鍵を鍵穴に挿す」是把鑰匙插入鎖孔，「枝を土に挿す」則可指用枝條扦插。"],
  ["活字が小さくて読みにくい。", "「活字」（かつじ）在本句指印出的字，因為字太小而難讀。在印刷語境中也可指排版用的一枚枚字模。"],
  ["締切は月曜日です。", "「締切」（しめきり，也寫作「締め切り」）在本句指截止日期。「申し込みを締め切る」指停止接受報名，「窓を締め切る」則指把窗戶關緊。"],
  ["彼は神経が細かい。", "「神経が細かい」（しんけいがこまかい）形容人心思細膩，容易留意細節。"],
  ["主君のあだを討つ物語だ。", "「あだを討つ」（うつ）指替遭到殺害或傷害的人報仇。「敵を討つ」則可用於戰鬥，表示討伐敵人。"],
  ["警察が犯人を捕らえた。", "「犯人を捕らえる」（とらえる）是抓住犯人。表示理解時常寫作「捉える」，例如「意味を捉える」是掌握意思，「心を捉える」則是吸引人心。"],
  ["雨で洗濯物が湿ってしまった。", "「洗濯物が湿る」（しめる）指洗好的衣物變得潮濕。「湿った雰囲気」則可比喻氣氛低沉、沒有活力。"],
  ["ガラスが粉々に砕けた。", "「ガラスが砕ける」（くだける）指玻璃碎裂。「砕けた口調」則形容語氣輕鬆、少有拘束。「砕けた説明」也可指用較淺白的方式說明。"],
  ["この病院は大学に附属している。", "「大学に附属する」（ふぞくする）指隸屬於大學。「附属に通う」若在談就學，則可把「附属」當作「附属学校」的簡稱。"],
  ["鉛筆の先が尖っている。", "「先が尖っている」（とがっている）表示末端是尖的。「声が尖る」形容聲音或語氣變得尖銳。「尖ったデザイン」則可形容設計大膽、有鮮明個性。"],
  ["今日は波が荒い。", "「波が荒い」（なみがあらい）表示浪大、海面不平靜。「言葉遣いが荒い」形容說話粗魯，「金遣いが荒い」則形容花錢大手大腳。"],
  ["彼は強い信仰心を持っている。", "「信仰」（しんこう）在這裡指宗教信仰。「信仰心」（しんこうしん）指對信仰的虔誠之心。"],
  ["彼は信頼できる人だ。", "「信頼できる」（しんらいできる）指可以信任。「信頼できる人」就是值得信賴的人。"],
  ["サッカーの試合で審判が笛を吹いた。", "「審判」（しんぱん）搭配「笛を吹く」時，指吹哨的裁判員。「審判を下す」則指作出裁決，重點在判定這個行為。"],
  ["彼は不運が続いている。", "「不運」（ふうん）在這裡是名詞，指不好的運氣。「不運が続いている」表示接二連三遇到倒楣的事。"],
  ["屋根の修繕を頼んだ。", "「修繕」（しゅうぜん）指修理損壞的地方。「屋根の修繕を頼んだ」表示委託別人修理屋頂。"],
  ["至急ご連絡ください。", "「至急」（しきゅう）在這裡表示事情很急，請對方儘快採取行動。「至急ご連絡ください」就是請儘快聯絡。"],
  ["桜の並木が続いている。", "「並木」（なみき）指沿路成排的樹。「桜の並木が続いている」表示一排排櫻花樹沿路延伸。"],
  ["そんな仕事は御免だ。", "「そんな仕事は御免だ」（ごめんだ）表示不願接受那種工作，語氣直接。單說「ごめん」可表示道歉，「ごめんください」則常用於登門時打招呼。"],
  ["詳細についてはウェブサイトをご覧ください。", "「詳細について」（しょうさいについて）指關於更細的內容。「詳細な説明」中的「詳細な」則用來形容說明很仔細。"],
  ["パンの生地が膨らんだ。", "「膨らむ」（ふくらむ）在這裡指體積變大。「パンの生地が膨らんだ」表示做麵包的麵團膨脹起來了。"],
  ["雪で電話が不通になった。", "「不通」（ふつう）在這裡指通訊中斷。「電話が不通になった」表示電話線路不通了。"],
  ["長い文を短く区切った。", "「文を区切る」（くぎる）是把句子分成較短的部分，也可在閱讀時指按意思斷句。「部屋をカーテンで区切る」則是用簾子把房間分隔開。"],
  ["この方法を採ることにした。", "「方法を採る」（ほうほうをとる）指採用某種方法。「果実を採る」是摘取果實，「学生を採る」是招收學生，「慎重な態度を採る」則是採取謹慎的態度。"],
  ["出発を一日延ばした。", "「出発を一日延ばす」（のばす）是把出發日期延後一天。「締切を延ばす」是把截止日期往後移，「寿命を延ばす」則是使生命持續更久。"],
  ["彼には音楽の素質がある。", "「音楽の素質」指學習或表現音樂的先天潛質。談到人的「素質」時，也可指其本來的性情或體質。"],
  ["深く潜るほど水は冷たい。", "「深く潜る」（もぐる）在本句指潛到水下深處。「机の下に潜る」是鑽到桌子下方，談到躲避追查時也可用「地下に潜る」表示轉入地下藏身。"],
  ["議論の焦点は経済問題に移った。", "「議論の焦点」（ぎろんのしょうてん）指討論最關注的問題。光學上的「レンズの焦点」則指平行光經透鏡折射後會聚，或看起來像是從那裡發散的一點。"],
  ["車が電柱に衝突した。", "「衝突する」（しょうとつする）在這裡指物體撞上另一個物體。「電柱に衝突した」表示撞上了電線桿。"],
  ["りんごの皮を剥いた。", "「皮を剥く」（かわをむく）指把外皮去掉，例句是削掉蘋果皮。「牙をむく」則表示露出獠牙，也可比喻顯露敵意。"],
  ["毎日水筒に水を入れて持ち歩いています。", "「水筒」（すいとう）指便於攜帶的水壺。「水筒に水を入れる」表示把水裝進水壺。"],
  ["赤ん坊が床を這っている。", "「床を這う」（はう）在本句形容嬰兒在地板上爬行。「蛇が地面を這う」指蛇貼著地面滑行，「つるが地面を這う」則指藤蔓沿地面蔓延。"],
  ["挨拶に代えて、感謝の気持ちをお伝えします。", "「挨拶に代えて」（あいさつにかえて）表示用接下來要說的話代替一般致詞。「古い部品を新しい部品に換える」側重換成另一個部件，「選手を替える」則指更換上場的人。"],
  ["身分証明書を提示してください。", "「証明」（しょうめい）指證實某項事實。「身分証明書」（みぶんしょうめいしょ）是用來證明身分的文件。"],
  ["工事で道が塞がれている。", "「道を塞ぐ」（ふさぐ）指擋住道路，例句以被動形表示道路因施工而被堵住。「穴を塞ぐ」是把洞堵起來，「気が塞ぐ」則表示心情鬱悶。"],
  ["庭の花がよく匂う。", "「花が匂う」（におう）在本句指花散發香氣。形容發出令人不快的氣味時常用同音的「臭う」。口語的「何かにおう」有時也比喻事情有可疑的跡象。"],
  ["荷物が規定の重量を超過した。", "「超過する」（ちょうかする）表示超出規定的限度。「規定の重量を超過した」表示重量超過了規定上限。"],
  ["そんな意地悪をしないで。", "「意地悪」（いじわる）在「意地悪をする」中是名詞，指故意為難人的行為。例句表示請對方別那樣刁難人。"],
  ["なお、詳細は後日連絡します。", "句首的「なお」在本句用來補充說明，可譯為「另外」。「今なお続いている」指至今仍在持續，「なお一層」則表示程度更進一步。"],
  ["彼の提案は承認された。", "「承認された」（しょうにんされた）是被動形式，表示提案獲得核准。「新しい国家を承認する」中的「承認」則表示正式承認。"],
  ["話が脱線してしまった。", "「脱線する」（だっせんする）在這裡比喻談話偏離原本的主題。「話が脱線してしまった」表示談著談著就離題了。"],
  ["生活が不規則になった。", "「不規則」（ふきそく）在這裡指生活作息失去規律。「不規則になった」表示變得不規律。"],
  ["彼は社長に次ぐ立場だ。", "「社長に次ぐ」（しゃちょうにつぐ）表示位階僅次於社長。「事故に次ぐ事故」中的「次ぐ」則表示事故接連發生。"],
  ["彼は洒落を言って皆を笑わせた。", "「洒落を言う」（しゃれをいう）指說句俏皮話，有時會用到雙關。形容事物時，「洒落た店」則是有品味、裝潢別緻的店。"],
  ["折角来たのに休みだった。", "「折角」（せっかく）在本句表示特地來了一趟，卻遇到休息。「せっかくの機会」則指難得的機會。「せっかくのお誘いですが」也可在婉拒時表達對對方邀請的感謝。"],
  ["当時の記憶が蘇った。", "「蘇る」（よみがえる）在這裡指過往的記憶再度浮現。「当時の記憶が蘇った」表示又想起了當時的事。"],
  ["ご飯を炊く。", "「ご飯を炊く」（たく）是加水把米煮成飯。「豆を炊く」也可指把豆子煮熟。生火或燃燒枝葉時則用同音的「焚く」。"],
  ["この洗剤は中性です。", "「中性」（ちゅうせい）用於洗劑時，表示酸鹼性接近中性。「電気的に中性」則指整體沒有淨電荷。「中性名詞」是在有文法性別的語言中，屬於中性的名詞。"],
  ["彼は口が堅い。", "「口が堅い」（くちがかたい）是守口如瓶。「守りが堅い」則指防守牢靠。形容物體質地不軟，例如「硬い石」，也常用同音的「硬い」。"],
  ["彼は笑みを浮かべた。", "「笑みを浮かべる」（うかべる）指臉上露出笑容。「船を水に浮かべる」指讓船浮在水上，「故郷を思い浮かべる」則是讓故鄉的景象浮現在腦海。"],
  ["先生が答案を採点している。", "「採点する」（さいてんする）指按照答案或評分標準給分。例句表示老師正在批改考卷並評分。"],
  ["危うい所を助けられた。", "「危うい」（あやうい）在這裡形容情況危急。「危うい所を助けられた」表示在緊要關頭獲救。"],
  ["風が花びらを散らした。", "「花びらを散らす」（ちらす）指讓花瓣散開。「注意を散らす」是讓注意力分散，「書き散らす」則指不加整理地到處寫下文字。"],
  ["財布が空っぽになった。", "「空っぽ」（からっぽ）表示裡面空無一物。「財布が空っぽになった」表示錢包變空了。"],
  ["この箱はとても重たい。", "「重たい」（おもたい）在這裡指物體的重量大。例句表示這個箱子很重。"],
  ["少し休息を取りましょう。", "「休息を取る」（きゅうそくをとる）表示停下活動休息一下。例句是在提議稍微休息一會兒。"],
  ["その件は存じております。", "「存じる」（ぞんじる）在這裡是「知る」的謙讓說法。「その件は存じております」是客氣地表示自己知道那件事。"],
  ["後ろから声をかけて彼を驚かした。", "「驚かす」（おどろかす）在這裡指讓人嚇一跳。例句表示從背後出聲，嚇了他一跳。"],
  ["物凄い雨が降っている。", "「物凄い」（ものすごい）在本句表示程度驚人，形容雨下得非常大。「物凄い形相」則形容神情、臉色非常可怕。"],
  ["磁石の針は北を指す。", "「磁石」（じしゃく）在這裡指指南針。「磁石の針」就是指南針的指針。"],
  ["床にマットを敷いた。", "「床にマットを敷く」（しく）是把墊子鋪在地板上。「線路を敷く」是鋪設鐵路軌道，「戒厳令を敷く」則指施行戒嚴令。"],
  ["空港でドルを円に両替した。", "「両替する」（りょうがえする）在這裡指兌換貨幣。「ドルを円に両替した」表示把美元換成日圓。"],
  ["二本の道がここで交差する。", "「道が交差する」（こうさする）在本句指兩條道路在這裡相交。在遺傳學中，染色體之間交換對應片段的現象也可稱為「交差」。"],
  ["彼女は純粋な心の持ち主だ。", "「純粋な心」（じゅんすいなこころ）形容心地純真。「純粋な金」則形容金沒有混入其他物質。"],
  ["ご飯を茶碗によそう。", "「茶碗」（ちゃわん）搭配「ご飯をよそう」時指飯碗。「抹茶茶碗」則指用來盛抹茶的茶碗。"],
  ["子どもが道路に飛び出した。", "「道路に飛び出す」（とびだす）表示衝到馬路上。「棚から飛び出している」可指物品凸出架子的邊緣。「会社を飛び出す」則可形容毅然離開原本任職的公司。"],
  ["今回は聴解に重点を置く。", "「聴解に重点を置く」表示把主要心力放在聽力。「重点（じゅうてん）」也可指「々」等重複符號，舊時曾用作冒號的譯名。"],
  ["鉢に花を植えた。", "「鉢」（はち）可指較深的容器。在「鉢に花を植える」裡指花盆，「大鉢に料理を盛る」裡則指盛菜用的大碗。"],
  ["領収書をください。", "「領収」（りょうしゅう）指收到款項。「領収書」（りょうしゅうしょ）是證明已收款的單據，也就是收據。"],
  ["経験を重ねることで成長する。", "「重ねる」（かさねる）在「経験を重ねる」中指一次次累積經驗。例句表示人會隨著經驗增加而成長。"],
  ["線を垂直に引いてください。", "「垂直」（すいちょく）在沒另指基準線時可指直立方向。「線に対して垂直」則是相對於那條線成直角，方向取決於基準線。"],
  ["ご面倒をおかけして恐縮です。", "「恐縮です」（きょうしゅくです）在本句是為麻煩對方而感到過意不去。「お褒めにあずかり恐縮です」則用於受到稱讚時，謙遜地表示感謝。"],
  ["意味は文脈による。", "「文脈」（ぶんみゃく）可指文字的前後內容，例句表示意思取決於上下文。「歴史的な文脈」則指理解一件事時需要考慮的歷史背景。"],
  ["荷物を預かってもらった。", "「荷物を預かる」（あずかる）是替人暫時保管行李，使用「てもらう」時表示請人幫自己保管。「店を預かる」則可指受託管理店面。"],
  ["この商売は儲かるらしい。", "「儲かる」（もうかる）在這裡指有利可圖。「この商売は儲かるらしい」表示聽說這門生意能賺錢。"],
  ["彼は大学卒業後、すぐに就職した。", "「就職する」（しゅうしょくする）指找到工作並開始任職。例句表示他大學畢業後馬上就找到了工作。"],
  ["そう言ってもらえて有難い。", "「有難い」（ありがたい）在本句表示對對方那麼說心懷感謝。「ありがたい申し出」是讓人感激的提議，常因對方的提議能提供難得的幫助。"],
  ["新しい社長の就任式が行われた。", "「就任」（しゅうにん）指正式擔任某個職位。「就任式」（しゅうにんしき）是正式上任時舉行的典禮。"],
  ["冷たい水で目を覚ました。", "「目を覚ます」（めをさます）可以指醒過來或恢復清醒，例句說冷水讓人清醒了。「酔いを覚ます」則是醒酒、讓醉意消退。"],
  ["生意気な口をきくな。", "「生意気な口をきく」（なまいきなくちをきく）指用傲慢、沒禮貌的口氣說話。句尾的「な」表示禁止。"],
  ["人生は旅に例えられる。", "「例える」（たとえる）指用另一件事物來比喻。「旅に例えられる」表示可以用旅行來比喻。"],
  ["女房と買い物に行った。", "「女房と買い物に行った」中的「女房」是較口語的自稱妻子用語。古代宮廷語境裡，「女房」也可指在宮中服侍的女性。"],
  ["ご意見を承ります。", "「承る」（うけたまわる）在這裡是「聞く」的謙讓說法。「ご意見を承ります」表示願意聽取對方的意見。"],
  ["子どもが木の後ろに隠れた。", "「木の後ろに隠れる」（かくれる）指躲在樹後。「雲に隠れる」可指被雲遮住，「隠れた才能」則比喻尚未顯露或被發現的才能。"],
  ["瓶の栓を抜いた。", "「瓶の栓」（びんのせん）指瓶塞，所以「栓を抜く」是拔出瓶塞。「ガスの元栓を閉める」則是把瓦斯總閥關上。"],
  ["この物質は水と混ざる。", "「混ざる」（まざる）在這裡指兩種物質混合。「水と混ざる」表示與水混在一起。"],
  ["熱湯で手に火傷をした。", "「熱湯で手に火傷をした」指手被熱水燙傷。「やけど」可泛指熱水造成的燙傷或火焰等造成的燒傷。"],
  ["毎朝コーヒーを飲む。", "「コーヒーを飲む」（のむ）是喝咖啡，「薬を飲む」是服藥。「条件をのむ」指接受條件。「波にのまれる」是被海浪吞沒，「相手の気迫にのまれる」則比喻被對方的氣勢壓住。"],
  ["この電球の寿命は長い。", "「電球の寿命」（でんきゅうのじゅみょう）指電燈泡可以使用多久。「人の寿命」則指人的生命可持續多久。"],
  ["丁寧に包装してもらった。", "「包装する」（ほうそうする）指把物品包起來。「包装してもらった」表示請別人幫忙包裝。"],
  ["今年は米の収穫が多かった。", "「米の収穫」（こめのしゅうかく）指稻米收成。「今回の取材は収穫があった」則指這次採訪取得了有用的資訊或成果。"],
  ["彼は平和主義者です。", "「主義」（しゅぎ）在這裡指一套信念或原則。「平和主義者」（へいわしゅぎしゃ）指奉行和平主義的人。"],
  ["長い名前を略して呼ぶ。", "「名前を略す」（りゃくす）在本句指用簡稱稱呼較長的名字。「詳しい説明は略す」則指省略詳細說明。"],
  ["予算案が可決された。", "「可決された」（かけつされた）是「可決する」的被動形式。「予算案が可決された」表示預算案經表決獲得通過。"],
  ["声に不安が混じっていた。", "「声に不安が混じる」（まじる）指聲音中透出不安。「砂に小石が混じる」說的是小石子混在沙裡，「大人に交じる」則常寫作「交じる」，指加入一群大人。"],
  ["砂糖を水に溶かした。", "「砂糖を水に溶かす」（とかす）是讓糖溶解於水。「バターを溶かす」則是讓奶油融化。口語的「ギャンブルで貯金を溶かす」可指把存款賭輸、耗光。"],
  ["待合室で名前が呼ばれるのを待った。", "「待合室」（まちあいしつ）是等候室。「で」指出等候的地點，「名前が呼ばれる」表示等人叫到自己的名字。"],
  ["鏡に自分の姿を映した。", "「鏡に映す」（うつす）指讓影像反射在鏡面上。「映像をスクリーンに映す」則指把影像投映到銀幕上。"],
  ["実際、彼はとても忙しいです。", "句首的「実際」（じっさい）用來強調事實，可譯為「事實上」。「実際に使ってみる」是親自試用，「理論と実際」則是在對照理論和實際情況。"],
  ["計画は来週実施されます。", "「実施されます」（じっしされます）是「実施する」的被動形式。例句表示這項計畫會在下週實施。"],
  ["仕事を溜めないようにしている。", "「仕事を溜める」（ためる）在本句指讓沒做完的工作越積越多。「水を溜める」是蓄水，「家賃を溜める」則可指房租一直沒繳而累積欠款。"],
  ["二つの計画を並行して進める。", "「並行して進める」（へいこうしてすすめる）表示讓兩項計畫同時進行。「川と並行する道路」則是沿著河流方向延伸的道路。"],
  ["この機械は実用性が高い。", "「実用性」（じつようせい）由「実用」加上表示性質的「性」構成，指實際使用時的價值。例句表示這台機器很實用。"],
  ["彼が真っ先に手を挙げた。", "「真っ先に」（まっさきに）表示比其他人都早採取行動。例句表示他第一個舉手。"],
  ["彼は仕事の要領がいい。", "「要領がいい」（ようりょうがいい）形容人懂得掌握訣竅、做事有效率。「話の要領を得ない」則表示談話沒有切中要點。"],
  ["道具を乱暴に扱うな。", "「乱暴に扱う」（らんぼうにあつかう）指粗手粗腳地使用物品。「乱暴な言葉」是粗魯的用語，「人に乱暴する」則可表示對人動粗。"],
  ["この町は水産が盛んだ。", "「水産」（すいさん）在這句指漁業等水產業。「水産物」則指魚、貝等水產品。"],
  ["予算を大きく削った。", "「予算を削る」（けずる）指刪減預算。「木を削る」是削去木材的一部分，「原稿から一文を削る」則指刪掉原稿中的一句話。"],
  ["この辺りは地盤が弱い。", "「地盤が弱い」（じばんがよわい）在本句形容這一帶的土層不夠穩固。「選挙の地盤」則指候選人一向獲得支持的地區或支持基礎。"],
  ["抽象的な話は分かりにくい。", "「抽象的な」（ちゅうしょうてきな）表示內容偏向概念。「抽象的な話は分かりにくい」表示抽象的說法很難懂。"],
  ["妥協点を探ることにした。", "「妥協点を探る」（さぐる）表示試著找出雙方都能接受的方案。「手探りで鍵を探る」是用手摸索鑰匙，「原因を探る」則是調查、查找原因。"],
  ["校内放送で彼を呼び出した。", "「呼び出す」（よびだす）在這裡指叫某人到場。「校内放送で」交代通知方式是校內廣播。"],
  ["争いは醜いものだ。", "「醜い」（みにくい）在這裡形容爭鬥令人反感。「争いは醜いものだ」表示爭鬥的樣子很難看。"],
  ["経済危機により失業者が増えた。", "「失業」（しつぎょう）指失去工作。「失業者」（しつぎょうしゃ）指失去工作的人，例句說經濟危機使失業者增加。"],
  ["彼の夢が実現した。", "「実現する」（じつげんする）表示成為現實。例句用「夢が」標出成真的事物，意思是他的夢想成真了。"],
  ["夜行の列車で移動した。", "「夜行」（やこう）在這裡指夜間行駛。「夜行の列車」就是夜間行駛的列車。"],
  ["計画を実行する。", "「実行する」（じっこうする）在這裡指付諸實行。「計画を実行する」表示按照計畫採取行動。"],
  ["昼食を持参してください。", "「持参する」（じさんする）指自行攜帶物品到場。「昼食を持参してください」表示請自備午餐。"],
  ["父の肩を揉んだ。", "「肩を揉む」（もむ）是用手揉按肩膀。「布を揉む」指搓揉布料，「世間に揉まれる」則比喻在社會上經過各種磨練。"],
  ["あの大きな木が目印です。", "「目印」（めじるし）是幫人辨認位置或物品的標記。本句把大樹當作認路的地標。「荷物に目印をつける」則指在行李上加上容易辨認的記號。"],
  ["この新聞は只です。", "「只」（ただ）在本句表示不用付錢，也常寫成假名「ただ」。「ただの紙」是普通的紙，「ただ一人」是只有一人。句首的「ただ、条件がある」則表示「不過，有條件」。"],
  ["彼が先に言い出した。", "「彼が先に言い出した」表示他先開口提起那件事。「旅行に行こうと言い出した」則表示有人率先提出去旅行。"],
  ["雷の音が遠くに響いた。", "「雷の音が響く」（ひびく）表示雷聲傳到遠處。「言葉が心に響く」指話語讓人深受感動，「寝不足が仕事に響く」則表示睡眠不足影響工作表現。"],
  ["桜の花が散る。", "「花が散る」（ちる）形容花瓣掉落。「観客が散る」指觀眾往各處散去，「気が散る」則表示注意力分散。"],
  ["期日までに税金を納めた。", "「税金を納める」（おさめる）指繳稅。「品物を納める」在交易中可指交貨，「神社に品物を納める」則可指奉納。「仕事納め」指結束一年最後一段工作。"],
  ["彼女はスチュワーデスになった。", "「スチュワーデス」是女性空服員的舊稱。現今常用「客室乗務員」（きゃくしつじょうむいん）稱呼空服員。"],
  ["空には無数の星が見えた。", "「無数」（むすう）表示多得數不清。「無数の星」就是數不清的星星。"],
  ["二人は一位を争っている。", "「一位を争う」（あらそう）指競爭第一名。「相続をめぐって争う」表示因繼承發生爭執，「証拠の信用性を争う」則指對證據的可信性提出爭議。"],
  ["作業にかかる時間を計る。", "「時間を計る」（はかる）指計時。「身長を測る」指測量身高，「荷物の重さを量る」是秤行李的重量，三個動詞讀音相同，常依測量對象選擇寫法。"],
  ["捨てるには惜しい品だ。", "「捨てるには惜しい」（おしい）表示東西仍有價值，丟掉很可惜。「惜しくも敗れた」表示差一點就能贏，結果仍落敗。"],
  ["その国は独裁者の支配下にある。", "「支配下にある」（しはいかにある）表示處於他人的統治或控制之下。「不安に支配される」則比喻被不安的情緒左右。"],
  ["この虫は全国に分布している。", "「分布する」（ぶんぷする）在這裡指某種生物分布於一定範圍。「全国に分布している」表示全國各地都有這種蟲。"],
  ["こちらを向いてください。", "「こちらを向く」（むく）是把臉或身體轉向這邊。「窓が南を向く」描述窗戶的朝向，「この仕事に向いている」則表示某人適合做這份工作。"],
  ["彼は頭が固い。", "「頭が固い」（あたまがかたい）比喻想法不夠靈活。「結び目が固い」則形容繩結很緊，「決意が固い」表示下定決心、很難動搖。"],
  ["部屋に明かりをつける。", "「明かりをつける」指開燈或點燈，「窓から明かりが差す」的「明かり」則指光線。舊式用語也可指證明清白的證據。"],
  ["傷口を消毒した。", "「消毒する」（しょうどくする）指進行消毒。「傷口を消毒した」表示已經替傷口消毒。"],
  ["扇風機の羽根を掃除した。", "「扇風機の羽根」（はね）指風扇的扇葉。「鳥の羽根」可以指鳥的羽毛，「バドミントンの羽根」則指用來擊打的羽球。"],
  ["予定が重なってしまった。", "「予定が重なる」（かさなる）在本句指行程撞期。「紙が重なる」表示紙張疊在一起，「不運が重なる」則表示接連遇到倒楣的事。"],
  ["彼は食べ物の好き嫌いが多い。", "「好き嫌い」（すききらい）指對事物有所偏好。「食べ物の好き嫌いが多い」表示很挑食。"],
  ["この部屋の定員は二十人だ。", "「定員」（ていいん）指依規定設定的人數。「部屋の定員」是可容納的人數，「募集の定員」則是預定招收的名額。"],
  ["庭の手入れをしている。", "「手入れ」（ていれ）在這裡指整理和照料。「庭の手入れをする」表示照料庭院。"],
  ["会社が潰れてしまった。", "「会社が潰れる」（つぶれる）在本句指公司倒閉。「箱が潰れる」是盒子被壓扁，「予定が潰れる」是計畫告吹，「酔い潰れる」則指喝醉到無法起身或行動。"],
  ["時間がたっぷりあるから、ゆっくり準備しよう。", "「時間がたっぷりある」表示時間很充裕。「たっぷり二週間かかる」中的「たっぷり」用來強調足足需要兩週。"],
  ["毎度ありがとうございます。", "「毎度」（まいど）指每次或屢次。「毎度ありがとうございます」是店家向顧客道謝的客套話，可譯為「感謝您一直以來的惠顧」。"],
  ["彼は重い責任を背負っている。", "「責任を背負う」（せおう）指承擔責任。「荷物を背負う」是把東西背在背上，「山を背負った村」則是背靠山的村落。"],
  ["彼の話は私を混乱させた。", "「混乱させる」（こんらんさせる）是使役形式，表示使人困惑。「私を」指出感到困惑的是說話者。"],
  ["みんなで乾杯をした。", "「乾杯する」（かんぱいする）通常指舉杯祝酒，例句表示大家一起舉杯。「乾杯！」是舉杯時的招呼。依場合也可表示把杯裡的酒喝完。"],
  ["女王が冠をかぶっている。", "「冠をかぶる」（かんむりをかぶる）在本句指戴上王冠。「草冠」指漢字上方的草字頭，「冠番組」則可指以主持人等人的名字冠名的節目。"],
  ["間接的な表現を使った。", "「間接」（かんせつ）加上「的な」修飾「表現」，指沒有直接說出意思的表達方式。"],
  ["二人でよく話し合った。", "「話し合う」（はなしあう）表示彼此討論。「二人で」指出是兩個人一起商量。"],
  ["この飛行機は高度1万メートルを飛行しています。", "「高度」（こうど）在這裡是名詞，指飛行的高度。「高度1万メートル」表示飛機在一萬公尺的高度飛行。"],
  ["公園に彫刻が置かれている。", "「彫刻」（ちょうこく）在這裡是擺在公園裡的雕塑作品。「木を彫刻する」則表示在木頭上雕刻。"],
  ["店に防犯カメラを付けた。", "「防犯」（ぼうはん）指預防犯罪。「防犯カメラ」指為了防止犯罪而安裝的監視器。"],
  ["祖母に料理を教わった。", "「教わる」（おそわる）表示向別人學習。「祖母に」指出教的人是祖母，「料理を」指出學的是做菜。"],
  ["犯人に心当たりはない。", "「心当たり」（こころあたり）指心裡想得到的人或線索。這句表示說話者想不出誰可能是犯人。"],
  ["航空券を予約しました。", "「航空券」（こうくうけん）指機票。「航空」（こうくう）在這個複合詞中指航空運輸。"],
  ["棚を水平に取り付けた。", "「水平に」（すいへいに）修飾「取り付けた」，表示安裝時讓架子保持水平。"],
  ["紙を三角に折った。", "「三角に」（さんかくに）指出摺完後的形狀。「紙を三角に折る」就是把紙摺成三角形。"],
  ["無理をすると体調を崩す。", "「体調を崩す」（くずす）指健康狀況變差。「予定を崩す」是打亂原來的安排，「千円札を崩す」則是把千圓鈔票換成較小面額的錢。"],
  ["バスは十分間隔で来る。", "「十分間隔」（じゅっぷんかんかく）表示每隔十分鐘一班。「椅子の間隔」則指椅子之間的距離。"],
  ["浜辺で貝を拾った。", "「貝」（かい）在海邊撿拾的語境中指貝殼。"],
  ["彼は客に丁寧に接する。", "「客に接する」（せっする）在本句指與客人打交道。「海に接する地域」指臨海地區，「訃報に接する」則指得知某人去世的消息。"],
  ["油断は禁物だ。", "「油断」（ゆだん）指放鬆警戒而大意。「油断は禁物だ」表示切忌大意。"],
  ["映画は来月公開されます。", "「映画が公開される」表示電影對外上映。「資料を公開する」則表示讓大眾能查閱資料。"],
  ["本にしおりを挟んだ。", "「しおりを挟む」（はさむ）是把書籤夾進書頁。「戸に指を挟む」是手指被門夾住，「休憩を挟む」則是安排一段休息時間。"],
  ["この道路は東西に延びている。", "「東西に延びる」指沿東西方向延伸。「東西の文化」可指東方與西方文化；傳統表演的開場口號「東西、東西」用來招呼觀眾注意。"],
  ["夜間の外出は禁止だ。", "「夜間」（やかん）指夜晚這段時間。「夜間の外出」表示夜間出門。"],
  ["荷物を車に積んだ。", "「荷物を車に積む」（つむ）是把行李裝上車。「箱を積む」可指把箱子疊起來，「経験を積む」則指累積經驗。"],
  ["危ないので手を離さないで。", "「手を離す」（てをはなす）表示放開手。「離さないで」是請對方別放手。"],
  ["絵が斜めに掛かっている。", "「斜め」（ななめ）在本句指畫掛歪了。「機嫌が斜め」是慣用說法，表示心情不好。"],
  ["船を岸に着けた。", "「船を岸に着ける」（つける）指把船靠到岸邊。「身に着ける」可指穿戴在身上，像是佩戴飾品，也可比喻學會技能，這時也常寫「身につける」。"],
  ["警備が厳重な建物です。", "「厳重」（げんじゅう）在這裡形容警備嚴密。「警備が厳重な」修飾「建物」，表示這棟建築物戒備森嚴。"],
  ["時間を潰すために本を読んだ。", "「時間を潰す」（つぶす）指找事消磨時間。「缶を潰す」是把罐子壓扁，「会社を潰す」則是使公司倒閉。"],
  ["カメラを花に向けた。", "「カメラを花に向ける」（むける）指把相機對準花。「現地に調査員を向ける」可表示派調查人員前往現場，「試験に向けて準備する」則是為考試做準備。"],
  ["講座に申し込んだ。", "「講座に申し込む」（もうしこむ）指報名課程。「利用を申し込む」是申請使用服務，「結婚を申し込む」則指向人求婚。"],
  ["負けてみじめな気分だ。", "「みじめな」（みじめな）修飾「気分」，形容輸了之後心裡很不好受。"],
  ["仕事を一気にやっつけた。", "「仕事をやっつける」在本句是口語，指趕快把工作處理掉。「敵をやっつける」則指打敗對手。"],
  ["安いイコール悪いではない。", "「イコール」在本句是把兩件事畫上等號的比喻，全句表示便宜未必品質差。數學裡的「イコール」也指等號，念算式時可用來說「等於」。"],
  ["飛行機は大阪を経由して東京へ向かう。", "「経由する」（けいゆする）表示途中經過某處。「大阪を」是途中經過的地點，「東京へ」是前往的方向。"],
  ["鼻が詰まって苦しい。", "「鼻が詰まる」（つまる）指鼻子堵塞不通。「予定が詰まる」指行程排得很滿，「言葉に詰まる」則指一時不知道該說什麼。"],
  ["大粒の雨が降ってきた。", "「大粒の雨」（おおつぶのあめ）指雨滴很大。「米粒」中的「粒」指一顆顆米，「薬を二粒飲む」中的「粒」則用來計數。"],
  ["来月から病院で実習する。", "「実習する」（じっしゅうする）表示到實際場域練習所學。「病院で」指出實習地點是醫院。"],
  ["改札口はあちらです。", "「改札口」（かいさつぐち）指車站檢查車票或刷卡進出的閘口。這句是指示閘口的位置。"],
  ["コップから水がこぼれた。", "「水がこぼれる」指水從杯中灑出。「涙がこぼれる」是眼淚掉下來，「笑みがこぼれる」則表示不自覺地露出笑容。"],
  ["予備の鍵を持っている。", "「予備の鍵」（よびのかぎ）是備用鑰匙。「予備調査」則指正式調查開始前先做的調查，用於事前準備。"],
  ["彼は穏やかな性質だ。", "「性質」（せいしつ）在這裡指人的性情。「穏やかな性質」表示個性溫和。"],
  ["金銭的な問題で困っている。", "「金銭的な」（きんせんてきな）修飾「問題」，表示與金錢有關的問題。「で」指出感到困擾的原因。"],
  ["他人のことに首を突っ込むな。", "「首を突っ込む」（つっこむ）在本句比喻插手他人的事。「かばんに手を突っ込む」是把手伸進包裡，「細かい点に突っ込む」則指追問細節。"],
  ["会議の時間をずらした。", "「ずらす」在這裡表示把原訂的時間往前或往後調整。「会議の時間をずらす」就是改動會議時間。"],
  ["銀行で強盗事件があった。", "「強盗」（ごうとう）在「強盗事件」中指搶劫。「銀行で」指出事件發生在銀行。"],
  ["電話のダイヤルを回した。", "「ダイヤル」在這裡指電話上的撥號轉盤。「回す」表示轉動這個轉盤。"],
  ["彼はデパートで迷子になった。", "「迷子になる」（まいごになる）表示迷路或走失。「デパートで」指出迷路的地點是百貨公司。"],
  ["ぼろが出ないように気をつける。", "「ぼろが出る」是慣用說法，指原本想藏住的缺點或破綻露出來。「ぼろ」單用也可指破布或破舊衣服。"],
  ["雲行きが怪しくなってきた。", "「雲行きが怪しい」（あやしい）可形容天色變壞，也可比喻事情的走向不妙。「怪しい人物」則指行跡或身分可疑的人。"],
  ["彼は強引に自分の意見を通した。", "「強引に」（ごういんに）修飾「意見を通した」，表示他用強硬的方式讓自己的主張獲得採納。"],
  ["気温が急激に下がった。", "「急激に」（きゅうげきに）修飾「下がった」，表示氣溫在短時間內明顯下降。"],
  ["どちらの方面にお住まいですか。", "「方面」（ほうめん）在這裡指方向或一帶。「どちらの方面に」用來詢問對方住在哪一帶。"],
  ["十八歳未満は入れません。", "「未満」（みまん）接在數量後面，表示低於該數量。「十八歳未満」指還沒滿十八歲的人。"],
  ["太陽が地平線に沈む。", "「太陽が沈む」（しずむ）表示太陽落下地平線。「船が沈む」是船往水下沉，「気分が沈む」則表示心情消沉。"],
  ["彼らはその問題について議論した。", "「議論する」（ぎろんする）在這裡表示討論。「その問題について」指出討論的主題。"],
  ["緊張して胸がどきどきした。", "「どきどき」模擬心臟怦怦跳的感覺。「胸がどきどきした」表示心跳得很快。"],
  ["砂糖はお湯によく溶ける。", "「砂糖が溶ける」（とける）指砂糖溶於水。「氷が溶ける」是冰融化成水，兩句都用「が」來標示發生變化的東西。"],
  ["流石にプロは違う。", "「流石に」（さすがに）在本句表示表現符合對專業人士的期待，可譯為「不愧是專業的」。「さすがに今日は疲れた」則表示即便平時還撐得住，今天也確實累了。"],
  ["でたらめを言うな。", "「でたらめ」在這裡是名詞，指沒有根據的話。「でたらめを言うな」表示別胡說八道。"],
  ["彼は食べ物にやかましい。", "「食べ物にやかましい」表示對食物很挑剔。「外がやかましい」則是說外面太吵。"],
  ["彼女はコーラスに入っている。", "「コーラス」可指合唱。「コーラスに入る」在這裡是加入合唱團，「コーラスを練習する」則是練習合唱。"],
  ["電話又はメールでご連絡ください。", "「又は」（または）連接兩個可選的方式。「電話又はメールで」表示可用電話或電子郵件聯絡。"],
  ["調査の結果が公表された。", "「公表された」（こうひょうされた）是被動形式。「調査の結果が」指出被公開的是調查結果。"],
  ["彼は入口でうろうろしていた。", "「入口でうろうろしていた」表示在入口附近徘徊。形容坐立難安時，這個詞也能傳達當事人的慌亂或不知所措。"],
  ["彼は有名な映画監督です。", "「監督」（かんとく）在「映画監督」中指電影導演，也就是負責執導電影的人。"],
  ["時間を勘違いしていた。", "「時間を勘違いする」（じかんをかんちがいする）表示把時間弄錯了。「時間を」指出弄錯的內容。"],
  ["素直に謝ったほうがいい。", "「素直に謝る」（すなおにあやまる）是坦率認錯道歉。「素直に指示を聞く」是願意聽從指示，「素直な髪質」則可形容髮絲服貼、好整理。"],
  ["例を三つ挙げてください。", "「例を挙げる」（あげる）指列舉例子。「式を挙げる」指舉行典禮，「手を挙げる」是舉手，「成果を挙げる」則指取得成果。"],
  ["車が右に大きくカーブした。", "「カーブする」在這裡指車輛沿彎道轉彎。「右に」指出轉彎的方向。"],
  ["昼ご飯に蕎麦を食べた。", "「蕎麦」（そば）在本句因為搭配「食べる」指蕎麥麵。「蕎麦を栽培する」則指栽種蕎麥這種作物。「中華そば」是另一個固定名稱，通常指拉麵一類的麵食。"],
  ["彼の説明はあいまいだった。", "「説明があいまい」是說解釋含糊，讓人不易判斷具體意思。「記憶があいまい」則表示記不清楚，「あいまいな返事」可指沒有表明是否同意的答覆。"],
  ["彼は優勝を狙っている。", "「優勝を狙う」（ねらう）是以奪冠為目標。「的を狙う」指瞄準靶子，「留守を狙う」則指等人不在時找機會行動。"],
  ["地震の直後に停電した。", "「直後」（ちょくご）是時間名詞。「地震の直後に」指出停電發生在地震剛過的時候。"],
  ["荷物を隣の部屋に移す。", "「荷物を移す」（うつす）是把行李搬到別處。「計画を実行に移す」指開始落實計畫，「風邪をうつす」則是把感冒傳染給別人。"],
  ["ロケットが発射された。", "「ロケットが発射された」指火箭升空。「発射」也可指射出子彈；成人口語中有時用作「射精」的委婉說法。"],
  ["参加者は百人を超えた。", "「百人を超える」（こえる）表示人數多於一百人。「限界を超える」是超越限度。跨過地理界線或障礙時，常見同音寫法如「山を越える」。"],
  ["くれぐれもお体を大事に。", "「くれぐれも」加強叮囑的語氣，本句是請對方務必保重。「くれぐれも忘れないで」則是再三提醒對方千萬別忘記。"],
  ["私は国語の授業が好きです。", "「国語の授業」在日本學校指日語文課。談到不同國家時，「国語」也可指一國的語言。閱讀詞彙分類時，還可能指本國固有詞。"],
  ["元々そういう約束だった。", "「元々」（もともと）在這裡作副詞，表示從一開始就是那樣約定的。"],
  ["ごちそうさまでした。", "「ごちそうさまでした」是用餐後向準備餐點或請客的人道謝。看到別人親密地互動時，也有人用「ごちそうさま」開玩笑，表示已經看夠了兩人的甜蜜模樣。"],
  ["三時前後に着きます。", "「三時前後」（さんじぜんご）表示三點左右。「出発の前後」指離開前後的時間，「車の前後」則指車子的前方和後方。"],
  ["毎朝、階段を上って通勤している。", "「階段を上る」（のぼる）是走上階梯。「被害額が百万円に上る」表示損失金額達到一百萬日圓，「議題に上る」則指被提出來討論。"],
  ["会議は深夜まで続いた。", "「深夜」（しんや）是時間名詞。「深夜まで」表示會議一直持續到深夜。"],
  ["しつこく誘われて困った。", "「しつこく」修飾被動形式「誘われて」，表示對方一再邀約，讓說話者感到困擾。"],
  ["この場所は禁煙です。", "場所標示的「禁煙」（きんえん）指禁止吸菸。「禁煙して三年になる」則指已經戒菸三年。"],
  ["報告書を作成した。", "「作成する」（さくせいする）在這裡指撰寫文件。「報告書を作成する」就是撰寫報告。"],
  ["あれこれ考えすぎだ。", "「あれこれ」表示各種事情。「あれこれ考えすぎだ」是說東想西想，想得太多了。"],
  ["身長は百七十センチだ。", "「センチ」跟在身高數字後時，是「センチメートル」（公分）的簡稱。形容情緒時，「センチになる」則是變得多愁善感。"],
  ["イベントは来週開催されます。", "「開催されます」（かいさいされます）是被動形式，表示活動將於下週舉辦。"],
  ["いちいち文句を言うな。", "本句的「いちいち」強調每件小事都要抱怨，帶有不耐煩的語氣。「いちいち確認する」則可以只是指逐一確認。"],
  ["ドアは開放されている。", "「開放されている」（かいほうされている）描述門處於敞開的狀態。"],
  ["彼はストレスから解放された。", "「ストレスから解放される」（かいほうされる）指擺脫壓力。「メモリーを解放する」在電腦語境中則指釋出原先占用的記憶體。"],
  ["その車は改造されている。", "「車を改造する」（かいぞうする）指改動車輛原本的構造或裝備。「内閣改造」則指改組內閣。"],
  ["こんばんは、お邪魔します。", "「こんばんは」是晚上見面時的問候。「お邪魔します」是進入別人家時說的客套話。"],
  ["彼はその秘密を守った。", "「秘密を守る」（ひみつをまもる）表示保守祕密。「成功の秘密」則常指成功背後的原因或訣竅。"],
  ["そのバンドは昨年解散した。", "「バンドが解散する」（かいさんする）指樂團終止活動。「会議の後で解散する」表示到場的人散會，「衆議院の解散」則是國會制度中的用語。"],
  ["彼は会議で積極的に発言する。", "「積極的に」（せっきょくてきに）修飾「発言する」，表示他在會議上主動發言。"],
  ["この物語の続きが気になる。", "「物語の続き」（ものがたりのつづき）指接下來的故事內容。「続きは明日」可表示剩下的部分明天再做，「雨続き」則表示一連多天下雨。"],
  ["蚊に腕を刺された。", "「蚊に刺される」（さされる）指被蚊子叮咬。「針を刺す」則是把針扎進某物。例句用被動形表達手臂被叮。"],
  ["なんとか間に合った。", "「なんとか」在這裡表示經過一番努力，總算來得及。「間に合った」表示趕上了。"],
  ["試しに一度やってみよう。", "「試しに」（ためしに）表示姑且試試看。「一度」指出先試一次。"],
  ["少しも寒くない。", "「少しも」（すこしも）和否定的「寒くない」搭配，表示一點也不冷。"],
  ["一人一人に名札を配った。", "「一人一人」（ひとりひとり）指每一個人。「一人一人に」指出名牌發給每個人。"],
  ["彼は何でもよく知っている。", "「何でも」（なんでも）在這裡表示不論什麼事，都是他熟悉的。"],
  ["とんでもない、私の力ではありません。", "「とんでもない」在這裡用來謙虛地推辭稱讚，可譯為「哪裡的話」。"],
  ["冷蔵庫になにもない。", "「なにもない」（何もない）表示什麼都沒有。「何もそんなに急がなくてもいい」則是說完全沒必要那麼急。"],
  ["わがままを言わないで。", "「わがまま」在「わがままを言う」中是名詞，指任性的要求。這句是請對方別提這種要求。"],
  ["彼が怒るのも尤もだ。", "「尤もだ」（もっともだ）在本句表示他生氣是有道理的。用在句首的接續詞「もっとも」則用來補充但書，例如「行くつもりです。もっとも、雨なら中止です」表示打算去，不過下雨就取消。"],
  ["会議は予定より延長された。", "「会議を延長する」（えんちょうする）指讓會議開得更久。「線分を延長する」指沿原方向把線段拉長，球賽的「延長戦」則是正規時間結束後加賽。"],
  ["彼は英語を話せる一方、フランス語は苦手だ。", "「～一方」（いっぽう）在本句對照兩種情況，一方面會說英語，另一方面不擅長法語。「二つの案の一方」指兩個方案中的一個，「増える一方だ」則表示一直增加。"],
  ["もうすぐ夜が明ける。", "「夜が明ける」（あける）表示天亮，這句用「もうすぐ」說明即將發生。「梅雨が明ける」表示梅雨季結束，「年が明ける」則表示新的一年開始。"],
  ["答案を集めて先生に渡した。", "「答案」（とうあん）可指寫下的答覆或整份作答卷。「答案を集める」在本句是收齊學生交出的考卷。"],
  ["夕べは風が強かった。", "「夕べ」（ゆうべ）在本句指昨天晚上，表示昨晚風很大。「夏の夕べ」可指夏日傍晚，「音楽の夕べ」則可作晚間音樂活動的名稱。"],
  ["彼は待遇に不平を言った。", "「不平」（ふへい）是名詞，指不滿。「待遇に不平を言う」表示對受到的待遇發牢騷。"],
  ["昨シーズンの成績はよかった。", "「昨」（さく）在這裡接在「シーズン」前面，表示上一季。「昨シーズンの成績」就是上一季的成績。"],
  ["昼食はパンで済ませた。", "「パンで済ませる」（パンですませる）表示用麵包簡單解決一餐。「で」指出用什麼應付這頓午餐。"],
  ["猫が車に轢かれそうになった。", "「轢かれる」（ひかれる）是「轢く」的被動形式。「車に轢かれそうになった」表示差點被車輾到。"],
  ["高いというより、寧ろ安いほうだ。", "「寧ろ」（むしろ）在這裡修正前面的說法，表示「不如說還算便宜」。「むしろ家にいたい」則表示「我寧可待在家裡」。"],
  ["いつも大変お世話になっております。", "「お世話になっております」（せわ）是感謝對方平日關照的客套話。「子どもの世話をする」指照顧孩子，「お世話をかける」則表示勞煩對方照應。"],
  ["一瞬の出来事だった。", "「一瞬」（いっしゅん）是時間名詞，指極短的一段時間。「一瞬の出来事」表示一瞬間發生的事。"],
  ["予期しない問題が起きた。", "「予期しない」（よきしない）表示事先沒預料到，修飾後面的「問題」。"],
  ["今日の為替レートはいくらですか？", "「為替レート」（かわせレート）指貨幣兌換的匯率。這句是在問今天的匯率。"],
  ["システムに異常が見つかりました。", "「異常」（いじょう）在這裡是名詞，指不正常的情況。「異常が見つかる」表示發現了異常。"],
  ["駅の前で降ろしてください。", "「駅の前で降ろす」（おろす）是把乘客載到車站前，讓他在那裡下車。「荷物を車から降ろす」則指把貨物或行李卸下來。"],
  ["食べ物を粗末にしてはいけない。", "「粗末にする」（そまつにする）表示不珍惜。這句用來提醒人要珍惜食物。"],
  ["手伝ってくれて助かった。", "「助かる」（たすかる）在這裡表示得到幫助而減輕負擔。「手伝ってくれて助かった」是感謝對方幫了大忙。"],
  ["彼はようやく姿を現した。", "「姿を現す」（あらわす）指從看不見到現身。「本性を現す」指顯露本性。用文字、圖像或符號表達意思時，通常寫作「表す」。"],
  ["安易な解決策は避けるべきだ。", "「安易な」（あんいな）在這裡形容解決辦法考慮得不夠周全，帶有草率的意思。"],
  ["原因はまだ見当がつかない。", "「見当がつかない」（けんとうがつかない）表示還無法推測或毫無頭緒。「駅の見当をつける」可指抓出車站的大致方位，「百人見当」則是約一百人。"],
  ["彼は今年から新しい職に就いた。", "「職に就く」（つく）指開始擔任某職。「席に就く」是就座，「先生に就く」則指跟隨老師學習。"],
  ["この靴は幾らですか。", "「幾ら」（いくら）在本句是問價錢。「一万円いくら」表示一萬日圓再多一些。「いくら待っても来ない」則表示不管等多久都不來。"],
  ["この道を真っ直ぐ行ってください。", "「真っ直ぐ」（まっすぐ）在這裡作副詞，修飾「行く」，表示沿著這條路一直往前走。"],
  ["彼は苦しい状況にいる。", "「苦しい状況」（くるしいじょうきょう）指艱難的處境。「息が苦しい」表示呼吸難受，「家計が苦しい」指經濟拮据，「苦しい言い訳」則形容辯解很牽強。"],
  ["彼は五七五の句を作った。", "「句」（く）在「五七五の句」指按五、七、五音拍寫成的俳句。「文の中の句」則可以指句子中的詞組。"],
  ["同じ失敗を繰り返さないように気をつける。", "「繰り返す」（くりかえす）表示重複。「同じ失敗を繰り返さないように」表示為了避免再犯同樣的錯。"],
  ["夜中に目が覚めた。", "「夜中」（よなか）是時間名詞，指半夜。「夜中に」指出醒來的時間。"],
  ["彼らには共通の趣味があります。", "「共通の趣味」（きょうつうのしゅみ）指彼此都有的興趣。「両者に共通する点」則指兩方都具有的特點。"],
  ["コップに水を注いだ。", "「水を注ぐ」（そそぐ）是把水倒進容器裡。「力を注ぐ」則比喻投入心力，「川が海に注ぐ」是河水流入海中。"],
  ["料理の出来上がりを待つ。", "「出来上がり」（できあがり）在這裡指料理完成。「料理の出来上がりを待つ」表示等菜做好。"],
  ["審判が笛を鳴らした。", "「笛」（ふえ）在裁判的語境中指哨子。「笛を鳴らす」在這裡就是吹哨。"],
  ["彼は私の遅刻を許してくれた。", "「遅刻を許す」（ゆるす）在本句指原諒遲到。「入場を許す」則是允許入場。「気を許す」表示對人放下戒心。"],
  ["この問題を解くのに三十分かかった。", "「問題を解く」（とく）是解答問題。「ひもを解く」是解開繩子，「誤解を解く」是消除誤會，「任を解く」則是解除職務。"],
  ["給料は月末に支払われる。", "「月末」（げつまつ）是時間名詞，指月底。「月末に」指出發薪的時間。"],
  ["彼女の指摘はいつも鋭い。", "「鋭い」（するどい）在這裡形容她的見解敏銳，總能指出問題的關鍵。"],
  ["バスに酔って気分が悪い。", "「酔う」（よう）和交通工具搭配時表示暈車、暈船等。「バスに酔う」就是搭公車時暈車。"],
  ["彼女は花を一束買った。", "「束」（たば）在「一束」（ひとたば）中用來計算成束的物品。這句指她買了一束花。"],
  ["彼の話に疑問を感じた。", "「疑問」（ぎもん）在這裡是名詞。「彼の話に疑問を感じる」表示對他的說法有所懷疑。"],
  ["電車で席を譲った。", "「席を譲る」（ゆずる）指把座位讓給他人。「家を子に譲る」可指將房屋轉讓給子女，「要求の一部を譲る」則表示在協商中讓步。"],
  ["緑は草を連想させる。", "「連想させる」（れんそうさせる）表示讓人聯想到某事物。這句說綠色讓人想到草。"],
  ["この薬は胃に良い働きをする。", "「働き」（はたらき）在本句指藥對胃發揮的作用。「彼の働きで計画が進んだ」則指計畫因他的努力或貢獻而有進展。"],
  ["互いに助け合うことが大切だ。", "「互いに」（たがいに）表示彼此、互相。「互いに助け合う」就是彼此幫助。"],
  ["彼は腹の痛みを訴えた。", "「痛みを訴える」（うったえる）指向別人反映疼痛。「相手を裁判所に訴える」表示向法院提告，「感情に訴える」則指訴諸情感。"],
  ["先生が資料を貸して下さった。", "「貸して下さった」（かしてくださった）是「貸す」接上「て下さる」的形式，表示老師借資料給說話者，帶有敬意與感謝。"],
  ["彼はまるで子供のようだ。", "「子供のようだ」在本句表示他像個孩子。「雨が降るようだ」則表示根據跡象推測似乎會下雨。「見本のように書く」是照著範例寫。"],
  ["工事のため通行できません。", "「工事のため通行できません」表示因施工，人或車無法通過。書面語中的「通行」也可指用語或形式廣泛通用，如「広く通行している表記」。"],
  ["この物語は終わりが悲しい。", "「物語の終わり」（おわり）指故事的結局。一般文章多寫「終わり」，簡短標示也可只寫「終」。「人生の終わり」指生命的最後階段或終結。"],
  ["家族で食卓を囲んだ。", "「食卓を囲む」（かこむ）指大家圍坐在餐桌旁。「城を囲む」在作戰時可指包圍城池。「碁盤を囲む」則可指坐到棋盤旁下棋。"],
  ["子どもと手を繋いで歩いた。", "「手を繋ぐ」（つなぐ）是牽手。「犬を柱に繋ぐ」指把狗拴在柱子旁，「担当者に電話を繋ぐ」是轉接電話，「命を繋ぐ」則表示維持生命。"],
  ["明日、お宅に伺ってもよろしいですか。", "「伺う」（うかがう）是謙讓語。「お宅に伺う」指登門拜訪，「お名前を伺う」指詢問姓名，「お話を伺う」則可表示聽對方說話。"],
  ["幸運にも席が空いていた。", "「幸運にも」（こううんにも）用來評述接下來的情況，表示幸好還有空位。"],
  ["この薬は頭痛によく効く。", "「頭痛に効く」（きく）表示藥對頭痛有效。「ブレーキが効く」指煞車發揮作用，「融通が利く」則常用同音的「利く」，表示能視情況彈性處理。"],
  ["入学の祝いに本をもらった。", "「入学の祝いに」（にゅうがくのいわいに）表示為了祝賀入學。句中的書就是收到的入學賀禮。"],
  ["彼は大会で勝利を収めた。", "「勝利を収める」（おさめる）指取得勝利。「書類を箱に収める」是把文件收進箱裡，「予算内に収める」則指把支出控制在預算內。"],
  ["まだ望みは残っている。", "「望み」（のぞみ）在本句指事情仍有成功的可能。「望みをかなえる」中的「望み」則指希望實現的願望。"],
  ["残り時間は僅か五分だ。", "「僅か」（わずか）在「僅か五分」中表示「只有」，強調剩下的時間很短。"],
  ["会議は来週に延期された。", "「延期された」（えんきされた）是被動用法，表示會議被改到較晚的日期。「来週に」指出改到下週。"],
  ["唯それだけのことだ。", "「唯（ただ）それだけ」表示「僅此而已」。同讀「ただ」的「ただで」可表示免費，「ただ、」放在句首則可表示「不過」。"],
  ["駅まで三十分掛かる。", "「三十分掛かる」（かかる）指需要三十分鐘。「費用が掛かる」是要花錢，「鍵が掛かる」表示鎖扣上了，「結果は準備にかかっている」則指結果取決於準備。"],
  ["お昼は社員食堂で食べます。", "「お昼」（おひる）在本句和「食べる」搭配，指午餐。「お昼ごろ」是中午左右，「お昼の番組」也可指白天播出的節目。"],
  ["資料に一通り目を通した。", "「一通り目を通す」（ひととおり）表示把資料大致從頭到尾看過一遍。「道具が一通りそろう」則表示基本需要的工具已大致備齊。"],
  ["彼は深く息を吐いた。", "「吐く」（はく）在「息を吐く」中表示呼出氣息。「深く」形容這次吐氣的程度。"],
  ["子どもの熱心さに感心した。", "「熱心さに感心する」（かんしんする）指對對方的熱心感到佩服。「感心しないやり方」則表示不值得肯定的做法，語氣較委婉。"],
  ["会社から制服が支給された。", "「支給された」（しきゅうされた）是被動用法，表示制服由公司發給員工。「会社から」指出發放的來源。"],
  ["又の機会にお願いします。", "「又の機会」（またのきかい）指下次或另外一次機會。「また会う」是再見面，「又は」（または）則表示可擇其一，相當於「或者」。"],
  ["これは一種の芸術だ。", "「一種」（いっしゅ）在「一種の芸術」中表示某一類。「の」把「一種」和「芸術」連起來。"],
  ["工事は未だ終わっていない。", "「未だ」（まだ）搭配「終わっていない」表示尚未完工。「まだ雨が降っている」表示還在下雨，「まだ三時だ」則表示才三點。"],
  ["彼は約束を破ってしまった。", "「約束を破る」（やぶる）表示沒有遵守承諾。「紙を破る」是把紙撕破，「沈黙を破る」是打破沉默，「記録を破る」則是打破紀錄。"],
  ["スイッチを押して機械を動かした。", "「機械を動かす」（うごかす）在本句指讓機器開始運轉。「机を動かす」則是移動桌子，「人の心を動かす」比喻打動人心。"],
  ["彼は声を殺して泣いた。", "「声を殺す」（ころす）在本句是壓低聲音，盡量不讓別人聽見哭聲。「人を殺す」是殺人，「持ち味を殺す」則比喻讓原有的特色無法發揮。"],
  ["賛成か否かを決めてほしい。", "「否」在「賛成か否か」讀作「いな」，表示「是否贊成」。「賛否（さんぴ）」中的「否」讀「ひ」，表示反對。"],
  ["週末は大抵家にいる。", "「大抵」（たいてい）在本句表示通常。「大抵の人」是大多數人，「冗談は大抵にしなさい」則是叫人開玩笑要適可而止。"],
  ["来週なら少し空きがあります。", "「空き」（あき）在這裡指行程中尚未排定的時間，也就是下週還有空檔。"],
  ["会場は熱気に満ちていた。", "「満ちる」（みちる）在這裡表示充滿。「熱気に」指出充滿會場的是熱烈的氣氛。"],
  ["この本は余り面白くない。", "「余り」（あまり）搭配否定時表示「不太」，所以本句是說這本書不太有趣。「五を二で割った余り」是五除以二的餘數，「驚きのあまり」則是因為太驚訝。"],
  ["来月の半ばに帰国する。", "「半ば」（なかば）在「来月の半ば」中是名詞，指下個月中旬。「に」標示回國的時間。"],
  ["彼女は長い髪の毛をしている。", "「髪の毛」（かみのけ）指頭髮。「長い髪の毛」表示長頭髮。"],
  ["手術は順調に終わった。", "「順調に」（じゅんちょうに）修飾「終わった」，表示手術過程順利並已結束。"],
  ["父は今日は機嫌がいい。", "「機嫌がいい」（きげんがいい）表示心情好。「ご機嫌いかがですか」則是較客氣的問候，詢問對方近況如何。"],
  ["飲み物を室温に戻す。", "「戻す」（もどす）在這裡表示讓某物回到原有或設定的狀態。「室温に」指出要讓飲料回到室溫。"],
  ["彼は仕事に熱心だ。", "「熱心」（ねっしん）表示認真投入。「仕事に」指出他認真投入的是工作。"],
  ["この木は寒い土地でもよく育つ。", "「育つ」（そだつ）在這裡表示植物生長。「寒い土地でも」表示即使在寒冷的地方，這種樹也長得好。"],
  ["車が故障した。", "「車が故障する」（こしょうする）指車子出了機械問題。「肩の故障で欠場する」則常見於運動語境，指因肩部受傷或功能受影響而不能上場。"],
  ["彼の日本語はかなり上達した。", "「日本語が上達する」指日語能力進步。舊式書面用法也可指把下層的意見傳達給上層。"],
  ["靴の紐がほどけた。", "「靴の紐」（くつのひも）就是鞋帶，「紐がほどける」表示繩結鬆開。「荷物を紐で縛る」中的「紐」則指用來綁東西的細繩。"],
  ["この書類は郵便で送ります。", "「郵便で送る」（ゆうびんでおくる）是透過郵政服務寄出。「郵便が届く」則可以指實際的郵件送到了。"],
  ["時計の針が十二時をさした。", "「時計の針」（はり）是時鐘的指針。「縫い針」是縫衣的針，「釣り針」是魚鉤，「蜂の針」則指蜂的螫針。"],
  ["随分久しぶりですね。", "「随分久しぶり」用副詞「随分」強調隔了很久。「随分な言い方だ」則常帶有責難語氣，表示那種說法未免過分。"],
  ["人に頼らず自分でやりなさい。", "「頼る」（たよる）在這裡表示依賴。「人に」指出依賴的對象，「頼らず」表示不依賴。"],
  ["脇に荷物を置いた。", "「脇」（わき）在本句指旁邊。「脇の下」指腋下，「話が脇にそれる」則指談話偏離原本的主題。"],
  ["たまには贅沢をしてもいい。", "「贅沢をする」（ぜいたくをする）是花費比平常多，享受較講究的生活。「贅沢な要求」則可指要求超過通常能提供的程度。"],
  ["この記号は危険を表す。", "「表す」（あらわす）在這裡表示符號代表某個意思。「危険を表す」就是代表危險。"],
  ["弟は野球に夢中だ。", "「野球に夢中だ」（むちゅうだ）表示對棒球非常著迷。「夢中で走る」則形容只顧著跑，沒注意周圍。"],
  ["町の中を川が流れている。", "「川が流れる」（ながれる）描寫河水流動。「店内に音楽が流れる」表示店內播放音樂，「計画が流れる」則表示計畫作罷。"],
  ["庭の梅が咲きはじめた。", "「梅が咲く」（うめがさく）指梅樹開花。「梅を漬ける」則是醃漬梅子。用「松・竹・梅」標示三種等級時，「梅」通常是最基本的一級。"],
  ["寺で仏に手を合わせた。", "「仏に手を合わせる」中的「仏」（ほとけ）在寺院語境可指禮拜的佛或佛像。「仏のような人」則比喻心地慈悲的人。"],
  ["遠慮しないでもっと食べてください。", "「遠慮しないで」（えんりょしないで）是請對方別客氣。「参加を遠慮する」可表示婉拒參加，「撮影はご遠慮ください」則是委婉請對方不要拍攝。"],
  ["今が桜の盛りだ。", "「桜の盛り」（さくらのさかり）指櫻花盛開的時期。「夏の盛り」指夏季最熱的時候，「働き盛り」則指工作能力與精力旺盛的人生階段。"],
  ["うわさが町中に広がった。", "「広がる」（ひろがる）在這裡表示傳聞傳開。「町中に」指出消息傳遍了整個城鎮。"],
  ["この資料は永久に保存される。", "「永久に保存される」表示資料會永久保存。歷史文獻中的「永久」也可指日本平安時代的年號，同樣讀作「えいきゅう」。"],
  ["毎朝、金魚に餌をやる。", "「餌」（えさ）在這裡指餵金魚的食物。「金魚に餌をやる」表示餵金魚。"],
  ["この条件は我々に有利だ。", "「我々に有利だ」（ゆうりだ）表示條件對我方有利。「有利な取引」則是條件划算或能帶來較多收益的交易。"],
  ["大したけがではなかった。", "「大した」（たいした）修飾「けが」。「大したけがではなかった」表示傷勢不算嚴重。"],
  ["最後に一言お願いします。", "「一言」（ひとこと）在這裡指簡短說幾句話。「最後に一言お願いします」是請對方在最後簡短發言。"],
  ["事故の被害者は重体だ。", "「重体」（じゅうたい）在這裡形容事故傷者的傷勢危急。"],
  ["この写真はよく写っている。", "「写る」（うつる）在這裡表示影像呈現在照片上。「よく写っている」指照片拍出來的效果很好。"],
  ["電話は十九世紀の発明だ。", "「十九世紀の発明」指十九世紀發明出來的事物。古文裡，「発明」也可形容人聰穎或理解力強。"],
  ["二つの言葉の区別がつかない。", "「区別がつかない」（くべつがつかない）表示分辨不出差異。這句說的是兩個詞語難以區分。"],
  ["予定がすっかり狂ってしまった。", "「狂う」（くるう）在這裡表示原先的安排被打亂。「すっかり」強調計畫完全亂了。"],
  ["これらのデータは種類別に分類されている。", "「分類されている」（ぶんるいされている）是被動用法，描述資料已經分好類的狀態。「種類別に」表示依種類分類。"],
  ["ボールを壁に当てる。", "「壁に当てる」（あてる）在本句表示讓球擊中牆面。「光を当てる」是把光照到某處，「答えを当てる」則是猜中答案。"],
  ["荷物を箱に詰めて送った。", "「荷物を箱に詰める」（つめる）是把物品裝進箱子。「間隔を詰める」是縮短距離，「計画の詳細を詰める」則指把計畫細節逐一敲定。"],
  ["ボールを打つ。", "「ボールを打つ」（うつ）是擊球。「釘を打つ」是把釘子敲進去，「文字を打つ」是用鍵盤輸入文字，「心を打つ」則比喻使人感動。"],
  ["定期券を落としてしまった。", "「定期券」（ていきけん）指可在指定期間使用的交通票券，例如月票。句中只說票弄丟了。"],
  ["湯の加減をみてから入る。", "「湯の加減」（ゆのかげん）在本句指洗澡水的熱度。「味を加減する」是調整味道，「お加減はいかがですか」則在詢問對方身體狀況。"],
  ["彼は強い不満を抱いている。", "「不満を抱く」（いだく）表示心裡懷有不滿。「赤ちゃんを抱く」用於把人抱在懷中時，通常讀作「だく」。"],
  ["雨で川の水が増した。", "「増す」（ます）在這裡表示增加。「川の水が」指出增加的是河水，「雨で」說明原因。"],
  ["祖母は孫の写真を大事にしている。", "「孫」（まご）泛指子女的孩子，包含孫子和孫女。「孫の写真」指孫輩的照片。"],
  ["彼は奨学金で大学に通っている。", "「奨学金」（しょうがくきん）指就學資助。「奨学金で」表示靠這筆資助就讀大學，句中未交代資助形式。"],
  ["彼は表情が豊かだ。", "「表情が豊か」（ゆたか）指表情多樣，能清楚流露心情。「資源が豊か」是資源豐富，「豊かな暮らし」則可形容生活富足。"],
  ["日曜を除く毎日開いている。", "「日曜を除く」（のぞく）是把星期日排除在營業日之外。「汚れを除く」則指把原有的污垢去掉。"],
  ["この材料は熱をよく通す。", "「熱を通す」（とおす）在本句指讓熱穿過材料。「客を部屋に通す」是引客人進房間，「糸を針に通す」是穿針，「肉に火を通す」則指把肉加熱到熟。"],
  ["売上が目標に達するのは難しい。", "「達する」（たっする）在這裡表示達到某個水準。「売上が」是主語，「目標に」指出要達到的水準。"],
  ["彼はドアを強く叩いた。", "「ドアを叩く」（たたく）在本句指用力敲門。「肉を叩く」可指拍打肉品，「値段を叩く」是把價格壓低，「人を叩く」在輿論語境中則可指抨擊某人。"],
  ["幸い、けがはありませんでした。", "句首的「幸い」（さいわい）在本句表示幸好沒受傷。「不幸中の幸い」則把「幸い」當名詞使用，指不幸之中值得慶幸的事。"],
  ["彼らは交際している。", "「交際する」（こうさいする）在這裡表示兩人正在談戀愛，也就是正在交往。"],
  ["不注意から事故が生じる。", "「事故が生じる」（しょうじる）表示事故發生。「差が生じる」則表示因條件不同而產生差距。「から」可標示造成結果的原因。"],
  ["健康こそが彼の資本だ。", "「資本」（しほん）在這裡比喻賴以生活或做事的本錢。「こそ」強調健康正是他所倚重的資源。"],
  ["試験は案外簡単だった。", "「案外」（あんがい）在這裡是副詞，修飾「簡単だった」，表示考試比原先想的簡單。"],
  ["この道は駅に通じている。", "「駅に通じる」（つうじる）表示通往車站。「こちらの意図が通じる」指對方理解自己的意圖，「事情に通じる」則指熟悉相關情況。"],
  ["猫が膝の上で寝ている。", "「膝」（ひざ）可指膝蓋。「膝の上で猫が寝る」是在描述人坐著時，貓躺在大腿上。"],
  ["この店は輸入品を扱っている。", "「輸入品を扱う」（あつかう）是經營或販售進口商品。「機械を扱う」指操作機器，「問題を扱う」則可指處理或討論某個問題。"],
  ["急いで買って損をした。", "「損」（そん）在「損をする」中是名詞。這句表示因為買得太急而吃了虧。"],
  ["募集は明日で締め切ります。", "「締め切る」（しめきる）在募集的語境中表示截止受理。「明日で」指出明天就是最後期限。"],
  ["日本では十八歳で成人になる。", "「成人になる」（せいじんになる）指成為成年人。「成人向け」則用「成人」指成年人這一群體。"],
  ["支払いは現金でお願いします。", "「現金」（げんきん）在這裡是名詞。「現金で」表示以現金作為付款方式。"],
  ["彼にはひとつ貸しがある。", "「彼には貸しがある」（かしがある）在本句指曾幫過他，所以他欠自己一份人情。「貸しがまだ返ってこない」若談金錢，也可指借出去的款項還沒收回。"],
  ["この記事は事実を基に書かれている。", "「事実を基に」（もとに）表示以事實為根據。「経験を基に判断する」同樣指以經驗作為判斷的基礎。"],
  ["彼はアルバイトで学費を稼いでいる。", "「稼ぐ」（かせぐ）在這裡表示賺取金錢。「学費を稼ぐ」表示靠工作賺學費。"],
  ["この道は海まで至る。", "「海まで至る」（いたる）表示道路一路通到海邊。「結論に至る」是得出結論，「今に至る」則指從以前延續到現在。"],
  ["冬は鍋を囲むのが楽しい。", "「鍋を囲む」在這裡指大家圍坐在一起吃火鍋，「鍋」指火鍋料理。"],
  ["りんごの皮をむいて食べる。", "「りんごの皮」（かわ）指蘋果的外皮。「指の皮」指皮膚，「豆の皮」則是包覆豆子的薄皮。"],
  ["二人の関係は微妙だ。", "「関係が微妙」（びみょう）表示關係微妙、難以簡單說明。「合格できるかは微妙だ」表示是否能通過還難說。「この味は微妙だ」則可委婉表示不太滿意味道。"],
  ["駅で友人にばったり会った。", "「ばったり」在「ばったり会う」中表示沒有事先約定，碰巧遇見某人。"],
  ["木の棒で地面に線を引いた。", "「木の棒」（きのぼう）指木製棍子。「棒グラフ」用長條表示數量，「棒読み」則指沒有抑揚頓挫地念。"],
  ["昨夜は雨が激しかった。", "「雨が激しい」（はげしい）表示雨勢猛烈。「激しい競争」形容競爭激烈，「気温の変化が激しい」則指氣溫變化幅度很大。"],
  ["食後に温かい茶を飲む。", "「茶を飲む」（ちゃをのむ）指喝茶。「茶を栽培する」中的「茶」則指製茶用的茶樹，「茶をたてる」可指刷泡抹茶。"],
  ["時間を無駄にしてはいけない。", "「時間を無駄にする」（むだにする）表示浪費時間。句尾的「～てはいけない」接在動詞的「て」形後，表示不可以做某事。整句是說不可以浪費時間。"],
  ["家族が彼の生活を支えている。", "「支える」（ささえる）在這裡表示提供支持，讓對方得以維持生活。「彼の生活を」是受詞。"],
  ["その格好で出かけるの。", "「その格好」（かっこう）在這句指那身打扮。「変な格好で座る」則形容坐姿奇怪，「ちょうど格好の場所」中的「格好」表示合適。"],
  ["駅で道を聞いた。","「聞く」（きく）在「道を聞く」中表示詢問。「道を」指出詢問的內容，也就是怎麼走。"],
  ["彼は息子を自慢している。","「息子を自慢する」表示得意地向別人談起兒子。「を」標示引以為傲的對象。"],
  ["彼は一人で冒険に出た。","「冒険」（ぼうけん）在這裡是名詞。「冒険に出る」表示出發去冒險，「に」標示出發的目的。"],
  ["会議でその問題を取り上げた。","「取り上げる」（とりあげる）在這裡表示把某件事提出來討論。「その問題を」標示會議討論的議題。"],
  ["日中は気温がかなり上がる。","「日中」（にっちゅう）在這裡是時間名詞，表示白天。「は」把白天的情況提出來說明。"],
  ["投手は百球を投げた。", "「球」（きゅう）在「百球」中是量詞，用來計算投球次數。「百球を投げた」表示投了一百球。"],
  ["神様にお願いした。", "「神様」（かみさま）在本句指祈求的對象。「野球の神様」則可用來尊稱在棒球界成就極高、備受敬仰的人。"],
  ["電波が弱い。", "「電波が弱い」（でんぱがよわい）指無線訊號微弱，可能影響收訊。「電波を発信する」則指發射用於無線通訊等用途的電波。"],
  ["大勢の方々にお世話になった。", "「方々」（かたがた）是對多位人士的敬稱。「大勢の方々に」指出照顧說話者的是許多人。"],
  ["定規を使って直線を引いた。", "「直線」（ちょくせん）指筆直的線。「直線を引く」表示畫直線，「を」標示畫出的對象。"],
  ["名前の順に並んでください。", "「名前の順に」（じゅんに）表示依姓名的排列次序。「順番を守る」則表示照應有的次序輪流。"],
  ["参加者の大半が学生だった。", "「参加者の大半」（たいはん）指大多數參加者。「作業は大半終わった」則是說工作大部分已經做完。"],
  ["彼は大きな問題を抱えている。", "「抱える」（かかえる）在這裡表示有難題要處理。「大きな問題を抱えている」就是正面臨一個大問題。"],
  ["平日は仕事で忙しいです。", "「平日」（へいじつ）指平常的工作日。「平日は」用「は」提出時間話題，說明平日工作很忙。"],
  ["彼は必死に走った。", "「必死に走る」表示拼命跑。「必死」字面也可表示必然死亡；將棋裡的「必死」又寫作「必至」，指對手無法化解下一手被將死的威脅。"],
  ["彼と組んで研究を進める。", "「彼と組む」（くむ）是與他合作。「腕を組む」是把雙臂交叉抱在胸前，「足場を組む」是搭建鷹架，「予定を組む」則是安排日程。"],
  ["あいにく先生は外出しています。", "句首的副詞「あいにく」表示說話者覺得事情不湊巧。這裡是說老師碰巧外出了。"],
  ["この製品は日本で製造された。", "「製造された」是「製造する」（せいぞうする）的被動形，用來說明這項產品在哪裡製造。「日本で」標示製造地點。"],
  ["信号が青に変わった。", "「信号」（しんごう）在這裡指紅綠燈。日文用「青」稱呼交通號誌的綠燈，「青に変わった」表示轉為綠燈。"],
  ["彼は記憶力が優れている。", "「優れている」（すぐれている）表示能力或特質很出色。「記憶力が」指出他出色的地方是記憶力。"],
  ["永遠に続くものなどない。", "「永遠に」（えいえんに）修飾「続く」，表示一直持續下去。整句表示沒有什麼會永遠持續下去。"],
  ["雨は一時やんだが、また降りだした。", "「一時」（いちじ）在這裡表示暫時。「一時やんだ」指雨停了一小段時間。"],
  ["結婚式に招待された。", "「招待された」是「招待する」（しょうたいする）的被動形，表示受邀。「結婚式に」指出受邀參加的活動。"],
  ["結婚式でスピーチをした。", "「スピーチ」在這裡指婚禮致詞。「結婚式で」標示致詞的場合。"],
  ["締め切りには何とか間に合った。", "「何とか間に合う」（なんとかまにあう）表示經過努力勉強趕上。「何とかする」則常譯為想辦法處理。"],
  ["この製品は一年の保証がつく。", "「製品の保証」（せいひんのほしょう）在本句指一年的產品保固。「品質を保証する」則是對產品品質作出保證。"],
  ["九時に駅で待ち合わせよう。", "數字「九」也可讀作「きゅう」，但在「九時」中讀作「く」。「九時に」（くじに）表示在九點。"],
  ["転んで足の骨を折った。", "「足の骨」（あしのほね）指腿腳的骨頭。「傘の骨」則指撐住傘面的傘骨，「骨が折れる仕事」可比喻很費工夫的工作。"],
  ["来週、健康診断を行う。", "「行う」（おこなう）在這裡表示實施。「健康診断を行う」就是進行健康檢查。"],
  ["走ったので汗をかいた。", "「汗をかく」指流汗。「コップが汗をかく」則可比喻冰冷的杯壁凝結了小水珠。"],
  ["もっと具体的に説明してください。", "「具体的に」修飾「説明する」，表示說明的方式。「もっと」表示希望對方說得更具體。"],
  ["込む時間を避けて出かけた。", "「込む時間を避ける」（さける）是刻意避開人多的時段。「飛んできたボールをよける」則指閃身躲開飛來的球，有時也用「避ける」的表記。"],
  ["この件は君に任せる。", "「君に任せる」（まかせる）指把事情交給對方處理或決定。「運に任せる」則表示不再設法控制結果，任由運氣決定。"],
  ["身の程をわきまえるべきだ。", "「身の程」（みのほど）指自己的能力或分寸。「一時間ほど」是大約一個小時，「練習するほど上達する」則表示越練習越進步。"],
  ["展示品に手を触れないでください。", "「手を触れる」（ふれる）在本句指用手碰觸展品。「異文化に触れる」指接觸並體驗異文化，「問題に触れる」是提到該問題，「法律に触れる」則指觸犯法律。"],
  ["会社の利益が増えた。", "「利益」（りえき）在這裡指公司經營所得的利潤。"],
  ["その噂は事実ではなかった。", "「噂」（うわさ）指傳聞。「その噂は」提出話題，後半句說這個傳聞並非事實。"],
  ["名簿から名前が抜けている。", "「名前が抜けている」（ぬけている）表示名單漏掉了名字。「歯が抜ける」指牙齒脫落，「トンネルを抜ける」指穿過隧道，「会議を抜ける」則是離開會議。"],
  ["運動のあとで足の筋が痛い。", "「足の筋」（あしのすじ）指腿腳的筋或筋腱。「肉の筋」指肉裡較韌的纖維，「話の筋」指故事主線，「筋が通る」則表示合乎道理。"],
  ["この靴は少しきつい。", "「きつい」在這裡形容鞋子穿起來偏緊。「少し」表示有一點。"],
  ["人に迷惑をかけないように。", "「迷惑をかける」（めいわくをかける）指給他人添麻煩。「大声で話されて迷惑だ」則站在受影響一方，表示對方大聲說話令人困擾。"],
  ["子どもがビー玉で遊んでいる。", "「ビー玉」（ビーだま）指玻璃彈珠。「汗の玉」可指圓珠狀的汗滴，「そろばんの玉」則指算盤珠。"],
  ["計画を見直す必要がある。", "「計画を見直す」（みなおす）指重新評估計畫。「答案を見直す」是把答案再檢查一遍，「彼を見直した」則表示對他的評價提高了。"],
  ["彼女はおとなしい性格だ。", "「おとなしい」在這裡修飾「性格」，表示個性文靜。"],
  ["彼はこの土地に詳しい。", "「詳しい」（くわしい）在這裡表示熟悉。「この土地に」指出他熟悉的是這一帶。"],
  ["彼はよくしゃべる人だ。", "「よくしゃべる」表示很愛說話。「よく」修飾「しゃべる」，整個片語用來形容這個人很健談。"],
  ["今月の末に引っ越す。", "「末」（すえ）是名詞，指一段期間的末尾。「今月の末に」表示在這個月底。"],
  ["地震に備えて水を用意する。", "「備える」（そなえる）在這裡表示事先做好準備。「地震に」指出要應對的是地震。"],
  ["すてきな服ですね。", "「すてきな」修飾「服」，表示衣服漂亮、好看。"],
  ["雨は更に強くなった。", "「更に」（さらに）在這裡是程度副詞，表示雨勢比原先更強。"],
  ["これは旅行の記念です。", "「記念」（きねん）在這裡指這趟旅行留下的紀念品。"],
  ["子どもがいたずらをして叱られた。", "「いたずらをする」指做了淘氣或捉弄人的事。「機械にいたずらをする」則常指擅自亂動機器。"],
  ["痛くても少しは我慢してください。", "「我慢する」（がまんする）在本句是忍住疼痛。「甘いものを我慢する」則指克制自己想吃甜食的慾望。"],
  ["法律が改正された。", "「改正された」是「改正する」的被動形，表示法律經過修訂。「法律が」指出被修訂的是法律。"],
  ["友達に電話をかける。", "「電話をかける」是打電話，「眼鏡をかける」是戴眼鏡。「時間をかける」是花時間，「鍵をかける」則是上鎖。"],
  ["彼女は友達とおしゃべりしている。", "「おしゃべりする」表示聊天。「友達と」的「と」標示一起聊天的對象。"],
  ["データを保存してください。", "「保存する」（ほぞんする）在這裡指儲存數位資料。「データを」標示要儲存的內容。"],
  ["彼はじっと私を見つめた。", "「じっと見つめる」指目不轉睛地注視。「じっと座る」形容坐著不動，「じっと痛みに耐える」則形容默默忍著疼痛。"],
  ["駅の案内所で地図をもらいました。", "「案内所」（あんないじょ）是提供資訊的服務處。「会場まで案内する」指帶人到會場，「開催のご案内」則指活動通知或邀請。"],
  ["彼は私にその仕事を依頼した。", "「依頼する」（いらいする）在這裡表示委託。「私に」的「に」標示受託者，「その仕事を」的「を」標示委託的事項。"],
  ["旧市街には古い建物が多い。", "「旧市街」（きゅうしがい）中的「旧」是前綴，表示原有或較舊的市區。「旧制度」指以前使用的制度，「旧暦」則是相對於新曆的曆法。"],
  ["経済の安定が重要だ。", "「安定」（あんてい）在這裡是名詞。「経済の安定」指經濟維持穩定的狀態。"],
  ["暑くてたまらない。", "「～てたまらない」表示某種感受強烈到難以忍受。「暑くてたまらない」就是熱得受不了。"],
  ["ご飯を残さないで食べなさい。", "「ご飯を残す」（のこす）是在餐後留下沒吃完的飯。「仕事を残す」指留下沒做完的工作，「財産を子に残す」則是把財產留給子女。"],
  ["先生が今日の授業のプリントを配った。", "「プリント」在這裡指老師分發的紙本講義。"],
  ["世界の平和を願う。", "「平和」（へいわ）在這裡是名詞。「世界の平和を願う」表示希望世界和平。"],
  ["それは無理です。", "「無理です」（むりです）在本句表示辦不到。「無理な要求」是難以接受或不合情理的要求，「無理をする」則指勉強自己，做超出負荷的事。"],
  ["事件の謎はまだ解けていない。", "「事件の謎」（なぞ）指事件中尚未釐清的疑點。「謎めいた人物」則形容一個人難以捉摸。"],
  ["そんな馬鹿なことを言うな。", "「馬鹿なこと」（ばかなこと）指愚蠢或荒唐的事。「馬鹿！」直接用來罵人時是「笨蛋」。「ねじが馬鹿になる」則是口語，指螺紋滑牙而失去作用。"],
  ["彼は罪を認めて謝った。", "「罪を認める」表示承認自己犯下的過錯或罪行。「罪に問われる」指被追究罪責；舊式說法中的「罪」也可指刑罰。"],
  ["シャツのボタンが取れた。", "「取れる」（とれる）在這裡是自動詞，表示脫落。「ボタンが」指出掉下來的是鈕扣。"],
  ["彼の様子がおかしい。", "「様子がおかしい」（ようすがおかしい）在本句指他的言行或神情和平常不一樣。「会場の様子」則可指現場整體情況。"],
  ["私には従兄弟が三人います。", "「従兄弟」（いとこ）在這裡指男性的堂兄弟或表兄弟。「三人」表示共有三位。"],
  ["シャワーで汗を流した。", "「シャワーで汗を流す」（ながす）指沖掉身上的汗。「音楽を流す」是播放音樂，「うわさを流す」是散播謠言，「計画を流す」則可指取消計畫。"],
  ["ホテルのボーイが荷物を部屋まで運んでくれた。", "「ホテルのボーイ」在本句指幫忙搬行李的飯店男服務生。「ボーイスカウト」中的「ボーイ」則保留男孩的意思。"],
  ["このサイズがぴったりです。", "「ぴったり」在這裡表示剛好合適，說明這個尺寸正好。"],
  ["相手の身になって考えなさい。", "「相手の身になる」表示站在對方的立場。「身」（み）在這裡指立場或處境。"],
  ["困った時は先生に相談してください。", "「相談する」（そうだんする）在這裡指請教。「先生に」的「に」標示請教的對象。"],
  ["窓から海が見える。", "「見える」（みえる）表示看得見。「海が」指出看得見的是海，「窓から」指出從哪裡看出去。"],
  ["普通は電車で通勤します。", "句首的「普通は」（ふつうは）表示通常情況，這裡指平常搭火車通勤。"],
  ["彼の気持ちがよく分かります。", "「気持ち」（きもち）在這裡是名詞。「彼の気持ちが」指出能理解的是他的感受。"],
  ["この本は結構面白いです。", "「結構」（けっこう）在這裡是程度副詞，修飾「面白い」，表示這本書相當有趣。"],
  ["この料理はとてもうまい。", "「うまい」在這裡形容料理的味道，意思是好吃；「とても」表示程度很高。"],
  ["足元に注意してください。", "「注意する」（ちゅういする）在這裡表示留意。「足元に」的「に」標出要留意的是腳下。"],
  ["この機械は電気エネルギーを使う。", "「電気エネルギー」指電能，「を」標出機器使用的是電能。"],
  ["彼はその事実を否定した。", "「否定する」（ひていする）在這裡表示否認，「その事実を」指出他否認的是那項事實。"],
  ["いずれまた会いましょう。", "「いずれ」指將來的某個時候，句子是在相約有機會再見。"],
  ["間違いはないと思いますが、一応、確認しておきます。", "「一応確認する」（いちおうかくにんする）在本句指以防萬一還是確認一下。「一応終わった」則可表示大致完成，可能還有細節要處理。"],
  ["全員が会議に出席しました。", "「全員」（ぜんいん）是名詞，指在場團體的所有成員。「全員が」標出出席會議的是所有人。"],
  ["質問がありますか？", "「質問」（しつもん）指想提出的問題。這句是在詢問對方有沒有想問的事。"],
  ["こんなに美味しい料理は初めてだ。", "「こんなに」修飾形容詞「美味しい」，表示「這麼好吃」。"],
  ["重要なことをメモしました。", "「メモする」表示記下內容，「重要なことを」指出記下的是重要的事。「メモ」也可單用作名詞，指筆記或備忘。"],
  ["週末にコンサートに行きます。", "「コンサート」指音樂會。「コンサートに行く」就是去聽音樂會。"],
  ["その銀行は全国に支店がある。", "「支店」（してん）指分支據點。銀行的支店在中文稱為分行，「全国に」指出分行遍及全國。"],
  ["彼はワールドカップで優勝した。", "「ワールド」表示世界，在複合詞「ワールドカップ」中指世界盃。「で」標出奪冠的賽事。"],
  ["ワークライフバランスを大切にしたい。", "「ワークライフバランス」指工作與生活的平衡。其中「ライフ」指工作以外的生活。"],
  ["彼女はガールズバンドでギターを弾いている。", "「ガールズバンド」是指女子樂團的複合詞。「で」標出她在哪個樂團彈吉他。"],
  ["他に質問はありませんか。", "「他に」（ほかに）在這裡表示「另外、還有」，整句是在問還有沒有其他問題。"],
  ["これはビッグなニュースです。", "「ビッグな」修飾「ニュース」，表示消息很重大。「ビッグなニュース」就是大新聞。"],
  ["辞書で言葉の意味を調べた。", "「調べる」（しらべる）在這裡表示查閱。「辞書で」指出用字典查，「言葉の意味を」指出查的是詞語的意思。"],
  ["旅行に最適な時期です。", "「時期」（じき）是名詞，指一段時間。「旅行に最適な時期」指最適合旅行的一段時間。"],
  ["彼はもう大人です。", "「大人」（おとな）是名詞，指成年人。在「大人です」中接「です」作句子的述語。"],
  ["彼女はとても幸せそうだ。", "「幸せそうだ」表示從外在表現看起來很幸福。「そうだ」在這句表示說話者的觀察和推測。"],
  ["毎日7時間の睡眠が必要です。", "「7時間の」修飾名詞「睡眠」（すいみん），合起來就是七小時的睡眠。"],
  ["ここに来る度に、新しい発見がある。", "「度に」在這裡讀作「たびに」。「来る度に」表示每次來都會發生後面的事。"],
  ["十時までに来てください。", "「十」是數詞，在「十時」（じゅうじ）中表示十點。「までに」標出最晚到達的時間，十點整也算在內。"],
  ["これらの資料は全部必要だ。", "「これら」是指示代名詞，表示「這些」。「これらの」修飾「資料」。"],
  ["突然、雨が降り出した。", "「突然」（とつぜん）在句首作副詞，修飾「降り出した」，表示雨一下子就下了起來。"],
  ["彼は仕事に不満がある。", "「不満」（ふまん）是名詞。「仕事に」指出他不滿的對象是工作。"],
  ["遅れて申し訳ありません。", "「申し訳ありません」（もうしわけありません）是正式的道歉用語。「遅れて」交代道歉的原因是遲到了。"],
  ["居酒屋でイカの刺身を食べた。", "「イカ」是魷魚、烏賊等的日文通稱。這句的「イカの刺身」譯為魷魚生魚片。"],
  ["建物の後ろに駐車場がある。", "例句用「後ろ」（うしろ）表示後方。「建物の後ろに」指出停車場位於建築物後面。"],
  ["夜明けに家を出た。", "「夜明け」（よあけ）是天亮、黎明。「夜」在這個複合詞中讀作「よ」，「に」標出出門的時間。"],
  ["人にはそれぞれ事情がある。", "「それぞれ」表示各自。這句是說每個人都有自己的情況。"],
  ["入場券をなくしてしまった。", "「券」（けん）在複合詞中可表示票券，如「入場券」是入場票、「割引券」是折價券、「債券」則是金融商品。"],
  ["これは期間限定の特別メニューです。", "「限定」（げんてい）表示限制範圍。「期間限定」指只在一定期間供應，「数量限定」才指限制供應數量。"],
  ["彼は私に手で合図を送った。", "「合図」（あいず）是用來傳達訊息的信號。「手で」指出這句用手勢傳達。"],
  ["車掌が切符を確認した。", "「車掌」（しゃしょう）指在列車上服務乘客、查驗車票的車掌。「切符を」指出查驗的是車票。"],
  ["ビニール袋は環境に悪い。", "「ビニール」可指聚氯乙烯等塑膠材料，日常用語「ビニール袋」通常譯為塑膠袋。"],
  ["ストーブに灯油を入れた。", "「灯油」（とうゆ）在這句是暖爐用的煤油。「ストーブに」指出把煤油加進暖爐。"],
  ["フライパンに油をひいた。", "「油をひく」表示在鍋面抹上一層油。「フライパンに」指出抹油的位置是平底鍋。"],
  ["フライパンで卵を焼きます。", "「フライパン」是平底鍋。「で」標出煎蛋用的鍋具。"],
  ["髪をブラシでとかす。", "「ブラシ」是刷子的通稱，在這裡指髮刷。「ブラシで」指出梳頭髮用的工具。"],
  ["兄弟が些細なことで喧嘩した。", "「喧嘩する」（けんかする）在這裡指兄弟為小事吵架。「殴り合いの喧嘩」則指互相揮拳打架。"],
  ["問題はそれほど単純ではない。", "「単純」（たんじゅん）在這裡表示簡單、不複雜。「単純な人」則可形容人想法簡單或天真。"],
  ["彼は若い頃から作家を目指していた。", "「作家」（さっか）可指寫作的人。「陶芸作家」中的「作家」則是指陶藝創作者。"],
  ["彼女は上級クラスで日本語を学んでいる。", "「上級クラス」（じょうきゅうクラス）指進階班。「上級」也可表示較高職級，例如「上級職」。"],
  ["博物館に古い刀が飾ってある。", "「刀」（かたな）在這裡指博物館展示的一把古刀。這個詞常用來指日本刀。"],
  ["服をたんすにしまった。", "「たんす」是收納衣物的櫃子，也可指抽屜式的斗櫃。「たんすに」指出衣服被收進哪裡。"],
  ["流れに逆らって泳ぐのは難しい。", "「流れに逆らう」表示逆著水流。「命令に逆らう」則表示違抗命令。"],
  ["失敗を人の所為にするな。", "「～の所為にする」（～のせいにする）表示把事情歸咎於某人或某事。這句勸人別把失敗怪到別人頭上。"],
  ["彼はチームのメンバーです。", "「メンバー」在這句指團隊成員。「会議のメンバー」可指與會成員，「先発メンバー」則是比賽的先發陣容。"],
  ["芝生を刈る。", "「刈る」（かる）在這句指修剪草坪。「髪を短く刈る」是把頭髮剪短，「稲を刈る」則是收割稻子。"],
  ["部屋の明かりを点けた。", "「点ける」（つける）在這裡表示開燈。「ろうそくに火をつける」中的「つける」則表示點燃。"],
  ["永い年月が過ぎた。", "「永い」（ながい）表示時間漫長。「永い年月」也可寫作「長い年月」。表示物體的長度時則用「長い」，例如「長いひも」。"],
  ["ずうずうしいお願いですみません。", "「ずうずうしい」形容不顧他人感受、厚著臉皮。說「ずうずうしいお願い」是在自謙，表示自己提出了冒昧的請求。"],
  ["日本を巡るツアーに参加した。", "「ツアー」在這裡指遊覽日本各地的旅遊行程。「全国ツアー」在演出語境中則指到各地巡迴演出。"],
  ["もっとパワーが必要だ。", "「パワー」指力量、動力。這句表示需要更大的力量，日文省略了需要力量的人或物。說「エンジンのパワー」時則指引擎的動力。"],
  ["彼女は有名なアーティストです。", "「アーティスト」指藝術創作者，在音樂語境中也可指歌手、樂手等音樂人。這句只說她知名，沒有交代她從事哪一類藝術。"],
  ["彼はチェスのナイトを動かした。", "「ナイト」在這裡是西洋棋的騎士棋子。在冒險故事等語境中也可指騎士，例如「白馬に乗ったナイト」。"],
  ["白い糸に赤い糸が交ざっている。", "「交ざる」（まざる）是自動詞。「白い糸に赤い糸が交ざっている」表示白線中混有紅線。也可用於人加入群體，例如「子どもたちに交ざって遊ぶ」是和孩子們一起玩。"],
  ["この部屋はすぐ暖まる。", "「暖まる」（あたたまる）指變暖和。「この部屋はすぐ暖まる」表示房間很快就暖起來。「日なたで暖まる」則指在陽光下讓自己暖和起來。"],
  ["彼は多くの本を著した。", "「著す」（あらわす）用於寫作或出版著作。「多くの本を著した」著重他寫過許多本書。讀音相同的「表す」可用於表達情感，「現す」可用於顯露身影。"],
  ["新たな挑戦を始める。", "「新たな」（あらたな）修飾名詞，「新たな挑戦」是新的挑戰。「新たに」修飾動作，例如「新たに始める」可依上下文譯為重新開始或開始一項新的工作。"],
  ["授業料を払い込んだ。", "「払い込む」（はらいこむ）指把款項繳付給指定機構或存入指定帳戶。「授業料を払い込む」是繳學費，「指定口座に払い込む」是將款項繳入指定帳戶。"],
  ["彼はチームのキャプテンです。", "「キャプテン」在「チームのキャプテン」指球隊的隊長，在「船のキャプテン」指船長。例句表示他是這支球隊的隊長。"],
  ["彼女は新しいワンピースを着ていた。", "單說「ワンピース」並搭配「着る」，在本句指連身洋裝。指泳衣時可說「ワンピースの水着」，意思是連身泳衣。"],
  ["チームを応援する。", "「応援する」（おうえんする）在「チームを応援する」指為球隊加油。在「応援に駆けつける」中，如果是去幫忙處理工作，就表示趕去支援。"],
  ["瓶詰のジャムを買った。", "「瓶詰」（びんづめ，也寫作「瓶詰め」）在「瓶詰のジャム」指瓶裝果醬。「ジャムを瓶詰めにする」則指把果醬裝進瓶子。"],
  ["彼は十年前に故郷を離れた。", "「故郷を離れる」（はなれる）指離開故鄉，「職場を離れる」可指離開工作場所或崗位。「駅から離れている」表示離車站有一段距離，「人の心が離れる」則指人心逐漸疏離。"],
  ["彼は結果に満足している。", "「結果に満足する」（まんぞくする）指對結果感到滿意。「満足な説明が得られない」表示得不到充分的說明。數學中的「方程式を満足する」表示使方程式成立。"],
  ["スープに塩を少し加えた。", "「加える」（くわえる）的譯法隨受詞而變。「塩を加える」是加鹽，「速度を加える」是加快速度，「仲間に加える」是納入成員，「打撃を加える」是給予打擊。"],
  ["電話が話し中だった。", "「電話が話し中だった」表示當時電話佔線。「担当者は来客と話し中です」則表示負責人正在和訪客談話。"],
  ["赤ちゃんが寝ているので、そっとドアを閉めた。", "「そっとドアを閉める」指輕輕關門，避免聲響。「そっと部屋を出る」可譯為悄悄離開房間。「そっとしておく」用於人時，可表示先讓對方獨處。"],
  ["シャワーを浴びてさっぱりした。", "「さっぱりした」在洗澡後指神清氣爽。「さっぱりした味」是清淡爽口的味道，「さっぱりした性格」形容個性爽快。「さっぱり分からない」則是完全不懂。"],
  ["このパンは軟らかい。", "「軟らかい」（やわらかい）在本句指麵包質地柔軟。形容聲音、話題或思考時，可見「柔らかい声」（柔和的聲音）、「柔らかい話題」（輕鬆的話題）和「頭が柔らかい」（思考靈活）等寫法。"],
  ["シャワーを浴びてすっきりした。", "「すっきりした」在洗澡後表示覺得清爽舒暢。「すっきりした部屋」指整潔俐落的房間，「すっきりした説明」是清楚有條理的說明。疑問解開後也可說「疑問が解けてすっきりした」。"],
  ["この事実から真相が分る。", "本句的「分る」（わかる，也寫作「分かる」）指由已知事實看出真相。「説明が分かる」是聽得懂說明。口語只說「分かる」也可用來回應對方，表示自己懂對方的感受。"],
  ["洗濯物が洗濯槽の片側に片寄っている。", "「片寄る」（かたよる）在本句指衣物集中到洗衣槽的一側。抽象用法常寫作「偏る」，例如「栄養が偏る」是營養不均衡，「判断が偏る」是判斷偏頗。"],
  ["彼女は編物が上手だ。", "「編物」（あみもの，也寫作「編み物」）是名詞，可指編織、鉤織這項活動，也可指成品。「編物が上手だ」表示她很會編織。"],
  ["余所で買ったほうが安い。", "「余所」（よそ，亦可寫成假名「よそ」）在「よそで買う」指去別處買，「よその家」是別人家。「周りの心配をよそに」表示不顧周遭人的擔心。"],
  ["深呼吸して落ち着こう。", "「落ち着く」（おちつく）在本句指讓心情平靜下來。「新居に落ち着く」是在新家安頓下來，「話し合いはその案に落ち着いた」表示討論最後定案。「落ち着いた色合い」則是沉穩的色調。"],
  ["テストで零点を取った。", "「零点」（れいてん）在「テストで零点を取る」指考了零分。數學中的「関数の零点」則指讓函數值等於零的自變數值。"],
  ["その問題を詳しく論ずる。", "「論ずる」（ろんずる）在「問題を詳しく論ずる」表示詳細論述某個問題。「年齢を論ぜず」則表示不以年齡為考量，也就是不論年齡。"],
  ["この碗にひびが入っている。", "「碗」（わん）作名詞指碗，例句表示碗上有裂痕。計算用碗盛裝的份量時，也可寫「一碗」（いちわん），意思是一碗。"],
  ["彼女は舞台で歌った。", "「舞台で歌う」（ぶたいでうたう）指在舞台上唱歌。「物語の舞台」指故事發生的背景或地點，「世界を舞台に活躍する」則表示活躍於國際領域。"],
  ["作法をよく心得ている。", "「心得る」（こころえる）在「作法を心得ている」指熟悉禮節，也可表示懂得某項技藝。「心得ました」用於回應交代時，表示明白並接受對方的要求。"],
  ["長い戦いが終わった。", "「戦い」（たたかい）在本句指一場持續很久的戰鬥或抗爭，具體內容需看上下文。「病気との戦い」指對抗疾病，「優勝をかけた戦い」則指爭奪冠軍的較量。"],
  ["彼女はおしゃれな服を着ている。", "「おしゃれな服」是時髦、有品味的服裝。「おしゃれをする」表示打扮自己，「おしゃれな人」則是形容穿著講究的人。"],
  ["多くの人から支持を得た。", "「支持を得る」（しじをえる）指獲得支持，「要領を得る」可指掌握要領。接在其他動詞後時還可表示有可能，例如「起こり得る」表示有可能發生。"],
  ["彼は歴史上の重要な人物です。", "「人物」（じんぶつ）在「歴史上の人物」指歷史上的人。「信頼できる人物」是在評價一個人的品格，「なかなかの人物だ」則可稱讚對方頗有才幹。"],
  ["話の中味が薄い。", "「中味」（なかみ，也寫作「中身」）在「話の中味」指談話的實質內容。「話の中味が薄い」表示談話內容空泛。「箱の中身」則指盒子裡裝的東西。"],
  ["映画のシナリオを書いた。", "「シナリオ」在「映画のシナリオ」指電影劇本。用於規劃時，「最悪のシナリオを想定する」則是預想最糟的發展情境。"],
  ["残った料理にラップをかけた。", "「ラップ」在廚房語境中可指保鮮膜。「料理にラップをかける」是把料理用保鮮膜蓋起來，「ラップする」則可指用保鮮膜包起來。"],
  ["彼は信頼できる仲間だ。", "「信頼できる仲間」（なかま）指值得信賴的同伴。「仲間に入る」指加入一個群體，「クジラは哺乳類の仲間だ」則表示鯨魚屬於哺乳類。"],
  ["この部屋の広さは十分だ。", "「広さ」（ひろさ）是「広い」的名詞形式，表示某處有多寬廣。「部屋の広さ」指房間的大小，可用面積表示。若特指門或走道左右兩側之間的距離，通常說「幅」（はば）。"],
  ["四つ角を右に曲がってください。", "「四つ角」（よつかど）可指物體的四個角，也可指十字路口。例句是指路用語，「四つ角を右に曲がる」表示在十字路口右轉。"],
  ["正直な意見を教えてください。", "「正直な意見」（しょうじきないけん）是坦率、真實的意見。「正直に言うと」則用來引出接下來要坦白說的話，可譯為「老實說」。"],
  ["私は自然の中で過ごすのが好きです。", "「自然の中」（しぜんのなか）指大自然中，「で」標示度過時光的地點。「自然な笑顔」是自然流露的笑容，「自然に笑みがこぼれる」則表示自然而然露出笑容。"],
  ["自分の行動を反省した。", "「反省する」（はんせいする）表示回顧並檢討自己的言行。「自分の行動を反省した」是反省自己的行為。「失敗を反省する」則可包含對失誤的懊悔。"],
  ["焼肉店で牛のタンを注文した。", "「タン」在燒肉店的「牛のタン」是食用的牛舌。在鞋子的語境中，「靴のタン」則指鞋帶底下的鞋舌。"],
  ["その話題は会議で議論されました。", "「話題」（わだい）可指談話或討論的題目，例如這句中會議討論的議題。「話題になる」表示受到注意、引起討論。"],
  ["彼は大学のテニスサークルに入っています。", "「テニスサークル」是由網球同好組成的社團，這句表示他加入了大學的網球社。「サークル」用於描述圖形時，也可指圓形或圓圈。"],
  ["彼はサッカーチームのコーチです。", "「サッカーチームのコーチ」指足球隊的教練。「初心者をコーチする」則指指導初學者，重點在教練所做的指導。"],
  ["このパッケージはとても軽いです。", "「パッケージ」在本句指包裝或包好的物品。「パッケージツアー」則指把交通、住宿等項目組合起來販售的套裝行程。"],
  ["雨に雪が交じってきた。", "「交じる」（まじる）在本句指雨中開始夾雜雪。「大人に交じって話を聞く」則指加入一群大人，一起聽他人說話。"],
  ["最短ルートを探した。", "「最短ルート」指距離最短的路線。「販売ルート」中的「ルート」則是商品銷售的管道。"],
  ["彼のハートは温かい。", "「ハート」在本句比喻一個人的心，表示他心地溫暖。「ハートのマーク」是愛心形圖案，「ハートのエース」則是撲克牌的紅心 A。"],
  ["やはり、彼は来なかった。", "本句的「やはり」表示情況和預想一致，可譯為「果然」。重新考慮後說「やはり家に帰ろう」，則表示「還是回家吧」。「彼もやはり同じ意見だ」則強調他的看法也一樣。"],
  ["とにかく、やってみよう。", "「とにかく、やってみよう」表示先試試看，把其他疑慮暫放一旁。「理由はとにかく、結果を見よう」也是先擱置某事的用法。「とにかく忙しい」則用來強調非常忙。"],
  ["地震の発生に備える。", "「地震の発生」（はっせい）指地震的發生，「熱が発生する」是產生熱。生物學中的「発生」則可指生物從早期階段逐步形成與發育的過程。"],
  ["この薬は効果があります。", "「効果」（こうか）在「薬の効果」指藥物起到的作用。「効果がある」表示有效。「効果音」則指為了營造特定效果而加入的音效。"],
  ["彼の反応は予想外だった。", "「反応」（はんのう）在本句指他對某事的反應。「光に反応する」表示受到光刺激後作出反應。「化学反応」則指物質發生化學變化。"],
  ["彼は高くジャンプした。", "「高くジャンプする」是往高處跳。「スキージャンプ」是跳台滑雪項目。「リンク先にジャンプする」則是在網頁上跳轉到連結的目的地。"],
  ["彼はこの国のキングです。", "「この国のキング」指這個國家的國王。在撲克牌語境中，「キング」是 K 牌，在西洋棋語境中則是國王棋子。"],
  ["彼はいつもスマートな服装をしています。", "「スマートな服装」是俐落得體的穿著。「スマートな体つき」則指身材修長，「スマートな対応」形容處理事情的方式俐落得宜。"],
  ["新しいことにチャレンジしたいです。", "「新しいことにチャレンジする」是嘗試新事物。部分運動賽事中，「チャレンジを要求する」可表示要求透過影像重看以確認裁判的判決。"],
  ["彼女は私のビジネスパートナーです。", "「ビジネスパートナー」是商務夥伴。「ダンスのパートナー」是舞伴，談到個人生活時，「パートナー」也可指伴侶。"],
  ["このツールはとても便利です。", "「ツール」指做事所用的工具，依語境也可指軟體。「画像編集ツール」就是用來編輯圖片的軟體工具。"],
  ["新しい命の誕生を祝った。", "「誕生」（たんじょう）在「新しい命の誕生」指新生命的出生。「新しい組織の誕生」則比喻新組織成立。"],
  ["この街の中心は駅です。", "「街の中心」（まちのちゅうしん）指城鎮的核心地帶。「駅を中心に店が集まっている」表示商店以車站為中心聚集，「議論の中心」則指討論的焦點。"],
  ["このドアは自動で開きます。", "「自動で」（じどうで）在本句表示門會自動打開。日語文法中的「自動」也可作「自動詞」的簡稱，例如「開く」（あく）是自動詞，描述門打開。"],
  ["祖父は算盤が得意だ。", "「算盤」（そろばん）在本句指計算用的算盤，表示祖父很會打算盤。「算盤をはじく」也可用於比喻，表示盤算成本或得失。"],
  ["およそ10分で着きます。", "「およそ」放在數量前表示大約，「およそ10分」是大約十分鐘。「およそ次のとおり」是大致如下。「およそ見当がつかない」則搭配否定，表示完全沒有頭緒。"],
  ["以後、気をつけます。", "句首的「以後」（いご）在本句表示從現在起，可譯為「今後我會注意」。「３時以後」則以三點為起點，範圍包含三點。"],
  ["これは個人の意見です。", "「個人の意見」（こじんのいけん）指個人看法。在法律等語境中，「個人」也可和「法人」相對，指自然人。"],
  ["彼がその仕事を引き受けた。", "「仕事を引き受ける」（ひきうける）指同意接下工作。「業務を引き受ける」也可指接手業務，「保証人を引き受ける」則表示同意擔任保證人。"],
  ["ほとんど毎日泳ぎます。", "「ほとんど毎日」是幾乎每天。「ほとんど泳がない」搭配否定，表示幾乎不游泳。「参加者のほとんど」則指參加者當中的大多數。"],
  ["彼の説明を理解しました。", "「説明を理解する」（りかいする）指聽懂或看懂說明。「相手の立場を理解する」則指體諒或了解對方的處境。"],
  ["日本の技術は素晴らしいです。", "「日本の技術」（にほんのぎじゅつ）在本句指日本的技術水準。「医療技術」指醫療技術，「演奏技術」則指演奏的技巧。"],
  ["紙を手で押さえた。", "「紙を手で押さえる」（おさえる）是用手按住紙。「要点を押さえる」是掌握重點，「会場を押さえる」是確保能使用場地，「出費を押さえる」則是控制支出。"],
  ["ここに駐車するスペースはありますか？", "「駐車するスペース」指停車用的空間。「単語の間にスペースを入れる」是字詞之間留空格。"],
  ["彼の話は確かです。", "「彼の話は確かだ」（たしかだ）表示他的話可信。「確か明日でしたね」則帶有憑記憶確認的語氣，可譯為「我沒記錯的話，是明天吧」。"],
  ["この果実は熟すと甘くなる。", "「果実」（かじつ）在「果実が熟す」指植物的果實成熟。「努力の果実」則比喻努力後得到的成果。"],
  ["だいいち時間が足りない。", "「だいいち」（第一）在句首可用來提出最基本的理由。本句可譯為「首先，時間就不夠」。「第一回」的「第一」則用來表示順序。"],
  ["服装がだらしないと注意された。", "「服装がだらしない」形容穿著邋遢。「時間にだらしない」則說的是對時間管理散漫，例如經常遲到。"],
  ["初めまして、どうぞよろしく。", "初次見面時，「どうぞよろしく」可譯為「請多指教」。「ご家族にどうぞよろしく」則是請對方代自己向家人問好。"],
  ["このコースは湖の周りを一周する。", "「このコース」在本句指繞湖一周的路線。「日本語コース」是日語課程，「水泳のコース」可指泳道，「コース料理」則指依序上菜的一套餐點。"],
  ["彼はロックバンドでギターを弾いている。", "「ロックバンド」是搖滾樂團。「時計のバンド」指手錶錶帶，「周波数バンド」則指頻帶。"],
  ["メインの通りはこちらです。", "「メインの通り」指主要街道。用餐時單說「メイン」可指主菜，談節目時「番組のメイン」則可指節目最主要的部分。"],
  ["彼女は映画スターです。", "「映画スター」指電影明星。「スターの印」可指星形符號，描寫夜空時「スター」也可指天上的星星。"],
  ["このゲームにはたくさんのレアアイテムがある。", "「レアアイテム」在遊戲中指稀有道具。「旅行の必須アイテム」則是旅行時必備的物品。"],
  ["家族の古いアルバムを見つけた。", "「家族のアルバム」在本句指收藏家庭照片的相簿。「新しいアルバムを発売する」若談的是歌手，則指發行新專輯。"],
  ["重要なファイルを保存した。", "「ファイルを保存する」在電腦操作中指儲存檔案。「書類をファイルに入れる」中的「ファイル」則可以指用來收納紙本文件的資料夾。"],
  ["成績はまあまあだった。", "「成績はまあまあだった」表示成績還可以。「まあまあ、落ち着いて」中的「まあまあ」則用來安撫對方，相當於「好了，先冷靜一下」。"],
  ["現在、彼は日本に住んでいます。", "「現在」（げんざい）在本句指目前。「４月１日現在」則表示以四月一日當天的情況為準。「現在形」是在文法上表示現在時態的形式。"],
  ["急な知らせにあわてた。", "「急な知らせにあわてる」是因突如其來的消息而慌張。「あわてて家を出た」則描述慌忙地出了門。"],
  ["お帰り、今日は早かったね。", "單說「お帰り」（おかえり）是在迎接回來的人，較完整的招呼是「お帰りなさい」。「お帰りの時間」則是客氣地說對方回來或回去的時間。"],
  ["痛みをこらえて歩いた。", "「痛みをこらえる」是忍住疼痛，「笑いをこらえる」是忍住笑。「今回はこらえてください」也可用於請對方這次寬容些。"],
  ["駅で彼とすれちがった。", "「すれちがう」（擦れ違う）在本句是和他擦身而過。「入れ違いですれちがう」可指時間錯開而沒碰到，「意見がすれちがう」則表示雙方想法對不上。"],
  ["ネットで調べました。", "「ネットで調べる」是上網查詢。「テニスのネット」指擋在球場中央的球網。價格或重量語境中，「ネット」則可表示扣除其他部分後的淨額或淨重。"],
  ["私はこの店に良いイメージを持っています。", "「店に良いイメージを持つ」指對店家有好印象。「完成図をイメージする」是想像完成後的樣子，「商品イメージ」也可指用於呈現商品的示意圖。"],
  ["このレストランはサービスが良いです。", "「サービスが良い」用於餐廳時，表示服務好。「デザートはサービスです」表示甜點免費招待。「アフターサービス」則指售後服務。"],
  ["どんなタイプが好きですか？", "「タイプ」指類型。「どんなタイプが好きですか」若在談人，可譯為「你喜歡哪一型的人」。「このタイプの椅子」則指這一類椅子。"],
  ["彼の考えは素晴らしいです。", "「考え」（かんがえ）在本句指他的想法。「考えを聞く」可指聽取看法，「辞める考えはない」則表示沒有辭職的打算。"],
  ["舞台のセンターに立ってください。", "「舞台のセンター」指舞台中央。棒球中的「センター」可指中外野或中外野手，依前後文判斷。"],
  ["彼は許しを請うた。", "「請う」（こう）是向人懇求。「許しを請う」是請求原諒，「教えを請う」則是向人請教。"],
  ["案内状を千枚刷った。", "「刷る」（する）在本句指印製，例句是印了一千張通知。用木製版模把花紋印到布上，也可用「刷る」。"],
  ["庭で落ち葉を焚いた。", "「落ち葉を焚く」（たく）指燃燒落葉。「風呂を焚く」指燒熱洗澡水，「フラッシュを焚く」則指拍照時打閃光燈。"],
  ["間違った個所を直した。", "「個所」（かしょ，也寫作「箇所」）在本句指出錯的地方。「三箇所を直す」中的「箇所」用來計數，表示修正三處。"],
  ["会議の日にちを決めた。", "「会議の日にち」（ひにち）指會議的日期。「日にちがかかる」中的「日にち」則指需要經過的天數。"],
  ["寺で手を合わせて拝んだ。", "「拝む」（おがむ）在本句指合掌參拜。「拝むように頼む」可形容苦苦懇求，「ご尊顔を拝む」則是帶敬意地說看到對方的面容。"],
  ["冬に備えて食料を蓄える。", "「食料を蓄える」（たくわえる）指儲存糧食。「知識を蓄える」是累積知識，「ひげを蓄える」則指蓄鬍。"],
  ["山の清い水を飲んだ。", "「清い水」（きよいみず）指清澈潔淨的水。「清い心」則形容心地純潔。"],
  ["春になったら種を蒔く。", "「種を蒔く」（まく）是播種。「争いの種をまく」則比喻埋下紛爭的起因。工藝中的「蒔絵」也用這個字，指在漆器表面撒上金銀粉等形成圖案。"],
  ["この語は単数で使う。", "「単数」（たんすう）在本句指文法上的單數，和「複数」（複數）相對。「単数回答」則表示作答時只選一個答案。"],
  ["顔が青白いよ、大丈夫？", "「顔が青白い」（あおじろい）是說臉色蒼白。「青白い光」則描述帶藍色的白光。"],
  ["彼はいつも朗らかだ。", "「朗らか」（ほがらか）形容人開朗的性情或表情，也可用於描寫晴朗明亮的天空。例句是說他總是很開朗。"],
  ["駅で落し物を見つけた。", "「落し物」（おとしもの，也寫作「落とし物」）在本句指別人掉落的物品。「落とし物をする」則從失主的角度表示不慎掉了東西。"],
  ["彼はその組織の一員です。", "「組織の一員」（そしきのいちいん）指團體的一名成員。「組織の構造」談的是團體如何構成。「筋肉組織」則是生物學用語，指肌肉組織。"],
  ["船は今夜赤道を越える。", "「赤道」（せきどう）在本句指地球上緯度為零的赤道。天文學的「天の赤道」則是把地球赤道所在的平面延伸到天球所得的大圓。"],
  ["東京駅で電車の乗り換えをした。", "「乗り換え」（のりかえ）在本句指在東京站轉乘電車。「他社のサービスに乗り換える」則指改用另一家公司的服務。"],
  ["家主に家賃を払った。", "「家主」（やぬし）指房屋所有人。在「家主に家賃を払う」這個租賃語境中，指收取房租的房東。"],
  ["木に模様を彫った。", "「彫る」（ほる）在本句指把花紋刻在木頭上。「入れ墨を彫る」則指在皮膚上刺青。"],
  ["庭の垣根を直した。", "「庭の垣根」（にわのかきね）指庭院的圍籬。「部署間の垣根を越える」則比喻跨越部門之間的隔閡。"],
  ["この漢字の読みは何ですか。", "「漢字の読み」（よみ）指漢字的讀法，視字詞而定，可是音讀或訓讀。「相手の動きに対する読み」則指對對方下一步行動的推測。"],
  ["会議が三十分延びた。", "「会議が三十分延びた」（のびた）可能表示會議多開了三十分鐘，也可能表示會議的開始時間往後延了三十分鐘。「会議が翌日に延びた」則明確表示延期到隔天。"],
  ["紙を糊で貼り合わせた。", "「糊」（のり）在本句是用來黏合紙張的漿糊。「洗濯糊」則指衣物上漿用的材料，能讓布料挺一些。"],
  ["道が雪で塞がっている。", "「道が雪で塞がる」（ふさがる）表示道路被雪堵住。「傷口が塞がる」指傷口閉合，「席が塞がっている」則表示座位已被占用。"],
  ["食事の前に手洗いをしてください。", "「手洗い」（てあらい）在用餐前指洗手。「お手洗い」是對洗手間的客氣說法。「手洗いできる服」則是可以用手洗的衣服。"],
  ["背中を掻いてほしい。", "「背中を掻く」（かく）是抓背。「汗をかく」是流汗，「雪をかく」則是用工具把雪鏟開。"],
  ["雨で川の水が濁った。", "「水が濁る」（にごる）表示水變混濁。「声が濁る」形容聲音變得不清亮。談日語讀音時，也可用「濁る」指「か」變成「が」這類濁音化。"],
  ["彼の勇ましい行動に驚いた。", "「勇ましい行動」（いさましいこうどう）形容行動英勇。「勇ましい音楽」則形容音樂雄壯、振奮人心。"],
  ["洗濯物を畳んだ。", "「洗濯物を畳む」（たたむ）是把洗好的衣物摺好，「傘を畳む」是把傘收起來。「店を畳む」則表示結束營業、收掉店面。"],
  ["考え方が幼稚だと言われた。", "「考え方が幼稚だ」（ようちだ）是在批評想法不成熟。「幼稚な考え」形容思考方式像小孩子。「幼稚園」中的「幼稚」則保留年幼的意思。"],
  ["梯子をかけて屋根に上った。", "「梯子をかける」（はしごをかける）是架起梯子。「店をはしごする」則是接連光顧好幾家店，例如一晚跑好幾家酒吧。"],
  ["作業の時間を縮めた。", "「時間を縮める」（ちぢめる）是縮短時間。「身を縮める」指縮起身體，「布を縮める」則指讓布料縮小。"],
  ["この映画の製作には時間がかかった。", "「映画の製作」（せいさく）指電影的製作，本句表示製作這部電影花了不少時間。「機械を製作する」則指製造機械。"],
  ["部屋がきれいに片付いた。", "「部屋が片付く」（かたづく）指房間收拾整齊。「仕事が片付く」是工作做完，「問題が片付く」則是問題解決。"],
  ["犬が知らない人に吠えた。", "「犬が吠える」（ほえる）指狗吠叫。「風が吠える」把強風的聲音比喻成咆哮，形容人時也可帶有大吼大叫的語氣。"],
  ["台風が日本列島に接近している。", "「台風が接近する」（せっきんする）表示颱風逐漸靠近。「両者の意見が接近する」表示兩方的看法逐漸接近，「相手に接近する」也可指試著拉近關係。"],
  ["地図の符号を確かめた。", "「地図の符号」（ちずのふごう）指地圖上的符號。數學中的「正負の符号」則指表示正數或負數的正負號。"],
  ["氷を細かく砕いた。", "「氷を砕く」（くだく）指把冰弄碎。「希望を砕く」比喻粉碎希望。「かみ砕いて説明する」則是把難懂的內容說得淺顯易懂。"],
  ["説明書を見て棚を組み立てた。", "「棚を組み立てる」（くみたてる）指把零件組裝成架子。「文章を組み立てる」則指安排句子或段落，讓整篇文章有條理。"],
  ["車のドアが凹んでしまった。", "「車のドアが凹む」（へこむ）表示車門往裡凹陷。口語的「失敗して凹んだ」則表示因失敗而沮喪。"],
  ["新しい方法を取り入れた。", "「方法を取り入れる」（とりいれる）是採用方法。「洗濯物を取り入れる」指把晾在外面的衣物收進來，「稲を取り入れる」則指收割稻穀。"],
  ["水でジュースを薄めた。", "「水で薄める」（うすめる）在本句指加水把果汁稀釋。「印象を薄める」則指讓某種印象淡化。"],
  ["北極の氷が減っている。", "「北極」（ほっきょく）可指地理上的北極點，也可泛指周圍的北極地區。「北極の氷」在談氣候時通常指北極地區的冰。"],
  ["この作家の文体は独特だ。", "「作家の文体」（さっかのぶんたい）指作家寫作時形成的文風。「文語体」和「口語体」則是用來區分文章語言形式的文體名稱。"],
  ["生活水準が向上した。", "「生活水準」（せいかつすいじゅん）指生活達到的程度。「河川の水準」在談測量時可指水面的高度，日常更常說「水位」（すいい）。"],
  ["彼は頼もしい仲間だ。", "「頼もしい仲間」（たのもしいなかま）指讓人覺得可靠的同伴。「頼もしい若手」也可用來稱讚年輕人令人期待、有前途。"],
  ["看板が右に傾いている。", "「右に傾く」（みぎにかたむく）指向右傾斜。「日が傾く」表示太陽西斜，「賛成に傾く」表示逐漸傾向贊成，「経営が傾く」則表示經營狀況轉差。"],
  ["昆虫の標本を集めた。", "「昆虫の標本」（こんちゅうのひょうほん）是在觀察或研究時用的昆蟲標本。統計中的「標本」則指從母體抽出的樣本。"],
  ["西暦二千年に生まれた。", "「西暦二千年」（せいれきにせんねん）指西元兩千年。「西暦で書く」是用西元紀年書寫，和使用「令和」等日本年號相對。"],
  ["彼は障害を乗り越えて成功した。", "「障害を乗り越える」（しょうがいをのりこえる）在本句指克服阻礙。「聴覚障害」指聽覺方面的障礙，「障害物競走」則是賽程中需要跨越障礙物的競賽。"],
  ["紙の屑をごみ箱に入れた。", "「紙の屑」（かみのくず）指紙張剩下的碎屑。本詞用於人時是強烈的貶稱，例如「人間の屑」是侮辱人的說法。"],
  ["何事にも順序がある。", "「順序」（じゅんじょ）指事情的先後次序。「到着した順序」是抵達的先後順序，「順序を踏む」則指依必要的步驟進行。"],
  ["彼らは南極を探検した。", "「南極」（なんきょく）可指地理上的南極點，也可指以南極點為中心的一帶。和「探検する」搭配時，通常在談南極地區的探險。"],
  ["客席はほぼ満員だった。", "「客席」（きゃくせき）是供觀眾坐的位置，所以例句表示觀眾席幾乎坐滿。「客席が笑いに包まれた」則從座位引申到坐在那裡的觀眾。"],
  ["電池を新しいものに替える。", "「替える」（かえる）表示換掉原來使用的人或物。「電池を新しいものに替える」是換上新電池，「選手を替える」則是更換上場的選手。"],
  ["方程式の答えを求めなさい。", "「方程式」（ほうていしき）在本句是數學用語，「答えを求める」是求出使等式成立的解。「成功の方程式」則比喻達成成功的一套方法。"],
  ["新しい路線が開通した。", "「路線が開通する」（かいつうする）在本句指新路線開始通車。「工事を終えて道路が再開通した」則表示道路施工完畢，重新開放通行。"],
  ["猫の頭を撫でた。", "「頭を撫でる」（なでる）指用手輕輕摸頭。「髪を撫でつける」則指把髮絲往下順平，重點在將頭髮整理服貼。"],
  ["玉ねぎを細かく刻んだ。", "「玉ねぎを刻む」（きざむ）是把洋蔥切碎。「石に文字を刻む」是把文字刻在石頭上，「リズムを刻む」是打出節拍，「心に刻む」則指銘記在心。"],
  ["畑に種を撒いた。", "「種を撒く」（まく）是把種子撒開，也可寫作「種をまく」。「チラシをまく」指散發傳單，「追っ手をまく」則指甩掉追蹤自己的人。"],
  ["料理が出来上がった。", "「料理が出来上がる」（できあがる）是料理完成、可以上桌。飲酒場合說某人「すっかり出来上がっている」，則帶有口語調侃，意思是他已經喝醉了。"],
  ["朝早く出掛けた。", "「朝早く出掛ける」（でかける）指一早出門。「ちょうど出掛けるところだ」則表示正準備要出門。"],
  ["ご飯を茶碗に盛った。", "「ご飯を盛る」（もる）是把飯盛進碗裡。「土を盛る」指把土堆高，「薬を盛る」可指給人下藥。「話を盛る」則是把事情講得比實際情況誇張。"],
  ["摩擦でマッチに火がつく。", "「摩擦」（まさつ）在本句指火柴與火柴盒表面擦過而產生的摩擦。「意見の違いから摩擦が起きる」則用來比喻意見不同引發的衝突。"],
  ["お茶を盆に載せて運んだ。", "「盆に載せる」（ぼんにのせる）指放在托盤上。「盆に帰省する」則指在日本盂蘭盆節期間返鄉。"],
  ["この像は銅でできている。", "「銅」（どう）在本句指銅這種金屬。「銅を獲得した」若是在報導比賽成績，「銅」可作「銅メダル」（銅牌）的簡稱。"],
  ["この土地は水がよく湧く。", "「水が湧く」（わく）是地下水湧出。「勇気が湧く」則是比喻心中湧起勇氣，「涙が湧く」是淚水湧上來。"],
  ["二本のロープを繋げた。", "「ロープを繋げる」（つなげる）指把繩子接在一起。「電話を担当者に繋げる」則指把電話轉接給承辦人。"],
  ["人気が頂点に達した。", "「人気が頂点に達する」（ちょうてんにたっする）表示人氣達到最高點。「山の頂点」可指山的最高處，「三角形の頂点」則是在幾何中相鄰兩邊的交點。"],
  ["準備がすべて整った。", "「準備が整う」（ととのう）表示準備就緒。「服装が整う」可以形容衣著整理好，「条件が整う」表示所需條件已經具備。"],
  ["セメントが固まるまで待ってください。", "「セメントが固まる」（かたまる）是水泥硬化。「方針が固まる」指方針確定，「人が入口に固まる」則指人們聚在入口。"],
  ["峠を越えると村が見えた。", "「峠を越える」（とうげをこえる）在本句是越過山路的最高處。「暑さは峠を越えた」則比喻最熱的時期已經過去。"],
  ["彼の新しい事業は成功しました。", "「新しい事業」（あたらしいじぎょう）在本句可指開展的新業務。「公共事業」則指為公共目的推動的建設或其他計畫。"],
  ["敵は攻撃を開始しました。", "「攻撃を開始する」（こうげきをかいしする）在本句指敵方開始進攻。「発言を攻撃する」可表示抨擊對方的言論，「サイバー攻撃」則是透過電腦或網路發動的攻擊。"],
  ["この門は自由に出入りできる。", "「門を出入りする」（でいりする）是從這道門進出。「店に出入りする」也可指經常造訪店家，「お金の出入り」則指金錢的收入和支出。"],
  ["彼女とは昔から親しい。", "「彼女とは親しい」（したしい）表示和她關係親近。「耳に親しい言葉」則形容經常聽見、覺得熟悉的話語。"],
  ["東京までの片道切符を買った。", "「片道」（かたみち）指去程或回程的其中一程。「片道切符」是單程票，購票時單說「片道」也可指單程票。"],
  ["彼女は語学の才能がある。", "「語学の才能」（ごがくのさいのう）指學習語言的天分，常指學外語。「語学」也可指研究語言的學問。"],
  ["部屋のコーナーに本棚がある。", "「部屋のコーナー」是房間的角落。「番組の料理コーナー」是節目中的料理單元，「売り場の文具コーナー」則指賣場的文具區。"],
  ["この英文を訳してください。", "「この英文」（えいぶん）指這個英文句子或這段英文。「英文科」用於科系名稱時，也可能是「英文学科」的簡稱，指研讀英語文學等內容的科系。"],
  ["彼は自分が正しいと思い込んでいる。", "「自分が正しいと思い込む」（おもいこむ）指深信自己是對的，常帶有先入為主的語氣。「一度やると思い込んだら譲らない」則表示一旦認定要做某事就不肯改變心意。"],
  ["この量で足るだろうか。", "「この量で足る」（たる）表示這個分量夠用。「信頼に足る人」中的「～に足る」則表示值得，可譯為「值得信賴的人」。"],
  ["彼の顔は日焼けで真っ黒になった。", "「真っ黒」（まっくろ）表示黑得很深。本句中的「日焼けで真っ黒」是曬得很黑。「すすで真っ黒」則形容被黑煙或煙灰弄得漆黑。"],
  ["非常食として缶詰を買い置きしている。", "「缶詰」（かんづめ）指裝在罐子裡保存的食物。口語的「ホテルに缶詰になって原稿を書く」則指待在旅館裡集中趕稿，幾乎沒辦法外出。"],
  ["差別は許されない。", "「差別」（さべつ）在本句指歧視或不公平待遇。「差別をなくす」是消除歧視。有些較舊或專門的表達也可用「差別」指區分或差異，需看語境。"],
  ["ゆっくり料理を味わった。", "「料理を味わう」（あじわう）指細細品嘗料理。「詩を味わう」是細細體會詩的意味，「苦しみを味わう」則表示親身經歷痛苦。"],
  ["彼は椅子から立ち上がった。", "「椅子から立ち上がる」（たちあがる）指從椅子上站起來。「立ち上がって行動する」表示挺身採取行動，「パソコンが立ち上がる」則表示電腦啟動。"],
  ["彼には時間の観念がない。", "「時間の観念」（じかんのかんねん）指對時間的概念或意識。「もう逃げられないと観念する」則表示認清逃不了，放棄掙扎。"],
  ["小さな包みが届いた。", "「包み」（つつみ）在本句指包起來的東西，可能是包裹。「お菓子を一包み買う」中的「一包み」則是以一包為單位計數。"],
  ["雪で山が真っ白になった。", "「真っ白」（まっしろ）在本句形容山被雪覆蓋，白成一片。「頭が真っ白になる」則比喻一時想不出任何事，例如緊張到腦中一片空白。"],
  ["事故現場に急行した。", "「事故現場」（じこげんば）指事故實際發生的地點。「工事現場」是施工地點，「撮影現場」則指拍攝作業進行的地方。"],
  ["窓から中を覗いた。", "「覗く」（のぞく）在本句指從窗外往裡看。「望遠鏡を覗く」是透過望遠鏡看，「襟からシャツが覗く」則用來形容襯衫從領口露出一小部分。"],
  ["食塩水の濃度を測った。", "「濃度」（のうど）在本句指食鹽水含鹽的程度。數學集合論中的「集合の濃度」則指集合的基數，也就是用來比較集合大小的概念。"],
  ["電気の系統に問題がある。", "「電気の系統」（でんきのけいとう）指電氣設備彼此相連所構成的系統。「言語の系統」指語言的譜系關係，「同じ系統の色」則指同一類色調。"],
  ["肉の塊を煮込んだ。", "「肉の塊」（にくのかたまり）指一整塊肉。「人の塊」可指一群聚在一起的人，「好奇心の塊」則比喻某人充滿好奇心。"],
  ["鐘の響きが町に広がった。", "「鐘の響き」（かねのひびき）可指鐘發出後傳開的聲音。「柔らかい響き」則形容聲音的質感柔和，也可用來描述詞句聽起來的感覺。"],
  ["祖父が戦争の体験を語った。", "「体験を語る」（かたる）表示把經歷說給別人聽。「物語を語る」是講故事，「数字が実態を語る」則比喻數字反映了實際情況。"],
  ["誕生日を祝う。", "「誕生日を祝う」（いわう）是慶祝生日。「結婚を祝って品物を贈る」是送禮祝賀結婚，「新しい門出を祝う」則可表示祝福對方踏上新的人生階段。"],
  ["彼は次の社長の有力な候補だ。", "「社長の候補」（しゃちょうのこうほ）指可能當上社長的人。「開催地の候補」則是可能獲選的舉辦地點。"],
  ["これは公式発表です。", "「公式発表」（こうしきはっぴょう）是有關機構發布的正式消息。數學中的「公式」則指可套用的關係式，例如「面積を求める公式」。"],
  ["この券は全国で通用する。", "「券が通用する」（つうようする）表示票券能被接受、可以使用。「その言い訳は通用しない」則表示那個藉口行不通。"],
  ["ドアの隙間から風が入る。", "「ドアの隙間」（すきま）指門邊的縫隙。「予定の隙間」則指兩項行程之間的空檔。"],
  ["棒の先端を削った。", "「棒の先端」（ぼうのせんたん）是棒子的一端，通常指前端。「先端技術」則比喻走在發展最前面的技術。"],
  ["ファイルを圧縮して送った。", "「ファイルを圧縮する」（あっしゅくする）是縮小檔案所占的空間。「空気を圧縮する」是縮小空氣的體積，「経費を圧縮する」則指削減經費。"],
  ["古い寺を巡るのが好きだ。", "「寺を巡る」（めぐる）是走訪多座寺廟。「季節が巡る」指季節循環，「予算を巡る議論」則指圍繞預算展開的討論。"],
  ["子どもに服を着せた。", "「服を着せる」（きせる）是替別人穿上衣服。「ぬれぎぬを着せる」則是慣用說法，表示讓人蒙受莫須有的罪名。"],
  ["彼は二つの国籍を持つ。", "「国籍」（こくせき）在本句指個人依法具有的國籍。「船の国籍」則指船舶依法登記所屬的國家。"],
  ["彼女は地味な色を好む。", "「地味な色」（じみないろ）指不鮮豔、不顯眼的顏色。「地味な仕事」則可形容不太受注目、往往需要默默完成的工作。"],
  ["説明がくどくて眠くなる。", "「説明がくどい」指解釋反覆冗長。「味がくどい」則形容味道過濃、容易膩，「くどい配色」可形容色彩太過濃重。"],
  ["彼は部長と課長を兼ねている。", "「部長と課長を兼ねる」（かねる）指同時擔任兩個職務。「書斎を兼ねる部屋」指兼作書房的房間。接在動詞後的「お答えしかねます」則是客氣地表示無法回答。"],
  ["リポートを提出した。", "「リポートを提出する」指繳交書面報告。「現地からリポートする」則指從現場發回報導。"],
  ["裏山に竹が生えている。", "「竹」（たけ）在本句指竹子。在「松・竹・梅」三個等級的標示中，「竹」通常是中間等級。"],
  ["忙しいので誘いを断った。", "「誘いを断る」（さそいをことわる）在本句指謝絕邀約。「上司に断って席を外す」中的「断る」則指事先向主管告知一聲或徵得同意。"],
  ["最近、景気が悪い。", "「景気が悪い」（けいきがわるい）指經濟狀況不佳。「景気のいい話」依情境則可指令人振奮的消息或談起來很有氣勢的話。"],
  ["雨で崖が崩れた。", "「崖が崩れる」（くずれる）指崖壁崩塌。「姿勢が崩れる」表示姿勢走樣，「天気が崩れる」則表示天氣轉壞。"],
  ["必要な書類を揃えた。", "「書類を揃える」（そろえる）指把所需文件備齊。「靴を揃える」可指把鞋排整齊，「服の色を揃える」則指統一服裝的顏色。"],
  ["正座で足がしびれた。", "「足がしびれる」在本句指跪坐後腿腳發麻。「電気に触れてしびれる」可形容受到電刺激後發麻。「演奏にしびれる」是口語，表示被演出深深打動。"],
  ["二本の川がここで合流する。", "「川が合流する」（ごうりゅうする）表示水流在某處匯合。「駅で友人と合流する」則指在車站和朋友會合。"],
  ["針金を曲げる。", "「針金を曲げる」（まげる）指把鐵絲扳彎。「事実を曲げる」則是歪曲事實，「信念を曲げる」指改變自己原先堅持的信念。"],
  ["邪魔しないでください。", "「邪魔する」（じゃまする）指打擾或妨礙，例句是請對方別打擾。「お邪魔します」則是到訪別人家或進入對方空間時的客套話。"],
  ["客がどっと押し寄せた。", "「客がどっと押し寄せる」是客人一下子大量湧來。「どっと笑いが起きる」表示突然爆出一陣笑聲，「疲れがどっと出る」則形容疲憊一下子湧上來。"],
  ["なにしろ人が多すぎる。", "「なにしろ」在本句引出說話者認為最關鍵的理由，可譯為「畢竟人太多了」。「なにしろ急いでいたので」也以「なにしろ」強調接下來解釋的原因。"],
  ["荷物を車に載せた。", "「荷物を車に載せる」（のせる）是把東西放到車上。「記事を新聞に載せる」指刊登新聞文章。讓人搭車時則常寫作「人を車に乗せる」。"],
  ["庭に球根を埋めた。", "「球根を埋める」（うめる）是把球根埋在土裡。「穴を埋める」是把洞填平，「不足分を埋める」則指補足缺少的部分。"],
  ["この道は駅に繋がっている。", "「駅に繋がる」（つながる）表示路通往車站。「電話が繋がる」指電話接通，「努力が成果に繋がる」則表示努力帶來成果。"],
  ["昼食に丼を食べた。", "「丼」（どんぶり）可指盛飯用的深碗，也可指把配料放在米飯上的丼飯。搭配「食べる」時，這裡指吃丼飯。"],
  ["一日歩いてくたびれた。", "「歩いてくたびれる」是走到身體疲累。「くたびれた靴」則指穿久了而顯得破舊的鞋，「待ちくたびれる」是等得疲倦。"],
  ["メンバーが全員揃った。", "「全員が揃う」（そろう）表示大家都到齊。「必要な道具が揃う」是所需工具備齊，「靴の向きが揃う」則表示鞋子的朝向一致。"],
  ["食べすぎて消化が悪い。", "「消化」（しょうか）在本句指人體消化食物。「情報を消化する」比喻理解並吸收資訊，「日程を消化する」則指依次完成排定的事項。"],
  ["新聞は世論を反映する。", "「世論を反映する」（はんえいする）是呈現民眾的看法。「設定の変更が反映された」表示變更已套用，系統狀態或畫面已顯現更新。"],
  ["木の葉が水に浮いている。", "「水に浮く」（うく）指漂浮在水上。「交通費が浮く」則表示省下一筆交通費，「周囲から浮く」可比喻與周圍格格不入。"],
  ["庭に草が生えてきた。", "「草が生える」（はえる）是長出草。「歯が生える」則指牙齒長出來，「歯が生えてきた」常用來描述嬰兒開始長牙。"],
  ["魚を揚げて食べた。", "「魚を揚げる」（あげる）指用油炸魚。「たこを揚げる」在放風箏的情境中是把風箏放上天空，「荷を陸に揚げる」則指把貨卸到岸上。"],
  ["ビールを冷蔵庫で冷やした。", "「ビールを冷やす」（ひやす）是在冰箱裡把啤酒冰涼。「頭を冷やす」比喻讓自己冷靜。「肝を冷やす」則是嚇出一身冷汗的慣用說法。"],
  ["彼はぶつぶつ言っている。", "「ぶつぶつ言う」指低聲嘀咕或抱怨。用在外觀時，「肌にぶつぶつができる」則指皮膚上起了小疙瘩。"],
  ["この話は昔から伝わっている。", "「昔から伝わる」（つたわる）表示從以前流傳下來。「気持ちが伝わる」表示心意被對方感受到，「熱が伝わる」則指熱從一處傳到另一處。"],
  ["一旦決めたら最後までやる。", "「一旦決めたら」（いったんきめたら）表示一旦做了決定。「一旦作業を中止する」則表示暫時停止工作，之後可能恢復。"],
  ["授業中にふざけるな。", "「授業中にふざけるな」是在制止上課時嬉鬧。「ふざけて言った」表示只是開玩笑說的。「ふざけるな！」也可用來斥責對方的話太離譜。"],
  ["改めてご連絡いたします。", "「改めてご連絡いたします」（あらためて）表示稍後或另找時間再聯絡。「改めてお礼を申し上げます」是鄭重再致謝，「改めて難しさを感じた」則表示重新體會到事情的難度。"],
  ["この語のアクセントはどこですか。", "「語のアクセント」在日語發音中常指音高變化的位置。「アメリカ英語のアクセント」可指美式英語的口音，「赤い色をアクセントにする」則指用紅色作點綴。"],
  ["私はいつも手帳を持ち歩いている。", "「手帳」（てちょう）在本句指隨身記事本。「母子健康手帳」則指記錄母親及嬰幼兒健康狀況的手冊。"],
  ["余計なことを言うな。", "「余計なこと」（よけいなこと）是多餘或不該插手的事，本句是在勸人別說多餘的話。「余計に心配になる」則表示變得更加擔心。"],
  ["それはおめでたい話ですね。", "「おめでたい話」在本句指值得祝賀的消息。若對人說「おめでたい人だ」並帶有挖苦語氣，則可指對方太天真、容易相信別人。"],
  ["荷物をロッカーに預けた。", "「荷物を預ける」（あずける）指把行李交付保管或放進寄物櫃。「店を人に預ける」指把店交由人管理，「背中を壁に預ける」則指把背靠在牆上。"],
  ["机を壁の方に寄せた。", "「机を壁の方に寄せる」（よせる）指把桌子往牆邊移。「意見を寄せる」是把意見送交給對方，「信頼を寄せる」則表示對某人抱有信任。"],
  ["彼は動作がゆっくりだ。", "「動作」（どうさ）在本句指人的身體動作。「機械の動作を確認する」則是確認機器是否正常運轉。"],
  ["空いた欄を埋めなさい。", "「空いた欄」（あいたらん）指表格中還沒填寫的欄位。「新聞の投書欄」則指報紙刊登讀者來信的版面。"],
  ["この椅子のばねが弱い。", "「椅子のばね」指椅子裡提供彈力的彈簧。「足にばねがある」可形容腿部有彈跳力，「失敗をばねにする」則比喻把失敗化為進步的動力。"],
  ["国際機関で働きたい。", "「国際機関」（こくさいきかん）是國際性機構。「蒸気機関」指利用蒸氣作動的引擎，「交通機関」則指提供運輸的交通系統或工具。"],
  ["その映画はとても退屈だった。", "「映画が退屈だ」（たいくつだ）表示電影乏味。「待っている間に退屈する」則是人在等待時覺得無聊。"],
  ["爪を短く切った。", "「爪」（つめ）在本句指指甲。「猫の爪」指貓爪，「琴の爪」則指彈琴時用來撥弦的撥具。"],
  ["毎日家事を手伝っています。", "「家事」（かじ）在本句指做飯、清掃等家務。「家事事件」則是司法用語，指涉及婚姻、親子等家庭關係的案件。"],
  ["厚さは三ミリです。", "「三ミリ」在測量厚度時指三毫米。「ミリ」也可接在其他單位前，例如「ミリリットル」是毫升，前綴表示千分之一。"],
  ["新しい技術の開発が進んでいる。", "「技術の開発」（かいはつ）指研發新技術。「資源の開発」則指開發利用資源。"],
  ["新しい学年が四月に始まります。", "「新しい学年」（がくねん）在本句指新的學年度。「学年が一つ上」則是在比較在校年級，表示高一個年級。"],
  ["机の角に足をぶつけた。", "「足をぶつける」指腳撞到東西。「壁にボールをぶつける」是把球扔向牆使它撞上牆面，「相手に怒りをぶつける」則是把怒氣發洩在對方身上。"],
  ["彼女はダイヤモンドの指輪をしている。", "「ダイヤモンドの指輪」是鑽石戒指。撲克牌裡的「ダイヤモンド」是方塊花色，棒球的「ダイヤモンド」則指壘包構成的菱形區域。"],
  ["駅の周辺に店が多い。", "「駅の周辺」（えきのしゅうへん）指車站附近。「周辺機器」則指和電腦搭配使用的周邊設備，例如印表機。"],
  ["雨で川の水があふれた。", "「川の水があふれる」指水量太大而溢出河道。「会場に人があふれる」形容會場擠滿了人，「自信にあふれる」則形容充滿自信。"],
  ["自転車が壁にぶつかった。", "「壁にぶつかる」在本句指自行車撞上牆壁。「意見がぶつかる」指意見衝突，「予定がぶつかる」指行程撞期，「難題にぶつかる」則指碰到難題。"],
  ["泥が靴にくっついた。", "「泥が靴にくっつく」表示泥黏在鞋上。「壁にくっついて立つ」是緊靠牆站著。口語中用於人也可表示總待在對方身邊。"],
  ["このパンはふわふわだ。", "「ふわふわ」在本句指麵包鬆軟。「羽がふわふわと漂う」則描寫羽毛輕飄飄地浮動。"],
  ["事業を拡大する。", "「事業を拡大する」（かくだいする）表示擴大事業規模。「画像を拡大する」是放大影像，「被害が拡大する」則是受害範圍或程度擴大。"],
  ["朝の空気がさわやかだ。", "「さわやか」在本句形容早晨空氣清新。「さわやかな声」可形容聲音清亮，聽起來令人舒暢。"],
  ["この製品は標準を満たす。", "「標準を満たす」（ひょうじゅんをみたす）指達到既定標準。「標準的な体格」則可指接近一般水準的體格。"],
  ["靴のひもをしっかり結んだ。", "「ひもを結ぶ」（むすぶ）是把繩帶打結。「契約を結ぶ」指締結契約，「二つの町を結ぶ道」則指連接兩座城鎮的道路。"],
  ["彼は最悪の事態を覚悟していた。", "「最悪の事態を覚悟する」（かくごする）是做好最壞情況的心理準備。「失敗を覚悟で挑戦する」則表示明知可能失敗，仍下決心嘗試。"],
  ["洗濯物を干す。", "「洗濯物を干す」（ほす）是晾衣服。「杯を干す」指喝乾杯中的飲料，「仕事を干される」則是口語，指被排擠而長時間沒工作可做。"],
  ["痛みで彼は思わずうなった。", "「痛みでうなる」指痛得忍不住呻吟。「エンジンがうなる」形容引擎發出低沉聲響，「見事な技にうなる」則是對出色的技藝發出讚嘆。"],
  ["子供の背がぐんぐん伸びる。", "「背が伸びる」（のびる）是身高增加。「ゴムが伸びる」指橡膠被拉長，「成績が伸びる」則表示成績進步。"],
  ["彼は私の手を強く握った。", "「手を握る」（にぎる）指用手握住對方的手。「権力を握る」比喻掌握權力，「すしを握る」則指用手捏製握壽司。"],
  ["どうかよろしくお願いします。", "「どうか」在本句加強懇求語氣，可譯為「拜託」。「行けるかどうか」裡的「かどうか」表示能不能去，「今日はどうかしている」則表示今天情況有點不對勁。"],
  ["何か飲み物はいかがですか。", "「何か飲み物」（なにかのみもの）表示某種飲料，本句是在問對方要不要喝點什麼。「何か変だ」則可譯為「總覺得有點不對勁」。"],
  ["行きは電車、帰りはバスにした。", "「行き」（いき）和「帰り」相對時，指去程。「東京行き」（とうきょういき）指開往東京，「行きの切符」則是去程車票。"],
  ["彼は地図の上の一点を指した。", "「地図の一点を指す」（さす）指用手指出地圖上的一個點。「この語は道具を指す」中的「指す」表示所指涉的對象。下將棋則常說「将棋を指す」。"],
  ["布の切れで袋を作った。", "「布の切れ」（ぬののきれ）指一小塊布。「パン一切れ」中的「切れ」用來數切下來的片或塊。「包丁の切れがいい」則形容菜刀鋒利、好切。"],
  ["合格の知らせが届いた。", "「合格の知らせ」（しらせ）指通知某人通過的消息。「虫の知らせ」則是慣用說法，指心中莫名浮現的預感。"],
  ["メニューを見せてください。", "「メニュー」在點餐時指菜單。「設定メニュー」是程式裡供選擇的設定選單，「練習メニュー」則指安排好的練習項目。"],
  ["切手のコレクションを見せた。", "「切手のコレクション」指收藏的一批郵票。時裝語境的「春夏コレクション」則指品牌推出的春夏系列服裝。"],
  ["どうせ間に合わないだろう。", "「どうせ間に合わない」可譯為「反正也來不及」，帶有認定結果難以改變的語氣。「どうせ行くなら、早めに出よう」則表示既然都要去，乾脆早點出發。"],
  ["おやすみなさい、また明日。", "「おやすみなさい」是睡前說的「晚安」。「明日はお休みです」則可表示明天休假，也可用於店家明天不營業的公告。"],
  ["部屋がめちゃくちゃだ。", "「部屋がめちゃくちゃだ」形容房間亂七八糟。「説明がめちゃくちゃだ」可指解釋毫無條理，口語的「めちゃくちゃ面白い」則用來強調非常有趣。"],
  ["いよいよ明日は試験だ。", "「いよいよ明日」表示期待或關注已久的時刻終於要到了。「雨はいよいよ強くなった」則表示雨勢變得越來越強。"],
  ["質問に対する答えが曖昧だ。", "「質問に対する答え」（たいする）是針對問題所作的回答。「前年に対する増加率」則表示和前一年相比的成長率。"],
  ["老いを感じるようになった。", "「老い」（おい）在本句指隨年齡增長而出現的變化。「老いも若きも」則用「老い」來指年長的人，整句表示無論老少。"],
  ["人の粗ばかり探すな。", "「人の粗を探す」（あらをさがす）是挑別人的毛病。「魚のあら」則指魚切片後剩下的頭、骨等部位。"],
  ["茶道の作法を習っている。", "「茶道の作法」（さどうのさほう）指茶道中應遵循的禮節與程序。「文章作法」則指寫文章的方法與規則。"],
  ["彼は意識を失った。", "「意識を失う」（いしきをうしなう）指失去知覺。「周りの視線を意識する」則是察覺到旁人的目光，並對此有所留意。"],
  ["太陽が東の空に昇る。", "「太陽が昇る」（のぼる）指太陽升起。「部長の座に昇る」則用於地位，指升到部長的職位。"],
  ["彼はその点を詳しく論じた。", "「詳しく論じる」（ろんじる）指詳細論述某個問題。「年齢を論じない」若出現在資格條件的語境中，則表示不以年齡為考量。"],
  ["この漢字の訓を覚えましょう。", "「漢字の訓」（かんじのくん）指用日語固有詞來讀漢字，也就是訓讀。「家訓」裡的「訓」則是訓誡，指家族中傳下來的教誨。"],
  ["明日の天気予報は曇りだ。", "「曇り」（くもり）在天氣預報中表示陰天。「眼鏡の曇り」則是眼鏡起霧後不清楚的狀態。"],
  ["彼の話を聞いて、一層やる気が出た。", "「一層」（いっそう）放在「やる気が出た」前，表示更有幹勁。「布を一層重ねる」中的「一層」則用來計算層數，表示再疊一層布。"],
  ["一体、何が起こったのですか？", "「一体」（いったい）在疑問句中加強追問語氣，可譯為「究竟」。「地域と一体になる」則表示與當地融為一體。"],
  ["私の願いは世界平和です。", "「願い」（ねがい）在本句指內心期盼實現的願望。「願いを聞き入れる」可指答應他人的請求，「休暇願い」則指請假的申請。"],
  ["彼の家族は代々農家だ。", "「代々農家」（だいだいのうか）指一家人世代務農。「古い農家を改修する」若在談建築，「農家」則可指農戶居住的房屋。"],
  ["その映像はとても美しい。", "「映像」（えいぞう）在本句指看得到的影像畫面。「記録映像」指為記錄而拍攝的影片，「頭に映像が浮かぶ」也可描寫腦中浮現畫面。"],
  ["人工衛星が地球の周りを回っている。", "「衛星」（えいせい）是繞行星運行的天體或人造物。月球是地球的天然衛星，例句的「人工衛星」則指人造並送入軌道的衛星。"],
  ["このコーヒーは味が濃い。", "「味が濃い」（こい）形容味道濃。「濃い青」是深藍色，「可能性が濃い」則表示某事發生的可能性很大。"],
  ["暑さで魚が腐ってしまった。", "「魚が腐る」（くさる）指魚腐壞。「組織が腐る」則比喻組織內部腐敗，「失敗して腐る」可指因失敗而消沉或自暴自棄。"],
  ["旅行のお土産を買った。", "「旅行のお土産」（おみやげ）指從旅行地帶回送人的伴手禮。「訪問先へのお土産」也可指登門拜訪時帶給主人的禮物。"],
  ["彼は陽気な人だ。", "「陽気な人」（ようきなひと）表示個性開朗。「暖かい陽気が続く」中的「陽気」則指天氣，意思是溫暖的天氣持續著。"],
  ["今年の梅雨は長かった。", "「梅雨」（つゆ）在本句指梅雨季，形容今年雨季較長。「梅雨の雨」指這段期間下的雨。「梅雨入り」則指進入梅雨季。"],
  ["二つの県の境に川が流れている。", "「県の境」（さかい）指相鄰兩縣之間的界線。「就職を境に生活が変わる」則以就業為時間上的分界，表示就業前後的生活不同。"],
  ["彼は緊張している。", "「緊張する」（きんちょうする）在本句指人心裡緊張。「両国間の緊張」指兩國關係緊繃，「筋肉の緊張」則指肌肉維持一定張力或收縮的狀態。"],
  ["家族の健康を願っている。", "「家族の健康を願う」（ねがう）表示盼望家人健康。「ご協力を願います」則是向對方提出請求，請對方協助。"],
  ["彼は独りで暮らしている。", "「独りで暮らす」（ひとりでくらす）指獨自生活，也可寫作「一人で暮らす」。「まだ独りだ」若在談感情或婚姻，則可表示仍是單身。"],
  ["先ず名前を書いてください。", "「先ず」（まず，常寫成假名「まず」）在本句表示先做第一步。「まず間違いない」則表示大致可以肯定，語氣接近「應該沒錯」。"],
  ["この皿は丸くて浅い。", "「丸い」（まるい）在本句形容盤子的輪廓是圓的。「性格が丸くなった」則是比喻性格變得溫和，不再那麼尖銳。"],
  ["彼は貯金をしている。", "「貯金をする」（ちょきんをする）是存錢，「貯金を下ろす」是提領存款。職業棒球新聞說「貯金が三つある」時，則是指勝場比敗場多三場。"],
  ["窓から海を眺めていた。", "「海を眺める」（ながめる）指從窗邊望著海。「ぼんやり写真を眺める」可指沒特別專注地看著照片，「傍から眺める」則表示從旁觀看。"],
  ["屋上から街を見下ろした。", "「屋上から見下ろす」（みおろす）表示從屋頂往下看。表示看不起別人時，日常常用另一個動詞「見下す」（みくだす）。"],
  ["公園で紙飛行機を飛ばした。", "「紙飛行機を飛ばす」（とばす）是讓紙飛機飛出去。「一行飛ばして読む」是跳過一行來讀，「車を飛ばす」則指開得很快。"],
  ["演奏が終わると拍手が起こった。", "「拍手」（はくしゅ）在本句指觀眾於演出結束後鼓掌。神社參拜時也有拍手的動作，這時常稱為「柏手」（かしわで）。"],
  ["彼の説明は具体性に欠けている。", "「具体性に欠ける」（かける）表示說明不夠具體。「茶碗のふちが欠ける」指碗沿缺了一角，「月が欠ける」則形容月亮的亮面逐漸變小。"],
  ["子どもが母親の袖を引っ張った。", "「袖を引っ張る」（ひっぱる）指用手拉袖子。「チームを引っ張る」比喻帶領團隊，「話を引っ張る」則可指把話題拖長。"],
  ["来月から新しい社員が加わる。", "「社員が加わる」（くわわる）在本句指新員工加入。「圧力が加わる」表示物體受到外加的壓力，「新しい機能が加わる」則指原有功能之外又增添一項。"],
  ["風車がゆっくり回転している。", "「風車が回転する」（かいてんする）指風車繞軸轉動。「頭の回転が速い」形容思考敏捷，「商品の回転が速い」則表示商品很快售出並補貨。"],
  ["裁判所が判決を下した。", "「判決を下す」（くだす）是法院作出判決。「命令を下す」則是下達命令。兩種用法都可用於有權作決定的一方。"],
  ["結び目がひとりでに解けた。", "「結び目が解ける」（とける）指繩結鬆開。「問題が解ける」表示問題有了解答，「緊張が解ける」則指緊張感消退。"],
  ["書類をクリップで留めた。", "「クリップで留める」（とめる）是用迴紋針把紙張固定住。「心に留める」比喻記在心裡、加以留意，「原形を留める」則指保留原本的形狀。"],
  ["川の流れが速い。", "「川の流れ」（かわのながれ）指河水流動。「人の流れ」指人群移動的方向或情形，「話の流れ」則指話題如何一步步展開。"],
  ["会社は新しい人を雇うことにした。", "「人を雇う」（やとう）指聘人工作。「船を雇う」也可表示付費租用船隻，重點在雇用或包用所需的人力或服務。"],
  ["机の上に地図を広げた。", "「地図を広げる」（ひろげる）是攤開地圖。「道路を広げる」指拓寬道路，「活動範囲を広げる」則指擴大活動範圍。"],
  ["事故に遭った彼が気の毒だ。", "「気の毒だ」（きのどくだ）在本句表示同情遭遇事故的人。「わざわざ来てもらって気の毒だ」則表示給對方添了麻煩，心裡過意不去。"],
  ["今日の海は穏やかだ。", "「海が穏やかだ」（おだやかだ）表示海面平靜。「穏やかな人」形容個性溫和，「穏やかな口調」則指語氣和緩。"],
  ["彼女はとても賢い学生だ。", "「賢い」（かしこい）在本句形容學生聰明。「賢い選択」指明智的選擇。「賢い子だね」也可用來稱讚孩子懂事。"],
  ["シャツにアイロンをかける。", "「シャツにアイロンをかける」是用熨斗燙襯衫。整理頭髮用的「ヘアアイロン」則可指離子夾、捲髮棒等加熱工具。"],
  ["犯人はすぐに捕まった。", "「犯人が捕まる」（つかまる）是犯人被抓到。「タクシーが捕まる」則指叫得到計程車。用手抓住扶手時常寫作「手すりに掴まる」。"],
  ["あの店の看板はとても大きい。", "「店の看板」（みせのかんばん）在本句指實體招牌。「看板商品」是店家的主打商品。店家說「今日はもう看板です」時，則可表示今天已經打烊。"],
  ["警官が犯人を追っている。", "「犯人を追う」（おう）指追捕犯人。「流行を追う」是跟隨流行，「仕事に追われる」則是忙於工作，彷彿被一件件工作追著跑。"],
  ["時計を正しい時刻に合わせた。", "「時刻に合わせる」（あわせる）指把時鐘調到正確時間。「答えを合わせる」是核對答案，「手を合わせる」則指雙手合在一起。"],
  ["彼女は髪を伸ばしている。", "「髪を伸ばす」（のばす）指把頭髮留長。「腕を伸ばす」是伸直手臂，「生地を伸ばす」是把麵團擀開。談延後日期時常寫「日程を延ばす」。"],
  ["朝は濃い霧が出ていた。", "「濃い霧」（こいきり）在本句指空氣中水滴形成的濃霧。「霧吹き」則是把水噴成細小水滴的器具，形成的水霧也可用「霧」來形容。"],
  ["週末に公園でピクニックをした。", "「ピクニック」指到戶外遊玩，常會帶食物在戶外用餐。例句說週末到公園野餐。「ピクニックに出かける」也可著重出門郊遊。"],
  ["下りの電車は空いていた。", "「下り」（くだり）在鐵路語境中指下行方向，和「上り」相對。「下り坂」是下坡，「川下り」則指沿河順流而下。"],
  ["受付の係に聞いてください。", "「受付の係」（かかり）在本句指負責接待的工作人員。「係を決める」則可指分派各人要負責的工作。"],
  ["月日が経つのは早い。", "「月日が経つ」（つきひがたつ）是歲月流逝。用於描寫天體時，「月日」也可以合指月亮與太陽。"],
  ["机の端にコップを置かないで。", "「机の端」（つくえのはし）指桌子邊緣。「川の端から端まで」是從河的一端到另一端。"],
  ["彼はしきりに時計を見ていた。", "「しきりに時計を見る」指頻頻看錶。「しきりに誘う」也可形容一再力邀，除了頻率，也帶有積極、熱切的語氣。"],
  ["彼は帽子を被って出かけた。", "「帽子を被る」（かぶる）是把帽子戴在頭上。「泥をかぶる」可指沾上一身泥。「責任をかぶる」可指承擔責任，「予定がかぶる」是口語的行程重疊。"],
  ["災害を防ぐための対策が必要です。", "「災害を防ぐ」（ふせぐ）指防止災害發生或造成危害。「攻撃を防ぐ」則指抵擋已出現或即將發生的攻擊。"],
  ["このズボンは少し緩い。", "「ズボンが緩い」（ゆるい）是褲子穿起來有點鬆。「緩い坂」是坡度平緩，「規則が緩い」則表示規定寬鬆。"],
  ["芝居の幕が上がった。", "「幕が上がる」（まくがあがる）在本句指舞台幕布升起。「第二幕」中的「幕」用來分段，「幕を閉じる」則可比喻活動或事情告一段落。"],
  ["彼は何も言わずに去った。", "「何も言わずに去る」（さる）表示一語不發地離開。「夏が去る」指夏天已過，「去る四月」指已經過去的四月，「忘れ去る」則表示完全忘記。"],
  ["木の上に鳥の巣がある。", "「鳥の巣」（とりのす）指鳥築的巢。「クモの巣」則通常指蜘蛛結的網。「悪の巣」也可比喻壞人聚集的地方。"],
  ["彼は重い荷物を担いだ。", "「荷物を担ぐ」（かつぐ）指把東西扛在肩上。「候補に担ぐ」指把人推舉為候選人。「縁起を担ぐ」則指為了討吉利而講究某些做法。"],
  ["この寮には門限の決まりがある。", "「門限の決まり」（きまり）是宿舍規定的最晚返宿時間。「いつもの決まり」可指平常遵循的慣例，「きまりが悪い」則是感到尷尬、難為情。"],
  ["規則に従うのは当然だ。", "「規則に従う」（したがう）是遵守規定。「案内人に従って進む」是跟著嚮導走，「川に従って歩く」則是沿著河流走。"],
  ["私のことは構わないでください。", "「私のことは構わないで」（かまわないで）意為不用理我或不用顧慮我。「遅れても構わない」則表示晚到也沒關係，「子どもを構う」可指陪孩子玩或逗孩子。"],
  ["風邪で喉が痛い。", "「喉が痛い」（のどがいたい）指喉嚨疼痛。「自慢の喉を披露する」中的「喉」則指歌喉，整句表示一展得意的歌聲。"],
  ["彼らは一家で海外に移住した。", "「一家で」（いっかで）表示全家一起。「一家を成す」除了可指建立家庭，也可指在某個領域形成自成一家的風格。"],
  ["明後日、大阪へ行きます。", "「明後日」（あさって）在本句指後天。「明後日の方向を向く」則是慣用說法，表示朝向完全不對的方向。"],
  ["この木は根が深い。", "「木の根」（きのね）是植物吸收水分並固定在土裡的部分。「歯の根」指牙根，「問題の根」則比喻問題的根源。"],
  ["この紙を縦に半分に折る。", "「縦に折る」（たてにおる）指沿紙張的縱向摺疊。「縦の関係」則是上下層級的關係。談桌面尺寸時，「縦」也可指前後方向的長度。"],
  ["畑で野菜を育てている。", "「畑」（はたけ）在本句指種植蔬菜的田地。「研究畑の人」中的「畑」是比喻，指研究方面的專業或工作領域。"],
  ["温泉の近くに宿を取った。", "「宿を取る」（やどをとる）指安排或訂好住宿處。「宿」也可泛指暫時住的地方，例如「友人の家を宿にする」是把朋友家當作落腳處。"],
  ["学生割引がありますか？", "「学生割引」（がくせいわりびき）指學生可享有的折扣。「二割引」則具體表示從原價減去兩成，也就是打八折。"],
  ["料理するときはエプロンをする。", "「エプロンをする」在做菜時指穿圍裙。機場的「エプロン」則指供飛機停放、上下旅客或裝卸貨物的停機坪。"],
  ["坂を上って息が切れた。", "「息が切れる」（いきがきれる）表示喘得接不上氣。「息を吸う」是吸氣，「二人の息が合う」則比喻兩人配合得很有默契。"],
  ["空いた缶はここに捨ててください。", "「空いた缶」（かん）在本句指空金屬罐。「ツナ缶」則可以指罐裝鮪魚，包括裡面的食物。"],
  ["強い風が木を倒した。", "「木を倒す」（たおす）指使樹倒下。「強敵を倒す」是打敗強敵，「政権を倒す」則指推翻政權。"],
  ["本来、この会議は昨日行われる予定でした。", "句首的「本来」（ほんらい）在本句指原先的安排。「本来の目的」則指原有或根本的目的。"],
  ["これはあくまで目安です。", "「目安」（めやす）指可用來參考的大致基準。可指「時間の目安」這類粗估，也可指「選ぶときの目安」這類判斷依據。"],
  ["専門用語を理解するのは難しい。", "「専門用語」（せんもんようご）指某個領域使用的專門詞彙。「用語を統一する」則可指統一稱呼或文件中的用詞。"],
  ["私は今日、家で留守番です。", "「留守番」（るすばん）在本句指別人不在時留在家裡照看。「留守番を頼む」是拜託人看家，「留守番役」則指負責照看的人。"],
  ["この地域は交通が発達している。", "「交通が発達している」（はったつしている）表示交通系統發展得很完善。「子どもの発達」指身心各方面的發展，「低気圧が発達する」則指低氣壓系統增強。"],
  ["この歌は節が覚えやすい。", "「歌の節」（ふし）指曲調，所以這句是說旋律好記。「竹の節」是竹莖一段段之間突起的節，「指の節」則指手指的關節。"],
  ["仕事はだいたい終わりました。", "「だいたい終わった」表示工作大致完成。「だいたい一時間」表示約一個小時，「だいたい、なぜ急ぐのか」中的「だいたい」則用來追問根本原因。"],
  ["作業は完了しました。", "「作業が完了する」（かんりょうする）表示工作已經做完。文法中的「完了」則用來談動作或狀態已經完成的表達方式。"],
  ["この生地の見本を見せてください。", "「生地の見本」（みほん）指供人查看材質或顏色的布料樣品。「書き方の見本」則指可以參照的寫法範例。"],
  ["去年、車の免許を取った。", "「車の免許」（めんきょ）在本句指駕照。「教員免許」則指任教所需的教師資格證。"],
  ["引き出しの奥に鍵があった。", "「引き出しの奥」（おく）指抽屜裡面離開口較遠的地方。「心の奥」則比喻內心深處。"],
  ["インターネット接続が不安定です。", "「インターネット接続」（せつぞく）指網路連線。「列車の接続」指班次之間的轉乘銜接，「接続詞」則是連接詞。"],
  ["このきのこには毒がある。", "「毒」（どく）在本句指菇類含有的有毒成分。「毒のある言葉」則形容話語帶有惡意或尖刻的諷刺。"],
  ["同じ料理では飽きてしまう。", "「料理に飽きる」（あきる）指太常吃同樣的料理，吃到膩。「同じ作業に飽きる」則指反覆做同樣的工作而感到厭倦。"],
  ["道を渡る前に左右を確かめる。", "「左右を確かめる」（さゆうをたしかめる）是確認左邊和右邊的情況。「天候が結果を左右する」中的「左右する」則指影響結果。"],
  ["庭に大きな松がある。", "「松」（まつ）在本句指松樹。用「松・竹・梅」標示三種等級時，「松」通常是最高的一級。"],
  ["野に花が咲いている。", "「野」（の）在本句指開闊的野地。「野の花」指野外長的花，「野うさぎ」則指野生的兔子。"],
  ["走ったあと、心臓が激しく鼓動した。", "「心臓」（しんぞう）在本句指跳動的心臟。「都市の心臓部」則比喻城市最核心的區域。"],
  ["息子の嫁は看護師です。", "「息子の嫁」（むすこのよめ）在本句指兒媳。「花嫁」指新娘，「うちの嫁」在口語中也有人用來稱自己的妻子。"],
  ["医者は禁煙を勧めた。", "「禁煙を勧める」（すすめる）是建議對方戒菸。「お茶を勧める」是請對方喝茶。推薦特定書籍或人選時，也常寫作「薦める」。"],
  ["歯医者で虫歯を抜いた。", "「虫歯を抜く」（ぬく）指拔掉蛀牙。「手順を一つ抜く」是省略一道步驟，「タイヤの空気を抜く」是放掉輪胎裡的氣，「最後までやり抜く」則是堅持做到底。"],
  ["この虫は葉を食う。", "「葉を食う」（くう）指昆蟲啃食葉片。「食っていく」在人身上可指維持生計，「時間を食う」則是花掉很多時間。"],
  ["ハンドルを右に回してください。", "「ハンドルを回す」（まわす）是轉動方向盤或把手。「書類を回す」可指把文件依序傳給別人，「店を回す」則可指維持店面日常營運。"],
  ["コップに氷を入れた。", "「氷」（こおり）在本句指放進杯中的冰塊。點心店若把「氷」寫在旗子或招牌上，常是在表示有賣刨冰。"],
  ["熱があるので内科を受診しました。", "「内科」（ないか）可指內科這門醫療專科，也可指醫院的內科部門。「内科を受診する」在本句指去看內科。"],
  ["彼は眼鏡を外して目をこすった。", "「眼鏡を外す」（はずす）指摘下眼鏡。「席を外す」是暫時離開座位，「的を外す」是沒打中目標，「予想を外す」則是猜錯。"],
  ["彼は手を振って別れを告げた。", "「手を振る」（ふる）指揮手，本句是揮手道別。「塩を振る」是撒鹽，「漢字にふりがなを振る」是標注讀音，「相手を振る」則可指拒絕對方的感情。"],
  ["駅で道を聞いた。", "「道を聞く」（きく）是詢問怎麼走，「を」標示詢問的內容。「音楽を聴く」常用「聴」表示專心聆聽。「忠告を聞く」則可指接受並聽從忠告。"],
  ["会議でその問題を取り上げた。", "「問題を取り上げる」（とりあげる）指把問題提出來討論。「提案を取り上げる」也可指採納提案，「おもちゃを取り上げる」則可指把玩具拿走或沒收。"],
  ["今日は暖かい日です。", "「暖かい日」（あたたかいひ）指氣候溫暖的一天。「暖かい色」指有暖意的色調。形容飲料溫熱或態度溫情時，則常寫「温かい」。"],
  ["石の段を一つずつ上がった。", "「石の段」（いしのだん）指石階。「棚の上の段」指架子較高的一層，「柔道二段」表示柔道的段位，「九九の五の段」則指五的乘法表。"],
  ["この料理は手間がかかる。", "「手間がかかる」（てまがかかる）表示做起來費時費力。「手間を省く」指省下時間與工夫，「手間賃」則是支付給做工者的工錢。"],
  ["駅の手前でバスを降りた。", "「駅の手前」（てまえ）指沿行進方向還沒到車站的地方。「人に約束した手前」則表示顧及自己已作的承諾，因此有些事不能隨意改口。"],
  ["会議で新しい案を出した。", "「新しい案を出す」（あんをだす）指提出新方案。「契約書の案」則指尚未定稿的契約草案。"],
  ["買った物を袋に入れた。", "「袋」（ふくろ）在本句指裝東西的袋子。「みかんの袋」則可指包住一瓣橘子果肉的薄膜。"],
  ["朝、先生に挨拶した。", "「先生に挨拶する」（あいさつする）在本句指向老師打招呼。「式で挨拶する」指在典禮上致詞，「引っ越しの挨拶」則可指搬家後登門向鄰居致意。"],
  ["家の鍵が見つからない。", "「家の鍵」（いえのかぎ）在本句指找不到用來開門的鑰匙。「鍵をかける」是把門鎖上，「成功の鍵」則比喻成功的關鍵。"],
  ["友人から本を貰った。", "「本を貰う」（もらう）是收到一本書，「から」標示給書的人。「友人に手伝ってもらう」則用「～てもらう」表示請朋友幫忙。"],
  ["子どもたちが輪になって座った。", "「輪になる」（わになる）在本句指孩子們圍坐成一圈。「自転車の車輪」指自行車輪，「友達の輪」則指朋友圈。"],
  ["レジの前に長い列ができた。", "「列」（れつ）在本句指結帳櫃檯前排出的隊伍。「数字の列」指依一定順序排列的一串數字，「二列に並ぶ」則是排成兩排。"],
  ["夕日で影が長くのびた。", "「影」（かげ）在本句指夕陽照射下被拉長的影子。「水面に映る影」可指水面上的倒影，「不安の影」則比喻隱約出現的不安跡象。"],
  ["資料にざっと目を通した。", "「ざっと目を通す」是快速瀏覽一下，重點在只讀大概。「ざっと百人」則用來粗估人數，表示大約一百人。"],
  ["参加者は計三十人だった。", "「計三十人」（けいさんじゅうにん）表示參加者合計三十人。「体温計」中的「計」指測量用的器具，「一年の計」中的「計」則指計畫。"],
  ["朝は必ず飯を食べる。", "「飯」（めし）在本句指一餐。「飯を炊く」指煮飯，「絵で飯を食う」則是口語，比喻靠畫畫維生。"],
  ["転んで膝に傷ができた。", "「膝の傷」（ひざのきず）指膝蓋上的傷口或傷痕。「車の傷」通常指車上的刮痕，「心の傷」則比喻心理創傷。"],
  ["嵐で電車が止まった。", "「嵐」（あらし）在本句指暴風雨。「拍手の嵐」則比喻掌聲一陣接一陣、聲勢很大。"],
  ["この案は可とも不可とも言えない。", "「可」（か）在本句與「不可」相對，表示可接受或可行。「持ち込み可」表示允許自行帶入物品，成績欄中的「可」則可表示及格。"],
  ["この服の生地は柔らかい。", "「服の生地」（きじ）指做衣服用的布料。「パンの生地」則指做麵包用的麵團，「陶器の生地」可指尚未施釉的坯體。"],
  ["床の板がきしむ。", "「床の板」（ゆかのいた）是鋪地板用的木板。「鉄の板」則是平薄的鐵片，可見「板」也用於木材以外的材料。"],
  ["そのペンをちょうだい。", "句末的「ちょうだい」是向熟人索取東西的口語，例句是請對方把筆給自己。「見せてちょうだい」則是請對方給自己看。寫作「頂戴する」時，可謙遜地表示收下東西或享用飲食。"],
  ["彼は田舎で静かに暮らしている。", "「田舎で暮らす」（くらす）指住在鄉下過日子。「年金で暮らす」則交代怎麼維生，表示靠年金生活。"],
  ["この建物は十九世紀に建てられた。", "「十九世紀」（じゅうきゅうせいき）是第十九個百年。「世紀の大発見」則用「世紀の」來形容極不尋常、影響很大的發現。"],
  ["その説には根拠がない。", "「説」（せつ）在本句指一種說法。「学説」指學術上的主張或理論，「そういう説もある」也可表示有那樣的傳聞或說法。"],
  ["ケーキを四つに分けた。", "「ケーキを四つに分ける」（わける）是把蛋糕分成四份。「みんなに分ける」是在分配給大家，「種類ごとに分ける」則是依種類分類。"],
  ["秋になって木に赤い実がなった。", "「実がなる」（みがなる）指植物結出果實。「汁の実」指湯裡的固體配料，「実のある話」則形容談話內容充實。"],
  ["この布は模様がきれいだ。", "「布の模様」（ぬののもよう）指布上的花紋。「現場の模様」則指現場的情形，「欠航した模様です」則表示根據目前消息，似乎已經停航。"],
  ["冬は肌が乾燥する。", "「肌が乾燥する」（はだがかんそうする）在本句指皮膚乾燥。「木の肌」也可指木材或樹木的表面，「肌が合う」則比喻彼此性情合得來。"],
  ["値段より質を重視する。", "「質を重視する」（しつをじゅうしする）指重視品質。「やり方の質が違う」也可著重質的差異，也就是做法的性質有別。"],
  ["彼はその党を離れた。", "「党」（とう）在本句指政黨，「党を離れる」就是退出政黨。「甘党」（あまとう）中的「党」則用來稱呼喜歡甜食的人。"],
  ["節分には鬼の面をかぶる。", "「鬼の面」（おにのめん）指節分活動中的鬼怪面具。「鬼ごっこ」裡的「鬼」是負責抓人的一方，「仕事の鬼」則可比喻對工作格外投入的人。"],
  ["父は若いころから株をやっている。", "「株をやる」（かぶをやる）是口語，指投資股票。「切り株」指樹樁，「菌株」是微生物的一個株系，「株が上がる」也能比喻一個人的評價提高。"],
  ["この指輪は銀でできている。", "「銀」（ぎん）在本句指製作戒指的金屬。「銀を獲得した」在比賽報導中可指拿到銀牌，將棋裡的「銀」則是「銀将」的簡稱。"],
  ["そんなやり方では駄目だ。", "「そんなやり方では駄目だ」（だめだ）表示那個做法行不通。「ここで吸っては駄目」則表示禁止在這裡吸菸。"],
  ["彼は窓の外をぼんやり見ていた。", "「ぼんやり見る」在本句指心不在焉地望著。「山がぼんやり見える」則是山的輪廓模糊。「一日ぼんやり過ごす」指整天沒做什麼，恍恍惚惚地度過。"],
  ["牧場で牛が草を食べている。", "「牛」（うし）在牧場語境中指牛這種動物。點餐時，「牛と豚、どちらにしますか」中的「牛」則可指牛肉。"],
  ["運も成功を左右する要素の一つだ。", "「要素」（ようそ）在本句指影響成功的因素。談構造時可指組成整體的成分，例如「画面を構成する要素」。程式中的「配列の要素」則指陣列內的一筆資料。"],
  ["窓を開けた。すると風が入ってきた。", "「すると」在本句接續前一個動作，表示窗戶一開，風就吹了進來。對話中的「すると、明日は休みですね」則是根據對方剛說的資訊推論「那麼，明天就是休假了」。"],
  ["クラスの平均点が上がった。", "「平均点」（へいきんてん）指全班分數加總後除以人數所得的分數。「重さが平均する」則可表示各部分的重量趨於均衡。"],
  ["短い文で書いてください。", "「文」（ぶん）在本句指句子，因此是請對方用短句寫。「文を書く」也可依上下文指寫文章。"],
  ["不思議なことが起きた。", "「不思議なこと」（ふしぎなこと）指令人難以解釋的事。「不思議なことに、誰も気づかなかった」則用來引出令人意外的結果。"],
  ["彼は取材に応じた。", "「取材に応じる」（おうじる）指接受採訪。「呼びかけに応じる」是響應號召，「状況に応じて変える」則指依不同情況調整。"],
  ["部屋の中央に机がある。", "「部屋の中央」（ちゅうおう）指房間的正中間。「中央政府」則是與地方政府相對的中央層級。"],
  ["道路の横断は危険です。", "「道路の横断」（おうだん）指從道路一側穿到另一側。「大陸を横断する」可指橫越大陸，「横断面」則是物體橫切後的截面。"],
  ["山を下る。", "「山を下る」（くだる）指沿山路往下走。「判決が下る」是判決公布，「時代が下る」則指時間推進到較晚的年代。"],
  ["試合は三対二で終わった。", "「三対二」（さんたに）在比賽中指比分三比二，比例也可用「対」表示。「日本対韓国」則用「対」標示對戰的雙方。"],
  ["他人の目を気にしすぎる。", "「他人の目」（たにんのめ）指別人怎麼看自己。「血のつながりのない他人」則強調彼此沒有親屬關係。"],
  ["昆虫に詳しい彼は、友達から虫博士と呼ばれている。", "「虫博士」（むしはかせ）是對熟悉昆蟲的人取的綽號。「博士号」（はくしごう）則是正式的博士學位，這個複合詞的「博士」讀作「はくし」。"],
  ["この値段は税を含んでいる。", "「税を含む」（ふくむ）表示價錢包含稅金。「水を口に含む」指把水含在嘴裡，「皮肉を含む言い方」則指話中帶有諷刺意味。"],
  ["結果は君の努力次第だ。", "「努力次第」（どりょくしだい）表示結果取決於努力的程度。「到着次第、連絡します」表示一到就聯絡。「こういう次第です」則是解釋事情的經過或緣由。"],
  ["計画を予定どおり進めている。", "「計画を進める」（すすめる）是推進計畫。「車を少し前に進める」指讓車往前移一點，「時計を五分進める」則指把鐘調快五分鐘。"],
  ["着物の帯をきつく締めた。", "「着物の帯」（きもののおび）指繫在腰上的和服腰帶。「本の帯」則是繞在書封外、常印有推薦文字的紙帶。「時間帯」也用「帯」表示一段範圍。"],
  ["理由なしに欠席した。", "「理由なしに」（りゆうなしに）表示沒有理由就做某事。口語說「その案はなしだ」，則表示那個方案不可接受或不列入考慮。"],
  ["日本の経済は成長しています。", "「日本の経済」（にほんのけいざい）指日本的經濟活動與發展狀況。「家計の経済」可談家庭財務，「この車は燃費がよくて経済的だ」則指用起來省錢。"],
  ["次の便は三時発です。", "「次の便」（つぎのびん）在本句指下一個交通班次。「航空便」依語境可指飛機班次或透過空運寄送的郵件。"],
  ["靴のひもが切れてしまった。", "「ひもが切れる」（きれる）是繩帶斷掉。「期限が切れる」是到期失效，「在庫が切れる」是庫存用完。「よく切れる包丁」則是鋒利好切的菜刀。"],
  ["この花の匂いはとても良い。", "「花の匂い」（におい）指聞得到的花香。「昔の暮らしの匂いがする」則可用來比喻讓人感到有從前生活的氣息。"],
  ["水道のパイプが壊れて、水が漏れた。", "「水道のパイプ」是輸送自來水的管子。「パイプでたばこを吸う」中的「パイプ」則指煙斗，「海外へのパイプがある」可比喻與海外有聯絡管道。"],
  ["庭に花の種をまいた。", "「花の種」（はなのたね）指能播種的種子。「争いの種」指引發爭執的原因，「話の種」則指談話素材。"],
  ["コーヒーにミルクを入れる。", "「コーヒーにミルクを入れる」表示在咖啡裡加奶。「赤ちゃんにミルクをあげる」中的「ミルク」則常指泡給嬰兒喝的配方奶。"],
  ["冷蔵庫は空だった。", "「空」（から）在本句表示冰箱裡什麼都沒有。「空の箱」也是空無一物的箱子。這裡讀「から」，天空的「空」則讀「そら」。"],
  ["子どもにジュースを買った。", "「ジュース」可指果汁，也可在日常口語中泛指甜的非酒精飲料。要明確說純果汁，可用「果汁１００パーセントのジュース」。"],
  ["ところで、あの件はどうなった。", "句首的「ところで」用來轉換話題，可譯為「話說回來」。「今から急いだところで間に合わない」則是另一個句型，表示即使從現在開始趕，也來不及。"],
  ["この靴は軽くて楽だ。", "「靴が軽くて楽だ」（らくだ）在本句指穿著輕便舒服。「操作が楽だ」表示容易操作，「暮らしが楽になる」則可形容生活負擔變小。"],
  ["荷物を車に乗せた。", "「荷物を車に乗せる」（のせる）是把行李搬上車，也常寫「載せる」。「人を車に乗せる」是讓人搭車，「曲に乗せて歌う」則指配合曲調歌唱。"],
  ["もしも道に迷ったら電話して。", "「もしも～たら」用來提出假設，例句是說如果迷路就打電話。「もしものとき」則指萬一有突發狀況的時候。"],
  ["食事の前に手を洗う。", "「食事」（しょくじ）在本句指用餐。「食事に気をつける」則常指留意平時吃些什麼或如何安排飲食。"],
  ["一年、すなわち十二か月かかる。", "「すなわち」在本句用另一種說法重述前面的時間長度，可譯為「也就是」。它也可用來替前面的事項作明確定義。"],
  ["命は何より大切だ。", "「命」（いのち）在本句指生命。「機械の命は手入れだ」則比喻定期保養對維持機器性能至關重要。"],
  ["かつてこの町は都だった。", "「都」（みやこ）在本句指從前的首都。「音楽の都」則比喻一座城市以音樂聞名，是音樂文化的中心。"],
  ["空手の試験で一級に合格した。", "「一級」（いっきゅう）在本句指空手道的級別。「上級」則是較高的等級，適用於課程、技能等分級場合。"],
  ["この件は局の判断を待つ。", "「局」（きょく）在本句指有權處理這件事的機關或部門。「放送局」指電視台或廣播電台。棋類裡的「一局」則指一盤棋。"],
  ["正しいものに丸をつけなさい。", "「丸をつける」（まるをつける）指畫圓圈，在本句是圈出正確的選項。「丸一日」則指完整的一天，「日本丸」的「丸」則是船名常見的字尾。"],
  ["走ったあと胸がどきどきした。", "「胸がどきどきする」（むねがどきどきする）表示心跳得很快，例句描述跑步後的感覺。「胸が痛む」也可比喻因悲傷或內疚而難過。"],
  ["靴下に穴が空いてしまった。", "「靴下に穴が空く」（あながあく）指襪子破了一個洞。「計画の穴」比喻計畫的漏洞，「欠員の穴を埋める」則指補上人手缺口。"],
  ["お手紙を頂きありがとうございます。", "「お手紙を頂く」（いただく）是謙遜地說收到來信。「食事をいただく」可謙遜地表示用餐，「説明していただく」則表示請對方說明，或蒙對方提供說明。"],
  ["自転車のハンドルを握る。", "「自転車のハンドル」指自行車的車把。談汽車駕駛時，「ハンドルを回す」則是轉動方向盤。"],
  ["彼は三か国語をマスターした。", "「言語をマスターする」指熟練掌握一門語言。「喫茶店のマスター」指咖啡店老闆，錄音中的「マスター音源」則是用來製作其他版本的母帶音源。"],
  ["雨だった。だから出かけなかった。", "「だから」在本句引出結果，下雨，所以沒出門。對話中若把「だから」放在句首並加重語氣，也可表示「我不是說過了嗎」，用來重申先前說過的話。"],
  ["はい、分かりました。", "「はい」在本句表示已聽懂對方的話。點名時回答「はい」相當於「到」，接到指示時則可表示「好的」。"],
  ["どれがあなたの傘ですか。", "「どれ」在本句問多件物品中的哪一件。單獨在句首說「どれ、見せてごらん」，則是招呼對方把東西拿給自己看看。"],
  ["つまり、行かないということですね。", "句首的「つまり」表示把前面的話歸納成「也就是說」。「排水口の詰まり」（つまり）雖然讀音相同，卻是名詞，指排水口阻塞。"],
  ["破裂音が聞こえた。", "「破裂音」（はれつおん）在本句指聽到的爆裂聲。語音學也以「破裂音」稱呼例如日語「パ」開頭的子音。「漢字の音」若與「訓」對照，則指音讀。"],
  ["卒業式は三月に行われる。", "「卒業式」（そつぎょうしき）中的「式」指典禮。「入学式」也是典禮名稱。「計算式」裡的「式」則指寫出的算式。"],
  ["ご家族によろしくお伝えください。", "「よろしくお伝えください」是拜託對方代為問好。「これからもよろしくお願いします」則是請對方今後多關照。"],
  ["この店には様々な種類のパンがある。", "「種類」（しゅるい）在本句指麵包的類別。「パンを三種類買った」中的「三種類」則用來數不同的品項，表示買了三種麵包。"],
  ["宝くじが当たった。", "「宝くじが当たる」（あたる）指中了彩券。「ボールが壁に当たる」指球撞到牆，「予想が当たる」則表示猜中了。"],
  ["母の後ろ姿が見えなくなった。", "「後ろ姿」（うしろすがた）指從背後看見的身影。「制服姿」描述穿著制服的樣子，「町の昔の姿」則可指城鎮過去的面貌。"],
  ["テーブルの表面を拭いてください。", "「テーブルの表面」（ひょうめん）指桌子外露的那一面。「表面だけを見て判断する」則比喻只從外在表象作判斷。"],
  ["カメラを台の上に置いた。", "「台」（だい）在本句是拿來承托相機的平台。「車を一台買う」中的「台」用來數車輛，「価格は千円台」則指價格從一千日圓起、未滿兩千日圓。"],
  ["これはまさに探していた本だ。", "「まさに」在本句強調正是自己找的那本書。「まさに出発するところだった」則用在時間上，表示正要出發。"],
  ["まさか彼が来るとは思わなかった。", "「まさか～とは思わなかった」用來表達事情出乎意料，例句表示沒想到他會來。「まさか忘れたの？」則是難以置信地問「你不會忘了吧？」"],
  ["スープに塩で味を付けた。", "「味を付ける」（つける）指調味。「ラベルを付ける」是貼上標籤，「値段を付ける」是訂價格，「気を付ける」則是留意或小心。"],
  ["先生は生徒に課題を与えた。", "「課題を与える」（あたえる）在本句是指派作業。「情報を与える」是提供資訊，「悪影響を与える」則是造成負面影響。"],
  ["嘘をつくとあとで困るよ。", "「嘘をつく」（うそをつく）是說謊。對話中單說「うそ！」時，也可只是表示驚訝或難以置信，相當於「真的假的！」。"],
  ["地図を逆に持っていた。", "「逆に持つ」（ぎゃくにもつ）在本句指把地圖拿反。「逆の方向」是相反方向，「逆関数」則是數學中的反函數。"],
  ["では、始めましょう。", "句首的「では」在本句表示「那麼」，用來開始下一個動作。道別時，「では、また」則可譯為「那就下次見」。"],
  ["三人ずつの組に分かれた。", "「三人ずつの組」（さんにんずつのくみ）指每組三人。「一年二組」是在學校分班時說的一年級二班，「食器一組」則指一套餐具。"],
  ["この案には良い面もある。", "「良い面」（よいめん）指事情好的一面。「立方体の面」指幾何表面，「新聞の一面」則指報紙的頭版。"],
  ["毎日二時間勉強している。", "「勉強する」（べんきょうする）在本句指讀書。「いい勉強になった」表示從經歷中學到教訓，「もう少し勉強します」在議價時則可指再便宜一點。"],
  ["彼はいつも私の味方だ。", "「私の味方」（みかた）是站在我這邊、支持我的人。「彼の味方をする」則表示採取支持他的一方立場。"],
  ["いらっしゃい、どうぞお入りください。", "「いらっしゃい」在本句是對到訪的人說「歡迎」，後面接「請進」。「こちらにいらっしゃい」則是請對方到這邊來。"],
  ["それを取ってください。", "「それ」指靠近聽者或前面已提到的事物。例句請對方拿那個東西。「それなら」則承接對方剛說的情況，表示「既然那樣」。"],
  ["週末にキャンプに行きます。", "「キャンプに行く」在本句指去露營。「キャンプ場」是露營地，「チームのキャンプ」若談運動隊伍，也可指集訓。"],
  ["行きたい。でも時間がない。", "句首的「でも」表示轉折，可譯為「但是」。「子どもでもできる」表示連孩子也能做，「お茶でも飲もう」則用茶當作隨手提出的選項。"],
  ["コーヒーはいかがですか。", "「コーヒーはいかがですか」是客氣地問要不要喝咖啡。「お味はいかがですか」則是在詢問對味道的感想。"],
  ["新しいキーボードを買いました。", "「キーボード」依上下文可指電腦鍵盤或鍵盤樂器。這句只說買了新的鍵盤，還要看是在談電腦設備，還是在談演奏用的樂器。"],
  ["今度、一緒に映画を見に行きませんか。", "邀約裡的「今度」（こんど）指下次或近期可安排的時間。「今度の試験」則可指這次或即將到來的考試。"],
  ["家族は私にとって大切です。", "「家族は大切だ」（たいせつだ）指家人對自己很重要。「大切に扱う」則表示小心對待、珍惜對方或物品。"],
  ["レストランの予約をした。", "「店の予約」（よやく）指事先訂位。「録画予約」指預先設定錄影的時間。"],
  ["日本語で説明ができる。", "「説明ができる」表示能夠說明。「料理ができた」則常指料理做好了，「駅の前に店ができた」則表示車站前開了一家店。"],
  ["今日の日本では珍しくない。", "「今日の日本」（こんにちのにほん）指現今的日本。「今日、出発する」中的「今日」在日常會話通常讀「きょう」，指今天。"],
  ["去年より暑い。", "助詞「より」在「去年より暑い」標示比較基準，表示比去年熱。「本日より開始します」裡則標示起點，表示從今天開始。「より良い方法」的「より」作副詞，表示更好的方法。"],
  ["ここが痛いんです。", "「ここが痛い」中的「ここ」指說話者指出的身體部位。「ここ三日」則指最近這三天，將「ここ」用在時間上。"],
  ["この魚は生で食べられる。", "「生で食べる」（なまでたべる）表示不經烹煮就吃。「生放送」則指即時直播，「生ビール」則是啤酒的固定名稱。"],
  ["三日の内に返事をください。", "「三日の内に」（みっかのうちに）表示在三天這段期限內。「箱の内」指箱子裡面，「若いうちに」則表示趁年輕的時候。"],
  ["あと三日で夏休みだ。", "「あと三日」指還要三天。「食事のあと」說的是用餐之後。「あと、これもお願いします」則用來追加另一項請求。"],
  ["大学で多くの単位を取りました。", "「単位を取る」（たんいをとる）在大學語境中指取得學分。「長さの単位」則指表示長度的計量單位。"],
  ["そこに置いてください。", "「そこ」在本句指聽者身邊或剛提到的地方。「そこから話が変わった」也可指事情發展到那個階段後，情況有了轉變。"],
  ["この中でこれが一番おいしい。", "「一番おいしい」（いちばんおいしい）表示最好吃。「一番を取る」是拿到第一名，「一番勝負」則指比一場定輸贏。"],
  ["本を棚にしまってください。", "「本を棚にしまう」是把書收進書架。「仕事を終えてしまう」表示把工作做完，「鍵をなくしてしまう」則帶有不慎遺失、感到懊惱的語氣。"],
  ["この車は新しい型です。", "「車の型」（かた）指車的款式或型號。「型に生地を流す」是把麵糊倒進模具，武術中的「型」則指一套規定動作。"],
  ["子どもの頃はよく川で遊んだ。", "「子どもの頃」（こどものころ）指童年那段時間。「三時頃」（さんじごろ）則指三點左右。"],
  ["いえ、結構です。", "「いえ」在本句和「結構です」一起委婉拒絕，可譯為「不用了，謝謝」。「いえいえ」如果用來回應道謝，也可表示「不客氣」。"],
  ["この通りは車が多い。", "「この通り」（とおり）在本句指這條街。「説明の通りにする」表示照說明做，「二通りの方法」則表示有兩種方法。"],
  ["最近、体の調子が良い。", "「体の調子」（からだのちょうし）指身體狀況。「声の調子」可指聲音的語調，「機械の調子が悪い」則表示機器運作不順。"],
  ["しばらくお待ちください。", "「しばらくお待ちください」是客氣地請對方稍等。「しばらく会っていない」表示有好一陣子沒見面，「しばらく休業します」則表示暫時停止營業。"],
  ["この本はもう読んだ。", "連體詞「この」要接名詞。「この本」指說話者手邊或正在談的這本書。「この数年」則指最近這幾年。"],
  ["警察が事件を調査しています。", "「警察」（けいさつ）在本句指調查案件的警察機關。「警察に相談する」可表示向警方求助，「警察に行く」則可指前往警察局。"],
  ["やっと宿題が終わった。", "「やっと終わった」表示經過一番努力終於完成。「やっと間に合った」則可表示時間很緊，勉強趕上。"],
  ["私は全く分かりません。", "「全く分からない」（まったくわからない）搭配否定，表示完全不懂。「全く同じ」則強調完全相同。"],
  ["ちょうど今、着きました。", "「ちょうど今」指剛好現在，本句可譯為「我剛到」。「ちょうど百円」指正好一百日圓。"],
  ["会社のホームページを見てください。", "「ホームページ」可指網站首頁，日語日常用法也常泛指整個網站。「会社のホームページ」依語境可譯為公司首頁或公司網站。"],
  ["マスクを着用してください。", "「マスクを着用する」在衛生語境中指戴口罩。若談表演或裝扮，「仮面のようなマスク」則可指遮住臉的面具。"],
  ["そう、その通りです。", "句首的「そう」在本句用來肯定對方所說的話，可譯為「沒錯」。「そうしてください」中的「そう」則指按照剛提到的方式做。"],
  ["私は全然分かりません。", "「全然分からない」（ぜんぜんわからない）表示完全不懂。「全然大丈夫」則是口語中搭配肯定的用法，可譯為「完全沒問題」。"],
  ["この映画はもう三回見た。", "「三回」（さんかい）計算看電影的次數。「第九回」在棒球轉播中可指第九局，在連載或節目中則可指第九回。"],
  ["地図で場所を示す。", "「場所を示す」（しめす）在本句指利用地圖指出地點。「身分証を示す」是出示證件，「数字が傾向を示す」則指數字顯示出某種趨勢。"],
  ["あんまり好きじゃない。", "「あんまり」是「あまり」的口語形式，搭配否定的「あんまり好きじゃない」表示不太喜歡。「それはあんまりだ」則表示對方的作法太過分。"],
  ["その話は聞いたことがある。", "「その」接在名詞前。「その話」指對方剛說到的那件事。若單獨說「その、少し聞きたいことが……」，則是猶豫時用來起頭的語氣詞。"],
  ["木の葉が落ちる。", "「葉が落ちる」（おちる）指葉子往下掉。「汚れが落ちる」是污漬去掉，「試験に落ちる」是考試沒通過，「サーバーが落ちる」則指伺服器停止運作。"],
  ["彼はとてもクールな人だ。", "「クールな人」可形容冷靜沉著的人，也可能帶有冷淡或有型的印象，需看前後文。「クールな色合い」則形容偏冷的色調。"],
  ["勉強に集中してください。", "「勉強に集中する」（しゅうちゅうする）指把注意力放在讀書上。「人口が都市に集中する」則表示人口聚集在都市。"],
  ["このケーキはとてもおいしい。", "「とてもおいしい」表示非常好吃。「とてもできない」則和否定搭配，表示怎麼也辦不到。"],
  ["電気のスイッチを入れてください。", "「スイッチを入れる」在本句指打開電燈開關。「気持ちのスイッチを切り替える」則比喻轉換心情或心態。"],
  ["彼は運転が上手です。", "「運転が上手」（うんてんがじょうず）在本句表示擅長開車。「機械を運転する」則指使機器運轉。"],
  ["オレンジジュースを飲みます。", "「オレンジジュース」是柳橙汁，此處「オレンジ」指水果。「オレンジ色」則指橘色。"],
  ["毎朝シャワーを浴びます。", "「シャワーを浴びる」是沖澡。「シャワーを取り付ける」裡的「シャワー」則可指要安裝的淋浴設備。"],
  ["彼の計算には間違いがあった。", "「計算に間違いがある」（まちがいがある）指算錯了。「万一、間違いがあっては困る」則可指萬一發生差池就不好了。"],
  ["宿題のレポートを提出しました。", "「レポートを提出する」在本句是繳交書面報告。「現地レポート」則是在現場觀察後發出的報導。"],
  ["週末にパーティーがあります。", "「パーティー」在本句指週末的宴會或聚會。「登山パーティー」則指一同登山的一隊人。"],
  ["宿題をちゃんとやりました。", "「ちゃんとやる」表示認真、按要求做完。「ちゃんと聞こえる」則指聲音能清楚聽見。"],
  ["これから会議が始まります。", "「これから」在本句指從現在起或接下來。「これから駅まで歩く」也可以指接著從目前所在的地方走到車站。"],
  ["やっぱり雨が降ってきた。", "「やっぱり」在本句表示雨果然下了。「やっぱり家に帰る」則可用在重新考慮後，表示還是決定回家。"],
  ["彼はオンラインでゲームをしている。", "「オンラインでゲームをする」指透過網路玩遊戲。球賽中的「オンライン」則可指球落在界線上。"],
  ["友達に写真を送ってもらった。", "「友達に送ってもらう」是請朋友幫忙寄送，或蒙朋友寄來。「友達から写真をもらう」則直接說收到朋友給的照片。"],
  ["毎日、日記を書き続けている。", "「書き続ける」（かきつづける）把「続ける」接在「書く」後，表示持續寫。「練習を続ける」則直接以練習為受詞，表示繼續練習。"],
  ["駅はどちらの方ですか。", "「どちらの方」（どちらのほう）在問路時是問哪個方向。「電車の方が速い」則用「方」指出比較中較快的那一種。"],
  ["まず、手を洗ってください。", "「まず」在本句表示第一個步驟是洗手。「まず間違いない」則表示大致可以確定，相當於「應該沒錯」。"],
  ["仕事が大変です。", "「仕事が大変」（たいへん）指工作很辛苦。「大変おいしい」是用來強調非常好吃。「大変だ！」則可表示出了大事。"],
  ["記事の見出しを読んでください。", "「記事の見出し」（みだし）指文章標題。「辞書の見出し語」則是讀者可查找的詞條，通常排在解釋之前。"],
  ["私は日本へ行くつもりです。", "「行くつもり」表示打算去。「説明したつもりだ」則表示自己以為已經說明過，對方可能有不同看法。"],
  ["空港まで友達を見送りに行った。", "「見送り」（みおくり）在本句指去機場送行。「実施は見送りとなった」則表示暫緩實施，這次先不做。"],
  ["空港で友人を見送った。", "「友人を見送る」（みおくる）指送行。「次のバスに乗るために一本見送る」指先不搭這一班，「計画の実施を見送る」則是暫緩實施。"],
  ["彼は何も言わなかった。", "「何も言わなかった」（いわなかった）表示什麼都沒說。「この花は桜と言う」可用「と言う」說明名稱。「ブザーがピッと言った」則用擬聲詞描述響聲。"],
  ["いい天気ですね。", "句尾助詞「ね」用來和對方分享感受或尋求認同。「いい天気ですね」可譯為「天氣真好啊」。「明日ですよね」則是在確認是不是明天。"],
  ["祖母は百歳まで生きた。", "「百歳まで生きる」（いきる）指活到一百歲。「経験が仕事に生きる」則表示經驗在工作中派得上用場。"],
  ["時間が過ぎるのは早い。", "「時間が過ぎる」（すぎる）表示時間流逝。「締切が過ぎる」是期限已過，「食べ過ぎる」是吃得過多。「一例に過ぎない」則表示只是一個例子。"],
  ["何かおかしい。", "「何かおかしい」指總覺得有哪裡不對勁。「おかしくて笑った」則可形容事情好笑，讓人笑了出來。"],
  ["もっとゆっくり話してください。", "「ゆっくり話す」表示說慢一點。「ゆっくり休む」著重從容休息，「時間はゆっくりある」則可表示時間充裕。"],
  ["後で連絡します。", "「後で連絡する」（れんらくする）指稍後聯絡對方。「連絡バス」則指接駁巴士，重點在銜接兩個地點或班次。"],
  ["これは私にとって大事なものです。", "「大事なもの」（だいじなもの）指對自己重要或珍貴的東西。「大事に使う」指愛惜地使用，「大事に至らなかった」則表示事情沒有演變成嚴重的狀況。"],
  ["この席に座ってもいいですか。", "「～てもいいですか」用來詢問是否可以做某事，本句是在問能不能坐這個位子。「いい考え」中的「いい」則表示好、值得肯定。"],
  ["それはだめだよ。触らないで。", "「だめ」在本句搭配「触らないで」，表示不可以碰。「この方法ではだめだ」則表示這個方法行不通。"],
  ["クレジットカードを使えますか？", "「クレジットカード」指信用卡，本句是在問能不能刷卡。「メッセージカード」則指寫留言或祝福語的卡片。"],
  ["頭に強い痛みを感じる。", "「頭の痛み」（あたまのいたみ）指頭部疼痛。「心の痛み」則比喻哀傷等心理上的痛楚。"],
  ["東京までの往復切符を買いました。", "「往復切符」（おうふくきっぷ）是包含去程和回程的車票。「駅と家を往復する」則指在車站和家之間來回。"],
  ["世界は広い。", "「世界」（せかい）在本句泛指整個世界。「音楽の世界」則可指音樂這個領域，或參與音樂活動的人所形成的圈子。"],
  ["会計をお願いします。", "「会計をお願いします」（かいけいをおねがいします）在餐廳表示請結帳。「会社の会計」則指公司的帳務處理。"],
  ["彼は病気から回復した。", "「病気から回復する」（かいふくする）指病後恢復健康。「景気が回復する」則指經濟狀況從低迷轉好。"],
  ["日本には人が多いです。", "「人が多い」（おおい）表示人數多。「雨の多い季節」則指經常下雨的季節，著重發生頻率。"],
  ["それは本当ですか？", "「本当ですか」（ほんとうですか）是在確認一件事是不是真的。「本当の理由」則指實際的原因。"],
  ["彼は子供みたいだ。", "「子供みたいだ」表示言行像小孩。「雨が降るみたいだ」則根據看到或聽到的情況推測好像會下雨。"],
  ["彼女はブラックのドレスを着ていた。", "「ブラックのドレス」指黑色洋裝。點咖啡時說「ブラックで」通常表示不要加奶或糖。「ブラック企業」則是批評勞動條件惡劣的公司。"],
  ["会議中は静かにしてください。", "「会議中」（かいぎちゅう）指開會期間。「使用中」則表示正在使用。「中」（ちゅう）也可在尺寸標示中與「大」「小」並列，表示中等大小。"],
  ["その意見は私と違う。", "「私と違う」（ちがう）在本句指那個意見與我的看法不同。「答えが違う」則常表示答案有誤。"],
  ["毎朝、ラジオでニュースを聞きます。", "「ラジオでニュースを聞く」表示透過廣播收聽新聞。「ラジオを買う」則指購買收音機。"],
  ["車をバックさせて駐車した。", "「車をバックさせる」指倒車。「写真のバック」可指照片的背景，「バックで走る」在開車語境中則指以倒車檔行駛。"],
  ["宿題をやる。", "「宿題をやる」在本句是做功課。「花に水をやる」指澆花，「店をやる」則可指開店做生意。"],
  ["良い場所を見つけました。", "「場所」（ばしょ）在本句指合適的地點。相撲語境中的「本場所」則指正式舉辦的相撲賽事。"],
  ["これが最後のチャンスです。", "「最後のチャンス」（さいごのチャンス）指最後一次機會。「話の最後」指談話的末尾，「最後まで聞く」則是一直聽到結束。"],
  ["来月、日本語の試験を受ける。", "「試験を受ける」（うける）指參加考試。「ボールを受ける」是接球，「手術を受ける」是接受手術，「被害を受ける」則是受到損害。"],
  ["日本語の言葉を勉強しています。", "「日本語の言葉」（ことば）在本句可指日語詞彙。「励ましの言葉」則指鼓勵人的話語。"],
  ["彼の記憶力はすごい。", "「記憶力がすごい」是在稱讚記憶力驚人。「風がすごい」則強調風勢大。「すごく寒い」裡的「すごく」是表示程度的用法。"],
  ["彼はコンビニでバイトをしている。", "「バイトをする」中的「バイト」指兼職工作。「バイトの人」則可指做兼職工作的人。"],
  ["タバコをやめる。", "「タバコをやめる」指戒菸。「途中で作業をやめる」是停止手上的工作，「会議をやめる」則可指取消會議。"],
  ["部屋のライトを消してください。", "「部屋のライト」在本句指照明設備，所以「消す」是把燈關掉。「ライトな味」則指口味清淡。"],
  ["こうすればうまくいく。", "「こう」在本句指照說話者示範或剛說明的方式做。「こう暑いと外に出たくない」則用「こう」表示熱到這種程度。"],
  ["この地域は自然が豊かです。", "「地域」（ちいき）指具有某些共同特徵或在一定範圍內的地區。「自然が豊か」形容自然環境豐富，例如有多樣的動植物或景觀。"],
  ["このプロジェクトの期間は3ヶ月です。", "「期間」（きかん）指從開始到結束的時間長度。本句表示專案為期三個月。「申込期間」則指開放申請的起訖時段。"],
  ["週末にドライブに行った。", "「ドライブに行く」指開車出遊或兜風。在電腦語境中，「外付けドライブ」則可指外接的儲存裝置。"],
  ["彼の発想はいつもユニークだ。", "「発想」（はっそう）在本句指想出來的點子，也可指產生點子的思考方式。「発想を変える」是換個角度思考。"],
  ["過去を振り返る。", "「過去」（かこ）在本句指已經過去的事情。「過去を隠す」可指隱瞞自己以往不願公開的經歷。「過去形」則是文法上表示過去時態的形式。"],
  ["私の専門は経済学です。", "「専門」（せんもん）在本句指自己專攻的領域。「修理専門の店」則指專門做修理的店，著重只做或主要做這一類業務。"],
  ["庭に小さな小屋があります。", "「庭の小屋」（こや）指院子裡的小屋或棚屋。「芝居小屋」則指供人看戲的小型劇場。"],
  ["住所の番地を書いてください。", "「番地」（ばんち）是日本地址中用來標示地塊等位置的編號。填寫地址時，請依原地址填入該段號碼。"],
  ["彼はすでに家を出た。", "「すでに」（既に）在本句表示在談話所指的時間之前就離開家了。「到着した時、会議はすでに始まっていた」則以抵達當時為基準，表示會議在那之前就開始了。"],
  ["このアパートにはいくつかのユニットがあります。", "「ユニット」在本句指公寓大樓內的個別住宅單位。「音楽ユニット」則指由少數表演者組成的音樂團體。"],
  ["飛行機のシートに座ってください。", "「飛行機のシート」中的「シート」指飛機座椅。「座ってください」是客氣地請對方坐下。另有同形外來語「シート」，例如「防水シート」指防水布。"],
  ["地方の特産品を買う。", "「地方の特産品」（ちほうのとくさんひん）指某地區特有的產品。「東北地方」是地理區域的名稱，「地方から上京する」則以東京為基準，表示從其他地區到東京。"],
  ["卒直に意見を言ってほしい。", "「卒直」（そっちょく）指坦率，常見寫法是「率直」。「率直に意見を言う」表示直截了當地說出想法。"],
  ["季節の変化を感じる。", "「季節の変化を感じる」表示察覺季節正在改變。「変化に富んだ風景」形容景色多樣，「動詞の語形変化」則指動詞形式依文法而變化。"],
  ["来週なら明きがあります。", "「明き」（あき）在這句指時間上的空檔。這個詞也常寫作「空き」，例如「席に空きがある」表示有空位，「来週なら空きがあります」則表示下週還有可預約的時段。"],
  ["荷物の重さを量った。", "「重さを量る」（はかる）指秤重量。「米を量る」也可指量出一定分量的米。測量長度常寫「長さを測る」，計時則常寫「時間を計る」。"],
  ["この店は野菜を卸している。", "「野菜を卸す」（おろす）在本句指把蔬菜批發給其他業者。「大根をおろす」則是把白蘿蔔磨成泥，「魚を三枚におろす」是把魚剖成兩片魚肉和一片帶骨的中段。"],
  ["彼とのトークはいつも楽しい。", "「彼とのトーク」指和他的談話。「トーク番組」是以談話為主的節目。演唱會中的「曲の間のトーク」則指歌手在兩首歌之間與觀眾說話。"],
  ["手紙をポストに入れた。", "「手紙をポストに入れる」是把信投進郵筒。「重要なポストに就く」中的「ポスト」是職位，「ゴールポスト」則指球門柱。"],
  ["このボックスに書類を入れてください。", "「書類を入れるボックス」指收納文件的箱子。「ボックス席」可指包廂式座位，棒球的「バッターボックス」則指打者站立的區域。"],
  ["顔を画面に近付けすぎだ。", "「顔を画面に近付ける」（ちかづける）是把臉靠近螢幕。「子どもを危険な場所に近づけない」則表示別讓孩子靠近危險的地方。"],
  ["昨夜、映画を見た。", "「映画を見る」（みる）是看電影。「資料を見る」可指查看資料，「子どもの面倒を見る」指照料孩子。「食べてみる」則用假名寫出補助動詞，表示試著吃。"],
  ["サーバーがダウンしてしまった。", "「サーバーがダウンする」在電腦語境中指伺服器停止運作。「ウォーターサーバー」是飲水機，「ケーキサーバー」則指用來分送蛋糕的鏟具。"],
  ["船のデッキに出た。", "「船のデッキ」是船的甲板。「展望デッキ」指觀景平台，「カセットデッキ」指卡式錄放音機，「カードゲームのデッキ」則指遊戲使用的牌組。"],
  ["彼のツイッターをフォローしています。", "在社群網站上「フォローする」指追蹤帳號。「新人をフォローする」則指在新人遇到困難時提供協助，或在他完成工作後接著跟進。"],
  ["彼らは政府に抵抗した。", "「政府に抵抗する」（ていこうする）指反抗政府。「人前で話すことに抵抗がある」表示心裡有抗拒或顧慮。電路中的「抵抗」則可指電阻或電阻元件。"],
  ["母が弁当をこしらえてくれた。", "「弁当をこしらえる」是做便當。「資金をこしらえる」指籌措資金，「言い訳をこしらえる」則是編出一套說詞。"],
  ["このサイトはとても便利です。", "「サイト」在談網路時指網站，例句是說這個網站很方便。「キャンプサイト」裡的「サイト」則指可紮營的場地。"],
  ["重要なポイントです。", "「重要なポイント」指值得留意的重點。「買い物でポイントがたまる」表示消費能累積點數，「釣りのポイント」則指適合釣魚的地點。"],
  ["その映画の最後のシーンは感動的だった。", "「映画の最後のシーン」指片尾的一幕。「ビジネスシーン」則可指商務場合或工作情境。"],
  ["プログラムのコードを書く。", "「プログラムのコード」是撰寫程式用的程式碼。「行動コード」則可指組織訂出的行為規範。"],
  ["テストにマークをつけた。", "「マークをつける」是做記號。「相手の選手をマークする」指盯防對方球員，「新記録をマークする」則是寫下新紀錄。"],
  ["歌手がステージに上がった。", "「ステージに上がる」在本句指歌手走上舞台。「次のステージに進む」也可表示進入下一個階段。"],
  ["彼は社会に貢献したい。", "「社会に貢献する」（しゃかいにこうけんする）指為社會作出貢獻。「社会の授業」在學校則可指社會科課程。"],
  ["このカメラには複数の撮影モードがある。", "「撮影モード」指相機的拍攝模式。「仕事モードに入る」則是比喻說法，表示進入專心工作的狀態。"],
  ["彼はこちらを睨んでいる。", "「こちらを睨む」（にらむ）是瞪著這邊。「警察は彼が関与したと睨んでいる」表示警方根據線索懷疑他涉入。「需要の増加を睨んで」則表示把需求可能增加納入考量。"],
  ["一週間の献立を考えた。", "「献立」（こんだて）在本句指一週的餐點安排。「献立を立てる」就是安排要煮或要上的菜色。"],
  ["この装置は最新の技術を使っている。", "「装置」（そうち）在本句指有特定功能的設備。「舞台装置」則指用來布置舞台、呈現場景的布景和設備。"],
  ["気温が三十度を超した。", "「三十度を超す」（こす）表示氣溫超過三十度。跨越地形或度過季節時常寫作「越す」，例如「山を越す」是越過山，「冬を越す」是度過冬天。"],
  ["なくした鍵を捜している。", "「捜す」（さがす）在本句指尋找遺失的鑰匙。搜尋失蹤者時也常寫「捜す」。若是在找適合的工作或物件，則常寫作「探す」。"],
  ["彼は悠々と歩いてきた。", "「悠々と歩く」（ゆうゆうとあるく）形容走路從容不迫。「悠々と合格する」則形容輕鬆達到合格標準、綽有餘裕。"],
  ["鍋にふたを被せた。", "「ふたを被せる」（かぶせる）是把蓋子蓋在鍋上。「子どもに帽子を被せる」是替孩子戴帽子，「人に責任をかぶせる」則是把責任推到別人身上。"],
  ["溝を跳んで渡った。", "「溝を跳んで渡る」（とぶ）指跳過水溝。「跳ぶ」常用來寫離地跳躍。鳥或飛機在空中飛行時，通常寫作同音的「飛ぶ」。"],
  ["彼は株で儲けた。", "「株で儲ける」（もうける）指靠股票賺錢。「儲けた！」有時也可用於碰上好事，表示自己運氣好。表示生育子女的「子をもうける」則也可寫「子を設ける」。"],
  ["ベランダで植木を育てている。", "「植木」（うえき）可指栽種的庭園樹木，也可指種在盆裡的植物。由於這句是在說陽台上栽種，通常是指盆栽植物。"],
  ["凧が木に引っ掛かった。", "「凧が木に引っ掛かる」（ひっかかる）是風箏卡在樹上。「詐欺に引っ掛かる」指受騙，「言い方が引っ掛かる」則表示覺得那個說法有點不對勁。"],
  ["踏切で電車が通過するのを待った。", "「踏切」（ふみきり）在鐵路語境指鐵道與道路相交的平交道。「踏み切り」在跳遠等運動中也可指腳蹬地起跳的動作。"],
  ["筆に墨をつけた。", "「筆に墨をつける」（すみをつける）指讓毛筆沾上書寫用的墨汁。「イカの墨」則指烏賊噴出的墨汁。"],
  ["一昨日から雨が続いている。", "「一昨日」指今天往前推兩天，也就是前天。較正式的說法讀作「いっさくじつ」，日常會話常讀作「おととい」。"],
  ["ボールが坂を転がった。", "「ボールが転がる」（ころがる）表示球滾動。「足を滑らせて転がる」可指滑倒後滾出去，「床に雑誌が転がっている」則形容雜誌隨意散放在地上。"],
  ["彼は中指に指輪をはめている。", "「中指」（なかゆび）在戒指的語境指手的中指。在腳部的語境中也可指第三趾，例如「足の中指」。"],
  ["部屋の広さを測った。", "「広さを測る」（はかる）指量出房間的大小。計算重量時常寫「重さを量る」，計時則常寫「時間を計る」。三種寫法的讀音都是「はかる」。"],
  ["毎朝、髭を剃る。", "「髭を剃る」（ひげをそる）指刮鬍子。「猫のひげ」則指貓的觸鬚。"],
  ["棒で地面を突いた。", "「地面を突く」（つく）指用棒子戳地面。「杖をつく」指把拐杖支在地上，「相手の弱点を突く」則指針對對方的弱點下手。"],
  ["台風が近づくと気圧が下がる。", "「気圧」（きあつ）在本句指空氣造成的壓力。「一気圧」中的「気圧」則是壓力單位。"],
  ["庭に穴を掘った。", "「穴を掘る」（ほる）是挖出一個洞。「芋を掘る」則把埋在土裡的芋類作物挖出來。「過去を掘り下げる」比喻深入調查過去的事。"],
  ["この地方はお茶の産地だ。", "「お茶の産地」（さんち）指生產茶葉的地區。「化石の産地」則指發現化石的地點，重點由生產轉為出產或發現。"],
  ["説明の一部を省略した。", "「説明を省略する」（しょうりゃくする）是略去一部分說明。「正式名称を省略して書く」則是把名稱縮寫。"],
  ["タオルを絞って水を切った。", "「タオルを絞る」（しぼる）是把毛巾裡的水擰出來。「果汁を絞る」是榨汁，「候補を絞る」是縮小候選範圍，「音量を絞る」則是把聲音調小。"],
  ["鉛筆の芯が折れた。", "「鉛筆の芯」（しん）指書寫用的筆芯。「ろうそくの芯」指燭芯，「芯が強い人」則比喻內心堅定的人。"],
  ["その施設は最新の設備を備えている。", "「施設」（しせつ）指具特定用途的場所或機構，「設備」是場所內配置的器材或系統。例如「介護施設」是提供照護服務的機構。"],
  ["この紙は艶がある。", "「艶がある」（つやがある）在本句指紙面有光澤。「声に艶がある」則形容聲音圓潤、富有韻味。"],
  ["店舗を拡張することにした。", "「店舗を拡張する」（かくちょうする）指擴大店面的空間。「機能を拡張する」則是增加原有系統的能力，例如新增可執行的功能。"],
  ["彼の給与は毎月二十五日に支払われる。", "「給与」（きゅうよ）在發薪語境指受僱者的薪資。「制服を給与する」則可指由機構發給制服，重點在給付物品。"],
  ["このパンは少し硬い。", "「パンが硬い」（かたい）指麵包的質地偏硬。「硬い文章」則形容文章用語正式、生硬，讀起來不夠自然。"],
  ["彼は本当に偉い人です。", "「偉い人」（えらいひと）依情境可指值得尊敬的人或地位高的人。「よく最後まで頑張ったね、偉いね」則是在稱讚對方肯努力。"],
  ["彼女の瞳は大きい。", "「瞳」（ひとみ）可指眼睛中央的瞳孔，也可在描寫外貌時泛指眼眸。例句是在形容她的眼睛看起來很大。"],
  ["指輪をはめて出かけた。", "「指輪をはめる」是戴上戒指。「窓枠にガラスをはめる」是把玻璃嵌入窗框。「罠にはめる」則是設法讓人落入圈套。"],
  ["冬は空気が乾燥する。", "「空気が乾燥する」（かんそうする）表示空氣變乾。「乾燥した文章」則可比喻文字枯燥乏味。"],
  ["彼は絶対に来るでしょう。", "「絶対に」（ぜったいに）在本句表示說話者非常確信他會來。「絶対に行かない」則表示無論如何都不去。「絶対的な基準」中的「絶対的」強調不隨比較對象而改變。"],
  ["もう少し工夫が必要だ。", "「工夫」（くふう）指動腦想出能改善做法的辦法。「収納を工夫する」就是設法改善收納，例如重新安排各樣物品的位置。"],
  ["ごみを種類で区分する。", "「ごみを種類で区分する」（くぶんする）表示按種類分類垃圾。「行政区分」則可指依行政管理所劃定的區域分類。"],
  ["車が上り坂を進む。", "「上り坂」（のぼりざか）是往上走的坡道。「上りの電車」指鐵路上與「下り」相對的行駛方向，常朝主要城市或路線起點行駛。「川の上り」則是往上游的方向。"],
  ["この理論は様々な分野に応用できる。", "「理論を応用する」（おうようする）指將理論用在實際問題上。「応用物理学」則指著重物理原理實際用途的學科。"],
  ["買い物のついでに寄った。", "「買い物のついでに」表示利用去購物的機會順道做另一件事。「ついでに一つ聞きたい」則表示趁著正在談話，順便再問一件事。"],
  ["来年度の予算を組む。", "「来年度の予算」（らいねんどのよさん）中的「年度」指依會計制度劃定的期間。學校也可用「年度」指學年，例如「新年度の授業」。"],
  ["箱の中身を確かめた。", "「箱の中身」（なかみ）指箱子裡裝的東西。「話の中身」則指談話的實質內容。「中身」也可寫作「中味」。"],
  ["次のスライドを見せてください。", "「次のスライド」在簡報中指下一張投影片。「顕微鏡のスライド」則是載玻片。「予定を一日スライドさせる」指把預定日期移動一天。"],
  ["彼が手紙をよこした。", "「手紙をよこす」指把信寄到說話者這一方。「それをよこせ」則是語氣較強的命令，要求對方把手上的東西交過來。"],
  ["二枚の紙をくっつけた。", "「紙をくっつける」可指把兩張紙黏在一起。「椅子をくっつける」也可指把椅子挪到緊靠的位置。口語中「二人をくっつける」可指撮合兩人。"],
  ["表に項目を追加した。", "「項目」（こうもく）在本句指表格裡的一個項目。「辞書の項目」則可指有獨立解說的辭典條目。"],
  ["彼は大学の講師をしている。", "「大学の講師」（こうし）是大學的教學職務。「講演会の講師」指受邀來演講的人，「塾の講師」則指補習班的任課老師。"],
  ["パンをちぎって食べた。", "「パンをちぎる」表示用手把麵包撕成一塊塊。「草をちぎる」可指用手扯下草葉，「ほめちぎる」則把「ちぎる」接在動詞後，表示大力稱讚。"],
  ["雨の日には長靴を履く。", "「長靴を履く」（はく）指穿雨靴，「靴下を履く」是穿襪子。褲子或裙子同樣讀「はく」，但也常寫作「穿く」。"],
  ["魚が水面で跳ねた。", "「魚が跳ねる」（はねる）指魚從水面躍起。「泥が跳ねる」則指泥水濺起，「ボールが跳ねる」是球碰到地面後彈起。"],
  ["雨の中の子犬が哀れでならない。", "「哀れ」（あわれ）在本句形容雨中的小狗令人憐憫。「哀れを誘う」指引起同情，「哀れな結末」則可形容令人悲傷的結局。"],
  ["この店は年中開いている。", "「年中」（ねんじゅう）在本句表示一年到頭，整句是說這家店全年營業。「年中忙しい」則可形容老是很忙。"],
  ["調理場は清潔に保つこと。", "「清潔に保つ」（せいけつにたもつ）在本句指保持廚房衛生。形容穿著時，「清潔感がある」指給人乾淨整潔的印象。"],
  ["彼女は努力して医師になった。", "「医師になる」（なる）指成為醫師。「三部から成る本」中的「成る」表示由三個部分構成。「水が氷になる」則用於狀態轉變。"],
  ["彼は器用で何でも自分で直す。", "「器用」（きよう）在本句指手巧，因而能自己修理東西。「器用に仕事をこなす」則形容能熟練地應付工作。"],
  ["古い電池を新しいのに換えた。", "「電池を換える」（かえる）指把舊電池換成新電池。「円を外貨に換える」則是換匯。更換上場球員時也常寫作「選手を替える」。"],
  ["万一の場合は連絡します。", "「万一の場合」（まんいちのばあい）指不太可能發生、但仍須預作打算的情況。「万一遅れたら連絡する」則是用「万一」來引出「如果真的遲到了」這個假設。"],
  ["釣った魚を川に放した。", "「魚を川に放す」（はなす）指把魚放回河裡。「手を放す」則是鬆開原本抓住的東西。"],
  ["練習を怠けると下手になる。", "「練習を怠ける」（なまける）指懶得練習或偷懶沒練。「怠けてばかりいる」則形容整天偷懶，沒有專注在該做的事情上。"],
  ["私たちの意見は完全に一致した。", "「意見が一致する」（いっちする）表示雙方看法相同。「記録と証言が一致する」則表示兩項資料互相吻合。"],
  ["彼は一流の料理人だ。", "「一流の料理人」（いちりゅうのりょうりにん）指頂尖的廚師。「彼一流のやり方」則指他獨有的一套做法。"],
  ["宿題を終えてから遊びなさい。", "「宿題を終える」（おえる）表示把作業完成。「読み終える」則把「終える」接在另一個動詞後，表示把內容讀完。"],
  ["鳥の羽が一枚落ちていた。", "「鳥の羽」（はね）在本句搭配量詞「一枚」，指一根羽毛。「羽を広げる」則可指張開翅膀。"],
  ["部屋に入る前にノックしてください。", "「ノックする」在本句指進房前敲門。棒球練習中的「ノック」則指把球打向守備球員，讓他們練習接球。"],
  ["窓から日光が差し込んでいる。", "「日光」（にっこう）在本句指從窗戶照進來的陽光。同樣寫作「日光」、讀作「にっこう」的地名可指栃木縣日光市。"],
  ["彼は借金を全部返した。", "「借金を返す」（しゃっきんをかえす）是償還債務。職業棒球報導中的「借金が三つある」則比喻敗場比勝場多三場。"],
  ["彼はお金にけちだ。", "「けち」在本句形容人花錢吝嗇。「けちな考え」則可形容想法小氣、只在意眼前的一點好處。"],
  ["食べ終わった皿を洗う。", "「皿」（さら）在本句指裝過餐點的盤子。「料理を一皿頼む」中的「皿」則用來數以盤盛裝的餐點，表示點一盤料理。"],
  ["山を越すと海が見える。", "「山を越す」（こす）指跨過山。「冬を越す」是度過冬天，「引っ越す」是搬家。表示數量超過某標準時，也常寫作「超す」。"],
  ["遠くで雷が鳴っている。", "「雷が鳴る」（かみなりがなる）指打雷。「雷を落とす」用來形容人發火時，則表示大聲責罵。"],
  ["お礼の手紙を書いた。", "「お礼の手紙」（おれいのてがみ）是道謝的信。「礼をする」在動作語境中可指鞠躬，「礼を尽くす」則表示把應有的禮數做足。"],
  ["この絵は上下が逆になっている。", "「上下が逆」（じょうげがぎゃく）指上端與下端顛倒。「価格が上下する」則形容價格反覆上漲和下跌。"],
  ["壁にポスターを張った。", "「ポスターを張る」（はる）指把海報貼在牆上，這個搭配也常寫「貼る」。「ロープを張る」是把繩子拉緊，「池に氷が張る」則是池面結冰。"],
  ["父は今、家に居ります。", "「居ります」（おります）在本句是對外人客氣地說自己父親在家。「確認しております」中的「おります」則接在動詞後，表示正在確認或已做過確認，需看上下文。"],
  ["皆でこの問題を話し合おう。", "「皆で」（みんなで）指大家一起。「皆が賛成する」表示每個人都贊成，「資料をみんな読んだ」也可以表示資料全都讀過了。"],
  ["この壺は値がつけられない。", "「値をつける」（ねをつける）指給物品定價。本句表示這個壺難以定價。「測定の値」（あたい）則指測量所得的數值。"],
  ["彼はとても真面目な学生だ。", "「真面目な学生」（まじめながくせい）形容學生態度認真。「真面目に答える」則指認真、如實地回答，語氣有別於開玩笑。"],
  ["やがて雨がやんだ。", "「やがて雨がやんだ」表示過了一段時間，雨終於停了。「やがて結果が出る」則指結果不久後就會出來。"],
  ["店の雰囲気が落ち着いている。", "「店の雰囲気」（ふんいき）指出入店裡時感到的氣氛。「落ち着いた雰囲気の人」也可形容某人給人沉穩的感覺。"],
  ["毎日風呂に入る。", "「風呂に入る」（ふろにはいる）指洗澡或泡澡。「風呂を掃除する」則可指清洗浴缸或浴室。"],
  ["形式よりも内容を大切にしたい。", "「形式」（けいしき）在本句指與內容相對的外在樣式。「ファイル形式」指檔案格式，「形式的な手続き」則可能指主要為了符合程序而辦的手續。"],
  ["辛い経験を乗り越えた。", "「辛い経験」（つらいけいけん）指讓人痛苦的經歷。「辛い料理」（からいりょうり）裡的「辛い」則讀「からい」，指味道辣。"],
  ["走ったら腹が痛くなった。", "「腹が痛い」（はらがいたい）是肚子痛。「腹が立つ」是生氣，「腹を決める」則是下定決心。"],
  ["この食べ物は臭い。", "「臭い」（くさい）在本句表示食物發出難聞的味道。「話が臭い」可比喻說法可疑，「うそ臭い」則形容聽起來不太可信。"],
  ["2つの会社が合同でプロジェクトを進める。", "「合同で進める」（ごうどうですすめる）指由兩家公司共同推動專案。幾何上的「合同」則指形狀與大小相同，例如兩個三角形全等。"],
  ["ひどい天気ですね。", "「ひどい天気」指很糟的天氣。「ひどい扱い」是形容受到過分或殘酷的對待，「ひどい痛み」則指疼痛的程度很嚴重。"],
  ["彼の態度は最後まで変わらなかった。", "「態度」（たいど）可指人表現出來的舉止，也可指面對某件事所持的立場。「丁寧な態度」著重舉止，「反対の態度を示す」則是表明反對立場。"],
  ["この店は駅前に有る。", "「駅前にある」表示店位於車站前。「時間がある」是有時間，「会議がある」則表示有一場會議，需看主語和語境判斷。"],
  ["休みは十日間です。", "「十日間」（とおかかん）指十天的期間。單說「十日」也可指每月的十日。「日曜日」的第一個「日」讀「にち」，是星期日的「日」。"],
  ["私たちは同じ意見です。", "「同じ意見」（おなじいけん）指彼此的看法相同。「同じ行くなら早めに行こう」則是說既然都要去，乾脆早點去。"],
  ["冷蔵庫に何か入っている。", "「何か」（なにか）指某個尚未說明的東西，所以例句是說冰箱裡有東西。「何が入っていますか」則是在問裡面裝了什麼。"],
  ["彼はバイクで通勤している。", "「バイクで通勤する」通常指騎機車通勤。「ロードバイク」則是公路自行車，這個複合詞裡的「バイク」指自行車。"],
  ["彼女はグリーンが好きです。", "「グリーン」在談顏色時指綠色。「グリーンエネルギー」中的「グリーン」指有助減少環境負擔，高爾夫球場的「グリーン」則指果嶺。"],
  ["敵を攻める。", "「敵を攻める」（せめる）指向敵方進攻。「弱点を攻める」可指針對弱點發動攻勢，運動中的「攻めの姿勢」則指主動進攻的態度。"],
  ["彼女はピアノを弾くのが好きです。", "「ピアノを弾く」指彈鋼琴。樂譜上的力度術語「ピアノ」則表示要用較弱的力度演奏，也就是彈得輕一些。"],
  ["私はチーズが好きです。", "「チーズ」在本句指乳酪或起司。拍照時喊「はい、チーズ」則是請大家看鏡頭微笑時用的口令。"],
  ["どんどん食べてください。", "「どんどん食べてください」是請對方別客氣，繼續多吃一些。「仕事がどんどん進む」可形容工作迅速推進。「ドアをどんどん叩く」則用來模擬連續而響亮的敲門聲。"],
  ["高速道路で渋滞に巻き込まれた。", "「渋滞」（じゅうたい）在道路語境指車流壅塞。「事務が渋滞している」則比喻工作流程停滯、待辦事項積壓。"],
  ["今日の気分はどうですか？", "「気分はどうですか」（きぶん）可以問對方心情怎樣，也可以問身體感覺如何。「気分が悪い」依上下文可能表示身體不舒服，或心情不快。"],
  ["金がなくて旅行をあきらめた。", "「金がない」中的「金」讀「かね」，指沒錢。「金の指輪」中的「金」則通常讀「きん」，指黃金。"],
  ["会議で計画の中間報告を行った。", "「中間報告」（ちゅうかんほうこく）是在計畫尚未結束時所作的階段報告。「二駅の中間」則指兩站之間靠中間的位置。"],
  ["どんな音楽が好きですか。", "「どんな音楽」（どんなおんがく）是在問哪一類音樂。「どんなに難しくても」中的「どんなに」則表示「無論多難」。"],
  ["この店は安く、しかもうまい。", "連接詞「しかも」補充另一項特點，本句是「這家店便宜，而且好吃」。「何度も説明した。しかも彼は納得しなかった」則可用來凸顯後一句出乎預期。"],
  ["この店は品がそろっている。", "「品がそろう」的「品」讀「しな」，指商品準備齊全。「品がある」的「品」則讀「ひん」，可形容人的舉止高雅。"],
  ["この語の意味を辞書で調べた。", "「語」（ご）在「この語」指要查的詞語。接在名稱後的「日本語」或「英語」則用「語」標示一種語言。"],
  ["彼はベストを尽くした。", "「ベストを尽くす」表示盡全力，這裡的「ベスト」是名詞。「ベストな方法」則表示最好的方法。同形的外來語「ベスト」也可指背心，例如「ニットのベスト」。"],
  ["この歌手はとても人気があります。", "「人気がある」（にんきがある）表示受歡迎。市場語境的「人気」也可指投資者的看好程度。若說「人気のない道」並讀作「ひとけ」，則表示路上感覺不到有人。"],
  ["大切な書類は金庫に保管されている。", "「金庫」（きんこ）在本句指保管貴重物品的保險箱。「信用金庫」則是日本一類合作型金融機構的名稱。"],
  ["若い時にもっと勉強すればよかった。", "「若い時に」（わかいときに）在名詞「時」後用「に」標示年輕時這段時間，整句表示後悔當時沒更用功。「出発の時」也可指即將出發的時刻或時機。"],
  ["困った事になった。", "「困った事」（こまったこと）在本句指棘手的事態。「読むことが好きだ」中的「こと」把「読む」變成可作主語的成分。「廊下を走らないこと」則可用在規定裡，表示不得在走廊奔跑。"],
  ["夏にはプールで泳ぐのが好きだ。", "「プールで泳ぐ」是到游泳池游泳。「資金をプールする」則指把資金集中存放，供日後使用。「プール」也可指一類撞球。"],
  ["この薬には依存性がある。", "「依存性」（いぞんせい）的「性」是接尾詞，表示某種性質。用於藥品時，「依存性がある」指可能使人產生依賴。「性別」中的「性」則和性別有關。"],
  ["彼はいつもメガネをかけています。", "「メガネをかける」指戴眼鏡。慣用語「お眼鏡にかなう」則表示符合對方的眼光或評選標準。"],
  ["まあ、そんなに悪くない。", "句首的「まあ」在本句表示斟酌或保留，可譯為「嗯，倒也沒那麼糟」。「まあまあ、落ち着いて」則用來安撫對方。"],
  ["駅まで約二キロある。", "「キロ」在本句是距離單位「キロメートル」的簡稱，所以離車站約兩公里。談重量時，「二キロ」也可指兩公斤。作單位前綴時，「キロ」表示千倍。"],
  ["その場の空気が重くなった。", "「その場」（そのば）在本句是當時大家所在的現場，「空気が重い」形容氣氛沉重。「発表の場」則指可發表的場合，「磁場」中的「場」則是物理學用語。"],
  ["彼とは長い付き合いだ。", "「長い付き合い」（ながいつきあい）指彼此往來已久。「仕事上の付き合い」則可指因工作而維持的人際往來或應酬。"],
  ["あと十秒で始まる。", "「十秒」（じゅうびょう）在本句指十秒鐘。描述角度大小時，「秒」也可表示角秒，一角分等於六十角秒。"],
  ["彼は学のある人だ。", "「学のある人」（がくのあるひと）指有學識的人。「言語学」中的「学」則接在研究對象後，表示一門學科。"],
  ["銃に弾を込めた。", "「銃に弾を込める」是把子彈裝進槍裡。本句的「弾」讀「たま」。同音的「玉」可寫在「ビー玉」等詞裡，指珠子一類的圓形物。"],
  ["彼は多くの苦労を経験した。", "「苦労」（くろう）在本句指經歷過的艱辛。「資金のやりくりに苦労する」則表示為了周轉資金而費心思、遇到困難。"],
  ["タバコを吸ってもいいですか。", "「タバコを吸う」指抽菸，所以本句在詢問能不能抽菸。「タバコを栽培する」則指栽種菸草這種植物。"],
  ["二つの間に大きな違いがある。", "「二つの間に違いがある」（ちがいがある）表示兩者之間有差異。「聞き違い」則指聽錯，「思い違い」指以為是這樣，實際上想錯了。"],
  ["試験の結果が心配です。", "「結果が心配だ」（しんぱいだ）是擔心結果如何。「宿の心配は要りません」在有人代為安排住宿的語境中，可譯為住宿的事不用操心。"],
  ["映画の終わりが近づいています。", "「映画の終わり」（おわり）指電影接近結束的部分。「人生の終わり」則用來談生命的最後階段或終結。"],
  ["約三十分で着きます。", "「約」（やく）放在數量前，表示估計值。「約三十分」指大約三十分鐘。「約」在「約束」一類的詞中則和約定有關。"],
  ["外に方法はないだろうか。", "「外に方法はない」（ほかにほうほうはない）是說沒有其他辦法。「これのほかに」表示除此之外。若讀作「そと」，例如「外に出る」，則是走到外面。"],
  ["うん、それでいいよ。", "「うん」在本句是隨意地同意對方，可譯為「嗯，那樣就好」。「うーん」拉長聲音時可表示思索或猶豫，「うん？」用升調則可表示剛才沒聽清楚或感到疑惑。"],
  ["彼は将棋の名人です。", "「名人」（めいじん）一般指技藝高超的人，例如「料理の名人」。在正式的將棋競賽語境中，「名人」也可指競技頭銜，因此例句要看上下文才能確定是否在稱述頭銜。"],
  ["彼女は来年、留学する予定だ。", "「留学する」（りゅうがくする）在本句指到國外就讀。「国内留学」則可指到同一國家的其他學校或機構短期進修。"],
  ["雨がますます強くなった。", "「ますます強くなる」表示雨勢越來越強。「利用者がますます少なくなる」則表示使用者越來越少。「ますます」加強的是變化程度，方向由後面的說法決定。"],
  ["今日は宿題無しです。", "「宿題無し」（しゅくだいなし）指沒有作業。口語的「その案はなしだ」則表示不接受那個方案，或把它排除在考慮範圍外。"],
  ["彼はサッカーで怪我をした。", "「怪我をする」（けがをする）指受傷，本句說他踢足球時受了傷。「怪我の功名」則是慣用語，指原本的失誤或意外反而帶來好結果。"],
  ["彼は職を探している。", "「職を探す」（しょくをさがす）指找工作。「部長の職に就く」表示擔任部長職位，「手に職をつける」則比喻學會一門可以謀生的技藝。"],
  ["極まれにしか起こらない現象だ。", "「極」（ごく）在「極まれに」修飾「まれ」，表示極其少見。相同的用法也見於「ごく一部」，指非常小的一部分。"],
  ["彼は息子を自慢している。", "「息子を自慢する」（じまんする）表示引以為傲，並得意地向別人談起兒子。「この庭が私の自慢です」則把「自慢」用作名詞，指讓自己感到自豪的事物。"],
  ["彼は一人で冒険に出た。", "「冒険に出る」（ぼうけんにでる）指踏上冒險旅程。「料理で少し冒険する」則可比喻嘗試平時不敢試的食材或做法。"],
  ["彼は背が高い。", "「背が高い」表示身高較高，日常常讀作「せがたかい」。談身高時也可聽到「せいがたかい」。表示身體的背部時，例如「背を向ける」，讀作「せ」。"],
  ["熱いスープで舌をやけどした。", "「舌」（した）在本句指口中的舌頭。也可用來命名形狀像舌頭的部分，例如鞋帶下的「靴の舌」。"],
  ["母は毎朝、豆を煮る。", "「豆」（まめ）在本句指豆類食材。依料理語境也可特指大豆。「豆電球」裡的「豆」則表示尺寸小，即小燈泡。"],
  ["二人が出会ったのは偶然だった。", "「偶然だった」（ぐうぜんだった）表示這次相遇是巧合。「偶然会った」則以「偶然」修飾相遇的動作，可譯為「碰巧遇到」。"],
  ["窓から見える風景が好きだ。", "「窓から見える風景」（ふうけい）指從窗戶望見的景色。「授業風景」則指上課時的情景。"],
  ["明日、お宅に伺います。", "「お宅」（おたく）在本句是對他人住家的尊稱，可譯為「府上」。「自宅」（じたく）則指自己的住家。"],
  ["彼は納豆を嫌う。", "「納豆を嫌う」（きらう）表示討厭納豆。「この植物は直射日光を嫌う」則表示這種植物不適合陽光直射。"],
  ["誰かが玄関のベルを鳴らした。", "「ベルを鳴らす」（ならす）表示使門鈴響起。「警鐘を鳴らす」可指敲響警鐘，也可比喻提醒大眾留意某種危險。"],
  ["学問には終わりがない。", "「学問」（がくもん）在本句指持續求知、研究的活動。「歴史学は過去を研究する学問だ」則把「学問」用於一門研究領域。"],
  ["時計の針の回りが速い。", "「針の回り」（まわり）在本句指指針轉動。「大阪回り」指繞經大阪，「一回り大きい」則表示大上一圈或大一個尺寸。"],
  ["走って前の人に追い付いた。", "「前の人に追い付く」（おいつく）指追到跟前方的人同一位置。「同点に追いつく」指縮小分差到平手，「生産が需要に追いつかない」則表示供應趕不上需求。"],
  ["さっさと支度をしなさい。", "「さっさと支度をする」指不拖延地準備，本句帶有催促語氣。「さっさと帰った」也可能形容某人毫不遲疑就離開了。"],
  ["勝利に万歳を叫んだ。", "「万歳を叫ぶ」（ばんざいをさけぶ）指喊「萬歲！」來慶祝。「万歳三唱」是連喊三次萬歲，「万歳する」則可指一邊歡呼一邊把雙手高舉。"],
  ["くだらない話はやめよう。", "「くだらない話」指無聊或不值得談的話。「くだらない冗談」則可譯為愚蠢或沒意思的玩笑。"],
  ["ひとまずここまでにしよう。", "「ひとまず」在本句表示先暫停在這裡，之後還可繼續。「ひとまず安心だ」則表示眼前暫可放心，整件事可能仍未結束。"],
  ["犬がしっぽを振っている。", "「しっぽ」在本句指狗的尾巴。「行列のしっぽ」可比喻隊伍的最末端。"],
  ["彼の成功は確実だ。", "「成功は確実だ」（かくじつだ）表示成功幾乎可以確定。「確実な方法」則指可靠、能穩妥得到結果的方法。"],
  ["ギャングが銀行を襲った。", "「ギャング」可指犯罪幫派，也可指幫派成員。例句只說有歹徒襲擊銀行，日文沒有交代人數。"],
  ["この駐車場は有料だ。", "「有料」（ゆうりょう）在本句表示使用停車場要付費。「有料道路」是通行要付費的道路。"],
  ["経済の安定は社会の基盤である。", "「社会の基盤」（しゃかいのきばん）指讓社會得以穩定運作的根基。「情報基盤」是供資訊系統運作的基礎設施，地質用語中的「基盤岩」則指下方的岩層。"],
  ["マウスをワンクリックする。", "「ワンクリックする」指用滑鼠點一下。「クリック音」則指按下按鍵時發出的短促聲響。"],
  ["これがラストチャンスだ。", "「ラストチャンス」是最後一次機會。「映画のラスト」中的「ラスト」則可單獨表示電影的結尾。"],
  ["彼は年間100万円を稼ぎます。", "「年間」（ねんかん）在本句用來按年計算收入，表示每年賺一百萬日圓。「三年間」則指持續三年的期間。"],
  ["彼の笑いはいつも周りを明るくする。", "「笑い」（わらい）在本句指笑聲帶動周遭氣氛。「笑いが起きる」表示大家笑了起來，「冷たい笑い」則可形容帶有嘲諷的笑。"],
  ["机や椅子等を運んだ。", "助詞「等」（など）接在所列的事物後，表示桌椅只是搬運物品中的幾項。「お茶などいかがですか」則舉茶為例，委婉詢問對方的意願。"],
  ["彼は元教師だった。", "「元教師」（もときょうし）中的「元」接在職稱前，表示以前是老師。「元に戻す」中的「元」則指原來的狀態。"],
  ["山田氏が代表を務める。", "「氏」（し）接在人名後是較正式的稱謂。「山田氏」未交代性別，可直接譯為「山田氏」。「藤原氏」在歷史語境則可指藤原氏族。"],
  ["彼の健康状態は良好だ。", "「健康状態」（けんこうじょうたい）是指身體健康的狀況。「健康な人」則用「健康な」形容身體狀態良好的人。"],
  ["全社員が会議に出席した。", "「全社員」（ぜんしゃいん）的「全」接在名詞前，表示全體員工。「全三巻」則表示一整套共三卷。"],
  ["この消しゴムはよく消える。", "「消しゴム」是橡皮擦，本句形容它擦得乾淨。「ゴム」本身可指橡膠，「輪ゴム」則是用來綑綁物品的橡皮筋。"],
  ["以前ここに大きな木があった。", "句首的「以前」（いぜん）指從前。「三月以前」則以三月為時間界線。若須明確排除三月，可說「三月より前」。"],
  ["コーヒーにクリームを入れますか？", "「クリーム」在咖啡語境指加進咖啡的鮮奶油或奶精。「ハンドクリーム」中的「クリーム」則指用於護理皮膚的乳霜。"],
  ["おまえも一緒に来るか。", "「おまえ」是口語的第二人稱代名詞。用於親近的人時可有親暱語氣，也可能顯得粗魯或居高臨下，意思需由關係和語氣判斷。"],
  ["湖でボートに乗った。", "「ボート」在湖泊遊覽的語境可指小船。「ボートをこぐ」是划船，「モーターボート」則是有馬達推進的小艇。"],
  ["消防車がサイレンを鳴らして走っていった。", "「消防車」（しょうぼうしゃ）是供消防人員執勤的車輛。「消防活動」指救火等消防工作，「消防に通報する」則是通報消防單位。"],
  ["彼は隣の県から通っている。", "「隣の県」（となりのけん）指相鄰的縣。日文除了用「県」稱日本的行政區，也可用來稱其他地區的縣，例如「台湾の宜蘭県」。"],
  ["あっ、財布を忘れた。", "感嘆詞「あっ」在本句表示突然想起忘了帶錢包。單說「あっ！」也可表示突然看見某物而吃驚，或用來讓對方注意眼前的事。"],
  ["彼はいつも早く来る。", "「いつも早く来る」表示他總是很早來。「いつもの店」則指平常常去的店。「いつも早いわけではない」表示並非每次都早到。"],
  ["水をグラスに注ぐ。", "「水をグラスに注ぐ」是把水倒入玻璃杯。「ワイングラス」是酒杯，「サングラス」則指太陽眼鏡。"],
  ["ホームで電車を待っている。", "鐵路語境中的「ホーム」是「プラットホーム」的簡稱，指月台。「ホームページ」則是另一個固定詞，指網頁、網站或首頁。"],
  ["全ての書類をそろえた。", "「全ての書類」（すべてのしょるい）指所有文件。「書類はすべてそろった」則在句中用「すべて」表示所需的文件全都齊了。「すべて」也可寫成「全て」。"],
  ["男子学生が多いクラスです。", "「男子学生」（だんしがくせい）指男性學生。「男子」可依語境指男孩或成年男性，例如「男子バレー」可指成年男子排球。"],
  ["この地には昔から祭がある。", "「この地」（このち）在本句指當地，「この地には昔から祭がある」是說這地方自古就有祭典。「地に足がつく」的「地」則指腳下的地面。"],
  ["その国の王は国民に愛された。", "「王」（おう）在本句指一國的國王。「本塁打王」指全壘打數排名第一的打者。將棋也可用「王」簡稱王將。"],
  ["両国の軍が国境で向かい合った。", "「両国の軍」（ぐん）指兩國的軍隊。「軍の発表」指軍方發布的消息。在對抗賽等語境中，「東軍」「西軍」也可稱對抗的兩支隊伍。"],
  ["さて、そろそろ始めましょう。", "連接詞「さて」可提示話題或行動要進入下一步。本句是「那麼，差不多該開始了」。在敘事中也可用於轉場，例如「さて、そのころ村では……」。"],
  ["この店は量が多い。", "「量が多い」（りょうがおおい）在本句指餐點分量大。「水の量」是水的用量或存量，「器量」中的「量」則和人的能力或氣度有關。"],
  ["今月の目標を決めた。", "「今月の目標」（もくひょう）指想在本月達成的成果。「大きな木を目標に進む」則是以顯眼的大樹當作辨認方向的標記。"],
  ["温泉に入ってリラックスした。", "「温泉に入る」（おんせんにはいる）指泡溫泉。「温泉に泊まる」則常指在溫泉地的旅館或供住宿的溫泉設施過夜。"],
  ["冬にはスケートをするのが好きだ。", "「スケートをする」在冬季語境通常指滑冰。「スケート靴」指滑冰時穿的冰鞋，和表示運動活動的用法可以靠搭配區分。"],
  ["この日のことは一生忘れない。", "「一生忘れない」（いっしょうわすれない）指一輩子都不會忘記。「一生に一度」則指一輩子只有一次。"],
  ["今日は気分がよい。", "「気分がよい」表示心情好或感覺舒服。「これでよい」表示這樣就可以，「体によい」表示對身體有益。「使いよい道具」則指容易使用的工具。"],
  ["彼は長年の友だ。", "「長年の友」（ながねんのとも）指相交多年的朋友。「本を旅の友にする」則比喻讓書陪伴自己旅行。"],
  ["地下鉄に乗って駅へ行く。", "「地下鉄」（ちかてつ）是地下鐵路，「地下に駐車場がある」的「地下」指地面下方。「地下活動」則可指不公開進行的活動。"],
  ["無事に家に着いた。", "「無事に着く」（ぶじにつく）表示平安抵達。「無事に終わる」則表示過程沒有出問題、順利結束。「家族の無事を祈る」中的「無事」指家人的平安。"],
  ["旅先で古い友人に出会った。", "「友人に出会う」（であう）在本句指在旅途中遇到老朋友。「すばらしい本に出会う」也可表示偶然讀到一本好書。河流交會的語境中則可見「二つの川が出合う」的寫法。"],
  ["説明に図を添えると分かりやすい。", "「図を添える」（ずをそえる）是加上圖示輔助理解。「困り果てた図」則可用來描寫某人不知如何是好的場面。"],
  ["この本は十章から成っている。", "「十章」（じゅっしょう）指這本書共有十個章節。「勲章」中的「章」則指用來表揚功績的徽章。"],
  ["二社が共同で研究を進めている。", "「共同で研究を進める」（きょうどうで）表示兩家公司一起推動研究。「共同所有」則表示由兩個以上的人或團體一起持有。"],
  ["私は理科の授業が好きです。", "「理科の授業」（りかのじゅぎょう）在學校指自然科課程。較廣義的「理科」可泛指自然科學及相關領域，例如與「文科」相對的「理科系」。"],
  ["数字を書いてください。", "「数字」（すうじ）在本句指用來表示數量的數字符號。「売上の数字」則指銷售額等實際數據。"],
  ["映画のこの場面が好きだ。", "「映画の場面」（ばめん）指電影中的一幕。「説明が必要な場面」則指需要解釋的情境。"],
  ["赤ちゃんのへそは小さい。", "「へそ」在本句指肚臍。「へそ」也可比喻事物中央的凸起或凹陷。「日本のへそ」則可用來稱某個被視為日本中心的地方。"],
  ["箱の中には大小様々な石が入っていた。", "「大小様々」（だいしょうさまざま）表示有大有小、尺寸不一。「石の大小を比べる」則是比較石頭的大小。"],
  ["この判断は事実に基づいている。", "「事実に基づく」（もとづく）表示以事實為依據。「実体験に基づく物語」則表示故事取材自實際經歷。"],
  ["丘の上に高い塔が立っている。", "「塔」（とう）在本句指高聳的塔狀建築。「仏塔」則指佛教建築中的塔，例如供奉佛舍利的塔。"],
  ["ポケットから鍵を取り出す。", "「ポケットから鍵を取り出す」（とりだす）是把鑰匙從口袋拿出來。「混ぜた液体から成分を取り出す」則是從混合物中分離並取得所需成分。"],
  ["しみじみとありがたく思う。", "「しみじみとありがたく思う」指深切感受到對方的好意。「しみじみと語り合う」則可指兩人沉靜地談起內心感受或往事。"],
  ["彼はそれを肯定した。", "「肯定する」（こうていする）指承認某事成立或持正面看法。「肯定文」則是文法用語，指用肯定方式陳述的句子。"],
  ["卒業して初めて社会人になった実感がある。", "「実感がある」（じっかんがある）是對一件事有切身感受。「成長を実感する」則是親身感受到自己的成長。"],
  ["この製品の需要は高い。", "「製品の需要」（じゅよう）指市場對產品的需求。「需要が高い」是需求大，「需要と供給」則對照想買的需求與市場能提供的供給。"],
  ["来週は小学校の遠足があります。", "「遠足」（えんそく）在本句指小學安排的戶外團體活動。這個詞也可用於「山への遠足」，表示到山上走一趟、郊遊。"],
  ["原因はまだ断定できない。", "「断定する」（だんていする）指作出確定判斷。本句表示原因還無法確定。文法中的「断定の助動詞」則指表達確定陳述的助動詞，例如「だ」。"],
  ["明日、打合せがあります。", "「打合せ」（うちあわせ，也寫作「打ち合わせ」）在本句指事前商討或協調的會議。用於和服時，「打ち合わせ」也可指衣襟相互重疊的部分。"],
  ["この出合いを大切にしたい。", "「出合い」（であい）在本句指值得珍惜的一次相遇。「人との出会い」常用「出会い」來寫，「川の出合い」則可指兩條河流的交會處。"],
  ["新聞に投書を送った。", "「投書」（とうしょ）在本句是寄給報社、表達意見的讀者來信。「新聞に投書する」則把它當作動作，表示向報社投稿表達看法。"],
  ["体育館に器械が並んでいる。", "「器械」（きかい）可指用於特定用途的器具或儀器，例如「器械体操」用的單槓等器具。同音的「機械」則常用來寫透過機構運轉的機器。"],
  ["このリンクをクリックしてください。", "「リンクをクリックする」中的「リンク」指網頁上的超連結。電腦程式中的「リンク」也可指將個別編譯的程式碼連結起來。"],
  ["その情報はとても役に立ちます。", "「情報」（じょうほう）在本句指可供使用的消息或資料。「情報の授業」則可指日本學校的資訊科課程。"],
  ["彼との関係は良好です。", "「彼との関係」（かんけい）指和他的相處關係。「原因と結果の関係」指兩者的關聯，「事件に関係している」則表示與事件有關或涉入其中。"],
  ["彼は新しいタイを買った。", "「タイ」在本句指領帶。「タイで試合を終える」中的「タイ」則指平手。談紀錄時，「世界記録タイ」表示追平世界紀錄。"],
  ["名前をローマじで書いた。", "「ローマじ」（ローマ字）可指拉丁字母，也可指用拉丁字母拼寫日語的方式。本句表示用羅馬字拼寫姓名。"],
  ["円いテーブルを買った。", "「円い」（まるい）在本句形容桌面是圓形的，也可寫「丸い」。形容一個人的性格變溫和時，通常寫「性格が丸くなる」。"],
  ["祖父は去年、病気で死んだ。", "「病気で死ぬ」（しぬ）指因病死亡。在「この色は照明が悪いと死ぬ」這類比喻中，「死ぬ」則表示原有的效果或活力失去。"],
  ["この都市は急速に発展している。", "「都市が発展する」（はってんする）表示城市發展。「議論が大きな論争に発展した」則用來描述事態，表示討論演變成更大的爭議。"],
  ["彼は成功を希望しています。", "「希望する」（きぼうする）指希望某件事實現。「希望が見えてきた」則表示開始看見有望改善的前景。"],
  ["今、健康食品がブームだ。", "「健康食品がブームだ」指保健食品正流行。「好景気で起きた建設ブーム」則指景氣帶動的建設熱潮。"],
  ["主語と述語の関係を確かめる。", "文法中的「述語」（じゅつご）是說明主語做什麼、是什麼或處於什麼狀態的成分。邏輯中的「述語」則用來表達某個對象具有的性質，或對象之間的關係。"],
  ["人差指で地図を指した。", "「人差指」（ひとさしゆび，也寫作「人差し指」）在本句指用來指出地圖位置的食指。若加上「足の」，則可指腳的第二趾。"],
  ["駅前に酔っ払いがいた。", "「酔っ払い」（よっぱらい）搭配「いた」時，指現場有個喝醉的人。「酔っぱらう」則是動詞，表示喝醉。"],
  ["適確な指示が必要だ。", "「適確」（てきかく）指準確、恰當。「適確な指示」指切合情況、內容明確的指示，這個詞也常寫作「的確」。"],
  ["川に鉄橋がかかっている。", "「鉄橋」（てっきょう）可指以鐵或鋼材建造的橋。在鐵道語境中，如「列車が鉄橋を渡る」，也可指供列車通行的橋。"],
  ["重要な会合が開かれた。", "「会合」（かいごう）在本句指聚集開會。「惑星の会合」則是天文用語，可指從觀測者看來，兩個天體出現在相近方向的合相。"],
  ["彼女は強い女性です。", "「女性」（じょせい）在本句指成年女子。談具有文法性別的語言時，「女性名詞」則指文法上屬於陰性的名詞。"],
  ["彼は新しいスーツを着ている。", "「スーツを着る」在本句指穿西裝。「スーツ」也可用在「ウェットスーツ」等複合詞中，指為特定用途設計的一套服裝。"],
  ["多分、明日は雨でしょう。", "副詞「多分」（たぶん）在本句表示推測，可譯為「大概」。「多分に影響を受ける」中的「多分に」則表示在相當大的程度上受到影響。"],
  ["その男性はとても親切です。", "「男性」（だんせい）在本句指成年男子。談具有文法性別的語言時，「男性名詞」則指文法上屬於陽性的名詞。"],
  ["彼は交通事故に遭いました。", "「交通事故に遭う」（じこにあう）表示遇到交通事故。「事故のため出席できない」在較正式的語境也可能指因臨時有事而無法出席，具體事由需看上下文。"],
  ["牧場で馬に乗った。", "「馬」（うま）在本句指牧場裡可騎乘的馬。將棋中的「馬」（うま）則是「龍馬」的簡稱，指角行升變後的棋子。"],
  ["夏の祭には大勢の人が集まる。", "「夏の祭」（まつり）是夏季祭典。網路口語也會把短時間內湧入大量貼文、討論或批評的情況稱為「祭り」。"],
  ["その州は農業がさかんだ。", "「州」（しゅう）在本句指國家下轄的行政區，例如「カリフォルニア州」。表示大陸區域時也可見於「アジア州」，此時中文通常用「洲」。"],
  ["屋根に雪が積もった。", "「雪が積もる」（つもる）是自動詞用法，表示雪堆積起來。估算費用則常說「費用を見積もる」。"],
  ["自分を責めすぎないで。", "「自分を責める」（せめる）是責怪自己。「彼の不注意を責める」是因對方疏忽而責備他，「厳しく責め立てる」則形容不斷嚴厲責難或逼問。"],
  ["これはスペシャルな日です。", "「スペシャルな日」指特別的一天。「年末スペシャル」在電視語境可指年末特別節目。"],
  ["このマシンはとても速い。", "「マシン」可指機器。若在介紹賽事用車，這句也可譯為「這輛賽車速度很快」。"],
  ["この部屋は家具を具えている。", "「家具を具える」（そなえる）指備有家具，也可寫作「家具を備える」。「必要な能力を備える」則指具備所需能力。"],
  ["彼女はゴールドのネックレスをしています。", "「ゴールドのネックレス」依語境可指黃金項鍊或金色項鍊。要明確交代材質，可說「金製のネックレス」。"],
  ["必要な書類とその他を用意してください。", "「その他」（そのほか）在本句表示文件以外還需要準備的項目。句首的「そのほか、質問はありますか」則是在問除此之外是否還有問題。"],
  ["この社は山の神を祭っている。", "「神を祭る」（まつる）指舉行祭祀或供奉神明，在這個語境也可寫成「祀る」。本句是說這座神社供奉山神。"],
  ["その事実は明らかだ。", "「事実が明らかだ」（あきらかだ）表示事實很明確。「明らかな間違い」是明顯的錯誤，「原因を明らかにする」則是查明原因。"],
  ["庖丁で野菜を切った。", "「庖丁」（ほうちょう，也寫作「包丁」）在本句指用來切菜的刀。舊用法也可指烹調本身。"],
  ["目覚しが六時に鳴った。", "「目覚し」（めざまし）在本句是「目覚まし時計」的簡稱，指鬧鐘。「目覚ましにコーヒーを飲む」則指喝咖啡提神。"],
  ["子供たちはモンスターの物語が好きです。", "「モンスター」在本句指故事中的怪物。「モンスター級の選手」則是比喻，形容選手強得遠超一般水準。"],
  ["彼は大学のラボで研究しています。", "「大学のラボ」在本句指研究用的實驗室。「語学ラボ」則可指配有聽說練習設備的語言教室。"],
  ["充電ケーブルを忘れてしまった。", "「充電ケーブル」是充電線，本句表示忘了帶充電線。「ケーブルカー」則以纜索牽引車輛，「ケーブル」在這個複合詞中指纜索。"],
  ["彼の未来は明るい。", "「未来が明るい」（みらいがあかるい）指往後的發展有希望。文法術語「未来形」則指某些語言用來表達將來時間的形式。"],
  ["レストランでチップを渡した。", "「チップを渡す」在餐廳語境中指給小費。「ボールペンのチップ」則可指筆尖的組件，意思要看所搭配的物品。"],
  ["長いトンネルを抜ける。", "「トンネルを抜ける」指穿過隧道。棒球口語中的「トンネル」則比喻守備時讓滾地球從兩腿之間穿過。"],
  ["彼は文芸作品を多く読んでいる。", "「文芸作品」（ぶんげいさくひん）在本句指小說、詩等文學作品。「文芸」有時也可廣指文學與藝術，要依語境判斷。"],
  ["伯母さんが遊びに来た。", "「伯母さん」（おばさん）可指父母的姊姊，或父母的哥哥的妻子。這句只說她來家裡玩，未交代是哪一方的親屬。若是父母的妹妹或弟弟的妻子，通常寫「叔母さん」。"],
  ["その少年はとても元気だ。", "「少年」（しょうねん）在本句指少年或男孩。在「少年少女」這類並列用法裡，「少年」與「少女」相對。在「青少年」等複合詞中則可泛指年輕族群。"],
  ["茶碗にお茶を注した。", "「お茶を注す」（さす）在本句是把茶斟進碗裡。讀音相同的「紅を差す」則指塗上口紅，通常寫作「差す」。"],
  ["祖母は琴を弾く。", "「琴」（こと）在本句通常指日本的箏，也就是把琴身橫放、用手撥弦的樂器。「琴」在較廣泛的用法也可指同類的弦樂器。"],
  ["彼は有名なタレントだ。", "「タレント」在本句指常在電視、廣播等媒體露面的藝人。「タレントマネジメント」在人事管理語境中，則常指人才管理。"],
  ["彼の表現は豊かだ。", "「表現」（ひょうげん）在本句指用語言或其他方式表達的內容與手法。數學中的「群の表現」則是把群的元素對應到線性變換，並保留群的運算關係。"],
  ["古代文明の遺跡が発見された。", "「古代文明」（こだいぶんめい）指古代社會所形成的文明。「文明元年」中的「文明」則是日本的年號，字形和讀音相同。"],
  ["いろいろな本を読みます。", "「いろいろな本」指各式各樣的書。「いろいろ試す」則表示嘗試多種方法，「いろいろある」可指還有各種事物或情況。"],
  ["彼の突然の訪問にびっくりした。", "「びっくりする」指突然吃驚，本句的「に」標示讓人吃驚的原因，也就是他突然來訪。「びっくり箱」則指打開會跳出東西嚇人一跳的玩具。"],
  ["大切な書類なので、書留で送りました。", "「書留」（かきとめ）在郵寄語境指掛號郵件。「書留で送る」是用掛號寄送。「メモに書き留める」則是把資訊記下來。"],
  ["部長としての務めを果たす。", "「務め」（つとめ）在本句指部長應盡的職責。「務めを果たす」是履行職責。「勤め先」則常用同音的「勤め」，指任職的地方。"],
  ["父は毎朝、勤めに出かける。", "「勤め」（つとめ）在本句指工作，「勤めに出かける」是出門上班。佛寺語境中的「お勤め」也可指誦經等例行佛事。"],
  ["秋には紅葉が美しい。", "「紅葉」（こうよう）可指葉片在秋季轉紅，也可指變色的葉景。本句是說秋天的紅葉景色很美。「紅葉狩り」通常讀作「もみじがり」，是到戶外觀賞秋葉。"],
  ["答えはここに在る。", "「ここに在る」（ある）表示存在於這裡，也常直接寫成假名「ある」。強調擁有某物時則可寫「有る」，例如「時間が有る」。"],
  ["小麦粉に砂糖を交ぜた。", "「砂糖を交ぜる」（まぜる）指把糖摻進去，也常寫作「混ぜる」。讓原本分開的人或事物加入同一群時，也可用「交ぜる」，例如「仲間に交ぜる」。"],
  ["この部屋は幅が3メートルあります。", "「メートル」在本句是長度單位「公尺」。「幅が三メートル」表示房間寬三公尺。表示測量用的儀表時，現代日語常寫「メーター」，例如「ガスメーター」。"],
  ["素晴らしい景色ですね。", "「素晴らしい」（すばらしい）在本句用來稱讚景色優美。「素晴らしい成績」則形容成績出色。"],
  ["彼女の表情はとても明るかった。", "「明るい表情」（あかるいひょうじょう）指臉上流露出愉快的神情。「声に表情をつける」則指透過語調等變化傳達情緒。"],
  ["今日はやや寒い。", "副詞「やや」在本句修飾形容詞「寒い」，表示有點冷。「やや遅れる」則表示稍微晚到，修飾的是動作。"],
  ["公園の桜が満開になった。", "「桜」（さくら）可指櫻樹或櫻花，搭配「満開」時，重點是花已盛開。「桜色」指淡粉色。招攬生意時假扮顧客的人也可稱「サクラ」，常用片假名書寫。"],
  ["駅はいつも混雑している。", "「混雑する」（こんざつする）在本句指車站人多擁擠。「窓口が混雑している」也可形容洽辦的人多、秩序較亂。"],
  ["膨大な資料を整理した。", "「膨大な資料」（ぼうだいなしりょう）是數量非常多的資料。「費用が膨大になる」則表示費用增加到很大的金額。"],
  ["彼はバカじゃない。", "「バカじゃない」表示他並不愚蠢。「バカな話」可指荒唐的話。「ねじがバカになる」則形容螺紋滑牙、失去作用。"],
  ["子どものころ、よく川で遊んだ。", "「子どものころ」指童年那段時間。接在時刻後則可表示大約，例如「三時ごろ」是三點左右。"],
  ["週末にデートの予定がある。", "「デートの予定」在本句指約會行程。「デート機能」在相機等設備的語境則可指記錄或顯示日期的功能。"],
  ["大きなトラックが道を走っていた。", "「トラック」在本句指公路上載貨的卡車。同形的「トラック」也可指田徑跑道或錄音的音軌，例如「音声トラック」。"],
  ["すべての準備が整いました。", "「すべての準備」指一切準備工作。「準備はすべて整った」則把「すべて」放在動詞前，表示各項準備全都完成。「すべて」也可寫成「全て」。"],
  ["自己紹介をしてください。", "「自己紹介」（じこしょうかい）是自我介紹。「友人を紹介する」是介紹朋友讓人認識，「新製品を紹介する」則是向人說明新產品。"],
  ["農家はビニールハウスでトマトを育てている。", "「ビニールハウス」指用塑膠膜覆蓋的溫室，例句說農家在溫室裡種番茄。「ハウス」也見於表示房屋的「モデルハウス」，也就是供人參觀的樣品屋。"],
  ["この料理にはソースが必要です。", "「ソース」在本句指搭配料理的醬汁。談到日式炸豬排等料理時，也常指伍斯特醬一類的調味醬。同形的「ソース」在資訊語境則可指來源。"],
  ["マッチをすってろうそくに火をつけた。", "「マッチを擦る」指擦火柴，本句是用火柴點蠟燭。「タイトルマッチ」中的「マッチ」指比賽，「色がマッチする」則表示顏色搭配得宜。"],
  ["人々は神に祈りを捧げた。", "「神」（かみ）在本句是名詞，「に」標示人們祈禱的對象。口語的「神対応」則是高度稱讚對方的處理或服務非常出色。"],
  ["母の側にずっといた。", "「母の側」（ははのそば）指母親身旁。「聞いたそばから忘れる」則把「そばから」接在動詞後，表示一聽完馬上就忘。這個句型通常用假名寫。"],
  ["彼らのチームが大会で優勝した。", "「優勝する」（ゆうしょうする）指在競賽中奪冠。本句表示他們的隊伍拿到冠軍。「大会で」標示奪冠的場合。"],
  ["このチケットは明日まで有効です。", "「明日まで有効」（ゆうこう）表示票券到明天仍可使用。「この方法は有効だ」則表示做法能發揮作用。柔道的「有効」另可作計分術語。"],
  ["畑の土を掘り返した。", "「畑の土」（はたけのつち）指田地裡的土壤。「土に足をつける」則可指腳踏到地上。"],
  ["川で子どもたちが遊んでいる。", "「川」（かわ）在本句指孩子們遊玩的河流所在之處。接在河流名稱後的「川」則常讀作「がわ」，例如「隅田川」（すみだがわ）。"],
  ["結果を見てがっかりした。", "「がっかりする」表示期待落空而失望。「結果を見て」指出發生在看到結果之後。「がっかりさせる」則表示讓他人感到失望。"],
  ["ガムを噛む。", "「ガムを噛む」指嚼口香糖，「ガム」是「チューインガム」的簡稱。「ガムテープ」則指用來封箱等用途的膠帶。"],
  ["彼女は涙を流した。", "「涙を流す」（なみだをながす）指流淚。「涙を誘う話」則形容令人感動或同情、容易讓人落淚的故事。"],
  ["正の数と負の数を習った。", "「正の数」（せいのかず）是在數學中大於零的數，與「負の数」相對。需要判斷正誤時，「正」則表示正確，與「誤」相對。"],
  ["彼らはとても仲良しです。", "「仲良し」（なかよし）可表示彼此感情好，如本句，也可指關係親近的朋友，例如「昔からの仲良し」。"],
  ["海辺の大きな岩に波が当たる。", "「岩」指海邊的大岩石。「岩壁」則指陡峭而像牆壁的岩面。"],
  ["ガソリンのメーターがEを指している。", "「メーター」指顯示剩餘油量的油量表，E 表示油量接近空。長度單位「公尺」通常寫作「メートル」。"],
  ["この鳥は大陸から渡ってくる。", "「大陸」指候鳥飛來的大片陸地。若從日本說起，這裡可指亞洲大陸。"],
  ["彼女はいつも青いジーンズを履いている。", "「ジーンズ」在這裡指她穿的藍色牛仔褲。要特指製作牛仔褲的布料，可說「デニム生地」。"],
  ["毎朝、体操をしています。", "「体操」指每天早上做的健身操。「体操競技」指競技體操，「体育」則可指學校的體育課。"],
  ["彼の好みは私と違う。", "「好み」指個人偏好。形容喜歡的口味可說「好みの味」，食譜中的「お好みで」表示可依個人口味調整。"],
  ["彼は大きなあくびをした。", "「あくびをする」表示打哈欠。「あくび」也可用來稱呼漢字部首「欠」。"],
  ["大きな河を船で渡った。", "「河」在這句讀作「かわ」，指搭船渡過的大河。日常也常寫作「川」。地名「黄河」中的「河」則讀「が」。"],
  ["棚の上に塵がたまっている。", "「塵」在這裡指架子上積起來的灰塵，也可指細小的碎屑或垃圾。"],
  ["天井裏で鼠が走る音がした。", "「鼠」在這裡指在天花板上方跑動的老鼠。「鼠色」則用老鼠的毛色來稱呼灰色。"],
  ["コピーの枚数を確認してください。", "「コピーの枚数」指影印件的張數。相撲也用「枚」計算番付上的名次差，例如「三枚上がる」指排名提升三個位次。"],
  ["水道の管が破れて水が漏れた。", "「水道の管」的「管（くだ）」指輸送水的管子。紡織語境的「管」也可指梭子或紡車上用來捲線的線軸。"],
  ["学園祭で劇を上演した。", "「劇を上演する」指上演戲劇。藥品語境中，「劇」也可用作「劇薬」的簡稱，指藥理作用強、需要慎用的藥品。"],
  ["この家はモダンなデザインで建てられた。", "「モダンなデザイン」指現代風格的設計。眼鏡業也把鏡腳末端貼近耳朵的套件稱為「モダン」，又叫「先セル」。"],
  ["動物園で虎を見た。", "「虎（とら）」在這句指動物園裡的老虎。口語中也可用來比喻喝醉的人，如「大虎」。"],
  ["食べすぎて胃が重い。", "「胃が重い」指胃部不適、有沉重感。「胃」也可用於天文名稱「胃宿」，是二十八宿之一。"],
  ["校庭に旗が立っている。", "「旗（はた）」在這裡指校園裡的旗子。內蒙古的行政區劃名稱也使用「旗」，如「正藍旗」。"],
  ["この通りには店が三軒ある。", "「三軒（さんげん）」表示三間店。「軒」讀「のき」時可指屋簷，如「軒先」。它也可用於號或藝名的結尾。"],
  ["彼は研究室の助手をしている。", "「研究室の助手」指在研究室協助工作的人，也可指協助教師或研究人員的職務。「撮影助手」則指協助拍攝的人。"],
  ["沖に漁船が何隻も見える。", "「沖に漁船が見える」的「沖（おき）」指離岸的海面。地名縮寫中的「沖」也可指沖繩，需看它所在的詞或標題。"],
  ["電車の出発時刻を確認した。", "「出発時刻」指列車出發的具體時間。若是文學或較舊的用法，「時刻」也可能表示適合做某事的時機。"],
  ["みんなの知恵を借りたい。", "「みんなの知恵を借りる」指借助大家的點子和判斷力。佛教語境的「智慧（ちえ）」也可指通往覺悟的洞察力。"],
  ["修理に莫大な費用がかかった。", "「莫大な費用」指巨額費用。食材或生藥資料中的「莫大（ばくだい）」也可指胖大海。"],
  ["荷物を縄でしばった。", "「縄（なわ）」在這裡指綁行李的繩子。舊時也指捕人的繩索，相關說法「お縄になる」表示被捕。"],
  ["今朝は畑に霜が降りた。", "「霜が降りる」指草木或地面結霜。詩文裡也可以用白霜比喻白髮。"],
  ["丘の上から町が見渡せる。", "「丘（おか）」在這裡指可以俯瞰小鎮的山丘。麻將計分中的「オカ」則指結算時給第一名的額外分數。"],
  ["席を年寄に譲った。", "「席を年寄に譲る」指把座位讓給長者。大相撲也用「年寄（としより）」稱呼取得年寄資格的退役力士，通稱「親方」。江戶時代的史料中也可見作為職稱的「年寄」。"],
  ["駅で偶々昔の友人に会った。", "「駅で偶々会った」的「たまたま」表示碰巧遇見。它也可表示低頻率的「偶爾」，需依句子判斷重點是巧合還是頻率。"],
  ["城の周りに濠がめぐらされている。", "「城の周りに濠がめぐらされている」描述城堡四周挖有護城河。「濠（ほり）」也可指水渠或壕溝。"],
  ["日本では二十で酒が飲める。", "「二十で」在這句指年滿二十歲，讀作「はたち」。單指數字二十，通常讀作「にじゅう」。"],
  ["今日の試合は負けだった。", "「今日の試合は負けだった」指今天比賽輸了。「名前負け」指實際表現配不上名字，「お負けする」則可指折價或多送一點。"],
  ["近くの店でランチを食べた。", "「ランチを食べる」指吃午餐。菜單上的「日替わりランチ」也可指店家每日更換菜色的午間套餐。"],
  ["サービスを改善する。", "「サービスを改善する」指把服務做得更好。在製造與管理語境裡，「改善（カイゼン）」也可指持續找出問題、逐步改進工作流程的做法。"],
  ["会社の方針が変わった。", "「会社の方針」指公司做事的方向或原則。「方針」也可作名詞指指南針的磁針，依上下文區分。"],
  ["めでたい知らせが届いた。", "「めでたい知らせ」指值得慶賀的消息。用「おめでたい」形容人時，也可能帶有諷刺意味，說對方天真或太容易相信別人。"],
  ["今日は大分暖かい。", "「大分（だいぶ）暖かい」的意思是「暖和許多」。地名「大分県」的「大分」讀作「おおいた」。"],
  ["彼の成功に期待しています。", "「彼の成功に期待する」表示盼望他成功。「期待の新人」則指被看好、很有發展潛力的新人。"],
  ["三社が連合して開発する。", "「三社が連合して」表示三家公司聯合開發。日本勞工新聞中的「連合」也可作為「日本労働組合総連合会」的簡稱。"],
  ["子供が風船で遊んでいる。", "「風船で遊ぶ」的「風船」指玩具氣球。它也可指升空的氣球，例如「観測用の風船」。"],
  ["この車のメーカーはどこですか？", "「車のメーカー」指汽車製造商。「コーヒーメーカー」的「メーカー」則出現在製作咖啡的器具名稱裡。"],
  ["祖母は犬をかわいがっている。", "「犬をかわいがる」指疼愛、善待狗，也可用來表示格外照顧或偏愛某人。某些訓練場合會反諷地用「かわいがる」指嚴厲操練或欺負人。"],
  ["城の堀に水が張られている。", "「城の堀」指城堡外的壕溝，這裡有蓄水。「堀」也可指人工挖成的水道或溝渠。"],
  ["芸能界で活躍する。", "「芸能界」指演藝界。「伝統芸能」的「芸能」指傳統表演藝術；在較廣的用法中也可指習得的技藝。"],
  ["彼は役者として有名だ。", "「役者として有名だ」指以演員身分聞名。比喻說某人「なかなかの役者だ」，也可能是說對方很會演、很有手腕。"],
  ["彼に恨みはない。", "「彼に恨みはない」指對他沒有怨恨。「心残り」一類的語境中，「恨み」也可表示事情未能如願的遺憾。"],
  ["彼はチームのリーダーです。", "「チームのリーダー」指團隊領導者。文書排版的「リーダー」則指在欄位間引導視線的符號，例如目錄標題與頁碼之間的一串點。"],
  ["原始の森が残っている。", "「原始の森」指保有原始面貌的森林。「原始」也可指事物最初的階段或起源。"],
  ["彼は頭脳が明晰だ。", "「頭脳が明晰だ」表示頭腦清楚、思路明晰。比喻說「チームの頭脳」時，可以指負責思考或擬定策略的核心人物。"],
  ["先生の指導のおかげで、試験に合格できました。", "「先生の指導」指老師提供的教導。柔道比賽中的「指導」則是裁判對輕微違規給予的處分。"],
  ["水をやらずに花が枯れた。", "「花が枯れた」指花枯萎了。「枯れた演技」則可形容演技老練、自然，帶有成熟的意味。"],
  ["駅前に高層ビルが建った。", "「高層ビル」指樓層多、樓體高的建築。「高層気象」的「高層」則指較高處的大氣。"],
  ["矢印の方向に進んでください。", "「矢印の方向」指箭頭所指的方向。描述人物關係時，箭頭也可用來比喻某人的注意或好感指向誰。"],
  ["日本は南北に長い。", "「南北に長い」指由南到北的距離長。「南北朝鮮」的「南北」則用來合稱南韓與北韓。"],
  ["それはエチケットの問題だ。", "「エチケットの問題」指禮節問題。在葡萄酒語境中，「エチケット」也可指貼在酒瓶上的酒標。"],
  ["彼は実力でその地位を勝ち取った。", "「実力で勝ち取る」指靠真本事取得成果。「実力行使」則指採取強制手段，以實際力量達成目的。"],
  ["やかんから蒸気が出ている。", "「やかんから出る蒸気」指水壺冒出的水蒸氣。舊文獻中，單說「蒸気」也可指「蒸気船」或「蒸気機関車」。"],
  ["兵隊が橋を見張っていた。", "「橋を見張っていた兵隊」指守橋的士兵。「兵隊」可泛指軍隊，借用到職場時也可能指執行命令的基層人員。"],
  ["結婚して姓が変わった。", "「結婚して姓が変わった」指結婚後更改姓氏。談古代日本時，「姓」也可讀作「かばね」，指表示氏族身分地位的世襲稱號。"],
  ["近々お会いしましょう。", "「近々お会いしましょう」的「近々（ちかぢか）」指時間上的「近日」。描述位置時，「近々」也可表示距離很近。"],
  ["下町には古い店が多い。", "「下町には古い店が多い」指城市中保有許多老店的平民街區。「東京の下町」常指淺草等舊市街一帶。"],
  ["二人で綱を引っ張った。", "「二人で綱を引っ張った」的「綱」指粗繩。相撲的「横綱の綱」則指橫綱在入場儀式上繫在腰間的繩索。"],
  ["どちらの方角へ行けばいいですか？", "「どちらの方角」是在問往哪個方向走。「北の方角」是用方位描述方向；較少見的用法也可指處理事情的方法。"],
  ["岬の先に灯台が見える。", "「岬の先に見える灯台」指為船隻導航的燈塔。古代生活用具中的「灯台」也可指把油燈架高的燈架。"],
  ["人種差別は許されない。", "「人種差別」的「人種」指以族群身分或外貌特徵區分的人群。口語的「そういう人種」也可泛指某一類人，語氣可能帶有貶意。"],
  ["客を座敷に通した。", "「客を座敷に通す」指請客人進入鋪榻榻米的房間。在藝伎語境裡，「お座敷」也可指宴席或席間的表演邀約。"],
  ["生命の起源について研究する。", "「生命の起源」指生物生命的起源。比喻用法如「作家生命」，指一個人能以作家身分持續創作的生涯。"],
  ["彼は手紙を裂いて捨てた。", "「手紙を裂く」指把信撕開。描述人際關係時，「二人の仲を裂く」可比喻強行拆散兩人。"],
  ["不潔な場所は病気のもとだ。", "「不潔な場所」指環境骯髒或不衛生。形容談話內容時，「不潔」也可能指下流或不雅。"],
  ["結婚指輪は薬指にはめる。", "「指輪を薬指にはめる」的「薬指」指手上戴戒指的無名指。說「足の薬指」時，則指從大腳趾數過去的第四趾。"],
  ["椀にみそ汁を注いだ。", "「椀にみそ汁を注ぐ」指把味噌湯倒進碗裡。「一椀の汁」的「椀」也可用來計算以碗盛裝的份量。"],
  ["その年は大きな飢饉があった。", "「大きな飢饉」指一場嚴重的糧食短缺。「水飢饉」則借用「飢饉」表示嚴重缺水。"],
  ["子どもにおやつをあげた。", "「子どもにおやつをあげる」指給孩子吃正餐之間的點心。「三時のおやつ」特指下午三點左右的點心。"],
  ["彼女は有名なアイドルです。", "「有名なアイドル」指知名偶像藝人。「アイドル」也可指受人崇拜的人物，宗教語境中則可指供奉的偶像。"],
  ["車のドアをロックした。", "「ドアをロックする」指把門鎖上。橄欖球的「ロック」是球員位置，音樂語境的「ロック」則是搖滾樂。"],
  ["子供たちはブロックで遊んだ。", "「ブロックで遊ぶ」指玩積木。「コンクリートブロック」是混凝土砌塊，社群網站的「ブロックする」則是封鎖某人。"],
  ["この製品の最大の特色は何ですか？", "「製品の特色」指產品與眾不同的特點。印刷中的「特色」指用預先調配的專色油墨印出的顏色。"],
  ["彼はYouTubeで動画をよく見ます。", "例句的「動画」指影音平台上的影片。動畫製作中，「動画」也可特指填補原畫間動作的中間畫。"],
  ["原子力発電は議論の的だ。", "「原子力発電」中的「発電」指產生電力。舊文獻中的「発電」也可能是發送電報，需依年代和上下文判斷。"],
  ["旗がポールに掲げられている。", "「旗がポールに掲げられている」的「ポール」指懸掛旗幟的桿子。電車的「トロリーポール」則指接觸架空電線的集電桿。"],
  ["彼の判断は正しかった。", "「彼の判断」指他依據情況作出的判斷。占卜語境裡，「姓名判断」是按姓名推測運勢的說法。"],
  ["その会社のロゴはとてもシンプルだ。", "「会社のロゴ」指公司用來辨識品牌的標誌。在電腦教育語境裡，「ロゴ」也可指一種常用來教學的程式語言。"],
  ["全体の計画を見直す必要がある。", "「全体の計画」指整體計畫。疑問句中的「全体どうしたのか」是較舊的強調用法，可理解成「究竟怎麼回事」。"],
  ["いい店を見付けた。", "「いい店を見付けた」指找到一家好店。「見付ける」也可表示看慣，常見於「見つけない顔」這類說法，指不常見到的面孔。"],
  ["受付の人に伝言をことづけた。", "「伝言をことづける」指託別人傳話。「ことづける」另可寫作「託ける」，在「病気に託けて」等用法中表示拿某事當藉口。"],
  ["この村は耕地が少ない。", "「村の耕地」指可供耕種的土地。翻譯拉丁美洲的農業史時，「耕地」也可能指大型農莊或種植園。"],
  ["その少女はとても可愛い。", "「その少女」在現代日語指年輕女孩。日本律令時代的「少女」也曾用作具有特定年齡範圍的人口分類。"],
  ["日が照る日に草を干す。", "「日が照る」指陽光照耀。能樂語境也用「照る」描述面具略向上仰、看起來較明朗的姿態。"],
  ["犬が猫を追い掛けている。", "「犬が猫を追い掛ける」指狗追著貓跑。「追いかけて」有時也表示某事緊接在前一件事之後發生。"],
  ["テレビで新しい車の広告を見た。", "「新しい車の広告」指宣傳新車的廣告。「広告」也可泛指公開告知的訊息，像是公告徵求應徵者。"],
  ["薬缶でお湯を沸かした。", "「薬缶（やかん）でお湯を沸かす」指用水壺燒水。比喻用法中，也有人用「薬缶」戲稱光頭。"],
  ["連れが外で待っています。", "「連れが外で待っている」的「連れ」指一起來的同伴。能樂的「ツレ」則是協助主角「シテ」演出的角色。"],
  ["最近、忙しいですか。", "「最近、忙しいですか」的「最近」指近來。技術用語「最近点」則指距離最短的點。"],
  ["詳しい説明をお願いします。", "「詳しい説明」是對事情的詳細解說。「図の説明」也可指附在圖旁的說明文字。"],
  ["彼はきっと来るでしょう。", "「きっと来るでしょう」表示說話者有把握對方會來。「きっとにらむ」則形容目光嚴厲地瞪視。"],
  ["彼女はピンクのドレスを着ていた。", "「ピンクのドレス」指粉紅色洋裝。「ピンク映画」則是成人情色電影的類型名稱。"],
  ["私はペットを飼っています。", "「ペットを飼う」表示飼養寵物。在樂團口語中，「ペット」也可能是小號「トランペット」的簡稱。"],
  ["日本の文化に興味があります。", "「日本の文化」指日本的文化。「文化」也曾是日本江戶時代的年號，例如史料上的「文化三年」。"],
  ["問題を解決する良い方法を見つけた。", "「方法を見つける」指找到方法。「見つける」也可表示看慣，例如「見つけない顔」指陌生面孔。"],
  ["デザートにアップルパイを食べました。", "「アップルパイ」指蘋果派。「パイ」也可用於其他酥皮點心的名稱，例如蝴蝶形的酥餅。"],
  ["成績を表にまとめた。", "「成績を表にまとめる」表示把成績整理成表格。古代文書裡，「表」也可指臣子向君主呈上的奏表，例如「出師の表」。"],
  ["結局、彼は来なかった。", "「結局、彼は来なかった」的「結局」是副詞，表示到頭來他沒來。在棋局記錄裡，「結局」也可作名詞，指對局結束。"],
  ["睡眠が不足している。", "「睡眠が不足している」指睡眠量不夠。「不足を言う」則可指抱怨或表示不滿。"],
  ["その話は悪魔のささやきのようだ。", "「悪魔のささやき」用惡魔低語比喻誘惑人的話。宗教文獻中，「悪魔」也可依傳統指撒旦或佛教的魔羅。"],
  ["床にごみが落ちている。", "「床にごみが落ちている」的「床（ゆか）」指地板。文樂的「床」可指太夫和三味線演奏者所在的台座；京都的「納涼床」則是水邊搭設的用餐平台。"],
  ["彼はこの研究に大きく貢献した。", "「研究に貢献する」表示對研究作出貢獻。歷史文獻中的「貢献」也可能指向君主或其他政權進貢。"],
  ["この商品は10米ドルです。", "「米ドル」明確指美元。單說「ドル」通常也指美元，但「豪ドル」和「カナダドル」是其他貨幣；泛指錢的俚俗用法須依語境辨認。"],
  ["親の愛は見返りを求めない。", "「親の愛」指父母的關愛。佛教語境中的「愛」可指貪著；在國名的舊式漢字縮寫中，「愛」也可代表愛爾蘭。"],
  ["長時間の労働で疲れた。", "「長時間の労働」指長時間工作。政治文獻有時也用「労働」簡稱「労働党」。"],
  ["港に大きな船が停まっている。", "「港に大きな船が停まっている」的「船」指船隻。同讀「ふね」的「槽」可指容器；「刺身の舟盛り」則指把生魚片盛在船形容器中。"],
  ["今日のおかずは何ですか。", "「今日のおかず」指今天的配飯菜。鼓手可用「おかず」稱呼加在基本節奏中的過門；成人俚語中的「おかず」則可指用於性幻想的素材。"],
  ["椅子から尻が滑り落ちた。", "「椅子から尻が滑り落ちる」的「尻」指臀部。「瓶の尻」可指瓶底；「尻拭い」則可比喻替別人收拾留下的麻煩。"],
  ["王子様はとてもハンサムです。", "「王子様」通常指王子。熊野古道中的「九十九王子」是沿途一系列供奉熊野神祇的王子社，「王子」在這裡屬於神社名稱。"],
  ["この門は鉄でできている。", "「鉄でできている」描述鐵製品，也可泛指鋼鐵材質。「鉄の意志」比喻堅強意志；興趣語境裡單說「鉄」也可指鐵道或鐵道迷。"],
  ["社長夫人が挨拶をした。", "「社長夫人」是對社長妻子的敬稱。古代日本史中的「夫人」也曾用作貴族妻子或天皇妃嬪的稱號，具體身分須依時代判斷。"],
  ["彼はその点の重要性を強調した。", "「重要性を強調する」表示特別凸顯其重要性。金融新聞的「強調相場」則是走勢偏強的行情。"],
  ["小麦の粉を水で溶いた。", "「小麦の粉」指麵粉。「粉」也可泛稱粉末；在毒品俚語中可能特指海洛因，須依語境判斷。"],
  ["春になって木の芽が出てきた。", "「木の芽が出てきた」指樹上冒出新芽。談禽蛋構造時，「芽」也可指卵黃表面日後可能發育成胚胎的小區域。"],
  ["貨物列車が駅を通過した。", "「貨物列車」指運送貨物的列車。舊文獻中，「貨物」也可指財物或資產。"],
  ["この郡には町が三つある。", "「この郡には町が三つある」的「郡（ぐん）」指日本包含町或村的地理區劃。日本律令時代和古代中國也各有稱為「郡」的行政區劃。"],
  ["関東は今日雨だ。", "「関東は今日雨だ」的「関東」指以東京為中心的關東地方。在舊史料裡，「関東」所指的範圍可以更廣，須依時代判斷。"],
  ["紫の花が咲いている。", "「紫の花」指紫色的花。「ムラサキ」也是一種可用作染料的植物名稱；在壽司店等場合，「むらさき」還可指醬油。"],
  ["近代史を勉強している。", "「近代史」是研究近代的歷史。日本史裡，談「日本の近代」常以明治維新前後為起點，和今天所處的「現代」是不同的歷史分期。"],
  ["国王が国民に演説した。", "「国王が国民に演説した」的「国王」指發表演說的君主。法律或政治文獻中的「国王」也可指作為制度的王權。"],
  ["彼は相撲を見るのが好きだ。", "「相撲を見る」的「相撲」指觀看相撲競技。口語中的「お相撲さん」則指相撲選手，正式稱「力士」。"],
  ["はさみで紙を切ってください。", "「はさみで紙を切る」指用剪刀剪紙。「はさみ」也可指剪出孔洞的工具；一般文具打孔器常稱「穴あけパンチ」。"],
  ["彼は危険を警告した。", "「危険を警告する」指提醒他人注意危險。舊制柔道競賽裡，「警告」曾用作判罰名稱，閱讀比賽記錄時須留意當時的規則。"],
  ["過剰な情報に注意してください。", "「過剰な情報」指多到超出需要的資訊。「情報過剰」也能用來描述同一狀態；相對的「情報不足」則是資訊不夠。"],
  ["両国は外交を通じて問題を解決した。", "「外交を通じて」指透過國家之間的交涉。商業語境中的「外交」也可指到外面拜訪客戶、招攬生意。"],
  ["日本国憲法は1947年に施行されました。", "「日本国憲法」指日本的根本法。古代文獻中，「憲法」也可以指規範或法令，如「十七条の憲法」。"],
  ["今夜はピザを食べよう。", "「ピザを食べよう」的「ピザ」指披薩。網路上用「ピザ」稱呼別人時，可能是拿體型開玩笑的貶抑用語。"],
  ["日本は自動車を多く輸出している。", "「自動車を輸出する」指把汽車出口到國外。生理學的「輸出細動脈」則用「輸出」表示血液從腎絲球流出。"],
  ["日本は多くの食料を輸入しています。", "「食料を輸入する」指從國外進口食物。生理學的「輸入細動脈」則用「輸入」表示血液流入腎絲球。"],
  ["彼女は浴衣に下駄を履いていた。", "「下駄を履く」指穿木屐。漁業用語的「下駄」也可指拖網上的構件；印刷舊稱「下駄」則可指倒置活字留下的記號。"],
  ["卵を五分ゆでた。", "「卵をゆでる」指把雞蛋放入熱水中煮。舊式用法也可指用藥草產生的蒸氣熏蒸患處。"],
  ["氷の上で転んだ。", "「氷の上で転ぶ」指在冰上滑倒。「どちらに転ぶか」也可借指事情會往哪一方發展；日本宗教史料中還可指改宗或棄教。"],
  ["大学の寮に住んでいる。", "「大学の寮」指大學宿舍。古代日本官制中的「寮」也可指官署，例如負責天文與曆法等事務的「陰陽寮」。"],
  ["古い寺院を訪ねた。", "「古い寺院を訪ねた」通常可理解成參訪古老的佛寺。談其他宗教的建築時，「寺院」也可用作宗教場所的泛稱。"],
  ["国会で新しい法律が議論された。", "「国会で法律が議論された」的「国会」指國家立法機關。日本現行國會於戰後成立，舊制度下的正式名稱是「帝国議会」。"],
  ["彼はポケットから硬貨を取り出した。", "「ポケットから硬貨を取り出す」的「硬貨」指硬幣。國際金融語境中也可指幣值相對穩定、容易兌換的強勢貨幣。"],
  ["お住まいはどちらですか。", "「お住まいはどちらですか」是在客氣地問對方住在哪裡。「一人住まい」則描述獨居的生活狀態。"],
  ["この容器は真空になっている。", "「容器が真空になっている」描述容器內空氣被抽除的狀態。「真空」也可泛指空無一物的狀態。"],
  ["この半島は海に突き出ている。", "「海に突き出ている半島」指伸入海中的陸地。談南北韓局勢的文章裡，如果前文已提到朝鮮半島，後面單說「半島」也可能指朝鮮半島。"],
  ["彼の過失で事故が起きた。", "「彼の過失で事故が起きた」的「過失」指導致事故的疏失。「過失」也可泛指過錯，法律語境則常與「故意」區分。"],
  ["道に標識が立っている。", "「道に立っている標識」指道路上供人辨認的標誌。「標識」也可指用於識別或追蹤的標記，如「標識を付けた鳥」。"],
  ["彼は宗教を信じていない。", "「宗教を信じていない」的「宗教」指信仰或信仰體系。「宗教活動」則把焦點放在依信仰進行的集會、儀式等活動。"],
  ["この道は平らなので歩きやすい。", "「道が平ら」表示路面平坦。「お平らに」則是請對方放鬆坐姿的客氣說法，例如請對方把正坐的姿勢放鬆。"],
  ["野菜を地下に貯蔵する。", "「野菜を地下に貯蔵する」指把蔬菜存放在地下備用。指大量積存而有負面意味時，可視語境譯為「囤積」。"],
  ["彼は大学の助教授です。", "「大学の助教授」的「助教授」是日本大學的舊職稱，常譯為「副教授」。日本在二〇〇七年改設「准教授」，同時另設「助教」。"],
  ["材料の分量を量った。", "「材料の分量を量る」指量取食譜材料所需的份量。「分量」在此是被量取的數量；在較少見的用法中也可指量取這個動作。"],
  ["坊や、お母さんはどこ。", "「坊や、お母さんはどこ」是大人對小男孩的稱呼。若用「坊や」稱呼較年輕的成人，可能是在取笑對方年輕或沒經驗。"],
  ["窓に水滴がついている。", "「窓に付いた水滴」指附著在窗上的小水珠。書道器具中的「水滴」則可指用來把水滴入硯台的小容器。"],
  ["小数点以下を四捨五入した。", "「小数点以下を四捨五入する」表示依指定位數取近似值。「四捨五入」偶爾也可比喻把不同看法約略歸整成共同結論。"],
  ["二つの意見は同一である。", "「二つの意見は同一」表示這兩項意見一致。「同一の条件で扱う」則是在說按相同條件對待不同對象。"],
  ["彼女は来月デビューする。", "「来月デビューする」在演藝語境中指下個月出道。「社会人デビュー」則可指初次踏入職場。"],
  ["その国は1991年に独立した。", "「その国が独立する」指該國取得政治獨立。談個人時，「経済的に独立する」指經濟上自立。"],
  ["ボランティア活動に参加しました。", "「ボランティア活動」指從事志工服務。「活動写真」是電影早期的舊稱，有時也簡稱「活動」。"],
  ["この船は1000トンです。", "「この船は千トンです」在說船舶噸位，單憑這句無法判斷採哪個指標。一般公噸是質量單位；船舶的「総トン数」則按船內容積計算。"],
  ["蛍光灯が切れてしまった。", "「蛍光灯が切れた」指日光燈不亮了。較舊的戲稱也可用「蛍光灯」形容反應慢的人，借喻舊式日光燈開啟後需要片刻才亮。"],
  ["大気汚染は深刻な問題だ。", "「大気汚染」的「大気」指包圍地球的空氣。描述人的舊式用法中，「大気」也可指寬宏的氣度。"],
  ["私が着いたとき、会議は既に始まっていた。", "「既に始まっていた」指抵達時會議已經開始。「既に」也可表示以前；舊文中的強調用法則要依句子理解。"],
  ["彼は心臓の手術を受けました。", "「手術を受ける」指接受醫療手術。「手術」在較舊的用法裡也可指手上的技巧或手法。"],
  ["公園の裏山に猿がいる。", "「裏山に猿がいる」的「猿（さる）」指猴子。用來稱呼人時可能帶貶意；舊式器具名稱中也可指門窗的滑栓。"],
  ["雨で靴が泥だらけになった。", "「泥だらけ」指沾滿泥巴。「泥」也曾用作「泥棒」的簡稱，在部分網路用語中還可借指安卓系統。"],
  ["前者より後者のほうが安い。", "「前者より後者」的「後者」指前面提到的兩項中的第二項。舊式用法另可指繼承其後的人或後代。"],
  ["近頃、朝晩が冷えるようになった。", "「近頃、朝晩が冷える」的「近頃」指最近。舊式文句也可用「近頃」加強程度，意思接近「非常」。"],
  ["彼はスポーツで大活躍した。", "「スポーツで大活躍した」指在運動上大顯身手。較舊的用法也可描述精力充沛、四處奔走。"],
  ["山の奥に大きな滝がある。", "「山の奥にある滝」指山裡的瀑布。舊式地名或文獻裡，「滝」也可指流勢很急的水道。"],
  ["二つの液体を混合した。", "「液体を混合する」指把液體混在一起。「混合」也可用於成分、隊伍或群體等事物的混合，如「男女混合チーム」。"],
  ["国民の意見を聞くべきだ。", "「国民の意見」指一國人民的意見。日本政治新聞中的「国民」也可作為政黨「国民民主党」的簡稱。"],
  ["彼は海辺に別荘を持つ。", "「海辺に別荘を持つ」指在海邊擁有度假住所。俚語中也有人以「別荘」反諷地指監獄。"],
  ["彼女は毛皮のコートを着ている。", "「毛皮のコート」的「毛皮」指帶毛的獸皮。查部首時，也可見「毛皮」作為漢字部首「毛」的名稱。"],
  ["青少年向けの本を選んだ。", "「青少年向け」表示面向青少年。日常用語沒有固定的年齡界線，條例或計畫如另有定義，則依該文件認定。"],
  ["坊さんが読経している。", "「読経している坊さん」指正在誦經的僧人。「坊さん」也可用來稱呼男孩，此時需從人物與上下文辨別。"],
  ["昔の鉄砲が展示されている。", "「昔の鉄砲」指舊式槍械。相撲的「鉄砲柱」供力士練習推擊；餐飲俚語的「鉄砲」也可指河豚。"],
  ["この入れ物にお菓子を入れてください。", "「お菓子を入れる入れ物」指用來裝糖果的容器。舊式語境中的「入れ物」也可用來指棺木。"],
  ["この時代は変化が速い。", "「この時代」指這段時期。古物語境下，「時代」也可指出年代久遠，或出現在「時代物」指有年代的器物或以舊時代為背景的作品。"],
  ["それはとてもリアルな話だ。", "「リアルな話」指真切、有現實感的敘述。「リアルで会う」則指在現實生活中見面；說作品「リアル」也可以只是形容寫實。"],
  ["教育は社会にとって重要です。", "「教育は社会にとって重要」的「教育」泛指培養知識和能力的過程，涵蓋學校授課，也可見於「家庭教育」或「新人教育」。"],
  ["彼女は毎日メイクをする。", "「毎日メイクをする」指每天化妝。外送餐飲的工作用語裡，「メイク」也可指製作餐點或負責備餐的人員。"],
  ["庭の落ち葉を掃いた。", "「落ち葉を掃く」指用掃帚掃起落葉。養蠶的「掃き立て」則指把剛孵化的蠶移到蠶座開始飼養。"],
  ["彼は日本の文化に興味がある。", "國名「日本」可讀「にほん」或「にっぽん」，兩種讀法都通用。詞卡音訊示範其中一種；固定名稱的讀法則依該名稱的慣用讀法。"],
  ["その基地は山の中にあります。", "「山の中の基地」指設在山裡的據點。網路俚語中，接在事物名稱後面的「基地」另可戲稱某事物的狂熱愛好者，也可能帶有貶意。"],
  ["都会の生活は便利だ。", "「都会の生活」的「都会」指都市。辭典也記載同音的「都会」可縮稱東京都議會，需從議事語境辨認。"],
  ["子どもが小便をしたくてトイレへ行った。", "「小便をする」指小便，比「お手洗いに行く」直接。舊式俚語也可用「小便をする」指反悔或不履行約定。"],
  ["工場の煙突から煙が出ている。", "「工場の煙突」指排出煙氣的煙囪。計程車行業的舊俚語中，「煙突」也可指載客時未開計費表。"],
  ["彼は料理は素人だが、熱心に学ぶ。", "「料理は素人だ」指在料理方面是外行。歷史文獻談花街或性交易時，「素人」也可能依當時的職業或身分類別使用。"],
  ["この方法なら能率が上がる。", "「能率が上がる」表示做事效率提高。日本物理術語另有「能率」一詞，可指「モーメント」，例如力對旋轉軸的力矩。"],
  ["新しい大統領が選ばれた。", "「新しい大統領が選ばれた」的「大統領」指國家的總統。舊式口語中也可能用作帶玩笑或稱讚口吻的招呼語，例如向演員喝采時。"],
  ["東洋の文化に興味がある。", "「東洋の文化」指東方、尤其是亞洲的文化。中文舊文獻的「東洋」也可能特指日本，閱讀時須留意作者和年代。"],
  ["バッテリーがローです。", "看設備的電量提示時，「バッテリーがロー」可理解成電量偏低，日常也可說「バッテリー残量が少ない」。「ローギア」的「ロー」指低速檔。"],
  ["たとえ雨でも出かけます。", "「たとえ～でも」表示即使出現某種情況，結果也不變。這句表示即使下雨，說話者還是會出門。"],
]);

const reviewedVocabExplanationsById = new Map([
  ["vocab-0299","「季節の変化を感じる」的「感じる」指感受到變化。「親切な言葉に感じ入る」則表示被親切的話深深打動。舊文獻裡，「病を感じる」也可指染病。"],
  ["vocab-0751","「自然の中で過ごす」指在大自然中度過時間。「飲み過ごす」表示喝過量；「見過ごす」則可指看見後未加理會，或漏看。"],
]);

function vocabExplanationZh(row, meaningZh, exampleJa) {
  const reviewed = reviewedVocabExplanationsById.get(row.id) ?? reviewedVocabExplanations.get(exampleJa);
  if (reviewed) return reviewed;
  const term = row.term;
  const first = meaningZh.split("；")[0];
  const kana = row.reading && row.reading !== term ? "（" + row.reading + "）" : "";
  const pos = row.pos || [];
  const isSuru = pos.some((code) => /^vs/.test(code));
  const lexicalVerb = pos.some((code) => /^v(?:[1-9]|k|z|n|r)/.test(code));
  const usesSuru = isSuru && [term, row.reading].some((form) => {
    if (!form) return false;
    let at = exampleJa.indexOf(form);
    while (at !== -1) {
      const after = exampleJa.slice(at + form.length);
      if (/^(?:する|すれ|され|させ|せよ|せず|し(?:て|た|ます|まし|ませ|ない|なか|よう|ろ|ながら|続|始|終|過|[、。]|$))/.test(after)) return true;
      at = exampleJa.indexOf(form, at + form.length);
    }
    return false;
  });
  // Nouns that can take する are not necessarily verbs in this sentence:
  // 駐車禁止です / 彼の提案は採用された contain no 禁止する / 提案する.
  const nonVerbalSuru = isSuru && !lexicalVerb && !usesSuru &&
    pos.some((code) => !code.startsWith("v"));
  const isVerb = !nonVerbalSuru && (
    pos.includes("vt") || pos.includes("vi") || pos.includes("vs") || /^v[0-9k-z]/.test(pos[0] || "")
  );
  if (isVerb) {
    const role = pos.includes("vt") && pos.includes("vi")
      ? "可依語境作自動詞或他動詞使用"
      : pos.includes("vt")
      ? "有他動詞用法，可搭配用「を」標示的受詞"
      : pos.includes("vi")
        ? "描述主語本身的動作或變化"
        : "在句中作動詞使用";
    return "例句裡的「" + term + "」" + kana + role + "，這裡表示「" + first + "」。請留意它前面搭配的助詞。";
  }
  // Particle entries can also have adverb, conjunction or interjection senses.
  // Do not describe sentence-final ね as an isolated interjection, or comparative
  // より as necessarily an adverb, merely because those tags occur elsewhere.
  if (pos.includes("prt")) {
    const roles = ["助詞"];
    if (pos.includes("adv") || pos.includes("adv-to")) roles.push("副詞");
    if (pos.includes("conj")) roles.push("連接詞");
    if (pos.includes("int")) roles.push("感嘆詞");
    return "「" + term + "」" + kana + "可作" + roles.join("、") + "使用，這裡表示「" + first + "」。請觀察它的位置、前後搭配及語氣。";
  }
  if (pos.includes("conj")) {
    return "「" + term + "」" + kana + "可作連接詞，連接前後語句，表示「" + first + "」。請觀察前後內容的關係。";
  }
  if (pos.includes("adj-pn")) {
    return "「" + term + "」" + kana + "是連體詞，用來修飾後面的名詞，表示「" + first + "」。請連同它修飾的名詞一起理解。";
  }
  // adj-no describes an attributive use with の, not a sentence-wide adjective
  // classification. 編物が上手 and 大凡の見当 both use nominal forms.
  const nominalNo = pos.includes("n") && pos.includes("adj-no") &&
    !pos.includes("adj-i") && !pos.includes("adj-na") &&
    [term, row.reading].some((form) => form &&
      exampleJa.includes(form) && /^(?:の|が|を|は|も)/.test(
        exampleJa.slice(exampleJa.indexOf(form) + form.length)));
  if (nominalNo) {
    return "例句中的「" + term + "」" + kana + "是名詞，指「" + first + "」。作連體修飾時可加「の」接名詞，請觀察本句的助詞搭配。";
  }
  if (pos.includes("adj-i") || pos.includes("adj-na")) {
    return "「" + term + "」" + kana + "在句中描述狀態或性質，意思是「" + first + "」。注意它接名詞與放句尾時的形式差異。";
  }
  if (pos.includes("adv") || pos.includes("adv-to")) {
    return "「" + term + "」" + kana + "修飾後面的動作或整句語氣，表示「" + first + "」。可觀察它擺放的位置。";
  }
  if (pos.includes("exp")) {
    return "「" + term + "」" + kana + "是固定說法，整句表示「" + first + "」，不要拆開逐字理解。";
  }
  if (!pos.includes("n") && (pos.includes("ctr") || pos.includes("n-suf") || pos.includes("suf"))) {
    return "「" + term + "」" + kana + "接在前面的語詞之後，表示「" + first + "」。記憶時連同前面的搭配一起記。";
  }
  if (pos.includes("int")) {
    return "「" + term + "」" + kana + "是感嘆詞，單獨使用即可表達「" + first + "」的語氣。";
  }
  return "例句中的「" + term + "」" + kana + "是名詞，指「" + first + "」。請一併記住它在句中搭配的助詞。";
}

// A natural sentence conjugates: 集める appears as 集めている. Verbs and i-adjectives
// are therefore matched on their stem, while nouns keep the strict check, because
// loose matching on short kana nouns is exactly what filed a sentence about a bag
// under バック (rear).
function exampleDemonstrates(row, sentence) {
  const forms = [row.term, row.reading];
  const inflects =
    (row.pos || []).some((p) => /^v/.test(p)) || (row.pos || []).includes("adj-i");
  if (inflects) {
    for (const form of [row.term, row.reading]) {
      if (form && form.length > 1) forms.push(form.slice(0, -1));
    }
  }
  return forms.some((form) => form && sentence.includes(form));
}

function resolveVocabExample(row) {
  if (row.reviewedExample) return row.reviewedExample;
  // 1. A fully hand-written example, for entries the source deck cannot supply.
  const authored = vocabExamples[row.id];
  if (authored?.ja && authored?.zh) return { ja: authored.ja, zh: authored.zh };
  const deck = row.deckExample;
  if (!deck?.ja) throw new Error("單字缺少可用例句：" + row.id + " " + row.term);
  // 2. The deck sentence with a translation written for this entry.
  if (vocabExampleZh[row.id]) return { ja: deck.ja, zh: vocabExampleZh[row.id] };
  // 3. The deck sentence with a translation already in the shared pool.
  if (exampleTranslationsZh[deck.ja]) return { ja: deck.ja, zh: exampleTranslationsZh[deck.ja] };
  throw new Error("單字缺少例句中文翻譯：" + row.id + " " + deck.ja);
}

const vocabTeachingSenses = readSource("vocab-teaching-senses.json");

// Spread N items across the 12 periods as evenly as possible. Flooring index/5
// left 116-05 with two reading articles and 116-06 with none, because 52 does
// not divide by 5 into 12 buckets.
function spreadPeriod(index, total) {
  return Math.min(periods.length - 1, Math.floor((index * periods.length) / total));
}

function periodFor(index, caps) {
  return periods[caps.findIndex((cap) => index + 1 <= cap)];
}

// Which half-year each word belongs to, from the JLPT levels in its own source
// file rather than from its position in the spine. See that file's _note.
const vocabHalf = readSource("vocab-levels.json").half;
const vocabOrder = { N3: [], N2: [] };

function loadWords() {
  if (vocabAuthority.length !== 4000) {
    throw new Error("單字骨架數量不符：" + vocabAuthority.length);
  }
  const missingLevels = vocabAuthority.filter((row) => !vocabHalf[row.id]);
  if (missingLevels.length) {
    throw new Error("單字缺少分級：" + missingLevels.slice(0, 5).map((r) => r.id).join("、"));
  }
  vocabOrder.N3 = vocabAuthority.filter((row) => vocabHalf[row.id] === "N3").map((r) => r.id);
  vocabOrder.N2 = vocabAuthority.filter((row) => vocabHalf[row.id] === "N2").map((r) => r.id);
  return vocabAuthority.map((row, index) => {
    const key = row.id.slice(6);
    const meaningZh = row.reviewedMeaningZh ?? vocabZh[key];
    if (!meaningZh) throw new Error("單字缺少中文釋義：" + row.id + " " + row.term);
    const example = resolveVocabExample(row);
    if (!exampleDemonstrates(row, example.ja)) {
      throw new Error("例句未包含詞條：" + row.id + " " + row.term + " / " + example.ja);
    }
    const level = vocabHalf[row.id];
    if (!level) throw new Error("單字缺少分級：" + row.id + " " + row.term);
    const hasKanji = /[一-龯]/.test(row.term);
    return {
      id: row.id,
      level,
      category: "vocab",
      term: row.term,
      reading: row.reading,
      // Readings come from JMdict now, so reading quizzes no longer have to skip
      // long-vowel words in order to hide the macron-stripping bug.
      readingQuizEligible: hasKanji && row.reading !== row.term &&
        new Set([row.reading, ...(vocabTeachingSenses[row.id] ?? [])
          .map((sense) => sense.reading || row.reading)]).size === 1,
      meaningZh,
      meaningEn: row.glossEn,
      ...(vocabTeachingSenses[row.id] ? {
        senses: vocabTeachingSenses[row.id],
        senseSourceSequence: row.seq,
      } : {}),
      usageZh: vocabUsageZh(row, meaningZh),
      examples: [
        {
          ja: example.ja,
          zh: example.zh,
          explanationZh: vocabExplanationZh(row, meaningZh, example.ja),
        },
      ],
      // Speak the kana, not the word form. A speech engine reading 最中 off the kanji
      // says もなか (the sweet), 空く says あく, 仏 says ぶつ — the card then teaches one
      // reading and plays another. The kana is unambiguous, and nothing is given away
      // by it: the study quiz asks for the meaning, and the 漢字読み practice questions
      // carry no audio at all.
      audioText: row.reading || row.term,
      unlockPeriod: halfYearPeriod(vocabOrder, row.id, level),
      tags: [...new Set([...(row.pos || []).slice(0, 2), level])],
      sourceRefs: [
        "https://www.edrdg.org/jmdict/j_jmdict.html",
        "https://github.com/vbvss199/Language-Learning-decks",
        sigureRefs.vocabulary[level],
      ],
      referenceNoteZh:
        "詞形、假名讀音與詞性取自 JMdict；繁體中文釋義、用法說明與例句解析為本計畫自行撰寫，未轉載他站內容。",
      license:
        "JMdict/EDRDG licence (CC BY-SA 4.0); Language-Learning-decks MIT; Chinese glosses CC BY 4.0 — 本計畫自編",
    };
  });
}

const grammarPatterns = `〜うちに|〜間に|〜間|〜てからでないと|〜ところだ|〜たところだ|〜ているところだ|〜ばかりだ|〜たばかり|〜ようとする|〜つつある|〜つつ|〜一方だ|〜ことになっている|〜ことにしている|〜ことになる|〜ことにする|〜ようになる|〜ようにする|〜ようにしている|〜ことがある|〜ことはない|〜わけだ|〜わけではない|〜わけがない|〜わけにはいかない|〜はずだ|〜はずがない|〜べきだ|〜べきではない|〜ものだ|〜ものではない|〜ということだ|〜とのことだ|〜と言われている|〜とみえる|〜ようだ|〜みたいだ|〜らしい|〜そうだ（樣態）|〜そうだ（傳聞）|〜っぽい|〜がちだ|〜気味だ|〜げ|〜かもしれない|〜に違いない|〜に決まっている|〜おそれがある|〜可能性がある|〜ために（目的）|〜ために（原因）|〜ように（目的）|〜ように（祈願）|〜によって|〜によると|〜によれば|〜を通じて|〜を通して|〜に対して|〜について|〜に関して|〜をめぐって|〜にとって|〜として|〜において|〜に基づいて|〜に応じて|〜に比べて|〜に加えて|〜に反して|〜にかわって|〜に代わり|〜にこたえて|〜に沿って|〜につれて|〜にしたがって|〜にともなって|〜とともに|〜に限って|〜に限らず|〜だけでなく|〜ばかりでなく|〜はもちろん|〜のみならず|〜さえ|〜こそ|〜なんか|〜など|〜にしては|〜わりに|〜くせに|〜にもかかわらず|〜ながらも|〜ものの|〜とはいえ|〜といっても|〜からといって|〜ても|〜たとえ〜ても|〜としても|〜にしても|〜にしろ|〜にせよ|〜なら|〜としたら|〜とすれば|〜ば|〜たら|〜と|〜ないことには|〜限り|〜限りでは|〜ない限り|〜さえ〜ば|〜てこそ|〜からこそ|〜ば〜ほど|〜なら〜ほど|〜ほど|〜くらい|〜だけ|〜だけあって|〜だけに|〜だけのことはある|〜につき|〜ごとに|〜おきに|〜たびに|〜たび|〜にあたって|〜際に|〜に先立って|〜て以来|〜てからというもの|〜をきっかけに|〜を契機に|〜次第|〜次第で|〜次第だ|〜次第では|〜上で|〜上に|〜上は|〜以上|〜からには|〜からして|〜からすると|〜から見ると|〜から言うと|〜にしても|〜にしたって|〜というより|〜どころか|〜どころではない|〜どころではなく|〜反面|〜一方で|〜かわりに|〜にかわって|〜た末に|〜あげく|〜結果|〜ところを|〜ところに|〜ところへ|〜最中に|〜最中だ|〜途中で|〜かけ|〜きる|〜きれない|〜ぬく|〜通す|〜込む|〜出す|〜始める|〜終わる|〜続ける|〜ていく|〜てくる|〜ておく|〜てある|〜てしまう|〜てみる|〜てもらう|〜てくれる|〜ていただく|〜てくださる|〜させてもらう|〜させていただく|〜てもかまわない|〜てはいけない|〜ないで済む|〜ずに済む|〜ずにはいられない|〜ないではいられない|〜てたまらない|〜てならない|〜てしょうがない|〜て仕方がない|〜ないことはない|〜ないわけではない|〜というものではない|〜ものか|〜ことか|〜ことだ|〜ことだから|〜ことなく|〜ことに|〜ことから|〜ことには|〜ものなら|〜ものだから|〜ものの|〜ものを|〜わけにはいかない|〜どんなに〜ことか|〜なんて|〜とは|〜という|〜といった|〜といえば|〜というと|〜といったら|〜にほかならない|〜にすぎない|〜に相違ない|〜に違いない|〜に決まっている|〜に越したことはない|〜ざるを得ない|〜ないわけにはいかない|〜かねない|〜かねる|〜かのようだ|〜かと思うと|〜かと思ったら|〜や否や|〜なり|〜そばから|〜ては|〜てばかりいる|〜ないうちに|〜か〜ないかのうちに|〜を問わず|〜にかかわらず|〜にもかかわらず|〜をものともせず|〜をよそに|〜に先駆けて|〜に至るまで|〜に至って|〜に至る|〜に至っては`.split("|");

function explainGrammar(term) {
  const entry = grammarZh[term];
  if (!entry?.meaning) throw new Error("文法句型缺少語意說明：" + term);
  return entry.meaning;
}

function grammarUsageZh(term) {
  const entry = grammarZh[term];
  if (!entry?.usage) throw new Error("文法句型缺少接續說明：" + term);
  return entry.usage;
}

function grammarAudioText(term) {
  return term.replace(/[〜～]/g, "").replace(/[（(][^）)]*[）)]/g, "").trim();
}
// Which level each pattern belongs to. A source file rather than a slice index:
// the old `index < 180` cut a thematically ordered list, so it labelled 〜てみる
// and 〜てもらう N2 while calling 〜だけあって and 〜次第で N3. See its _note.
const grammarLevels = readSource("grammar-levels.json").levels;

/**
 * Which month an item opens in, derived from its level.
 *
 * Each half-year holds its own level and spreads its own items evenly, so the N3
 * set is complete before the mocks in 115/11 and the sitting on 115/12/06 —
 * whatever the counts turn out to be after a re-classification. Shared by
 * vocabulary and grammar because both had the same fault: a level from a slice
 * index, and a schedule from a separate hand-written cap that disagreed with it.
 *
 * `order` maps a level to its items in teaching order; `key` is the term (for
 * grammar) or the card id (for vocabulary).
 */
function halfYearPeriod(order, key, level) {
  const list = order[level];
  const at = list.indexOf(key);
  const offset = level === "N3" ? 0 : N3_MONTHS + 2; // skip the two revision months
  const months = level === "N3" ? N3_MONTHS : N2_MONTHS;
  return periods[offset + Math.min(months - 1, Math.floor((at * months) / list.length))];
}

const grammarOrder = { N3: [], N2: [] };

function makeGrammar() {
  const unique = [...new Set(grammarPatterns)].slice(0, 240);
  if (unique.length < 240) throw new Error(`文法句型不足：${unique.length}`);
  const missingExamples = unique.filter((term) => !grammarExamples.has(term));
  if (missingExamples.length) throw new Error(`文法例句不足：${missingExamples.join("、")}`);
  const missingLevels = unique.filter((term) => !grammarLevels[term]);
  if (missingLevels.length) throw new Error(`文法句型缺少分級：${missingLevels.join("、")}`);
  grammarOrder.N3 = unique.filter((term) => grammarLevels[term] === "N3");
  grammarOrder.N2 = unique.filter((term) => grammarLevels[term] === "N2");
  return unique.map((term, index) => {
    const exampleJa = grammarExamples.get(term);
    const exampleZh = exampleTranslationsZh[exampleJa];
    if (!exampleZh) throw new Error(`例句缺少中文翻譯：${exampleJa}`);
    const level = grammarLevels[term];
    return {
      id: `grammar-${String(index + 1).padStart(3, "0")}`, level, category: "grammar", term,
      reading: "文法句型", meaningZh: explainGrammar(term), usageZh: grammarUsageZh(term),
      examples: [{ ja: exampleJa, zh: exampleZh, explanationZh: `這句使用「${term}」。${explainGrammar(term)}` }],
      audioText: grammarAudioText(term), unlockPeriod: halfYearPeriod(grammarOrder, term, level),
      tags: [`${level}文法`], sourceRefs: ["self-authored", sigureRefs.grammar[level]],
      referenceNoteZh: `句型分級與接續觀念交叉參考時雨之町 ${level} 文法索引；解釋、例句與題目均為本計畫自編。`,
      license: "CC BY 4.0 — 本計畫自編"
    };
  });
}

function rotateOptions(correct, distractors, seed) {
  const options = [...new Set([correct, ...distractors.filter((item) => item !== correct)])].slice(0, 4);
  if (options.length !== 4) throw new Error(`選項不足：${correct}`);
  const shift = seed % options.length;
  const rotated = [...options.slice(shift), ...options.slice(0, shift)];
  return { options:rotated, answer:rotated.indexOf(correct) };
}

const grammarFunctions = [
  "条件や仮定を表している", "目的を表している", "原因や理由を表している", "願望や祈りを表している",
  "予想と異なる結果や対比を表している", "推量や伝聞を表している", "時間や動作の前後関係を表している",
  "範囲の限定や強調を表している", "決定・義務・許可を表している", "状態の変化や動作の進行を表している",
  "話題・立場・対象との関係を表している", "程度や比較を表している", "気持ちや評価を強く表している", "説明・引用・言い換えを表している",
  "経験・習慣・一般的な傾向を表している", "否定・不可能・部分否定を表している", "情報の根拠や引用を表している",
  "試み・授受・依頼を表している", "結果・きっかけ・判断の根拠を表している", "例示や話題の提示を表している",
  "追加・並行・変化の連動を表している", "自然に起こる強い感情や衝動を表している"
];

function grammarFunctionJa(term) {
  if (/(といっても|にしては|といったら)/.test(term)) return "予想と異なる結果や対比を表している";
  if (/(というものではない)/.test(term)) return "否定・不可能・部分否定を表している";
  if (/(に越したことはない)/.test(term)) return "程度や比較を表している";
  if (/(ことには|〜限り$|〜ては$)/.test(term)) return "条件や仮定を表している";
  if (/(〜つつ$)/.test(term)) return "追加・並行・変化の連動を表している";
  if (/(〜上で$)/.test(term)) return "時間や動作の前後関係を表している";
  if (/(〜ことなく$)/.test(term)) return "否定・不可能・部分否定を表している";
  if (/(〜ものだから$)/.test(term)) return "原因や理由を表している";
  if (/(〜次第だ$|にほかならない)/.test(term)) return "結果・きっかけ・判断の根拠を表している";
  if (/(ということだ|とのことだ|と言われている|によると|によれば)/.test(term)) return "情報の根拠や引用を表している";
  if (/(ずにはいられない|ないではいられない)/.test(term)) return "自然に起こる強い感情や衝動を表している";
  if (/(かと思ったら|かと思うと|や否や|なり$|そばから|か.*ないかのうちに)/.test(term)) return "時間や動作の前後関係を表している";
  if (/(ことになっている|ことにしている|ようにしている|ものではない|ことだ$)/.test(term)) return "決定・義務・許可を表している";
  if (/(わけではない|わけがない|はずがない|ことはない|ないことはない|ないわけではない|というものではない|ものか|どころではない|どころではなく|ないで済む|ずに済む)/.test(term)) return "否定・不可能・部分否定を表している";
  if (/(ことがある|ものだ$|てばかりいる)/.test(term)) return "経験・習慣・一般的な傾向を表している";
  if (/(てもらう|てくれる|ていただく|てくださる|させてもらう|させていただく|てみる|ようとする)/.test(term)) return "試み・授受・依頼を表している";
  if (/(に加えて|に沿って|につれて|にしたがって|にともなって|とともに|上に)/.test(term)) return "追加・並行・変化の連動を表している";
  if (/(をきっかけに|を契機に|た末に|あげく|結果|からして|からすると|から見ると|から言うと)/.test(term)) return "結果・きっかけ・判断の根拠を表している";
  if (/(なんか|など|なんて|とは$|という$|といった$|というと|といえば|というより)/.test(term)) return "例示や話題の提示を表している";
  if (/(ために（原因）|につき|ことだから|ことから)/.test(term)) return "原因や理由を表している";
  if (/(ために（目的）|ように（目的）)/.test(term)) return "目的を表している";
  if (/(ように（祈願）|どんなに.*ことか|ことか)/.test(term)) return "願望や祈りを表している";
  if (/(てからでないと|ば$|たら$|なら$|としたら|とすれば|としても|にしても|にしろ|にせよ|ないことには|ない限り|さえ.*ば|ものなら|たとえ|次第で|次第では|上は|以上|からには|ても$|〜と$|にしたって)/.test(term)) return "条件や仮定を表している";
  if (/(ものの|にもかかわらず|ながらも|くせに|わりに|に反して|とはいえ|からといって|どころか|反面|一方で|にしては|といっても|ものを)/.test(term)) return "予想と異なる結果や対比を表している";
  if (/(ようだ|みたいだ|らしい|そうだ|かもしれない|に違いない|に決まっている|おそれがある|可能性|とみえる|かのようだ|はずだ|に相違ない|かねない)/.test(term)) return "推量や伝聞を表している";
  if (/(うちに|間に|間$|ところ|最中|途中|際に|にあたって|に先立って|て以来|てからというもの|たび|次第$|ごとに|おきに|たばかり)/.test(term)) return "時間や動作の前後関係を表している";
  if (/(だけ|しか|に限|のみならず|ばかりでなく|はもちろん|さえ|こそ|を問わず|にかかわらず|にすぎない|限りでは)/.test(term)) return "範囲の限定や強調を表している";
  if (/(ことにする|ことになる|ようにする|べき|わけにはいかない|ざるを得ない|てはいけない|てもかまわない|かねる)/.test(term)) return "決定・義務・許可を表している";
  if (/(ていく|てくる|つつある|一方だ|始める|続ける|終わる|きる|きれない|ぬく|通す|込む|出す|ておく|てある|てしまう|ようになる|ばかりだ|かけ)/.test(term)) return "状態の変化や動作の進行を表している";
  if (/(について|に関して|に対して|にとって|として|において|をめぐって|に基づいて|に応じて|によって|を通じて|を通して|にかわって|に代わり|にこたえて)/.test(term)) return "話題・立場・対象との関係を表している";
  if (/(ほど|くらい|に比べて|ば.*ほど|なら.*ほど|だけあって|だけに|に越したことはない)/.test(term)) return "程度や比較を表している";
  if (/(てたまらない|てならない|てしょうがない|て仕方がない|ことに|げ|気味|がち|っぽい|といったら)/.test(term)) return "気持ちや評価を強く表している";
  return "説明・引用・言い換えを表している";
}

const assessmentUsage = {vocabulary:new Set(),grammar:new Set(),reading:new Set(),listening:new Set()};

function orderedLevelPool(items, level, maxPeriod) {
  const unlocked = items.filter((item) => periods.indexOf(item.unlockPeriod) <= maxPeriod);
  const exact=unlocked.filter((item)=>item.level===level);
  return exact.length ? exact : unlocked.filter((item)=>item.level!==level);
}

function takeUnused(items, used, seed, key = (item)=>item.id, label = "題庫") {
  for (let offset=0; offset<items.length; offset+=1) {
    const item=items[(seed+offset)%items.length];
    const itemKey=key(item);
    if (!used.has(itemKey)) { used.add(itemKey); return item; }
  }
  throw new Error(`${label}不足，無法產生不重複題目（可用 ${items.length}，已使用 ${used.size}）`);
}

// Exam items, shaped like the 大問 of the real paper.
//
// 読解 and 聴解 already came from JLPT-shaped source material. 文字・語彙 and 文法
// did not: 漢字読み asked "「違う」の読み方はどれですか" with no sentence, which the
// real exam never does, and the 文法 item asked what a pattern "means" and offered
// abstract function labels — a question about grammar rather than a use of it.
//
// The four types below are the ones this content can support honestly. Three
// more real 大問 are deliberately absent because building them from what we have
// would mean inventing data: 言い換え類義 needs vetted synonyms, 用法 needs
// sentences that use a word *incorrectly*, and 文の組み立て needs sentences split
// into chunks that are valid to reorder. Guessing at any of those produces items
// with more than one defensible answer, which is worse than not having them.


// How a paper is made up.
//
// The item types were already JLPT-shaped, but the paper was not: questions
// cycled 文字・語彙 → 文法 → 読解 → 聴解 one at a time, which left every mock with
// 13% listening against the real exam's 27–29%, and interleaved the sections
// rather than grouping them the way a real paper does.
//
// The mocks now follow the real proportions. The monthly checks deliberately do
// not: the listening bank holds 112 questions and no exam question may reuse a
// source, so faithful listening everywhere would need 121+. The mocks are what
// simulate the real sitting, so they get the full share and the monthly checks —
// progress checks, not rehearsals — run lighter at 20%.
// Every paper now uses the real exam's own question counts as weights, so the
// proportions come out right at any length. The monthly checks used to run at
// 15% listening because the bank could not supply more; twenty extra scripts
// took it from 112 questions to 132, which covers the 126 a full-proportion year
// needs.
const EXAM_BLUEPRINTS = {
  // N3 paper: 文字・語彙 35, 文法 23, 読解 16, 聴解 28
  N3: { vocab: 35, grammar: 23, reading: 16, listening: 28 },
  // N2 paper: 文字・語彙 32, 文法 22, 読解 21, 聴解 31
  N2: { vocab: 32, grammar: 22, reading: 21, listening: 31 },
};

// Within 文字・語彙, the real paper's own weighting between the three 大問 we build.
const VOCAB_MIX = {
  N3: { kanji: 8, orthography: 6, cloze: 11 },
  N2: { kanji: 5, orthography: 5, cloze: 7 },
};

// Largest remainder, so the parts always add back up to the whole.
function allocate(total, weights) {
  const sum = Object.values(weights).reduce((n, w) => n + w, 0);
  const exact = Object.entries(weights).map(([key, weight]) => ({
    key,
    value: (total * weight) / sum,
  }));
  const counts = Object.fromEntries(exact.map(({ key, value }) => [key, Math.floor(value)]));
  let left = total - Object.values(counts).reduce((n, v) => n + v, 0);
  for (const { key } of [...exact].sort((a, b) => (b.value % 1) - (a.value % 1))) {
    if (left <= 0) break;
    counts[key] += 1;
    left -= 1;
  }
  return counts;
}

/**
 * The question types of one paper, in the order a real paper asks them.
 *
 * Grouped by section — all 文字・語彙 first, then 文法, 読解, 聴解 — and inside
 * 文字・語彙 in the paper's own order of 漢字読み, 表記, 文脈規定.
 */
function examPlan(kind, level, questionCount) {
  const blueprint = EXAM_BLUEPRINTS[level] || EXAM_BLUEPRINTS.N3;
  const sections = allocate(questionCount, blueprint);
  const vocab = allocate(sections.vocab, VOCAB_MIX[level] || VOCAB_MIX.N3);
  return [
    ...Array(vocab.kanji).fill("kanji"),
    ...Array(vocab.orthography).fill("orthography"),
    ...Array(vocab.cloze).fill("vocab-cloze"),
    ...Array(sections.grammar).fill("grammar-cloze"),
    ...Array(sections.reading).fill("reading"),
    ...Array(sections.listening).fill("listening"),
  ];
}

function makeExamQuestions(id, level, period, questionCount, catalog, kind) {
  const maxPeriod = periods.indexOf(period);
  const vocabPool = orderedLevelPool(catalog.vocabulary,level,maxPeriod);
  const kanjiPool = vocabPool.filter(usableForReading);
  const clozePool = vocabPool.filter(hasOwnExample);
  const grammarClozePool = orderedLevelPool(catalog.grammar,level,maxPeriod).filter(usableForGrammarCloze);
  const readingPool = orderedLevelPool(catalog.reading,level,maxPeriod).flatMap((item)=>item.questions.map((question,questionIndex)=>({item,question,questionIndex,id:`${item.id}-q${questionIndex+1}`})));
  // 統合理解 carries two questions; taking only the first threw half the pool away.
  const listeningPool = orderedLevelPool(catalog.listening,level,maxPeriod).flatMap((item)=>item.questions.map((question,questionIndex)=>({item,question,questionIndex,id:`${item.id}-q${questionIndex+1}`})));
  const used=assessmentUsage;
  const seedBase = [...id].reduce((sum, char) => sum + char.charCodeAt(0), 0);
  const plan = examPlan(kind, level, questionCount);

  return Array.from({length:questionCount}, (_, index) => {
    const seed = seedBase * 17 + index * 13;
    const qid = `${id}-q${index+1}`;
    const type = plan[index];

    // ---------------------------------------------------------- 文字・語彙
    if (type === "kanji" || type === "orthography") {
      const item=takeUnused(kanjiPool,used.vocabulary,seed,undefined,`${id} ${type==="kanji"?"漢字読み":"表記"}`);
      return { id:qid, ...ITEM_BUILDERS[type](item,kanjiPool,seed) };
    }
    if (type === "vocab-cloze") {
      const item=takeUnused(clozePool,used.vocabulary,seed,undefined,`${id} 文脈規定`);
      return { id:qid, ...ITEM_BUILDERS[type](item,clozePool,seed) };
    }

    // -------------------------------------------------------------- 文法
    if (type === "grammar-cloze") {
      const item=takeUnused(grammarClozePool,used.grammar,seed,undefined,`${id} 文法形式`);
      return { id:qid, ...grammarClozeItem(item,grammarClozePool,seed,grammarFunctionJa) };
    }

    // ------------------------------------------------------- 読解・聴解
    if (type === "reading") {
      const entry=takeUnused(readingPool,used.reading,seed,undefined,`${id} 読解`);
      return { id:qid, section:"読解", type:entry.question.jlptType, instruction:"次の文章を読んで、質問に答えなさい。", passage:entry.item.content, prompt:entry.question.prompt, options:entry.question.options, answer:entry.question.answer, explanationZh:entry.question.explanation, sourceQuestionId:entry.question.id, logic:"reading-source" };
    }
    const entry=takeUnused(listeningPool,used.listening,seed,undefined,`${id} 聴解`);
    return { id:qid, section:"聴解", type:entry.question.jlptType, instruction:"音声を聞いて、質問に答えなさい。", prompt:entry.question.prompt, audioText:entry.item.audioText, options:entry.question.options, answer:entry.question.answer, explanationZh:entry.question.explanation, sourceQuestionId:entry.question.id, logic:"listening-source" };
  });
}

function makeAssessment(id, title, level, period, minutes, questionCount, kind, catalog) {
  return { id, title, level, category:"assessment", kind, unlockPeriod:period, durationMinutes:minutes, threshold:60, scoreTotal:100, sourceRefs:["self-authored", "https://www.jlpt.jp/e/samples/sampleindex.html"], license:"CC BY 4.0 — 自編題目；官方連結僅供題型參考", questionCount, questions:makeExamQuestions(id,level,period,questionCount,catalog,kind) };
}

const vocabulary = loadWords();
const grammar = makeGrammar();
const reading = buildReading(periods, spreadPeriod);
const listening = buildListening(periods, spreadPeriod);
const catalog = { vocabulary, grammar, reading, listening };
/*
 * All of a level's mocks open together, in the month after its last card unlocks.
 * Until then there is still vocabulary or grammar a full paper could not fairly
 * test; from then on there is nothing left to learn at that level, so holding the
 * later papers back only shortens the run-up. This was two hand-written month
 * strings, and they put three N3 mocks in 115/11 and the other two in 115/12 —
 * days before the sitting on 115/12/06, and against a plan that asks for all five
 * in 115/11.
 *
 * Reading and listening are deliberately not counted: they run to the last month at
 * both levels, so waiting for them would mean waiting forever.
 */
function mockPeriod(level) {
  const last = [...vocabulary, ...grammar]
    .filter((item) => item.level === level)
    .reduce((latest, item) => Math.max(latest, periods.indexOf(item.unlockPeriod)), -1);
  if (last < 0) throw new Error(`找不到 ${level} 教材，無法決定模考開放月份`);
  return periods[Math.min(periods.length - 1, last + 1)];
}
const assessmentPlan = [
  ...periods.map((p,i)=>({id:`monthly-${String(i+1).padStart(2,"0")}`,title:`${p.replace("-","/")} 月檢核`,level:i<6?"N3":"N2",period:p,minutes:35,questionCount:20,kind:"monthly"})),
  ...Array.from({length:5},(_,i)=>({id:`mock-n3-${i+1}`,title:`N3 自編模考 ${i+1}`,level:"N3",period:mockPeriod("N3"),minutes:95,questionCount:30,kind:"mock"})),
  ...Array.from({length:2},(_,i)=>({id:`mock-n2-${i+1}`,title:`N2 自編模考 ${i+1}`,level:"N2",period:mockPeriod("N2"),minutes:105,questionCount:35,kind:"mock"}))
];
/*
 * Build them in the order the learner meets them, not in the order they are
 * listed. No exam question may reuse a source, and a paper may only draw on
 * material unlocked by its own month, so whoever is built first gets first pick
 * of a shared bank. Listing every monthly check before the mocks meant the checks
 * for 116/05 and 116/06 took N2 listening before the mock in 116/04 — a paper the
 * learner sits two months earlier — and the earlier paper was left short. Sorting
 * by period makes the draw order match the calendar. The sort is stable, so
 * papers inside one month keep their listed order.
 */
const assessments = assessmentPlan
  .slice()
  .sort((a,b)=>periods.indexOf(a.period)-periods.indexOf(b.period))
  .map((row)=>makeAssessment(row.id,row.title,row.level,row.period,row.minutes,row.questionCount,row.kind,catalog));

function auditGeneratedQuestions() {
  const hasJapanese=(value)=>/[\u3040-\u30ff\u3400-\u9fff]/.test(value||"");
  // Was a whitelist of Chinese words the old templates happened to use, which
  // rejected perfectly good Chinese written any other way. An explanation is
  // Chinese if, once the Japanese it quotes in 「」 is removed, what is left has
  // Han characters and no kana.
  // The point of this check is to catch an explanation that is accidentally in
  // Japanese, not to ban quoting Japanese — explanations legitimately cite the
  // word, the pattern and an example sentence. A Chinese explanation therefore
  // has Han characters and only a minority of kana; a Japanese one is mostly kana.
  const hasChineseExplanation=(value)=>{
    // Explanations legitimately cite Japanese — in 「」 and after 例句： — and a
    // 発話表現 note may compare four expressions at once, so citations are removed
    // before judging. What remains is the author's own prose: it must be Chinese,
    // which means Han characters and only incidental kana.
    const prose=(value||"")
      .replace(/「[^」]*」/g,"")
      .split("例句：")[0]
      .replace(/\s/g,"");
    if(!/[㐀-鿿]/.test(prose))return false;
    const kana=(prose.match(/[぀-ヿ]/g)||[]).length;
    return kana/Math.max(1,prose.length)<0.15;
  };
  const assert=(condition,message)=>{if(!condition)throw new Error(`題庫稽核失敗：${message}`)};
  const readingContents=new Set(reading.map((item)=>item.content));
  const listeningScripts=new Set(listening.map((item)=>item.audioText));
  const awkwardPatterns=[/するください/,/するもらえ/,/事前に前日まで/,/までに前日まで/,/早めに前日まで/];
  assert(readingContents.size===52,`閱讀內容僅 ${readingContents.size}/52 篇不重複`);
  assert(listeningScripts.size===LISTENING_TOTAL,`聽力稿僅 ${listeningScripts.size}/${LISTENING_TOTAL} 組不重複`);

  const sourceQuestions=new Map();
  for(const item of [...reading,...listening]){
    const sourceText=item.category==="reading"?item.content:item.audioText;
    assert(!awkwardPatterns.some((pattern)=>pattern.test(sourceText)),`${item.id} 含不自然的日文接續`);
    // Question count and line count now follow the item's JLPT 大問 rather than a
    // single number: 長文 carries three questions, 即時応答 one line, 統合理解 nine.
    const format=item.category==="reading"?readingFormatFor(item.jlptFormat):listeningFormatFor(item.jlptFormat);
    assert(format,`${item.id} 沒有對應的 JLPT 題型`);
    assert(item.questions.length===format.questions,`${item.id} 題數不正確（${item.questions.length}，${format.jlpt} 應為 ${format.questions}）`);
    if(item.category==="listening"){
      assert(item.lines.length>=format.lines[0]&&item.lines.length<=format.lines[1],`${item.id} 語音行數 ${item.lines.length} 不在 ${format.jlpt} 的 ${format.lines} 範圍`);
      assert(item.audioText===item.lines.join(" "),`${item.id} 聽力稿與逐句內容不一致`);
    }
    for(const question of item.questions){
      assert(!sourceQuestions.has(question.id),`來源題 ID 重複：${question.id}`);
      assert(hasJapanese(question.prompt),`${question.id} 題幹不是日文`);
      assert(question.options.length===4&&new Set(question.options).size===4,`${question.id} 選項不是四個唯一值`);
      assert(question.options.every((option)=>hasJapanese(option)&&!hasChineseMarker(option)),`${question.id} 含非日文選項`);
      assert(Number.isInteger(question.answer)&&question.answer>=0&&question.answer<4,`${question.id} 答案索引錯誤`);
      assert(sourceText.includes(question.evidence),`${question.id} 的答案證據「${question.evidence}」不在素材中`);
      assert(hasChineseExplanation(question.explanation),`${question.id} 缺少中文解析`);
      sourceQuestions.set(question.id,{item,question});
    }
  }

  const cards=new Map([...vocabulary,...grammar].map((item)=>[item.id,item]));
  const examQuestionIds=new Set();
  const examSignatures=new Set();
  const usedSources=new Set();
  // 読解 and 聴解 questions now carry the source item's real 大問 name, so the
  // check is that every section is represented rather than one fixed label.
  const requiredSections=["文字・語彙","文法","読解","聴解"];
  let examQuestionCount=0;
  for(const assessment of assessments){
    assert(assessment.questions.length===assessment.questionCount,`${assessment.id} 題數不符`);
    assert(requiredSections.every((section)=>assessment.questions.some((question)=>question.section===section)),`${assessment.id} 題型有缺漏`);
    for(const question of assessment.questions){
      examQuestionCount+=1;
      assert(!examQuestionIds.has(question.id),`考題 ID 重複：${question.id}`); examQuestionIds.add(question.id);
      // Options are part of the signature because homophones legitimately share a
      // prompt: 地震 and 自信 both read じしん, and each makes a valid, distinct
      // orthography question once its own option set is taken into account.
      const signature=`${question.passage||""}|${question.audioText||""}|${question.prompt}|${[...question.options].sort().join("/")}`;
      assert(!examSignatures.has(signature),`考題內容重複：${question.id}`); examSignatures.add(signature);
      assert(hasJapanese(question.instruction)&&hasJapanese(question.prompt),`${question.id} 題目說明或題幹不是日文`);
      assert(question.options.length===4&&new Set(question.options).size===4,`${question.id} 選項重複或缺漏`);
      assert(question.options.every((option)=>hasJapanese(option)&&!hasChineseMarker(option)),`${question.id} 含非日文選項`);
      assert(Number.isInteger(question.answer)&&question.answer>=0&&question.answer<4,`${question.id} 答案索引錯誤`);
      assert(hasChineseExplanation(question.explanationZh),`${question.id} 缺少作答後中文解析`);
      const sourceId=question.sourceQuestionId||question.sourceCardId;
      assert(sourceId&&!usedSources.has(sourceId),`${question.id} 重複使用來源 ${sourceId}`); usedSources.add(sourceId);
      if(question.sourceQuestionId){
        const source=sourceQuestions.get(question.sourceQuestionId);
        assert(source,`${question.id} 找不到來源題 ${question.sourceQuestionId}`);
        assert(question.prompt===source.question.prompt&&JSON.stringify(question.options)===JSON.stringify(source.question.options)&&question.answer===source.question.answer,`${question.id} 與來源題答案不一致`);
        const expectedText=source.item.category==="reading"?source.item.content:source.item.audioText;
        assert((question.passage||question.audioText)===expectedText,`${question.id} 與來源素材不一致`);
        assert(periods.indexOf(source.item.unlockPeriod)<=periods.indexOf(assessment.unlockPeriod),`${question.id} 使用尚未解鎖的素材`);
      }else{
        const card=cards.get(question.sourceCardId);
        assert(card,`${question.id} 找不到來源卡片 ${question.sourceCardId}`);
        const correct=question.options[question.answer];
        if(question.logic==="kanji-reading")assert(correct===card.reading,`${question.id} 漢字讀音答案錯誤`);
        if(question.logic==="orthography")assert(correct===card.term,`${question.id} 表記答案錯誤`);
        if(question.logic==="grammar-function")assert(correct===grammarFunctionJa(card.term)&&question.passage===card.examples[0].ja,`${question.id} 文法功能或例句錯誤`);
        assert(periods.indexOf(card.unlockPeriod)<=periods.indexOf(assessment.unlockPeriod),`${question.id} 使用尚未解鎖的卡片`);
      }
    }
  }
  assert(examQuestionCount===460,`考試總題數 ${examQuestionCount}，應為 460`);
  return {readingUnique:readingContents.size,listeningUnique:listeningScripts.size,sourceQuestions:sourceQuestions.size,examQuestions:examQuestionCount,uniqueExamSources:usedSources.size};
}

const questionAudit=auditGeneratedQuestions();

// Ids whose word changed when the list was rebuilt from JMdict. A rating recorded
// against the old word says nothing about the new one, so the app drops them once,
// keyed on contentVersion.
const reissuedIds = readSource("vocab-reissued-ids.json").ids;
// Counted from what was actually assigned rather than declared alongside it —
// a second hand-written copy of this schedule is exactly what went wrong before.
const cumulativeBy = (cards) =>
  periods.reduce((running, period) => {
    const upto = running.at(-1) || 0;
    return [...running, upto + cards.filter((card) => card.unlockPeriod === period).length];
  }, []);
const grammarCumulative = cumulativeBy(grammar);
const vocabCumulative = cumulativeBy(vocabulary);
// Lesson packs, hashed. The service worker drops its cached packs when this
// changes, so a rebuild reaches the learner on their first visit rather than
// their second.
//
// Kept separate from contentVersion, which is a hand-written marker for the
// one-off progress migration above: tying that to the content would re-clear the
// learner's ratings on every future rebuild. This one has to change whenever the
// lessons do, and nothing else — which a hand-edited string does not, as the
// JLPT rebuild proved by shipping under the previous version's name.
// The 文字・語彙 and 文法 practice sets for the 閱讀聽力 page, built from the same
// item builders the exam uses.
const practice = buildPractice(periods, vocabulary, grammar, grammarFunctionJa);

const packPayloads = periods.map((period) => ({
  period,
  vocabulary: vocabulary.filter((x) => x.unlockPeriod === period),
  grammar: grammar.filter((x) => x.unlockPeriod === period),
  reading: reading.filter((x) => x.unlockPeriod === period),
  listening: listening.filter((x) => x.unlockPeriod === period),
  assessments: assessments.filter((x) => x.unlockPeriod === period),
  practice: practice.filter((x) => x.unlockPeriod === period),
}));
const contentHash = createHash("sha256")
  .update(packPayloads.map((payload) => JSON.stringify(payload)).join("\n"))
  .digest("hex")
  .slice(0, 16);
const index = { generatedAt:new Date().toISOString(), contentVersion:"2026-08-jmdict-rebuild", contentHash, reissuedIds, periods, counts:{vocabulary:vocabulary.length,grammar:grammar.length,reading:reading.length,listening:listening.length,practice:practice.length,monthlyChecks:12,n3Mocks:5,n2Mocks:2}, unlockSchedule:periods.map((period,i)=>({period,vocabulary:vocabCumulative[i],grammar:grammarCumulative[i]})), sources:[{name:"Language-Learning-decks",url:"https://github.com/vbvss199/Language-Learning-decks",license:"MIT / CC BY-SA 4.0 frequency data"},{name:"EDRDG/JMdict",url:"https://www.edrdg.org/",license:"EDRDG licence"},{name:"時雨之町",url:"https://www.sigure.tw/",use:"classification and grammar cross-check only; no copied explanations, examples, articles, or quizzes"},{name:"JLPT sample questions",url:"https://www.jlpt.jp/e/samples/sampleindex.html",use:"link only"}] };
if (!dryRun) {
  fs.mkdirSync(outRoot,{recursive:true});
  // Written from the same payloads the hash was taken over, so the two can never
  // describe different content.
  for (const payload of packPayloads) {
    fs.writeFileSync(path.join(outRoot,`${payload.period}.json`),JSON.stringify(payload));
  }
  fs.writeFileSync(path.join(root,"public","content","index.json"),JSON.stringify(index,null,2));
}
console.log({...index.counts,assessments:assessments.length,questionAudit,dryRun});
if(printSamples)console.log(JSON.stringify({
  readingVariants:[0,13,26,39].map((position)=>reading[position]),
  listeningVariants:[0,13,26,39,52,65,78,91].map((position)=>listening[position]),
  monthlySample:assessments[0].questions.slice(0,6),
  n2MockSample:assessments.at(-1).questions.slice(-6)
},null,2));
if(printGrammarMap)console.log(JSON.stringify(Object.fromEntries(Object.entries(Object.groupBy(grammar,(item)=>grammarFunctionJa(item.term))).map(([key,items])=>[key,items.map((item)=>item.term)])),null,2));
